        \bbE\Big[\bbW_1^2(P_t^1(\bfJ),\gamma_q)\Big]\geq \frac{C(t,q)}{N}.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:38:13.640000+00:00","domain":"probability theory","id":"claim_001ce081dc4b4c3104d2b1d30094d7f00f7af1373371f97f40152667c87e3f24","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2609.00690, 'Boundary behavior and optimal pointwise H\"older exponent of the total local time of $(1+\'] Let $V^\lambda$ be the bounded nonnegative distributional solution to \eqref{V lambda} which vanishes at infinity. Then we have
	\begin{equation}
		V^\lambda(x)=\bigg[\frac{\beta}{\sqrt{\beta+2}}|x|+\bigg(\frac{2}{\lambda\sqrt{\beta+2}}\bigg)^{\frac{\beta}{2+\beta}}\bigg]^{-\frac{2}{\beta}},\quad x\in\mathbb R,\ \lambda>0.
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:18:27.578871+00:00","domain":"probability theory","id":"claim_0022a926c4304dacb5149ae7b865212c443887973d2ae2cf8f9008f89b5ba249","kind":"concept","schema_version":1,"statement":"[Lem 54 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$. For every $\beta\geq 0$, and every $x,y\in \mathbb Z^d$,
\begin{equation}
	\mathbf P_{\beta}^{\emptyset,\emptyset}[x,y\in \mathbf{C}_{\n_1+\n_2}(0)]\leq \langle \sigma_0\sigma_x\rangle_{\beta}\langle \sigma_x\sigma_y\rangle_{\beta}\langle \sigma_y\sigma_0\rangle_{\beta}+(x\Leftrightarrow y),
\end{equation}
where $(x\Leftrightarrow y)$ denotes the same term with $x$ and $y$ inverted. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.754251+00:00","domain":"probability theory","id":"claim_0024a41e4cd1d2784b7c8ade47609a23af03f731fad5df1377483b88df436266","kind":"concept","schema_version":1,"statement":"[Theorem thm:intro-lbm-spectrum of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For every $0<\gamma<2$, almost surely, $A_h$ has compact resolvent, and its
positive eigenvalues, listed with multiplicity, satisfy
\begin{equation}
 0<\Lambda_1^h<\Lambda_2^h<\cdots\uparrow\infty.

\end{equation}
Moreover, for every $N\ge1$ and $1\le n_1<\cdots<n_N$,
\begin{equation}
 (\Lambda_{n_1}^h,\ldots,\Lambda_{n_N}^h)_\#\mathbb P
 \ll\mathcal L^N.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.777827+00:00","domain":"probability theory","id":"claim_0033789497d474c69b5681ff923f051beede6825324717335b52c4090e8f43d5","kind":"concept","schema_version":1,"statement":"[Prop unmin of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Under the assumptions of Proposition (cormain of the paper), the following hold
\begin{enumerate}

\item[(i)] We have that
\begin{equation}
\begin{aligned}
&\inf_{\mu \in {\mathcal M }_1({\mathcal C }_\beta)}\Bigl\{I^{{\scriptscriptstyle{({\rm sym}})}}_{W,{\mathfrak m}}(\mu)-\langle \mu_{0,\beta},\log g\rangle\Bigr\}=\\
&\inf\limits_{q\in{\mathcal M }_1^{\ssup{{\rm s}}}(\mathbb{R}^d\times\mathbb{R}^d)}\Big\{H(q|\overline{q}\otimes{\mathfrak m})-\int_{\mathbb{R} ^d}\int_{\mathbb{R} ^d}\log \mathbb{E}^\beta_{x,y}\Big[e^{-\Tilde{W} }\Big]q({\rm d} x, {\rm d} y)-\langle g,\log g\rangle\Bigr\}.\\
\end{aligned}
\end{equation}

\item[(ii)] The unique minimizer of the (non-normalized) rate function defined in Proposition (cormain of the paper) (i) is given by 
\begin{equation}
    \mu^*_{g,{\mathfrak m},W}=\int_{\mathbb{R}^d}\int_{\mathbb{R}^d}Q^{\beta}_{x,y}\circ B^{-1}q^*_{g,{\mathfrak m},W}({\rm d} x, {\rm d} y),
\end{equation}
where for $x,y \in \mathbb{R} ^d $, we define
\begin{equation}
    Q^\beta_{x,y}({\rm d} \omega):=\frac{1}{\mathbb{E}^\beta_{x,y}\big[e^{-\Tilde{W} }\big]}e^{-\Tilde{W}(\omega)}\mathbb{P}^\beta_{x,y}({\rm d} \omega),\qquad \omega \in {\mathcal C }_\beta,
\end{equation}
and $q_{g,{\mathfrak m},W}^*\in{\mathcal M }_1^{\ssup{{\rm s}}}(\mathbb{R}^d\times\mathbb{R}^d)$ is the unique minimizer of the formula on the right hand side of (equation infIg of the paper).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:44:17.162672+00:00","domain":"probability theory","id":"claim_00338a3661f62d473270a2b3e03727db93be3f8107c82d4dd975922bfd05fde9","kind":"concept","schema_version":1,"statement":"[Theorem 14 (Theorem 2.3 of \cite{zhang2016central}) of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Suppose $\{Z_{n}\}$ converges to the constant $\theta^{*}$ almost surely, and that Assumptions~\eqref{gen_assump_dist_1} and \eqref{gen_assump_dist_3} are satisfied. Suppose $\rho>1/2$, and that
\begin{equation}
\sum_{i=0}^{n-1}\delta_{i}=o\left(\sqrt{n}\right) \text{ almost surely}.
\end{equation}
Then 
\begin{equation}
\sqrt{n}\left(Z_{n}-\theta^{*}\right)\convd N(0,\Sigma),
\end{equation}
where, with $\Gamma$ is the matrix mentioned in Assumption~\eqref{gen_assump_dist_3}, we set
\begin{equation}
\Sigma=\int_{0}^{\infty}\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\Gamma\left[\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\right]^{t}du.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:19.042401+00:00","domain":"probability theory","id":"claim_004ce9813dec54b7a70a5e3d6c0b6db0fe5e471975ef30cef98a20fb237374dc","kind":"concept","schema_version":1,"statement":"[Thm thm-P1 of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Let $d=3$ and $\lambda\in \Sigma_\theta$.
Let $(u, \phi )$ be a weak solution of (equation eq-0 of the paper), where
$F\in C_{0, \sigma}^\infty(\Omega)$ and $\Omega$ is a bounded Lipschitz domain.
Let  $B(x, 2r)\subset \Omega$.
Then
\begin{equation}
\left(
\fint_{B(x, r)} |\phi -\fint_{B(x, r)}  \phi  |^q \right)^{1/q}
\le C  M_2(|\nabla u|)(\delta(x) )
\end{equation}
for any $2< q< \infty$, 
where $C$ depends only on  $\Omega$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.770915+00:00","domain":"probability theory","id":"claim_0051a1adbe08c96111922dea142fa5738df798885969717d0b48a352e228a7b7","kind":"definition","schema_version":1,"statement":"[Definition 43 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same parameters as in Definition \ref{Def.ParametersBulk}. Fix $m \in \mathbb{N}$, $t_1, \dots, t_m \in [0, \infty)$ with $t_1 < t_2 < \cdots < t_m$, and set $\mathcal{T} = \{t_1, \dots, t_m\}$. We also define for $t \in \mathcal{T}$ the quantity $T_{t} = T_t(N) =  \lfloor t N^{2/3} \rfloor$ and the lattice $\Lambda_t(N) = a_t(N) \cdot \mathbb{Z} + b_t(N)$, where 
\begin{equation}
a_t(N) = \sigma_1^{-1} N^{-1/3}, \mbox{ and } b_t(N) = \sigma_1^{-1} N^{-1/3} \cdot \left( - h_1 N - p_1 T_{t} \right).
\end{equation}

We let $\mathbb{P}_N$ be the Pfaffian Schur process from Definition \ref{Def.SchurProcess}. Here, we assume that $M = M(N)$ is sufficiently large so that $M \geq T_{t_m}$. If $(\lambda^0, \dots, \lambda^M)$ have law $\mathbb{P}_N$, we define the random variables
\begin{equation}
X_i^{j,N} = \sigma_1^{-1} N^{-1/3} \cdot \left( \lambda_i^{T_{t_j}} - h_1 N - p_1 T_{t_j}  - i\right) \mbox{ for } i \in \mathbb{N} \mbox{ and } j \in \llbracket 1, m \rrbracket.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:21:56.724863+00:00","domain":"probability theory","id":"claim_0054b28e407cb4a2095f0f08594508aa24d985f12442f2462ae63dbec4f2089d","kind":"concept","schema_version":1,"statement":"[Lemma le:dist_across_chain of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Fix $a_1 > 0$. There exists $N\in\mathbf{N}$ such that the following is true. Let $\widetilde{z}\in D$ and $\delta>0$ such that $B(\widetilde{z},\delta) \subseteq D$, and let $\lambda \in (0,1]$. Let $\widetilde{G}_{\widetilde{z},\delta,\lambda}$ be the event that there is a set of at most $N$ points $z_1,z_2,\ldots \in A(\widetilde{z},\delta^{1+a_1},\delta)$ with $\abs{z_{i_1}-z_{i_2}} \ge \delta^{1+a_1}$ for each pair $i_1 \neq i_2$ and such that whenever $\eta \cap B(\widetilde{z},\delta^{1+a_1}) \neq \varnothing$, the following hold.
\begin{itemize}
\item The set $\{z_1,z_2,\ldots\}$ separates $\eta \cap B(\widetilde{z},\delta^{1+a_1})$ from $\partial B(\widetilde{z},\delta)$ in $\Upsilon_\Gamma$.
\item Let $K'$ be any connected component of $\Upsilon_\Gamma \setminus \{z_1,z_2,\ldots\}$ adjacent to $\eta \cap B(\widetilde{z},\delta^{1+a_1})$, and let $i_1,i_2$ so that $z_{i_1},z_{i_2} \in \partial K'$. Let $U'_1 \in \metregions$ be such that $\overline{U'_1}$ contains all \emph{simple} admissible paths within $K'$ from $z_{i_1}$ to $z_{i_2}$. Then
\[ \metapproxacres{\epsilon}{U'_1}{z_{i_1}}{z_{i_2}}{\Gamma} \le \lambda^{{d_{{\mathrm{dbl}}}}}\median{\epsilon}+\lambda^{a_0}\epsilon^{-a_0}\mathbf{a}_{\epsilon} . \]
\end{itemize}
Then $\mathbf{P}[\widetilde{G}_{\widetilde{z},\delta,\lambda}^c] = O((\delta/\lambda)^{{\alpha_{\mathrm{apr}}}})$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:51:15.030740+00:00","domain":"probability theory","id":"claim_00584744a55aaa43f7ba0aff456f824b5012486af4d00fd5faea87c3c9a6812d","kind":"concept","schema_version":1,"statement":"[Lemma proptfund1 of arXiv:2609.03909, 'Conic Pseudo-Finslerian Mechanical Systems'] Let  $\mathcal{U} \subset TM \setminus 0$ be an open subset invariant under positive scalar multiplication and let$ \mathcal L$ be a Lagrangian, of class $C^2$ on $\mathcal U$, which is positively $2$-homogeneous. Then its fundamental tensor satisfies the following properties:
\begin{enumerate}
    \item[(i)] $g_v$ is positively homogeneous of degree 0, that is, $g_{\lambda v}=g_{v}$ for any $\lambda >0;$
    \item[(ii)] $g_v(v,v)=2\mathcal L(v);$
    \item[(iii)] $g_v(v,w)=\ell_v(w)=d\mathcal L_v(w)$ for any $w\in T_{\pi(v)}M.$
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:33.751027+00:00","domain":"probability theory","id":"claim_0058f4388ea941ef1e2987ae1fd8773987e009ee40a549d6f07a03749f33eda6","kind":"concept","schema_version":1,"statement":"[Proposition 24 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Suppose that Assumption \ref{Assumption} holds, and
let $\ka>0$ be fixed.
\begin{enumerate}
\item If $\rho>0$, then
\begin{align}

\lim_{\th\to0}\mbf E\big[\tfrac{\ka^2}{2}\be^\th_1(B)\big]=\frac{\ka^2\mf b}{(1+\rho)\rho}.
\end{align}
\item If $\rho=0$, then
there exist bounded and continuous functions $\msf b_i:[0,\infty)\to\mbb R$, $(i=1,2)$,
such that for every $\th>0$, one has
\begin{align}

\mbf E\big[\tfrac{\ka^2}{2}\be^\th_1(B)\big]
=
\begin{cases}
\ka^2\mf b\,\ell(\th)+\ka^2\msf b_1(\th)&H_0<1,\\
\ka^2\mf b\,(1+\th)\log(1+1/\th)+\ka^2\msf b_2(\th)&H_0=1,
\end{cases}
\end{align}
where
\begin{align}

\ell(\th)=\frac{1}{2\Ga(H_0)\Ga(1-H_0)}\int_0^{2\pi}\left|\frac{\sin\theta}{\cos\theta}\right|^{2H_0-1}
\Ga_0\Big(\th\big(|\sin\theta|+|\cos\theta|\big)\Big)\d\theta,
\end{align}
and $\Gamma_0$ denotes the zero-parameter upper incomplete Gamma function, i.e.,
\[\Gamma_0(\th)=\int_{\th}^\infty \mr e^{-z}z^{-1}\d z,\qquad \th>0.\]
\item 
If $\rho<0$,
then there exists a bounded and continuous function $\msf z:(0,\infty)\to\mbb R$ such that
for every $\th>0$,
\begin{align}

\mbf E\big[\tfrac{\ka^2}{2}\be^\th_1(B)\big]=\ka^2\mf d\,\th^{\rho}+\,\ka^2\msf z(\th).
\end{align}
Moreover,
$\msf z$ satisfies the limit
\begin{align}

\lim_{\th\to0}\msf z(\th)=
\begin{cases}
\frac{\mf b}{(1+\rho)\rho}&H_0>1/2,\\
0&H_0=1/2.
\end{cases}
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.588240+00:00","domain":"probability theory","id":"claim_005dd38b7f80a002b4c1a5dbbe4b4629d3575c67af5d77d6f4fe5dd0a28cc852","kind":"concept","schema_version":1,"statement":"[Proposition MartingaleReProp of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] For each $x\geq 0$, the random variable 
  \begin{eqnarray}
  \mathbf{Y}_x:=  \lambda\cdot  X_\zeta(x)+  \big(g-\boldsymbol{\mathcal{R}}_0\circ V^g_\lambda\big)  *X_\zeta(x) \end{eqnarray}
  is integrable and can be written as
  \begin{eqnarray*}
  \mathbf{Y}_x \!\!\!&=\!\!\!& Y_x(0)  + \int_0^x \int_0^{X_\zeta(s)}   V^g_\lambda(x-s) \, B_c(ds,dz) \cr
  \!\!\!&\!\!\!& + \int_0^x\int_0^{X_\zeta(s)} \int_0^\infty \Big( \int_{(x-s-y)^+}^{x-s} V^g_\lambda(r)\,dr\Big) \, \widetilde{N}_\nu(ds,dz,dy),\cr
  Y_x(0)\!\!\!&:=\!\!\!&   \zeta\cdot c \cdot  V^g_\lambda(x)+ \int_0^\zeta \int_0^\infty \Big( \int_{(x-y)^+}^{x} V^g_\lambda(r)\,dr\Big) N_0(dz,dy).  
  \end{eqnarray*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:31:57.857333+00:00","domain":"probability theory","id":"claim_005f3c546f828ddb61c7a965b15dfba87db788859de95a8fc4c1b5dea4af4831","kind":"concept","schema_version":1,"statement":"[Conjecture conj:matrixspencer of arXiv:2510.01021, '\Large Random Matrices, Intrinsic Freeness, and Sharp Non-Asymptotic Inequalities\relatedv'] There exists a positive universal constant $C$ such that, for all positive integers $n$, and all choices of $n$ self-adjoint $n\times n$ real matrices $A_1,\dots,A_n$ satisfying, for all $i\in[n]$, $\|A_i\|\leq 1$ 
    the following holds
    \begin{equation}
