{"assumptions":[],"created_at":"2026-10-27T07:58:01.556558+00:00","domain":"probability theory","id":"claim_02a58dce321dafd201b0d839a0d55a278c5febdfe97b18c8d79a6db1b571d6a9","kind":"theorem","schema_version":1,"statement":"[Corollary 8 of arXiv:2608.27156, 'Traveling Waves in Equity Markets with\\Rank-Based Entry and Exit'] Under the hypotheses of Theorem~\ref{thm:wave}, the profile satisfies $1 - V(y) = e^{-\alpha y (1 + o(1))}$ as $y \to \infty$, where
\begin{equation}
    \alpha \;=\; \frac{a + \sqrt{a^{2} - 2\,\sigma^{2}(1)\,\tilde f'(1)}}{\sigma^{2}(1)},
    \qquad a \;=\; c - \tilde b(1):
\end{equation}
the capitalization distribution of the wave has a Pareto tail with exponent $\alpha$ at the top of the market. Symmetrically, $V(y) = e^{\beta y (1 + o(1))}$ as $y \to -\infty$, where $\beta$ is the positive root of \eqref{eq:char-poly} at $e = 0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:35:04.166269+00:00","domain":"probability theory","id":"claim_02a64ec2fcf68297f165e4ec25f77e3b0336898658ee8468a18bb86199d1a4b4","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2608.30848, '\huge \bf Limit Laws of the Iterated Logarithm Under Sub-linear Expectations'] A sub-linear expectation $\widehat{\mathbb E} :\mathscr{H}\rightarrow\bar{\mathbb{R}}$ on the space $\mathscr{H}$ is a function satisfying the following properties: for all $X,Y\in\mathscr{H}$,
\begin{itemize}
\item[(a)] If $X \geq Y$, then $\widehat{\mathbb E} [X] \geq \widehat{\mathbb E} [Y]$;
\item[(b)] $\widehat{\mathbb E} [c]=c$;
\item[(c)] When $\widehat{\mathbb E} [X]+\widehat{\mathbb E} [Y]$ is not of the form $+\infty-\infty$ or $-\infty+\infty$, we have $\widehat{\mathbb E} [X+Y] \leq \widehat{\mathbb E} [X]+\widehat{\mathbb E} [Y]$;
\item[(d)] For $\lambda>0$, we have $\widehat{\mathbb E} [\lambda X]=\lambda\widehat{\mathbb E} [X]$. \end{itemize}
Here, $\bar{\mathbb{R}}=[-\infty,\infty]$, and $0\cdot\infty$ is defined as $0$. The triple $(\Omega,\mathscr{H},\widehat{\mathbb E})$ is called a sub-linear expectation space. Given a sub-linear expectation $\widehat{\mathbb E}$, $\widehat{\mathcal E}$ denotes its conjugate expectation, i.e., $$ \widehat{\mathcal E} [X]:=-\widehat{\mathbb E} [-X],\quad\forall X\in\mathscr{H}. $$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.256153+00:00","domain":"probability theory","id":"claim_02a95d93453c8303a195c5b9d1219f21664baad50c29db54c461c90d20b33539","kind":"concept","schema_version":1,"statement":"[Prp 46 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $(F,R,\mu)$ be in $\bbF^{\circ}$.
  Set $\g{c}{suffcond1,1}=\mu(F)^{-1}+\diam F$ and $\g{c}{suffcond1,2}=\left[\mu(F)^{1/2}\g{c}{continuity,1}\right]^{2\kappa-1}$.
\begin{itemize}
  \item [$\mathrm{(i)}$]Suppose that $F$ is compact. Then it holds that
  \begin{equation*}
     \|(\alpha-\Delta)^2P_th\|_{F}\lesssim \g{c}{suffcond1,1}t^{-3}\|h\|_{L^1(F,\mu)},
    \quad \|(\alpha-\Delta)^2P_th\|_{F}\lesssim (\g{c}{suffcond1,1})^{1/2}t^{-5/2}\|h\|_{L^2(F,\mu)},
  \end{equation*}
  \begin{equation*}
  \|(\alpha-\Delta)^2P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{suffcond1,2}\alpha^{-( 2\kappa-1 )} t^{-(\kappa+2)}\|h\|_{L^1(F,\mu)},
  \end{equation*}
  and
  \begin{align}
  \|(\alpha-\Delta)^2 P_t h \|_{\Lip^{\kappa}}\lesssim (\g{c}{suffcond1,1})^{1/2} \g{c}{suffcond1,2} \alpha^{-( 2\kappa-1 )} t^{-(\kappa+5/2)}\|h\|_{L^2(F,\mu)},
  \end{align}
  for any $\alpha,\;t\in (0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$. 
     \item [$\mathrm{(ii)}$]
     If $(F,R,\mu)$ satisfies assumption $\rm{(A1)}$, and is compact, 
     then it holds that
  \begin{equation*}
     \|(\alpha-\Delta)^2P_th\|_{F}\lesssim c_{\rm{A1}}t^{-\left(2+\frac{s_0}{1+s_0}\right)}\|h\|_{L^1(F,\mu)},
    \quad \|(\alpha-\Delta)^2P_th\|_{F}\lesssim c_{\rm{A1}}^{1/2}t^{-\left(2+\frac{s_0}{2(1+s_0)}\right)}\|h\|_{L^2(F,\mu)},
  \end{equation*}
  and
  \begin{equation*}
  \|(\alpha-\Delta)^2P_th\|_{\Lip^{\kappa}}\lesssim c_{\rm{A1}}^{1/2}\g{c}{suffcond1,2}\alpha^{-( 2\kappa-1 )} t^{-(\kappa+2+\frac{s_0}{2(1+s_0)})}\|h\|_{L^1(F,\mu)},
  \end{equation*}
  for any $\alpha,\;t\in (0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.

   \item [$\mathrm{(iii)}$]If $(F,R,\mu)$ satisfies assumption $\rm{(A2)}$, 
     then it holds that
  \begin{equation*}
  \|(\alpha-\Delta)^2P_th\|_{\Lip^{\kappa}}\lesssim c_{\rm{A1}}^{\kappa}\g{c}{suffcond1,3}\alpha^{-(1+\frac{s_1}{2(1+s_0)\theta})( 2\kappa-1 )} t^{-(\kappa+2+\frac{s_0}{2(1+s_0)})}\|h\|_{L^1(F,\mu)},
  \end{equation*}
  and
  \begin{equation*}
  \|(\alpha-\Delta)^2P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{suffcond1,3}\alpha^{-(1+\frac{s_1}{2(1+s_0)\theta})(2\kappa-1)}t^{-(\kappa+2)}\|h\|_{L^2(F,\mu)},
  \end{equation*}
  for any $\alpha,\;t\in (0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$, where
  \begin{align*}
     \g{c}{suffcond1,3}= \left\{ \g{c}{continuity,1}\left[ c_{\rm{A2}}\Gamma\left(1-\frac{s_1}{(1+s_0)\theta}\right) \right]^{-1/2} \right\}^{2\kappa-1}.
  \end{align*}

     \item [$\mathrm{(iv)}$]If $(F,R,\mu)$ satisfies assumption $\rm{(A3)}$, 
     then it holds that
  \begin{equation*}
  \|(\alpha-\Delta)^2P_th\|_{\Lip^{\kappa}}\lesssim c_{\rm{A1}}^{\kappa}\g{c}{suffcond1,4}\alpha^{-(1+\frac{s_1}{2(1+s_0)\Theta})( 2\kappa-1 )} t^{-(\kappa+2+\frac{s_0}{2(1+s_0)})}\|h\|_{L^1(F,\mu)},
  \end{equation*}
  and
  \begin{equation*}
  \|(\alpha-\Delta)^2P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{suffcond1,4}\alpha^{-(1+\frac{s_1}{2(1+s_0)\Theta})(2\kappa-1)}t^{-(\kappa+2)}\|h\|_{L^2(F,\mu)},
  \end{equation*}
  for any $\alpha,t\in (0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$, where
  \begin{align*}
     \g{c}{suffcond1,4}= \left\{ \g{c}{continuity,1}\left[ c_{\rm{A3}}\Gamma\left(1-\frac{s_1}{(1+s_0)\Theta}\right) \right]^{-1/2} \right\}^{2\kappa-1},\quad \Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)}.
  \end{align*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.261378+00:00","domain":"probability theory","id":"claim_02b4ea9721ed8d01002e64055bd3b8d6cd1ca72b24db92c03ce096541dcb2051","kind":"concept","schema_version":1,"statement":"[Lemma lem: SFT decouple lemma of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] Assume that $\widetilde{e}_j(\cdot)$ ($j=1,2,\ldots,k_0$) is a probability measure supported on $\partial A_j$ satisfying that 
    \begin{equation}

        1-\frac{v}{3} \leq \frac{\mathsf{P}_y(X_{H_{A}}=x|X_{H_{A}}\in A_j)}{\widetilde{e}_j(x)} \leq 1+\frac{v}{3}
    \end{equation}
    for all $x \in \partial A_j$ and $y \in \partial A'_j$.
    Then, there exists a probability measure $\mathbf{P}$ extending $\mathsf{\mathsf{P}}$ and a family of events $(G_{j}^{m_0})_{1 \leq j \leq k_0}$ independent with random walk $(X_k)_{k \geq 0}$ such that
    \begin{itemize}
        \item $(G_{j}^{m_0})_{1 \leq j \leq k_0}$ are independent from each other.
        \item $\mathsf{P}(G_{j}^{m_0}) \geq 1-C \exp(-cvm_0)$ for all $j=1,2,\ldots,k_0$.
        \item For all $j=1,2,\ldots, k_0$ and $m>m_0$, on the event $U_{j}^{m_0}$, we have
        \begin{equation}
            \begin{aligned}
                \{Z_1^{(j)},Z_2^{(j)},\ldots, Z_{(1-v)m}^{(j)} \} &\subset \{\widetilde{Z}_1^{(j)},\widetilde{Z}_2^{(j)},\ldots, \widetilde{Z}_{(1+3v)m}^{(j)} \},\mbox{ and}\\
                \{\widetilde{Z}_1^{(j)},\widetilde{Z}_2^{(j)},\ldots, \widetilde{Z}_{(1-v)m}^{(j)} \} &\subset 
                \{Z_1^{(j)},Z_2^{(j)},\ldots, Z_{(1+3v)m}^{(j)} \},
            \end{aligned}
        \end{equation}
        where $(\widetilde{Z}_{i}^{(j)})_{i \geq 0}$ is a sequence of i.i.d.\ excursions with law $\mathbf{P}^{(\widetilde{e}_j)}$.
        Moreover, $(\widetilde{Z}_{i}^{(j)})_{i \geq 0}$ and $(\widetilde{Z}_{i}^{(j')})_{i \geq 0}$ are independent if $j \neq j'$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:00.771050+00:00","domain":"probability theory","id":"claim_02b550cb537086be7c0198be899c878de182c1320fc49ca83cb56dea5b64ad36","kind":"concept","schema_version":1,"statement":"[Proposition 12 of arXiv:2512.05340, 'The rate of convergence of the critical mean-field $O(N)$ magnetization via multivariate n'] If $V$ satisfies Assumption~\ref{assumption: assumptions on V}, then for $x, u, v, w\in \RR^{d}$ and $t>0$,
\begin{equation}
     |\,\sU_{u}^x(t)| \leq |u|,
 \end{equation}
\begin{equation}
     \EE|\,\sU_{u}^x(t)|^{2} \leq C_{1}^{2}e^{-2\theta t}|u|^{2},
 \end{equation}
\begin{equation}
     \EE|\,\sU_{u,v}^x(t)|^{2} \leq C_{2}^{2}|u|^{2}|v|^{2},
 \end{equation}
 \begin{equation}
     |\,\sU_{u,v,w}^x(t)| \leq |u||v||w|P(t),
 \end{equation}
 where, 
 \begin{align*}
     C_{1} &:= \frac{1}{\sqrt{J(2t_{0})}},                               &\theta :=& \frac{\log(1/J(2t_{0}))}{2t_{1}},\\ 
     C_{2} &:= \sqrt{2}M_1\left(1+\frac{C_1^2}{\theta^2}\right)^{1/2},   &P(t)   :=& (3M_1^2(t+1)/2+M_2)(t+1).
 \end{align*}
with $J:[1,\infty)\to\RR$ defined via
   \begin{equation*}
     J(t):= 1-\frac{1-e^{-\chi}}{2t}, \qquad  \chi:=c_1B^k,
   \end{equation*}
   and 
   \begin{equation*}
     \begin{split}
        t_{0}&:= \frac{\eta + 2B + 2m_{1}(\mu)}{\eta\mu(\{x\in\RR^{d}: |x| > B+ 1\})},\\
        t_{1}&:= \max\left\{2t_{0}, \frac{1}{\chi}\log\left(\frac{4t_{0}}{1-e^{-\chi}}\right)\right\}.
        \end{split}
    \end{equation*}
   The constants $k,B,c_1,M_1,M_2$ are as defined in Assumption~\ref{assumption: assumptions on V}, while $\mu$ and $\eta$ are as defined in
   Lemma~\ref{lemma: geom erg}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.530133+00:00","domain":"probability theory","id":"claim_02b929fab8b5755bf9773e73d19f73d6835caa4ce6e965eb3c641254a5cacaad","kind":"concept","schema_version":1,"statement":"[Proposition 22 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu_{\rm d}$, $\mu_{\rm a} \in \mathcal{M}_F(\mathbb{R}^d)$ be such that $\mu_{\rm d} + \mu_{\rm a}$ is a non-zero measure and let $(\mathcal{Y}_s^{(\rm d)}, \mathcal{Y}_s^{(\rm a)})_{s \geq 0}$ be an $\text{ooSBM}(4, c, \Tilde{c})$ started from $(\mu_{\rm d}, \mu_{\rm a})$. For any $s \geq 0$ let $\mathcal{Y}_s = \mathcal{Y}_s^{(\rm d)} +  \mathcal{Y}_s^{(\rm a)}$. Then, for any fixed $t \geq 0$, we have
    \begin{equation*}
        \text{dim}\Big( \overline{\bigcup_{0 \leq s \leq t} \text{supp}(\mathcal{Y}_s)} \Big) = \text{dim}(\text{supp}(\mu_{\rm d})) \vee \text{dim}(\text{supp}(\mu_{\rm a})) \vee (4 \wedge d) \hspace{0.5cm} \mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}-\text{a.s.}
    \end{equation*}
    \begin{proof}
        This almost follows immediately from Lemma \ref{lemma oosbm range domination} and the dimension results given in Proposition \ref{proposition dimension range and support sbm} and Lemma \ref{lemma dimensions damped sbm}. First assume $\mu_{\rm a}$ is a non-zero finite measure. We wish to apply the dimension results in Proposition \ref{proposition dimension range and support sbm} and Lemma \ref{lemma dimensions damped sbm} for the ranges of the superprocesses to determine the dimension of the closure of the union of the supports from time $\delta$ to $t$, $\text{dim}(\overline{\bigcup_{\delta \leq s \leq t} \text{supp}(\mathcal{Y}_s)})$, for any $\delta > 0$. We note that the proof of the dimension result from \cite[Theorem IV.7]{le1999spatial} which shows that each constituent part of the SBM $\mathcal{X}$ formed by the snakes $(x^i, i \in \Tilde{I})$ has range dimension $4 \wedge d$. Now, some of these clusters a.s. have contour functions $f^i$ with height less than $t$, and the range from time $\delta$ of the component of the superprocess is equal to the closure of the union of supports from times $\delta$ to $t$. Therefore the dimension of the union of the supports is at least $4 \wedge d$. When we include the initial support of $\mathcal{X}_0$ which has dimension $\text{dim}(\text{supp}(\mu_{\rm d})) \vee \text{dim}(\text{supp}(\mu_{\rm a}))$ we have the dimension is at least $(\text{supp}(\mu_{\rm d})) \vee \text{dim}(\text{supp}(\mu_{\rm a})) \vee (4 \wedge d)$. The reverse inclusion is immediate so the dimension is equal to $(\text{supp}(\mu_{\rm d})) \vee \text{dim}(\text{supp}(\mu_{\rm a})) \vee (4 \wedge d)$ as required. 
        \par
        It remains to consider the case where $\mu_{\rm a} = 0$ and therefore that $\mu_{\rm d}$ is a non-zero finite measure. However, in this case we can show that there exists $T \in (0,t/2)$ and $n \in \mathbb{N}$ such that $\mathcal{Y}^{(\rm a)}_T(\mathbb{R}^d)>1/n$ a.s. To see this we recall from \cite[Proposition 1.9]{blath2023off} that the total mass processes $(q_s, p_s)_{s \geq 0} \coloneqq (\mathcal{Y}^{(\rm d)}_s(\mathbb{R}^d), \mathcal{Y}^{(\rm a)}_s(\mathbb{R}^d))_{s \geq 0}$ are governed by the stochastic differential equations
        \begin{equation*}
            dq_t = (cp_t - \Tilde{c}q_t) dt; \hspace{0.5cm} dp_t = (\Tilde{c}q_t - cp_t)dt + \sqrt{\gamma p_t} dB_t. 
        \end{equation*}
        Therefore, we can see that $p_s=0$ for all $s \in (0,t/2)$ leads to a contradiction. We also have that $(q_s)_{s \geq 0}$ and $(p_s)_{s \geq 0}$ are continuous processes (this can be seen for example by the continuity of $(\mathcal{Y}^{(\rm d)}_s)_{s \geq 0}$, $(\mathcal{Y}^{(\rm a)}_s)_{s \geq 0}$ with respect to the Prokhorov metric). Let the time $T_n$ be the first hitting time of $1/n$ for $(p_s)_{s \geq 0}$. Then the result follows for $t>T_n$ by the previous argument for the case where $\mu_{\rm a}$ is non-zero and the strong Markov property. We have a.s. that $t/2>T_n$ for some $n \in \mathbb{N}$ and therefore the result follows.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.300777+00:00","domain":"probability theory","id":"claim_02ba4d3a2cbe0955759e26e0b3a20dcd366dea04c4f31c6b52637c6825d36e78","kind":"theorem","schema_version":1,"statement":"[Coro advanced geographic ineq decoupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $n\in \mathbb N$ be such that $n\varepsilon\geqslant 1+r\tau_K$ and let 
