{"assumptions":[],"created_at":"2026-10-26T20:46:26.256251+00:00","domain":"probability theory","id":"claim_03cd209281fd111361a2100cc890781489aaf907db945aa1e1fb08f1f145d0ae","kind":"concept","schema_version":1,"statement":"[Prp 47 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $(F,R,\mu)$ be in $\bbF^{\circ}$.
  Set $\g{c}{suffcond2,1}=\left[\mu(F)^{1/2}\g{c}{unihk,1}\right]^{2\kappa-1}$ and $\g{c}{suffcond2,2}=\left[\mu(F)^{1/2}\g{c}{c_1,1}\right]^{2\kappa-1}$.
\begin{itemize}
  \item [$\mathrm{(i)}$]If $F$ is compact, then it holds that
  \begin{align}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{unihk,1} t^{-2\kappa}\|h\|_{L^1(F,\mu)},
  \end{align}
  and
  \begin{align}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{suffcond2,1} t^{-(3\kappa-1)}\|h\|_{L^2(F,\mu)},
  \end{align}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.

  \item [$\mathrm{(ii)}$]If $F$ is compact, and satisfies assumption $\rm{(A1)}$,
  then it holds that
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim\g{c}{c_1,1}t^{-\frac{2\kappa s_0+3\kappa-1}{1+s_0}}\|h\|_{L^1(F,\mu)},
  \end{equation}
  and
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{suffcond2,2} t^{-(3\kappa-1)}\|h\|_{L^2(F,\mu)},
  \end{equation}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.
  \item [$\mathrm{(iii)}$]If $(F,R,\mu)$ satisfies assumption $\rm{(A2)}$,
  then it holds that
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{c_1,2}t^{-\frac{2[(1+s_0)\theta-s_1]\kappa+s_0\theta+s_1}{2(1+s_0)\theta}}\|h\|_{L^1(F,\mu)},
  \end{equation}
  and
  \begin{equation}
     \|P_th\|_{\Lip^{\kappa}}\lesssim  \g{c}{suffcond1,3} t^{-[\kappa-\frac{s_1}{2(1+s_0)\theta}(2\kappa-1)]}\|h\|_{L^2(F,\mu)},
  \end{equation}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.
  \item [$\mathrm{(iv)}$]If $(F,R,\mu)$ satisfies assumption $\rm{(A3)}$,
  then it holds that
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{c_1,3}t^{-\frac{2[(1+s_0)\Theta-s_1]\kappa+s_0\Theta+s_1}{2(1+s_0)\Theta}}\|h\|_{L^1(F,\mu)},
  \end{equation}
  and
  \begin{equation}
     \|P_th\|_{\Lip^{\kappa}}\lesssim  \g{c}{suffcond1,4}t^{-[\kappa-\frac{s_1}{2(1+s_0)\Theta}(2\kappa-1)]} \|h\|_{L^2(F,\mu)},
  \end{equation}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$. Here, $\Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:13:22.516421+00:00","domain":"probability theory","id":"claim_03d15365b5c76a8f860027d24e8bdc646855d67aa09b536e227fb951bf081737","kind":"concept","schema_version":1,"statement":"[Thm commutation relation for chordal with marked point u infty of arXiv:2505.16093, 'Multiple chordal SLE($\kappa$) and quantum Calogero-Moser system'] In the upper half plane $\mathbb{H}$, $n$ chordal SLEs start at $x_1,x_2,\ldots,x_n\in \partial{\mathbb{H}}$ with a marked boundary point $u$. 
\begin{itemize}

\item[(i)] Let the infinitesimal diffusion generators be
\begin{equation}
\mathcal{M}_i=\frac{\kappa}{2} \partial_{ii}+b_i(x_1, x_2,\ldots, x_n,u) \partial_i +\sum_{j \neq i} \frac{2}{x_j-x_i}\partial_j 
\end{equation}

where $\partial_i=\partial_{x_i}$. If n SLEs locally commute, then the associated infinitesimal generators satisfy:
\begin{equation}
[\mathcal{M}_i, \mathcal{M}_j]=\frac{4}{(x_i-x_j)^2}(\mathcal{M}_j-\mathcal{M}_i)
\end{equation}
There exists a partition function $\psi(\boldsymbol{x})$ such that the drift term $b_i(\boldsymbol{x})$ is given by:
\begin{equation}
b_i(\boldsymbol{x})= \kappa \partial_i \log \psi
\end{equation}
where $\psi$ satisfies the null vector equations with an undetermined function $h_i(x)$.
\begin{equation}
\frac{\kappa}{2} \partial_{ii} \psi+\sum_{j \neq i} \frac{2}{x_j-x_i}\partial_i \psi+ \left[\left(1-\frac{6}{\kappa}\right) \sum_{j \neq i}\frac{1}{(x_j-x_i)^2}+h_i(x_i)\right]\psi=0
\end{equation}

\item[(ii)]
 By analyzing the asymptotic behavior of two adjacent growth points $x_i$ and $x_{i+1}$ ( with no marked points between $x_i$ and $x_{i+1}$ on the real line $\mathbb{R}$), we can further show that the $h_i(x)=h_{i+1}(x)$ in null vector equations ((null vector equations in mathbb H of the paper)). As a corollary, if all growth points lie consecutively on the real line $\mathbb{R}$ with no marked points between them, then there exists a common function $h(x)$ such that $h(x)=h_1(x)=\ldots=h_n(x)$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:04:59.428044+00:00","domain":"probability theory","id":"claim_03d5ea64fffbafeca54a37467def92d0dc61aa834de9f81f2952029b2312f9f6","kind":"lemma","schema_version":1,"statement":"[Lemma lem:burning of arXiv:2605.19419, 'Tail exponents of the three-dimensional uniform spanning tree and Abelian sandpile'] Let $K\Subset\mathbb{Z}^{d}$ contain $0$ and all nearest neighbours of $0$. Let $\mathcal{A}$ be an event of subsets of $K$ such that every $A\in\mathcal{A}$ contains at least one nearest neighbour of $0$. Then
\begin{equation}
\nu_{K}\bigl(W_{1,K}\in\mathcal{A}\bigr)
= g_{K}\,\nu_{K}^{(0)}\bigl(\mathfrak{T}_{K}\in\mathcal{A}\bigr),
\qquad
 g_{K}:=\frac{|R_{K^{\circ}}|}{|R_{K}|}=G_{K}(0,0),
\end{equation}
where $G_{K}$ is the inverse of the finite-volume toppling matrix.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:47:12.027967+00:00","domain":"probability theory","id":"claim_03d8d6528c3f908c4ad57ff354cb04010b83974d306939d1ba1474d1b2a4c7ab","kind":"concept","schema_version":1,"statement":"[Proposition prop:6 of arXiv:2512.09219, 'Strong confluence of geodesics in Liouville quantum gravity'] Almost surely, for any fixed $\text{\usefont{U}{bboldx}{m}{n}z}\in \mathbb{C}$ and simultaneously for all $0<t<s$, the following hold.
      \begin{enumerate}
      \item There is a finite set of points $\mathcal{X}_{t,s}(\text{\usefont{U}{bboldx}{m}{n}z})\subseteq \partial \mathcal{B}_t^\bullet(\text{\usefont{U}{bboldx}{m}{n}z})$ such that every leftmost $D_h$-geodesic from $\text{\usefont{U}{bboldx}{m}{n}z}$ to a point on $\partial \mathcal{B}_s^\bullet(\text{\usefont{U}{bboldx}{m}{n}z})$ passes via some $x\in \mathcal{X}_{t,s}(\text{\usefont{U}{bboldx}{m}{n}z})$.
      \item  There is a unique $D_h$-geodesic from $\text{\usefont{U}{bboldx}{m}{n}z}$ to $x$ for each $x\in \mathcal{X}_{t,s}(\text{\usefont{U}{bboldx}{m}{n}z})$.
      \item For $x\in \mathcal{X}_{t,s}(\text{\usefont{U}{bboldx}{m}{n}z})$, let $I_x$ denote the set of $y\in \partial \mathcal{B}_s^\bullet(\text{\usefont{U}{bboldx}{m}{n}z})$ for which the leftmost $D_h$-geodesic from $0$ to $y$ passes via $x$. Each $I_x$ for $x\in \mathcal{X}_{t,s}(\text{\usefont{U}{bboldx}{m}{n}z})$ is a connected arc of the Jordan curve $\partial \mathcal{B}_s^\bullet(\text{\usefont{U}{bboldx}{m}{n}z})$ and $\partial \mathcal{B}_s^\bullet(\text{\usefont{U}{bboldx}{m}{n}z})$ is a union of the arcs $I_x$ for $x\in \mathcal{X}_{t,s}(\text{\usefont{U}{bboldx}{m}{n}z})$, with any two such arcs being disjoint.
      \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:57:28.726327+00:00","domain":"probability theory","id":"claim_03e263ec2c22289e3504cf200cf517cc389344384fc09857e1a2ad327b7fe938","kind":"lemma","schema_version":1,"statement":"[Lemma 30 (Continuous local sewing) of arXiv:2609.01190, 'Rough differential equations on manifolds via natural bundles'] Let $[U,V]\subseteq\Rsf$ be an interval and let $K:\Delta[U,V]\to\Rsf^m$ be a function. Assume that $|K(s,t)|=0$ for every $(s,t)\in\Delta[U,V]$ such that $\omega(s,t)=0$ and that there are constants $C,M\in (0,\infty)$ such that 
	\begin{equation}

		|K(s,t)-K(s,u)-K(u,t)| \leq C|K(s,u)|\omega(u,t)^\frac{1}{p} + M\omega(s,t)^\frac{3}{p}
	\end{equation}
holds for every $(s,t)\in [U,V]^3$ satisfying $s\leq u\leq t$ and $\omega(s,t)\leq 1$. Then there exist constants $\delta\in (0,1)$ and $L \in (0,\infty)$ such that 
	\[
		| K(s,t) | \leq L M\omega(s,t)^\frac{3}{p}
	\] 
holds for every $(s,t)\in\Delta[U,V]$ such that $\omega(s,t)<\delta$. The constant $\delta$ depends only on $p$ and $C$ while $L$ only on $p$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.068654+00:00","domain":"probability theory","id":"claim_03e63a8c8091f948903d8807aad8344b1e47ab4ccebdb1fcb44fd41f2469919f","kind":"lemma","schema_version":1,"statement":"[Lemma 9 (Regularity of $\hat\bS_\up{\alpha,\nu}$ on $\cU_-$) of arXiv:2606.27774, 'Variational Formulas for the Spectrum of\\ Block Wishart Matrices'] Fix integer $k \ge 1,$
let $\alpha \in (0,\infty)$, and $\nu\in\cuP_0(\sa{k}{\C})$.
The Stieltjes transform $\hat\bS_\up{\alpha,\nu}(\bU)$ defined by 
Eq.~\eqref{eq:free_ST_def}
is analytic on an open set in $\sfM_{k}(\C)$ containing $\cU_-$.
In particular, for all $\bU\in\cU_-,$
\begin{equation}

    \lim_{y\downarrow 0} \hat \bS_\up{\alpha,\nu}(\bU + i y\bI) = \hat \bS_\up{\alpha,\nu}(\bU).
\end{equation}
Consequently, if $\hat \bS_\up{\alpha,\nu}(\bU)\in\cD_0$ we have
\begin{equation}

    \bK_\up{\alpha,\nu}(\hat\bS_\up{\alpha,\nu}(\bU)) = \bU.
\end{equation}
Furthermore,
 the derivative of $\hat\bS_\up{\alpha,\nu}$ at $\bU\in\cU_-$ as an operator on 
 $\sa{k}{\C}$ is given by
\begin{align}
    \De \hat\bS_\up{\alpha,\nu}(\bU)[\bDelta] &= \frac1\alpha(\bI_k \otimes \tau)\left(r_k(\bU)(\bDelta \otimes \id_\cA)r_k(\bU)\right) , \quad\bDelta\in\sa{k}{\C}\, ,\\
    r_k(\bU)&:= \big(w_k -(\bU \otimes \id_\cA)\big)^{-1}\, .\nonumber
\end{align}
Further,  $\De \hat\bS_\up{\alpha,\nu}(\bU)[\cdot]$ is non-singular and
\begin{equation}
    \langle \bDelta, \cuD\hat \bS_\up{\alpha,\nu}(\bU)[\bDelta]\rangle_\fro >0\quad\quad\forall
    \quad \bDelta\neq\bzero.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.684497+00:00","domain":"probability theory","id":"claim_03e835bdfe07ebb8c00f94697a42f08410f8fa590dd7cbbc875d69912b5e5bdb","kind":"concept","schema_version":1,"statement":"[Corollary 2 (Modified Lyons--Sidorova conjecture) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $V$ be a finite-dimensional real normed space, let $\gamma:[0,T]\to V$ be a continuous tree-reduced bounded-variation path, and let $v=\gamma_T-\gamma_0$. Then
\[
R\bigl(\log S(\gamma)\bigr)=\infty
\]
if and only if there is a based prefix $\beta$ of $\overline\gamma=\gamma-\gamma_0$ such that
\begin{equation}
\overline\gamma
 \sim_{\mathrm{rep}}
\beta*\lambda_v*\overleftarrow{\beta}.
\end{equation}
When $v=0$, the tree-reduced path is constant. When $v\neq0$, $S(\beta)$ is the gate from the identity to the unique minimum-displacement axis of left multiplication by $S(\gamma)$ in the signature tree. This prefix is unique up to waiting intervals and weak increasing reparametrisation. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:32:23.713827+00:00","domain":"probability theory","id":"claim_03f12ea293015865721a4342454ed7048e494f966e6b92f3dfb073b271708f0a","kind":"concept","schema_version":1,"statement":"[Theorem mainthm of arXiv:2603.24499, 'A central limit theorem for connected components of random coverings of manifolds with nil'] Suppose $G$ is a $\mathscr{T}$-group with at least linear subgroup growth, 
then the leading asymptotics of the mean and variance of the random variables $\mathsf{K}_{G,n}$ are given by
\begin{eqnarray*}
\mathbb{E}\mathsf{K}_{G,n}&\sim & 
\frac{1}{\alpha_G-1}\times{\alpha_G}^{-\left(\frac{m_G-1}{\alpha_G}\right)}
\times(x\mathcal{K}_G)^{\frac{1}{\alpha_G}}
\times n^{\frac{\alpha_G-1}{\alpha_G}}\times(\ln n)^{\frac{m_G-1}{\alpha_G}}
\ , \\
{\rm Var}(\mathsf{K}_{G,n}) & \sim & 
\frac{1}{\alpha_G(\alpha_G-1)}\times{\alpha_G}^{-\left(\frac{m_G-1}{\alpha_G}\right)}
\times(x\mathcal{K}_G)^{\frac{1}{\alpha_G}}
\times n^{\frac{\alpha_G-1}{\alpha_G}}\times(\ln n)^{\frac{m_G-1}{\alpha_G}}
\ . 
\end{eqnarray*}
Moreover, the normalized random variables
\[
\frac{\mathsf{K}_{G,n}-\mathbb{E}\mathsf{K}_{G,n}}{\sqrt{{\rm Var}(\mathsf{K}_{G,n})}}
\]
converge in distribution and in the sense of moments to the standard Gaussian $\mathcal{N}(0,1)$. Namely, we have
\[
\lim\limits_{n\rightarrow\infty}\mathbb{E}\left[f\left(
\frac{\mathsf{K}_{G,n}-\mathbb{E}\mathsf{K}_{G,n}}{\sqrt{{\rm Var}(\mathsf{K}_{G,n})}}\right)\right]
=\frac{1}{\sqrt{2\pi}}\int\limits_{-\infty}^{\infty}f(s)\ e^{-\frac{s^2}{2}}\ {\rm d}s\ ,
\]
for all $f$'s that are bounded continuous functions, or polynomials. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.142147+00:00","domain":"probability theory","id":"claim_03f3d81d4196a920ea011b806b45ec765d5ec1fa28ef40fc27ca5478ee4d194d","kind":"theorem","schema_version":1,"statement":"[Theorem thm:absorbing of arXiv:2607.04620, 'The Exact Ville Identity\\ \large From the Absorbing Case to the General Law\\ with an App'] Let $(M_n)$ be a nonnegative supermartingale with $M_0=1$, let $b>1$, and suppose (ass:absorbing of the paper) holds and $O_b<\infty$. Then
