{"assumptions":[],"created_at":"2026-10-27T07:23:05.304760+00:00","domain":"probability theory","id":"claim_03fde8a2aeffacb0865f30416ef146f2c46da2e88c2f268e23824b967dd2b4a7","kind":"theorem","schema_version":1,"statement":"[Corollary 10 of arXiv:2608.21905, '\bf Ruin theory incorporating MIPP-type jumps'] i)
