{"assumptions":[],"created_at":"2026-10-27T19:48:47.286605+00:00","domain":"probability theory","id":"claim_05002bb4e2e13e5ef5826c6f9e8b99f7c4eea3266a5d9038048fec2d55cb3c60","kind":"concept","schema_version":1,"statement":"[Proposition prop:annealed cond of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $n\ge2$. Let $\bm{u}=(u_1,\ldots,u_{n})$,
		$\bm{q}=(q_1,\ldots,q_n)$ be strictly increasing
		in~$(0,1)$, and $\zeta\in\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})$.
		Define the \emph{prefix free energy}
		\begin{equation}
			\mathcal{P}^{(n)}(\bm{u};\bm{q})
			\;:=\;
			\inf_{\zeta'\,\in\,\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})}
			\mathcal{P}\mathrm{arisi}(\zeta'),
		\end{equation}
		and the \emph{$n$-step complexity functional at level $f$}
		\begin{equation}
			\mathcal{C}^{(n)}_f(\bm{u};\bm{q})
			\;:=\;
			u_n\,\bigl(\mathcal{P}^{(n)}(\bm{u};\bm{q})-f\bigr).
		\end{equation}

		We assume:
		\begin{enumerate}
			\item[\emph{(i)}]
			\emph{(Tail optimality)} The infimum $\mathcal{P}^{(n)}(\bm{u};\bm{q})$ is
			attained at $\zeta$.
			\item[\emph{(ii)}]
			\emph{(Stationarity)} $(\bm{u};\bm{q})$ is a critical point of
			$\mathcal{C}^{(n)}_f$.
		\end{enumerate}
		Let $\varepsilon\in(0,1)$, let
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)})\in\mathrm{SUSY}_{n-1}(\zeta,\varepsilon)\cap\mathrm{LawMatch}_{n-1}(\zeta,\varepsilon)$. Let
		$\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})$ be the number of critical points $\mathbf{m}$
		of $F_{\mathrm{TAP},\zeta}$ with
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)},\mathbf{m})\in\mathrm{SUSY}_n(\zeta,\varepsilon)$ and
		$\tfrac{1}{N}F_{\mathrm{TAP},\zeta}(\mathbf{m})\in(f-\varepsilon,f+\varepsilon)$. Set
		\begin{equation*}
			\mathrm{Skel}_{n-1}=\left(\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),\ldots,\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)}), F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)})\right).
		\end{equation*} Then
		\begin{multline}
			\lim_{\varepsilon\to0}\lim_{N\to\infty}
			\frac{1}{N}\log\mathbb{E}\Bigl[
			\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})
			\;\Big|\;
			\mathrm{Skel}_{n-1}=(0,N\mathcal{P}\mathrm{arisi}(\zeta),\ldots,0,N\mathcal{P}\mathrm{arisi}(\zeta))
			\Bigr]
			=
			\mathcal{C}_f^{(n)}(\bm{u};\bm{q})
			\\=
			\zeta([0,q_n))\,(\mathcal{P}\mathrm{arisi}(\zeta)-f).
		\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:53.448176+00:00","domain":"probability theory","id":"claim_050763d87704ef01b00910151a25cdd19e6ae8298587845584414d57658077d5","kind":"concept","schema_version":1,"statement":"[Conjecture 1 (Matrix Spencer) of arXiv:2606.16005, '\bfseries An Algebraic Matrix Spencer Theorem'] There exists a universal constant $C$, such that for any choice of $n$ symmetric matrices $(A_{i})_{i=1}^n \in \mathbb R^{n\times n}$ satisfying $\|A_i\|_{\op}\le 1$ there is a coloring $x\in\{\pm1\}^{n}$, such that
