\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:44:39.752198+00:00","domain":"probability theory","id":"claim_057f1966d56e7dc0e0cd1ec01ec2a218fc66e5708b29cbbbcfd7e73b2ce43041","kind":"concept","schema_version":1,"statement":"[Lemma 34 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Under the assumptions of Theorem \ref{distribution of outliers}, for each $1\le i\le r$ and $1\le \mu \le s$, we have 
\begin{align}
\wt\lambda_{\alpha(i)}-\theta_i^a&=-\frac{1}{\sigma_i^am'_{2c}(\theta_i^a)}\pa{\frac{d_i^a}{d_i^a+1}}^2\cdot\theta_i^a\vv_i^*\pa{G(\theta_i^a)-\Pi(\theta_i^a)}\vv_i+\OO_{\prec}(n^{-1}),\\
\wt\lambda_{\beta(\mu)}-\theta_\mu^b&=-\frac{1}{\sigma_\mu^bm'_{1c}(\theta_\mu^b)}\pbb{\frac{d_\mu^b}{d_\mu^b+1}}^2\cdot\theta_\mu^b \uu_\mu^*\pa{G(\theta_\mu^b)-\Pi(\theta_\mu^b)}\uu_\mu+\OO_{\prec}(n^{-1}).
\end{align}
where $\vv_i:=((\vv_i^a)^T, 0)^T\in\RR^{p+n}$ and $\uu_\mu:= (0^T, (\vv_\mu^b)^T)^T\in\RR^{p+n}$ are the canonical extensions of the population eigenvectors $\vv_i^a$ and $\vv_\mu^b$ to $\RR^{p+n}$, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:32:19.968910+00:00","domain":"probability theory","id":"claim_058149ae6c9b1319b28f11e471babf5da65d0159ad62af231178b3514fe2eceb","kind":"concept","schema_version":1,"statement":"[Theorem 3 ($L$-fold, coupled spherical integration for $\mathrm{rank}(D_l D_l^\dagger)=M(N)>1$) of arXiv:2608.03273, 'On the Asymptotic of Coupled Spherical Integrals: An Operator-Valued Extension of the Free'] Let $L=O(1)$, $M(N)=O\left(N^{1/2-\epsilon}\right)$ for any $\epsilon>0$, and $D_l=O_l\Sigma_l V^\dagger$ be the singular-value decomposition of $D_l$ for all $l$, i.e. $D_l$ has $M(N)$ non-zero singular values $\sqrt{\theta_{l,i}}$, and the right unitary/orthogonal matrix $V^\dagger$ of the SVD of $D_l$ is identical for all $l$.
Let $Z_N$ and $Z$ be defined as in Theorem~\ref{thm:pL_rank1_integral} and all $\theta_{l,i}$ are small enough such that
\begin{align}
    -P_i=-\mathrm{diag}\left\{\frac{2\theta_{1,i}}{\beta},\ldots,\frac{2\theta_{L,i}}{\beta}\right\}
    \in \left\{\left.G^{\mathcal{D}_L}_Z(S) \right| S\in\mathcal S^Z_{\{-\}^L}\right\},
\end{align}
and $\hat \mu_D^N$, the joint empirical measure of all $\theta_{l,i}$, converges to some $\mu_D$ with analytic density
\begin{align}
\mu_D
=
\lim_{N\uparrow\infty}
\hat \mu_D^N
=
\lim_{N\uparrow\infty}
\frac{1}{M(N)}
\sum_{i=1}^{M(N)}
        \delta_{\{\theta_{l,i}\}},
\end{align}
where $\delta_{\{\theta_{l,i}\}}$ denotes the Dirac measure centered on the point $(\theta_{1,i}, \ldots, \theta_{L,i})$. 
Then, the $L$-fold coupled HCIZ integral of rank $M(N)>1$ factors into $M(N)$ coupled rank-one integrals as
\begin{align}
    \lim_{N\uparrow\infty}
    \frac{1}{N M(N)}\log I_N^{(\beta)}(\{D_l\},\{E_{lk}\}) 
    &=
    \lim_{N\uparrow\infty}
    \frac{1}{M(N)}
    \sum_{i=1}^{M(N)}
    \frac{\beta}{2}
    \int_{0}^1
        \mathrm{tr}\left(
            R_Z^{\mathcal D_L}(P_iw)P_i
        \right)
        \mathrm d w
        \\
    &=
    \int
        I^{(\beta)}_Z(\{\theta_l\})
        \mathrm d \mu_D(\{\theta_l\}).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.473067+00:00","domain":"probability theory","id":"claim_0589f642e68055171f390256f812f9491311b758df566fbf4f6fdb27bdc23443","kind":"concept","schema_version":1,"statement":"[Thm Kolmogorov of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Let $(X_t)_{t\in[0, T]}$ be a stochastic process on $\mathbb{R}^n$ for some $T > 0$. Suppose there exist constants $\alpha, \beta, \gamma, K, C > 0$ such that:
    \begin{itemize}
        \item $\mathbb{E}[|X_t - X_s|^\alpha] \leq K|t-s|^{1 + \beta}$ for all $t,s \in [0,T]$.
        \item $\mathbb{E}[\sup_{t \in [0,T] \cap D} |X_t|] \leq C$, where $D$ denotes the dyadic numbers $\frac{k}{2^n}$.
        \item $\gamma < \beta / \alpha$.
    \end{itemize}

    Then there is a modification $\tilde{X_t}$ of $X_t$ with almost surely $\gamma$-H\"{o}lder continuous sample paths. Additionally, there is a function $A: [0,\infty) \to [0,1]$ which depends only on $T,\alpha,\beta,\gamma,K,C$ (not on $X$) and satisfies: \begin{itemize}
        \item $\lim_{M \to \infty} A(M) = 0$.
        \item $\mathbb{P}(\|\tilde{X}\|_\gamma > M) \leq A(M)$, where $$\|\tilde{X}\|_\gamma \coloneqq |\tilde{X}_0| + \sup_{0 \leq s < t \leq T} \frac{|\tilde{X}_t - \tilde{X}_s|}{t-s} \,.$$
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.468223+00:00","domain":"probability theory","id":"claim_059162003c3a5b547b2f71ee380a9aee93787e14b41e4097e3ffed8f2a44dea8","kind":"lemma","schema_version":1,"statement":"[Lemma lem:proplo of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Under (assump:overdp of the paper), $\sigma_o$ is the reduced state of $\sigma$ on $\mathcal{F}(\mathcal{L}_S)$. Moreover, the fixed-point algebra $\mathcal{F}(\mathcal{L}_O)$ of $\mathcal{L}_O$ defined on $\mathcal{F}(\mathcal{L}_S)$ is characterized by 
