{"assumptions":[],"created_at":"2026-10-27T23:13:49.973331+00:00","domain":"probability theory","id":"claim_082dfba99550878f863807293881c0bfc0b43b3e452e2e85b99430814ff18b52","kind":"theorem","schema_version":1,"statement":"[Corollary coro:1 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Fix $T\in(0,1]$, and two families of functions $\theta=(\theta_\mu)_{\mu\in(0,T]}$ and $\tilde{R}=(\tilde{R}_\mu)_{\mu\in(0,T]}$ with $\theta_\mu,\tilde{R}_\mu\in C^\infty([0,T],\R^{{\mcb{n}}})$, and which for some universal constant $C_{\theta,\tilde{R}}>1$ satisfy, for every $\mu \in (0,T]$, 
\begin{equs}    {\| \theta_\mu 
    \|}_{L^\infty_{0;T}}\vee
 \mu^{-\delta/2}{\| \tilde{R}_\mu 
    \|}_{L^\infty_{0;T}}
\leqslant C_{\theta,\tilde{R}}\,.
\end{equs} 

Writing 
\begin{equs}
    \tilde{F}_{\eps,\mu}[]\eqdef K_\mu F_{\eps,\mu}[]\,,\quad \Tilde{I}_{\eps,\mu}[]\eqdef K_\mu I_{\eps,\mu}[]\,,\quad {and}\quad u_\mu \eqdef \theta_\mu+{\tt u}\,,
\end{equs}
we clearly have $K_\mu\theta_\mu+{\tt u}=K_\mu\theta_\mu+K_\mu\mathcal{R}_\mu{\tt u}=K_\mu u_\mu$ (since ${\tt u}$ is constant in time, so that $\mathcal{R}_\mu{\tt u}={\tt u}$) along with the estimate
\begin{equs}
    {\| u_\mu 
    \|}_{L^\infty_{0;T}}\leqslant C_{\theta,\tilde R}+|{\tt u}|\,.
\end{equs}

Then, there exists universal constants $K,r\geqslant1$ such that setting $C_F\eqdef K{\talloblong \omega\xi \talloblong}^r_{4}$ we have, for every $\eta>0$, 
    \begin{equs}
        {\|  \tilde{F}_{\eps,\mu}[K_\mu\theta_\mu] 
    \|}_{L^\infty_{0;T}}&\leqslant C_F\mathcal{G}_{\tt u}(C_{\theta,\tilde{R}})\mu^{-1+H-\eta}\,,\\
         \norm{ \mathrm{D}\tilde{F}_{\eps,\mu}[K_\mu\theta_\mu,\mathcal{R}_\mu\dot G_\mu \tilde{R}_{\mu}]}_{L_{0;T}^\infty}&\leqslant C_F\mathcal{G}_{\tt u}(C_{\theta,\tilde{R}})\mu^{-1+H-\eta}\,,\\
          {\| \Tilde{I}_{\eps,\mu}[K_\mu\theta_\mu] 
    \|}_{L_{0;T}^\infty}&\leqslant C_F\mathcal{G}_{\tt u}(C_{\theta,\tilde{R}})\mu^{-1+\delta-\eta}\,.
    \end{equs}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:04:39.780902+00:00","domain":"probability theory","id":"claim_082f6110ce17c308a0c02ea3a9219d05c79d675de6a778ee7195724b70f6a2e0","kind":"theorem","schema_version":1,"statement":"[Corollary cor:tailrl-binary-recovery of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] Suppose $r_i\in\{0,1\}$ and let
$M:=\sum_{i=1}^N\mathbf 1\{r_i=1\}$. If $M>0$, then every successful
rollout receives weight $1/M$ and every unsuccessful rollout receives weight
zero. Hence the uncentered TailRL{} estimator reduces to
\begin{equation}
g_{\mathrm{TailRL}}^{(N)}(x)
=
\frac{1}{M}
\sum_{i:r_i=1}S_i,

\end{equation}
which is the MaxRL estimator. After mean-centering, successful rollouts have
weight $1/M-1/N$ and unsuccessful rollouts have weight $-1/N$. If $M=0$,
all uncentered and centered weights are zero.","status":"unverified"}

