{"assumptions":[],"created_at":"2026-10-27T19:55:37.870502+00:00","domain":"probability theory","id":"claim_08e14f0b7943bf79d0d8c83da97fd29fdcea9979371b3d07d1a03f8bd5778c4b","kind":"lemma","schema_version":1,"statement":"[Lemma lem:cut_edge_prob of arXiv:2605.06511, 'Logarithmic Mixing of Random Walks on Dynamical Random Cluster Models'] Let $n \in \mathbb{N}$ be sufficiently large and $G = (V, E)$ a $d$-regular graph on $n$ vertices. For all $\mu > 0$, $t \geq 0$, $\Delta > 0$ such that $\mu \Delta > 2 \log 2$, $e = \{u, u'\} \in E$ such that $u$ does not lie on a cycle of length less than $r$ and $B_R(u)$ has at most one cycle, and $(\eta, v) \in \{0, 1\}^E \times V$,
		\begin{align*}
			&\ \mathbb{P}\left[\xi_{u, e}^{\mathrm{cut}} (t, \tau_e(t, t + \Delta))\mid \mathsf{C}_e\left(t, t + \Delta\right), (\eta_t, X_t) = (\eta, v)\right] \\
			\geq&\ \mathbb{P}\left[S_{[t, t + \Delta]} \left(R, K\right) \mid \left(\eta_t, X_t\right) = \left(\eta, v\right)\right] \left(1 - (2K + 1) e^{-{\mu \Delta}/{2}} - O\left((\log n)^{-3}\right)\right).
		\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:35:04.214836+00:00","domain":"probability theory","id":"claim_08e228e0d3fc08ef60bbc48c3bf1cf80f4094c4202171eed8b0bc9ab75dce2e2","kind":"lemma","schema_version":1,"statement":"[Lem 21 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] The Shannon entropy is given by
\begin{align}
\mathcal{S}^{(1,n)} = 2^{-n}\mathcal{S}^{(n)}  + n\log(2), 
\end{align}
for every $n\geq 2$. Hence, $-2^nn\log(2) \leq \mathcal{S}^{(n)} < 0$ for every $n\geq 2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.405333+00:00","domain":"probability theory","id":"claim_08ecf3ca336e63eb559287a229890348dedab4624b43751fc70097aa93707975","kind":"concept","schema_version":1,"statement":"[Theorem 4 of arXiv:2604.06516, 'From stochastic individual-based models to free-boundary Hamilton-Jacobi equations'] The set $\Omega_a$ is an open set. The function $u_a$ belongs to $C(\adh(\Omega_a))$ and it is the unique locally Lipschitz-continuous and bounded above viscosity solution of the following Hamilton-Jacobi equation  
 \beq

 \begin{cases}
 \p_t u=p(x) H(\p_x u)+R(x),& (t,x)\in \Omega_a\\
 u(t,x)=a,& (t,x)\in \p  \Omega_a , \, t>0,\\
 u(0,x)=\beta_0(x), &\text{for all $x$ s.t $\beta_0(x)>a$}.
 \end{cases}
 \eeq (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.361801+00:00","domain":"probability theory","id":"claim_08efa90c901256c5cca43556b4a3f284ab908c9581a97d95cb67c0bce83607e5","kind":"theorem","schema_version":1,"statement":"[Proposition 56 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1}--\eqref{H2}. Then:
\begin{enumerate}[label=(\arabic*), ref=\arabic*]
    \item Uniformly for all $1\le i\le m\le M_0$, $1\le r\le K_\theta$, and vertices $v^j_l$ with $h_r< j\le h_{r-1}$ and $1\le l\le q_n(j)-m$, 
    \begin{align}
        \p_n\big(\tau_i(v^j_l)<\infty\,\big|\,\widetilde{B}_{r}\big)
        =\frac{1}{m}\left\{1- \prod_{h=0}^{j-h_r-1}\Bigg[1-\frac{m\sigma^2_n(j-h)}{q_n(j-h)}\big(1+o_n(1)\big)\Bigg]\right\}.

    \end{align}
    \item Uniformly for all $1\le i\le m\le M_0$ and vertices $v^j_l,\,v^{j'}_{l'}$ with $h_r< j\le j' \le h_{r-1}$, $1\le l\le q_n(j)-m$, and $1\le l'\le q_n(j')-m$,  
    \begin{equation} 
    \begin{aligned} 
        &\p_n\big( \tau_i(v^j_l) < \infty \,\big|\, \tau_i(v^{j'}_{l'})<\infty,\,\widetilde{B}_{r} \big) \\
        \le \,& \frac{1}{m}\left\{1-\big(1+o_n(1)\big)\prod_{h=0}^{j-h_r-1}\Bigg[1-\frac{(m+1)\sigma^2_n(j-h)}{q_n(j-h)}\big(1+o_n(1)\big)\Bigg]\right\}. 
    \end{aligned} 
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:59:58.430648+00:00","domain":"probability theory","id":"claim_08f07f196cc6b9486d6e6a9a94eac52953e9f9fbf45440868b4e886d64f85cac","kind":"theorem","schema_version":1,"statement":"[Theorem thm:FG-common-noise-criterion of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] The following statements are equivalent:
\begin{enumerate}
\item[(i)] The common-noise input condition (equation eq:common-noise.input.condition of the paper) holds.
\item[(ii)] For every \(t\in[T]\), there exist orthogonal matrices \(\mathbf Q_t^1,\ldots,\mathbf Q_t^K\in\mathscr O(d)\) such that the matrix
\begin{equation}

(\mathbf P_t^\star)^{k,\ell}=\mathbf Q_t^k(\mathbf Q_t^\ell)^\intercal,
\qquad k,\ell\in[K],
\end{equation}
minimizes \(\Phi_t\) over \(\mathscr{P}_+(K,d)\).
\item[(iii)] There exists an unrestricted barycenter \(\overline{\mathbb{X}}\in\mathcal{FG}_K(T,d)\) constructed in Theorem~(thm:gaussian.multicausal.optimizer of the paper) which is \(\mathcal{AW}_2\)-equivalent to an element of \(\mathcal{FG}(T,d)\).
\item[(iv)] The unrestricted adapted barycenter problem admits a barycenter representative in \(\mathcal{FG}(T,d)\).
\end{enumerate}
When these equivalent conditions hold, the matrix \(\mathbf P^\star=\diag(\mathbf P_1^\star,\ldots,\mathbf P_T^\star)\in\mathscr{P}_+(K,T,d)\) minimizes \(\Phi\), and
$
\mathbb{G}^{
\accentset{\overline{\hphantom{a}}}{a}
,
\accentset{\overline{\hphantom{L}}}{L}
}\in \mathcal{FG}(T,d)
$
is an $\mathrm{FP}_2$-barycenter, where $
\accentset{\overline{\hphantom{L}}}{L}
\in\mathscr{L}(T,d)$ is defined by
\[

\accentset{\overline{\hphantom{L}}}{L}
_{\cdot,t}=\sum_{k=1}^K\lambda_kL_{\cdot,t}^k\mathbf Q_t^k,
\quad t\in[T].
\]
Moreover, if $
\accentset{\overline{\hphantom{\mathbb{X}}}}{\mathbb{X}}
:=\mathbb{G}_K^{
\accentset{\overline{\hphantom{a}}}{a}
,
\accentset{\overline{\hphantom{\mathbf L}}}{\mathbf L}
}$ denotes the barycenter representative built from the optimizers $\mathbf P_t^\star$ in Theorem~(thm:gaussian.multicausal.optimizer of the paper), then
\begin{equation}

\mathcal{AW}_2(
\accentset{\overline{\hphantom{\mathbb{X}}}}{\mathbb{X}}
,\mathbb{G}^{
\accentset{\overline{\hphantom{a}}}{a}
,
\accentset{\overline{\hphantom{L}}}{L}
})=0.
