{"assumptions":[],"created_at":"2026-10-27T13:52:23.576113+00:00","domain":"probability theory","id":"claim_0950ad8d85c99b5cae09fe117090c13899d5b02dfb4918eeb43384415ea70bb0","kind":"lemma","schema_version":1,"statement":"[Lemma L:ML of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] The Mittag--Leffler function $E_{a,b}(\cdot)$ defined in~(equation E:ML of the paper)
  satisfies the following properties:

  \begin{enumerate}[\rm (i)]

    \item For all $a>0$ and $b\in\mathbb{R}$, $E_{a,b}(z)$ is an analytic function on
          $\mathbb{C}$. Moreover, if $b>0$, then $E_{a,b} (0) =
            \Gamma(b)^{-1} > 0$.

    \item Suppose that $a \in (0,2]$ and $b \in \mathbb{R}$. Then, by restricting $x\in \mathbb{R}$, $E_{a, b} (- x)$
          admits the following asymptotic expansions as $x \to \infty$:
          \begin{subequations}
            \begin{empheq}[left={E_{a, b}(-x) = \empheqlbrace}]{align}
              & \frac{1}{\Gamma(b - a) x} + O\left(x^{-2}\right),                                                                     &  & a < 2, a \ne b,        \\
              & \frac{1}{\Gamma(-a) x^2} + O\left(x^{-3}\right),                                                                      &  & 1 \ne a = b \in (0,2), \\
              & \exp\left( - x \right),                                                                                               &  & a = b =  1,            \\
              & \frac{\cos \left(\sqrt{x} + (1 - b) \pi /2\right)}{x^{(b - 1)/2}} + \frac{1}{\Gamma(b - 2) x} + O\left(x^{-2}\right), &  & a = 2\ne b,            \\
              & \frac{\sin \left(\sqrt{x}\right)}{\sqrt{x}},                                                                          &  & a = b =  2.           
            \end{empheq}
          \end{subequations}

    \item For some finite constant $C>0$, the following uniform upper bounds
          hold for all $x\ge 0$:
          \begin{subequations} 
            \begin{empheq}[left={\left|E_{a, b}(-x)\right| \le \empheqlbrace}]{align}
              & \dfrac{C}{1 + x^{(b-1)/2}} &  & a = 2, \; b \in [2,3),     \\
              & \dfrac{C}{1+x},            &  & a \in (0,2), \: b \in \mathbb{R}. 
            \end{empheq}
          \end{subequations}

    \item For any $a>0$, $b$, $\lambda \in \mathbb{R}$, and $m=1,2,3,\cdots$, it holds
          that
          \begin{align}
            \frac{\ensuremath{\mathrm{d} }^m}{\ensuremath{\mathrm{d} } x^m} \left(x^{b - 1} E_{a,b} \left(\lambda x^a\right)\right)
            = x^{b-1-m} E_{a, b-m}(\lambda x^a).
          \end{align}

  \end{enumerate}","status":"unverified"}

