{"assumptions":[],"created_at":"2026-10-26T20:55:18.057299+00:00","domain":"probability theory","id":"claim_0aaf348e51dbf03aa9269de4eafe5c6341046fd85cfd4c3d4d3d6602ecf27191","kind":"definition","schema_version":1,"statement":"[Definition 33 (Viscosity solutions) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $\bar\xi$ be a regularization of $\xi$, and let $\H$ be defined by~\eqref{e.def_H_spin_glass}. Consider the Hamilton--Jacobi equation
\begin{align}
    \partial_t f- \H(\partial_q f)=0,\quad &\text{on $\R_+\times \mcl Q^\D_2$}.
\end{align}
\begin{enumerate}
    \item A continuous function $f:\R_+\times \mcl Q_2^\D\to \R$ is a \textbf{viscosity subsolution} of~\eqref{e.hj_H} if, for every $(t,q) \in (0,\infty)\times \mcl Q_2^\D$ and every smooth $\phi:(0,\infty)\times \mcl Q_2^\D\to\R$ such that $f-\phi$ has a local maximum at $(t,q)$, we have
    \begin{align*}
        \left(\partial_t \phi - \H(\partial_q\phi)\right)(t,q)\leq 0.
    \end{align*}
    \item A continuous function $f:\R_+\times \mcl Q_2^\D\to \R$ is a \textbf{viscosity supersolution} of~\eqref{e.hj_H} if, for every $(t,q) \in (0,\infty)\times \mcl Q_2^\D$ and every smooth $\phi:(0,\infty)\times \mcl Q_2^\D\to\R$ such that $f-\phi$ has a local minimum at $(t,q)$, we have
    \begin{align*}
        \left(\partial_t \phi - \H(\partial_q\phi)\right)(t,q)\geq 0.
    \end{align*}
    \item A continuous function $f:\R_+\times \mcl Q_2^\D\to \R$ is a \textbf{viscosity solution} of~\eqref{e.hj_H} if it is both a viscosity subsolution and a viscosity supersolution.
\end{enumerate}
Finally, a continuous function $f:\R_+\times \mcl Q^\D_2\to\R$ is called a \textbf{viscosity solution} of~\eqref{e.hj} if it is a viscosity solution of~\eqref{e.hj_H} for some regularization $\bar\xi$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:15:36.169629+00:00","domain":"probability theory","id":"claim_0ab16c90a2bed8bc97c3144c8f302cffcae0e7e2872d0bf4cb486ff4633f4535","kind":"concept","schema_version":1,"statement":"[Theorem 6 of arXiv:2609.01774, 'Hypoellipticity on time-periodic space-times'] Let $M$ be the interior of an asymptotically Euclidean manifold $X$, $\mathcal{M}=\Sb^1\times M$, $s\in\Nb$, 
$L$ as in \eqref{inhomog}, 
and $P\in\Psi^{r,\rho}_\cls(X)$ be elliptic, positive and self-adjoint, with order components $r,\rho>0$. Moreover,
let $\gamma_0=\frac{d}{\min\{r,\rho\}}$ and fix $\beta>\max(s(\gamma_0-1)+1,0)$.

Then: 

    \begin{enumerate}
        \item For almost every $\alpha \in \Rb \backslash (-1,1)$, there exists $C_{\alpha}>0$ such that 
        \begin{equation}
            \nm{u-\Pi_0 u}_{L^2_{t,x}(\M)} \leq C_{\alpha} \nm{L u}_{H^{\beta}_t L^2_x(\M)},
        \end{equation}
        where $\Pi_{0}$ is the projection onto $\ker P \cap \ker D_t$.
        \item For all $\ep>0$, there exists a set $\mathcal{B}_{\ep}$ with $\mu(\mathcal{B}_{\ep})<\ep$ and $C_{\ep}>0$ such that for all $\alpha \in ([-2,-1] \cup [1,2] )\backslash \mathcal{B}_{\ep}$ we have the uniform upper bound
        \begin{equation}
            \nm{u- \Pi_{0} u}_{L^2(\M)} \leq C_{\ep} \nm{L u}_{H^{\beta}_t L^2_x(\M)},
        \end{equation}
        where $\Pi_{0}$ is the projection onto $\ker P \cap \ker D_t$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

