{"assumptions":[],"created_at":"2026-10-26T19:33:46.771169+00:00","domain":"probability theory","id":"claim_0dfb8a4f3f3f31fb29a099e86dc868479184a110ee3f32c8c678216e1fbc3c4a","kind":"lemma","schema_version":1,"statement":"[Lemma 46 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definitions \ref{Def.ParametersBulk}, \ref{Def.ScalingBulk} and \ref{Def.ContoursBulk}, and that $c \neq 1$. Let $M^N$ be the point process on $\mathbb{R}^2$, formed by $\{(t_j, X_i^{j,N}): i \geq 1, j \in \llbracket 1, m\rrbracket \}$. Then for all large $N$ (depending on $q$ and $c$), $M^N$ is a Pfaffian point process with reference measure $\mu_{\mathcal{T},\nu(N)}$ and correlation kernel $K^N$ that are defined as follows. 

The measure $\mu_{\mathcal{T},\nu(N)}$ is as in Definition \ref{Def.ScaledLatticeMeasures} for $\nu(N) = (\nu_{t_1}(N), \dots, \nu_{t_m}(N))$, where $\nu_{t}(N)$ is $\sigma_1^{-1} N^{-1/3}$ times the counting measure on $\Lambda_{t}(N)$. 

The correlation kernel $K^N: (\mathcal{T} \times \mathbb{R}) \times (\mathcal{T} \times \mathbb{R}) \rightarrow\operatorname{Mat}_2(\mathbb{C})$ takes the form
\begin{equation}
\begin{split}
&K^N(s,x; t,y) = \begin{bmatrix}
    K^N_{11}(s,x;t,y) & K^N_{12}(s,x;t,y)\\
    K^N_{21}(s,x;t,y) & K^N_{22}(s,x;t,y) 
\end{bmatrix} \\
&= \begin{bmatrix}
    I^N_{11}(s,x;t,y) & I^N_{12}(s,x;t,y) + R^N_{12}(s,x;t,y) \\
    -I^N_{12}(t,y;s,x) - R^N_{12}(t,y;s,x) & I^N_{22}(s,x;t,y) + R^N_{22}(s,x;t,y) 
\end{bmatrix} ,
\end{split}
\end{equation}
where $I^N(s,x;t,y), R^N(s,x;t,y)$ are defined as follows. The kernels $I^N_{ij}$ are given by
\begin{equation}
\begin{split}
&I^N_{11}(s,x;t,y) = \frac{1}{(2\pi \im)^{2}}\oint_{\gamma_N^+(1)} dz \oint_{\gamma_N^+(1)} dw F_{11}^N(z,w) H_{11}^N(z,w) \mbox{, where }\\
& F^N_{11}(z,w) = e^{NS_1(z) + NS_1(w)} \cdot e^{T_s G_1(z) + T_t G_1(w)} \cdot e^{- \sigma_1 x N^{1/3} \log (z) - \sigma_1 y N^{1/3} \log(w)  }, \\
&H^N_{11}(z,w) = 4\sigma_1^2 N^{2/3} \cdot  \frac{z-w}{(z^{2}-1)(w^{2}-1)(zw-1)} \cdot ( 1 - c/z) (1 - c/w);
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&I^N_{12}(s,x;t,y) = \frac{1}{(2\pi \im)^{2}}\oint_{\gamma_N^+(1)} dz \oint_{\gamma_N^-(-1)} dw F_{12}^N(z,w) H_{12}^N(z,w) \mbox{, where }\\
& F^N_{12}(z,w) = e^{NS_1(z) - NS_1(w)} \cdot e^{T_s G_1(z) - T_t G_1(w)} \cdot e^{- \sigma_1 x N^{1/3} \log (z) + \sigma_1 y N^{1/3} \log(w)  }, \\
&H^N_{12}(z,w) =  \sigma_1 N^{1/3} \cdot \frac{zw - 1}{z (z-w)(z^2 - 1)} \cdot \frac{z - c}{w - c};
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&I^N_{22}(s,x;t,y) = \frac{1}{(2\pi \im)^{2}}\oint_{\gamma_N^-(-1)} dz \oint_{\gamma_N^-(-1)} dw F_{22}^N(z,w) H_{22}^N(z,w) \mbox{, where }\\
& F^N_{22}(z,w) = e^{-NS_1(z) - NS_1(w)} \cdot e^{-T_s G_1(z) - T_t G_1(w)} \cdot e^{ \sigma_1 x N^{1/3} \log (z) + \sigma_1 y N^{1/3} \log(w)  }, \\
&H^N_{22}(z,w) =  \frac{1}{4} \cdot \frac{z-w}{zw - 1} \cdot \frac{1}{(z- c)(w - c)}.
\end{split}
\end{equation}
The kernels $R^N_{ij}$ are given by
\begin{equation}
\begin{split}
&R^N_{12}(s,x;t,y) = \frac{-{\bf 1}\{s < t \} \cdot \sigma_1 N^{1/3} }{2 \pi \im} \oint_{\gamma_{N}^+(1)}dz e^{(T_s - T_t) G_1(z)} \cdot e^{ (\sigma_1 y N^{1/3}  - \sigma_1 x N^{1/3} - 1) \log (z)} \\
& +  \frac{{\bf 1}\{c > 1\}\cdot \sigma_1 N^{1/3}}{2\pi \im} \oint_{\gamma_N^+(1)}dz \frac{zc - 1}{z(z^2 - 1)} \cdot F_{12}^N(z,c);
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&R^N_{22}(s,x;t,y) = \frac{{\bf 1}\{c > 1\}}{2\pi \im} \oint_{\gamma^-_N(-1)} dz \frac{F_{22}^N(z,c)}{4(c z - 1)} - \frac{{\bf 1}\{c > 1\}}{2\pi \im} \oint_{\gamma^-_N(-1)} dw \frac{F_{22}^N(c,w)}{4(c w - 1)} \\
& + \frac{1}{2\pi \im}\oint_{\gamma^-_N(-1)} dw  \frac{(1-w^2)}{4(1-c w)(w-c)} \cdot e^{ ( \sigma_1 y N^{1/3} - \sigma_1 x N^{1/3} - 1) \log (w) - T_s G_1(w^{-1}) - T_t G_1(w)}.
\end{split}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:06:39.320590+00:00","domain":"probability theory","id":"claim_0dfcf641c6f8de503b245d2de8c2ea0062b75d602f1612638511e4bc45cfb4f7","kind":"concept","schema_version":1,"statement":"[Theorem t:caccioppoli of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Let $Q=I \times B$ be a parabolic cylinder with side length $\varrho\in (0,1/2]$. Fix $r\in (1,\infty)$ and $\eta\in (0,1)$.
Suppose that (equation eq:ass_caccioppoli1 of the paper)-(equation eq:ass_caccioppoli4 of the paper) hold. Then there is a constant $C>0$ depending only on $d,M,\varrho,\nu,\nu_0,r$ and $\eta$ for which the following estimates hold for all local solutions $(v,\pi,(\widetilde{\pi}_n)_n)$ to the stochastic Stokes system (equation eq:turbulent_stokes_caccioppoli of the paper) (see Definition (def:local_solutions_NSE of the paper)):
\begin{align*}
\Big({\mathbf E}\sup_{\eta I}\Big\|v- \fint_{\eta B}v\Big\|_{L^2(\eta B)}^r\Big)^{1/r}+
\big({\mathbf E}\|\nabla v\|_{L^2(\eta Q)}^r\big)^{1/r}&\leq C\mathcal{E}_{  Q}^{\#}, \\
\big({\mathbf E}\| \pi\|_{L^{2}(\eta Q)}^r\big)^{1/r}&\leq C\mathcal{E}_{ Q}^{\#},\\
\big({\mathbf E}\|( \nabla\widetilde{\pi}_n)_n\|_{L^{2}( \eta Q;\ell^2)}^r\big)^{1/r}&\leq C\mathcal{E}_{ Q}^{\#},
\end{align*} 
where $\mathcal{E}^{\#}_{ Q}$ is the sharp energy of the local solution $(v,\pi,(\widetilde{\pi}_n)_n)$ in $ Q$, i.e., 
\begin{align}
\nonumber
\mathcal{E}_{ Q}^{\#}
=\Big( \max\Big\{
{\mathbf E} \Big\|v-\fint_B v \Big\|_{L^2( Q)}^r
,\,

{\mathbf E} \|\pi\|_{L^2(I;H^{-1}( B))}^r,\, 
{\mathbf E} \|( \widetilde{\pi}_{n} )_{n}\|_{L^{2}( Q;\ell^2)}^r,&\\
{\mathbf E} \|F \|_{L^2( Q)}^r,\,
{\mathbf E} \|(G_n)_n \|_{L^2( Q;\ell^2)}^r & \Big\}\Big)^{1/r}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

