{"assumptions":[],"created_at":"2026-10-27T10:52:57.737584+00:00","domain":"probability theory","id":"claim_0ef9267e2c8e636997b986e05d1eb167f87e6a1f5f671b70dae05793375a047e","kind":"definition","schema_version":1,"statement":"[Definition 35 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] For $\zeta \in [0, \zeta_0)$ we write
	\begin{align*}
		E^\zeta_\vartheta = \{(Z, \boldsymbol{\psi}, \mcV) \in \cM_{\mathrm{adm}}(\tilde{\mfT}^\zeta) \times (C^{\vartheta - N\zeta})^3 \times \mathcal{D}^{3/2 + 2 \kappa - N\zeta, - \kappa - N\zeta} ({\tilde \mfT^\zeta_{\ge - 2\kappa}}) \},
	\end{align*}
	which we equip with the metric
	\begin{align*}
		d_{E^\zeta_\vartheta}&((Z, \boldsymbol{\psi}, \mcV), (\bar{Z}, \bar{\boldsymbol{\psi}}, \bar{\mcV})) \\
		&= \| Z; \bar{Z} \|^{(\zeta)}_{2+2\kappa; \mathcal{O}_T} + \| \boldsymbol{\psi} - \bar{\boldsymbol{\psi}} \|_{(C^{\vartheta - N\zeta})^3} + \| \mcV; \bar{\mcV} \|^{(\zeta)}_{3/2+2\kappa - N\zeta, -\kappa - N\zeta; \mathcal{O}_T}\;,
	\end{align*}
	with the dependence of this metric on the fixed terminal time $T$ suppressed.\\
	Furthermore, given $T > 0$, we define $E^\zeta_{\vartheta, T} \subset E^\zeta_\vartheta$ by
	$$E^\zeta_{\vartheta, T} = \{(Z, \boldsymbol{\psi}, \mcV) \in E^\zeta_\vartheta: \text{ there exists a unique solution to \eqref{eq: tct_sys} in } \mathcal{D}^{(\zeta)}_{T}(\vartheta; Z) \},$$
	where for $\zeta > 0$ all operations in \eqref{eq: tct_sys} are understood with respect to the grading $|\cdot|_\fs^{(\zeta)}$, with the truncation exponents lowered by $N\zeta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.439444+00:00","domain":"probability theory","id":"claim_0efb0d4404f49b26e93a83a53b8f945d10b74a545a775550057703c56fff0742","kind":"theorem","schema_version":1,"statement":"[Prop 20 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\A{1},\A{2}\leq 1$ be such that $N^{-1}\ll  \pr{\A{1}\A{2}}^{1/2}$ and let $f\in S(m,\A{1},\A{2})$. Then,  
    \begin{equation*}
        \mathrm{tr}\pr{f_{N,\A{1},\A{2}}}=\pr{N\A{1}^{1/2}\A{2}^{1/2}}^d\int_{\mc{T}_{\A{1},\A{2}}}f(x,\xi)dxd\xi+r_N
    \end{equation*}
    where, for all $k\in \N$, 
    \begin{equation*}
        r_N=\mc{O}_k(1)N^{d-k}\A{1}^{(d-k)/2}\A{2}^{d/2}\sum_{\bb{\beta}+\bb{\gamma}\leq \max(2d+1,k)}\norme{\partial_x^\beta\partial_\xi^\gamma f}_{L^1(\mc{T}_{\A{1},\A{2}})}.
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:53:10.161607+00:00","domain":"probability theory","id":"claim_0efe9e21c447258f3afbd878fa72b22d6590e07378b526275634d65c1ccbaee8","kind":"concept","schema_version":1,"statement":"[Proposition PropDataSingle of arXiv:2608.28949, 'The information geometry of product-reference discrete diffusion: Interaction growth compl'] For any choice of $u \in [a,b]$, the \textsf{IGC}\xspace increment is sandwiched as
\begin{subequations}
\begin{align}

  \frac{1}{2 c_u(a, b)} \mathsf{D}_u(a, b) & \leq \mathsf{G}(a, b) \leq 2
  c_u(a, b) \mathsf{D}_u(a, b).
\end{align}
Moreover, the one-step KL error~(equation EqnExactKL of the paper) is equal to
\begin{align}

\Gamma_{\scaleto{\operatorname{prod}}{5pt}}(a, b) & = \int_a^b \frac{\mathsf{D}_v(a, v)}{v (1 - v)} \, dv.
