{"assumptions":[],"created_at":"2026-10-27T10:07:48.566118+00:00","domain":"probability theory","id":"claim_0f1b18836de6982c00ffd68b7a61e2520b444924781f49adfe500e7e8a1d30d4","kind":"concept","schema_version":1,"statement":"[Proposition 26 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $V$ be a strictly convex, $p$-homogeneous, $C^2$ function on $\R^n$, $p>1$, satisfying $V(o)=0$. Then, the geometric inequality
    \begin{equation}

        \vol(K)\vol\left(\nabla \mathcal{L}V(K^\circ)\right)^{p-1} \leq \vol\left(\left\{V\leq \frac{1}{p}\right\}\right)^p, \qquad \forall \,K \in \mathcal{C}^n,
    \end{equation}
    holds if and only if for every $f \in \mathcal{F}_n$ and all measurable functions $g:\R^n\to\R_+$ and $\Omega:\R_+\to\R_+$, where $\Omega$ is non-increasing, that satisfy the pointwise bound
    \[
        f(x)^{\frac{1}{p}}g(y)^{\frac{p-1}{p}} \leq \Omega\left(\frac{\langle x,y \rangle}{p}\right), \qquad \forall \,\,x, y \in \R^n \text{ with } \langle x,y \rangle>0,
    \]
    one has the functional inequality:
    \begin{equation}

        \left(\int_{\R^n}f(x)dx\right)\left(\int_{\R^n}g(\nabla V(z))dz\right)^{p-1} \leq \left(\int_{\R^n}\Omega(V(z))dz\right)^p.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:04:07.031412+00:00","domain":"probability theory","id":"claim_0f1eca8377e7daf4c187cf58590f3515a6274fc9c2394e289542da4eef8ff5fe","kind":"concept","schema_version":1,"statement":"[Lemma lem:AC-identities of arXiv:2607.29330, 'Large deviations for the maximum of\\ the generalized TAP free energy'] For the process~(equation eq:AuffingerChen of the paper), the following identities hold.
		\begin{enumerate}[label=\textup{(\roman*)}]
			\item $M_t$ is a martingale and
			\begin{equation}
				\mathrm{d} M_t
				=\sqrt{\xi''(t)}\,\partial_{xx}\Phi_\zeta(t,X_t)\,\mathrm{d} B_t .
			\end{equation}

			\item The Parisi value along the optimal trajectory satisfies
			\begin{equation}
				\mathrm{d}\Phi_\zeta(t,X_t)
				=\frac12\zeta([0,t])\xi''(t)M_t^2\,\mathrm{d} t
				+\sqrt{\xi''(t)}M_t\,\mathrm{d} B_t .
			\end{equation}
			Equivalently, for $s<t$,
			\begin{equation}
				\Phi_\zeta(t,X_t)-\Phi_\zeta(s,X_s)
				=\frac12\int_s^t\zeta([0,r])\xi''(r)M_r^2\,\mathrm{d} r
				+\int_s^t\sqrt{\xi''(r)}M_r\,\mathrm{d} B_r .
			\end{equation}

			\item For $s<t$,
			\begin{equation}
				\mathbb{E}\bigl[(X_t-X_s)M_s\bigr]
				=\mathbb{E}[M_s^2]\int_s^t\zeta([0,r])\xi''(r)\,\mathrm{d} r,
			\end{equation}
			and
			\begin{equation}
				\mathbb{E}\bigl[(M_t-M_s)X_s\bigr]=0 .
			\end{equation}

			\item Suppose that
			\(\mathbb{E}[M_r^2]=r\) for \(\zeta\)-a.e.\ \(r\in[0,1]\).
			If \(s,t\in\mathrm{supp}(\zeta)\cap[0,1)\) and
			\(\zeta((s,t))=0\), then
			\begin{equation}
				\mathbb{E}\bigl[(M_t-M_s)(X_t-X_s)\bigr]
				=\bigl(\xi'(t)-\xi'(s)\bigr)\int_s^1\zeta([0,r])\,\mathrm{d} r .
			\end{equation}
			Consequently,
			\begin{equation}
				\mathbb{E}\bigl[M_t(X_t-X_s)\bigr]
				=\bigl(\xi'(t)-\xi'(s)\bigr)
				\left(\zeta([0,s])\,t+\widehat\zeta(t)\right),
			\end{equation}
			where in the last display we used $\zeta((s,t))=0$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

