{"assumptions":[],"created_at":"2026-10-26T20:24:30.019254+00:00","domain":"probability theory","id":"claim_0fe412d81e9669ee56c50a13751f71411d595b00a007989947efcc03ca74c399","kind":"concept","schema_version":1,"statement":"[Thm 10 of arXiv:2605.05986, '\bf Convergence rate of the occupation measure of { classes of ergodic processes toward th'] Assume $b$  and $\sigma$ are locally Lipschitz continuous and satisfy~\eqref{eq:onR+}.\\
\smallskip
\noindent $(a)$ {\it Uniform $L^q$-contraction}. Let {$q\! \in (1,+\infty)$}.  Assume that, for every $x$, $y\!\in \R^d$, $x\neq y$,
\begin{align} 
   \langle b(x)-b(y)\,|\,x-y\rangle +\tfrac 12\ \|\s(x)-\s(y)\|^2_F+ (\tfrac q2-1)\frac{|(\s(x)-\s(y))^{\top}(x-y)|^2}{|x-y|^2} \le   - \bar  \kappa_q |x-y|^2
\end{align}
where $\bar \kappa_{{q}}$ is positive constant.  Then, for every $\mu_i \!\in{\cal P}_q(\R^d)$, $i=1,2$, 
\begin{equation} 
\forall\, t\ge 0, \quad {\cal W}_{{q}}(\mu_1P_t, \mu_2P_t) \le e^{-\bar \kappa_{{q} t}}  {\cal W}_q(\mu_1, \mu_2). 
\end{equation}
In particular, for every $x$, $y\!\in \R^d$, for every $t\ge 0$, ${\cal W}_1(P_t(x,dy), P_t(x',dy)) \le e^{-\bar \kappa_1 t}  |x-y|$.

\smallskip
\noindent $(b)$ {\it $L^1$-contraction, elliptic case (see~\cite[Theorems~2.5  and 2.6]{Wang2020})}. Assume furthermore that $\sigma$ is uniformly elliptic (see \eqref{eq:sigmaUellip} with $d'\ge d$ to make ellipticity possible).  Assume furthermore that $b$ and $\s$ satisfy the following $L^1$-contraction assumption:   for every $x$, $y\!\in \R^d$, $x\neq y$,
\begin{align}
\nonumber \langle b(x)-b(y)\,|\,x-y\rangle +\tfrac 12\bigg( \|\s_0(x)-\s_0(y)\|^2_F-&\frac{|(\s(x)-\s(y))^{\top}(x-y)|^2}{|x-y|^2}\bigg) \\
 & \qquad\quad \le (\underline \kappa -(\underline \kappa +\bar  \kappa)\mbox{\bf 1} _{\{|x|\ge R\}})|x-y|^2
\end{align}
for some non-negative constants $\underline \kappa, \bar \kappa,R$ with $\bar \kappa>0$. Then there exists positive real constants $C,\lambda>0$ such that, for every $\mu_i \!\in{\cal P}_1(\R^d)$, $i=1,2$, 
\begin{equation} 
\forall\, t\ge 0, \quad {\cal W}_1 (\mu_1P_t, \mu_2P_t) \le  C e^{-\lambda t}  {\cal W}_1 (\mu_1, \mu_2).
\end{equation} 
\noindent In particular, for every $x$, $y\!\in \R^d$, for every $t\ge 0$, ${\cal W}_1(P_t(x,dy), P_t(x',dy)) \le C e^{-\lambda t}  |x-y|$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.433026+00:00","domain":"probability theory","id":"claim_0fe4c93f3b42e0a93363af212aa3878c3afbc899ecee564e6365916752cd6eaf","kind":"definition","schema_version":1,"statement":"[Dfn regular resistance forms of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] [{Regular resistance form, [Kigami_12_Resistance]}] 
