{"assumptions":[],"created_at":"2026-10-26T20:23:03.039927+00:00","domain":"probability theory","id":"claim_12294cc5379161d7736a8dc979a40674ab2ff91100f35ef4cc918997bfdc79e3","kind":"concept","schema_version":1,"statement":"[Lemma 26 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $T\in(0,\infty)$ and let $x^{(n)}_{t}$, $t\in[0,T]$, $n=0,1,2,...$,
be $\bR^{d}$-valued random functions measurable with respect to $(\omega,t)$. Assume that

(i) For any $\varepsilon>0$
$$
\lim_{n\to\infty}\int_{0}^{T}P(|x^{(n)}_{t}-
x^{(0)}_{t}|\geq\varepsilon)\,dt=0;
$$

(ii) For any $R\in(0,\infty)$ there exist $N,p\in[1,\infty)$ such that
for any Borel $f(t,x)\geq0$
vanishing for $|x|\geq R$ and $n\geq1$ we have
\begin{equation}

E\int_{0}^{T} f(t,x^{(n)}_{t})\,dt
\leq  N\|f\|_{L_{p} }.
\end{equation}

Let a sequence $t^{(n)}\to0$ and let Borel $f^{n}(t,x)$, $n=0,1,2,...$, be given
on $\bR^{d+1}$ such that $f^{n}\to f^{0}$ in  measure
  on any bounded subset
of $\bR^{d+1}$ 
and
\begin{equation}

\lim_{c\to\infty}\sup_{n\geq0}
E\int_{0}^{T} |f^{n}(t^{(n)}+t,x^{(n)}_{t})|
I_{[c,\infty)}\big(|f^{n}(t^{(n)}+t,x^{(n)}_{t})|\big)\,dt=0.
\end{equation}

Then  
\begin{equation}

\lim_{n\to \infty}E \int_{0}^{T}
\big|f^{n}(t^{(n)}+t,x^{(n)}_{t})
-f^{0}(t,x^{(0)}_{t})\big|\,dt =0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:01:15.327740+00:00","domain":"probability theory","id":"claim_122950a677988d9388878c89440f4dc39de32c446f35765c99c37bbc7fe568f3","kind":"definition","schema_version":1,"statement":"[Defi 2 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $p \in (0, \infty)$ and assume
 $\{K_n : n \ge 1\}$ is a family of compact subsets of $\cX$. A collection $\{X^n_s : s\in S_n, n \ge 1\}$ of $\cX$-valued random elements is \textit{$(\nu_n)$-compactly uniformly $p$-th order integrable w.r.t. $\{K_n\}$} (or $(\nu_n)$-$\CUI(p)$ w.r.t. $\{K_n\}$, for short) if:
	\begin{enumerate}[\rm (a)]
		\item the map $(\omega, s) \mapsto X^n_s(\omega)$ is $\cF \otimes \cS_n/\cB(\cX)$-measurable for every $n \ge 1$,

		\item  the following convergence holds:
		\begin{align}
			\lim_{n \to \infty} \bE\int_{S_n} \lt\|X^n_s\rt\|^p \1_{\{X^n_s \notin K_n\}} \nu_n(\od s)  =0.
		\end{align}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:41:11.633171+00:00","domain":"probability theory","id":"claim_1234f2687194aa8901b9bc3f24caf09763d1cab2ae2fb2179a98c96d19b765bc","kind":"lemma","schema_version":1,"statement":"[Lemma lem:subseqconv of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Let $(a_n)_{n\in\mathbb{N}},(b_n)_{n\in\mathbb{N}}$ be strictly increasing sequences and let $f$ be a decreasing function such that
