{"assumptions":[],"created_at":"2026-10-27T14:18:13.248987+00:00","domain":"probability theory","id":"claim_14009360243b2a70639bc0b8e0a65cbf0cc73f15e862e8c27f715c1bb7e4f7f9","kind":"theorem","schema_version":1,"statement":"[Corollary mshe of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Retain the setting of Lemma (lemma:mshe of the paper), and recall the function {\small$\mathscr{S}^{N}$} from Definition (definition:zsmooth of the paper). We have 

\begin{align}
\d\mathbf{S}^{N}_{\t,\x}&=\mathscr{T}_{N}\mathbf{S}^{N}_{\t,\x}\d\t+[\mathscr{S}^{N}\star(\sqrt{2}\lambda N^{\frac12}\mathbf{Z}^{N}_{\t,\cdot}\d\mathbf{b}_{\t,\cdot})]_{\x}+[\mathscr{S}^{N}\star(\mathfrak{e}[\tau_{\cdot}\bphi_{\t}]\mathbf{Z}^{N}_{\t,\cdot})]_{\x}\d\t\\
&=\mathscr{T}_{N}\mathbf{S}^{N}_{\t,\x}\d\t+[\mathscr{S}^{N}\star(\sqrt{2}\lambda N^{\frac12}\mathbf{Z}^{N}_{\t,\cdot}\d\mathbf{b}_{\t,\cdot})]_{\x}+[\mathscr{S}^{N}\star(\mathfrak{e}[\tau_{\cdot}\bphi_{\t}]\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}\d\t
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.856946+00:00","domain":"probability theory","id":"claim_1400c4b769274eec2e73d4319e4930f36e066856cb733ee88c529658b414ac52","kind":"definition","schema_version":1,"statement":"[Definition 15 of arXiv:2609.03875, 'Measure theory without infinities'] A set $\mathcal Q$ is called a semi-ring if
  \begin{enumerate}
  \item $A\cap B\in\mathcal Q$ for every $A,B\in\mathcal Q$,
  \item for every $A,B\in\mathcal Q$, there is a finite disjoint family $\mb C\colon I\to \mathcal Q$ such that $A\setminus B=\bigcup_{i\in I} \mb C(i)$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:49.210409+00:00","domain":"probability theory","id":"claim_14013bdd73e661c57b2fc5b566fa1c3889364e17313c456b76f1cab93ae8d62c","kind":"lemma","schema_version":1,"statement":"[Lemma 22 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \(\nu(s)\) be such that \(|\nu(s)|\leq C\) for all \(s\in\mathbb{R}\) and \(|\nu(s)|\sim K|s|^{\gamma}\) as \(s\to\infty\) for some \(\gamma<0\). Let \(\alpha, \beta\) and
\(m\) be such that \(\alpha+\beta+ (m-1)\gamma >-2\). Then as \(h\to\infty\) we have that
\begin{equation}
\int_{[0,h]^3}(s-u)_+^{\alpha}(s-v)_+^{\beta}\nu(u-v)^{m-1}dsdudv \asymp h^{\alpha+\beta+(m-1)\gamma+2}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.286019+00:00","domain":"probability theory","id":"claim_140478a66acde97be38987d71d9cdc5b205c242d44131516217f6506bc830363","kind":"lemma","schema_version":1,"statement":"[Lemma prob0 non deg of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Assume that $\xi$ is a genuine mixture, i.e.\ $\xi(t)=\sum_p \beta_p^2 t^p$ with
		at least two nonzero coefficients.  In particular, the quantity
		\begin{equation}
			D(q):=\xi(q)\bigl(\xi'(q)+q\,\xi''(q)\bigr)-q\,\xi'(q)^2
			=\tfrac12\sum_{a,b}\beta_a^2\beta_b^2(a-b)^2\,q^{a+b-1}
		\end{equation}
		is strictly positive on $(0,1)$.
		Let $\varepsilon>0$, $u\in(0,1)$, $q\in(0,1)$ and $f\in\mathbb{R}$.
		Let $\zeta\in\mathrm{Prefix}_2(u,q)$ where $\mathrm{Prefix}_2$ is as in
		Definition~(def:nprefix of the paper).

		Let $\delta\in[\varepsilon,1)$ and $\mathbf{m}\in[-1+\delta,1-\delta]^N$ and denote
		$Z(\mathbf{m}):=\bigl(\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}),\,F_{\mathrm{TAP},\zeta}(\mathbf{m})\bigr)$. Suppose in addition that $q_\mathbf{m}\in[q-\varepsilon,q+\varepsilon]$ and
		$\mathrm{dist}\!\bigl(\zeta_\mathbf{m},\,\zeta|_{(q,1]}+\zeta([0,q])\,\delta_q\bigr)\leq \varepsilon$,
		where both measures are viewed as elements of $\mathcal{P}([0,1])$ and $\mathrm{dist}$
		is the metric~(equation def:dist of the paper).

		\begin{enumerate}[label=(\roman*)]
			\item  The log-density of $Z(\mathbf{m})$ at $(0,Nf)$ satisfies
			\begin{multline}
				\log \varphi_{Z(\mathbf{m})}(0,Nf)\\ \leq \frac{1}{2}N\xi(q)u^2-\frac{1}{2}N\xi''(q)\left(\int_q^1 \zeta([0,t])\mathrm{d} t\right)^2 -\frac{1}{2\xi'(q)}\Vert \partial_m h_\zeta(q,\mathbf{m})-u\xi'(q)\mathbf{m}\Vert^2\\-\frac{N}{2}\log (2\pi \xi'(q))+\frac{N}{2\xi'(q)q}\left( \frac{1}{N}\langle \partial_m h_\zeta(q,\mathbf{m}),\mathbf{m}\rangle-\xi'(q)\int_0^1 \zeta([0,t])\mathrm{d} t \right)^2\\- u \left(\sum_{i=1}^N h_\zeta(q,m_i)+N\mathcal{U}_\zeta(q)+Nf\right)
				+O\!\left(N\frac{\varepsilon}{\delta}\right)+O(\log N),
			\end{multline}
			where the implicit constant depends only on $\xi$, $q$, and $u$.

			\item  Suppose in addition that
			\begin{equation}
				\langle \partial_m h_\zeta(q,\mathbf{m}),\mathbf{m}\rangle=N\xi'(q)\int_0^1 \zeta([0,t])\mathrm{d} t +O(N\varepsilon)
			\end{equation}
			and
			\begin{equation}
				\sum_{i=1}^N (h_\zeta(q,m_i)-\partial_m h_\zeta(q,m_i)m_i)+N\int_0^q t\xi''(t)\zeta([0,t])\mathrm{d} t+\frac{1}{2}N \int_q^1 t\xi''(t)\zeta([0,t]) \mathrm{d} t=-Nf+O(N\varepsilon).
			\end{equation}
			Then,
			\begin{multline}
				\log \varphi_{Z(\mathbf{m})}(0,Nf) \\= \frac{1}{2}N\xi(q)u^2-\frac{1}{2}N\xi''(q)\left(\int_q^1 \zeta([0,t])\mathrm{d} t\right)^2 -\frac{1}{2\xi'(q)}\Vert \partial_m h_\zeta(q,\mathbf{m})-u\xi'(q)\mathbf{m}\Vert^2-\frac{N}{2}\log (2\pi \xi'(q))\\-u \left(\sum_{i=1}^N h_\zeta(q,m_i)+N\mathcal{U}_\zeta(q)+Nf\right)
				+O\!\left(N\frac{\varepsilon}{\delta}\right)+O(\log N).
			\end{multline}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:09:15.296654+00:00","domain":"probability theory","id":"claim_140856c0ac5dff3d0314f81aa6247918105d10b2cf1310c34d166822066349ee","kind":"concept","schema_version":1,"statement":"[Theorem th consta of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] For any $t_0\in (0,T]$, there exists a positive constant $\mathcal{C}=\mathcal{C}(t_0)$ such that for some generic constant $\gamma\in (0,1)$ (which is independent of $t_0$) and for any $M>0$, for all $ y_0, \hat y_0\in U_{M,0} $, it holds that

\begin{equation}
| y(t_0)-\hat y(t_0)|_{L^2_{\mathcal{F}_{t_0}}(\Omega;L^{2}(G))} \leq
\mathcal{C} M^{1-\gamma}| y(T)-\hat y(T)|_{L^2_{\mathcal{F}_{T}}(\Omega;H^{1}(G))}^{\gamma},
\end{equation}

where $y(\cdot)$ (resp. $\hat y(\cdot)$) is the solution to (sp-eq1 of the paper) with respect to the initial datum $y_0$ (resp. $\hat y_0$). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.227437+00:00","domain":"probability theory","id":"claim_140ad3a6d5c0780d54d0bb538bfa4e551d03e5541fd0b5f2df0dace736f4262a","kind":"concept","schema_version":1,"statement":"[Lemma BBM-F-KPP-Connection of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For a measurable function $\phi:\mathbb{R} \to [0,1]$, let
\begin{equation}
u_\phi(t,x) = 1 - \mathbb{E}[\prod_{k=1}^{n(t)}\{1-\phi(x- \chi_k(t))\}].
\end{equation}
Then $u = u_\phi$ solves the following F-KPP equation
\begin{equation}
\partial_t u = \frac{1}{2}\partial_x^2 u + u- u^2
\end{equation}
 with the initial condition $u(0,x) = \phi(x)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:18:27.578423+00:00","domain":"probability theory","id":"claim_140dc68557a19594367e45edb919cd577938baaddbfab4bdf79b7434ee279431","kind":"concept","schema_version":1,"statement":"[Lem 48 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $G=(V,E)$ be a subgraph of $\mathbb Z^d$ and let $A\subset V$ be a finite even subset of $G$. Let $\beta>0$. Let $\n$ be distributed according to $\mathbf P_{G,\beta}^{A}$. Let $(\omega_e)_{e\in E(\mathbb Z^d)}$ be an independent Bernoulli percolation with parameter $1-\exp(-\beta)$. For each $e\in \mathbb Z^d$, we define
\begin{equation}
	\eta_e:=\max(\mathds{1}_{\n_e>0},\omega_e).
\end{equation}
Then, the law of $\eta$ is $\phi_{G,\beta}^0[\:\cdot\:|\: \mathcal F_A]$. As a consequence, if $\mathcal A$ is an increasing event, one has
\begin{equation}
	\mathbf P^{A}_{G,\beta}[\mathcal A]\leq \phi_{G,\beta}^0[\mathcal A\: | \: \mathcal F_A].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.761854+00:00","domain":"probability theory","id":"claim_140e4c3f99595de0722f0e413491174cffaedf0c95aded7b08d077c862c2a663","kind":"lemma","schema_version":1,"statement":"[Lemma lem:eigenfunction-square-laplacian of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] The square $\phi^2$ belongs to $H_0^1(D)$ and satisfies
\begin{equation}
 L_0(\phi^2)
 =2\Lambda\phi^2M_x-2\Gamma_\mathcal E(\phi)\,\mathcal L^2
 \qquad\text{in }\mathcal D'(D).
\end{equation}
Equivalently, for every $\zeta\in C_c^\infty(D)$,
\begin{equation}
 \mathcal E(\phi^2,\zeta)
 =2\Lambda\int_D\zeta\phi^2\,dM_x
  -2\int_D\zeta\Gamma_\mathcal E(\phi)\,dz.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:13:21.306469+00:00","domain":"probability theory","id":"claim_14109427b14f9f5a20320691f9adf19d938fd2e505c5512cf71af8b9c548d76d","kind":"theorem","schema_version":1,"statement":"[Proposition 44 of arXiv:2609.01473, 'Keller sequences of exact $\infty$-categories'] Let $\cal{D}$ be an $\infty$-category equipped with an orthogonal factorisation system $(\cal{D}^l,\cal{D}^r)$, such that there is some object $0 \in \cal{D}$ which is initial for maps in $\cal{D}^r$.
    Let $p\colon\cal{E} \to \cal{D}$ be a functor satisfying the following:
    \begin{enumerate}
        \item Maps in $\cal{D}^l$ admit $p$-cocartesian lifts given any lift of their domain and maps in $\cal{D}^r$ admit $p$-cartesian lifts for any lift of their target.
        \item The fibre inclusion $\cal{F} := p^{-1}(0) \to \cal{E}$ admits a retraction $r\colon \cal{E} \to \cal{F}$. 
    \end{enumerate}
    Then the functor 
    \[ (r,p)\colon \cal{E} \to  \cal{F} \times \cal{D} \]
    is a weak homotopy equivalence.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.890647+00:00","domain":"probability theory","id":"claim_1420fc6a7b854674a4c27b19a2c40040bb1e9d605cc071ea38e58d3e630f6600","kind":"theorem","schema_version":1,"statement":"[Teorema 31 (integration by parts formula) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let $ (X,W)$ be a solution to  $ SDE_{\mu,\sigma}$ and let $ V= (Y, C, \tau, H)$ be an infinitesimal stochastic symmetry for  $SDE{\mu,\sigma}$. Let $T_{\lambda}=(\Phi_{\lambda}, B_{\lambda}, \eta_{\lambda}, h_{\lambda})$ be the one-paramer group related to $ V$, where, as usual $\Phi_{\lambda}=(\tilde{\Phi}_{\lambda},f_{\lambda})$ and $\ Y=(\tilde{Y},m)$. Assuming Hypothesis A' (\ref{ipotesi A'}), then the following integration by parts formula holds for every $ t \in [0,T]$, for all $ F$  bounded functional with bounded first and second derivative:
\begin{equation}
    -m(t) \mathbb{E}_{\mathbb{P}}[L(F(X_t))] + \mathbb{E}_{\mathbb{P}}[F(X_t) \int_0^t (H_{\alpha}(X_s,s) d W_s^{\alpha})] + \mathbb{E}_{\mathbb{P}}[Y(F(X_t))] - \mathbb{E}_{\mathbb{P}}[Y(F(X_0))]=0.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:03.897879+00:00","domain":"probability theory","id":"claim_14261e3b4f580d4b4a43238c5c2b1a6edb48675849adb545d44c1af7715b0d6b","kind":"lemma","schema_version":1,"statement":"[Lem 4 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] Suppose that assumptions $({\bf A1})$--$({\bf A3})$ hold. Furthermore, assume that either the time horizon $T$ or the Lipschitz constant $K$ is sufficiently small so that
\begin{eqnarray}
(57 + 432K)K e \max(1, T^2)< 1.
\end{eqnarray}			
Then there exists a positive constant $C$, independent of $\varepsilon$, such that for every $x,y\in\R$,
\begin{eqnarray*}
&&\E\left[\sup_{ t\leq s \leq T}e^{\beta s} |X^{t,x,\varepsilon}(s)- X^{t,y,\varepsilon}(s)|^2 +  \sup_{ t\leq s \leq T}e^{\beta s} |Y^{t,x,\varepsilon}(s)- Y^{t, y,\varepsilon}(s)|^2\right.\nonumber\\
&&\left.+ \int_t^T e^{\beta s} |Z^{t,x,\varepsilon}(s)- Z^{t, y,\varepsilon}(s)|^2 ds \right]\leq  C |x-y|^2.
\end{eqnarray*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:19:46.235845+00:00","domain":"probability theory","id":"claim_14289d2f2f5ec0f7ec2c43867dbafb985e2fbe70fa4ead888f1b2f162f3e5ec0","kind":"theorem","schema_version":1,"statement":"[Thm 86 (Three-entropy formula) of arXiv:2507.08909, 'Annealed almost periodic entropy'] If~\eqref{eq:traces-fast} holds and $\phi \in \B(\A,\rmM_k)_+$, then
