{"assumptions":[],"created_at":"2026-10-27T17:18:19.447098+00:00","domain":"probability theory","id":"claim_14983aaf5b73307cab1bc0670261fb0cf9efdbfdf789207ed2c23b3e8d7fb101","kind":"definition","schema_version":1,"statement":"[Definition def:NBP-Wishart of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $H\in\mathbb{C}^{N\times M}$ be a $N\times M$ matrix, and let $x,y$  respectively denote  elements in $[N], [M]$.  For each integer $n\ge0$, define the nonbacktracking power matrix $V_n$ (viewed as an operator) as follows:

\paragraph{Even case ($n=2m$):}
\begin{itemize}
  \item $V_{2m}:\,\mathbb{C}^{[N]}\to\mathbb{C}^{[N]}$, with
  \begin{equation}
  (V_{2m})_{x_0x_{2m}} = \sum_{y_1,x_2,\dots,y_{2m-1}}
  \Bigl[\prod_{i=0}^{2m-2}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H_{x_0y_1}H^*_{y_1x_2}\cdots H^*_{y_{2m-1}x_{2m}},
  \end{equation}
  summing over $y_{2k+1}\in[M],\,x_{2k}\in[N]$. Here $\zeta_i$ denotes $x_i$ or $y_i$.
  \item $V_{2m}:\,\mathbb{C}^{[M]}\to\mathbb{C}^{[M]}$, with
  \begin{equation}
  (V_{2m})_{y_0y_{2m}} = \sum_{x_1,y_2,\dots,x_{2m-1}}
  \Bigl[\prod_{i=0}^{2m-2}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H^*_{y_0x_1}H_{x_1y_2}\cdots H_{x_{2m-1}y_{2m}},
  \end{equation}
  summing over $x_{2k+1}\in[N],\,y_{2k}\in[M]$.
\end{itemize}

\paragraph{Odd case ($n=2m+1$):}
\begin{itemize}
  \item $V_{2m+1}:\,\mathbb{C}^{[N]}\to\mathbb{C}^{[M]}$, with
  \begin{equation}
  (V_{2m+1})_{x_0y_{2m+1}} = \sum_{y_1,x_2,\dots,x_{2m}}
  \Bigl[\prod_{i=0}^{2m-1}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H_{x_0y_1}H^*_{y_1x_2}\cdots H_{x_{2m}y_{2m+1}},
  \end{equation}
  summing over $y_{2k+1}\in[M],\,x_{2k}\in[N]$.
  \item $V_{2m+1}:\,\mathbb{C}^{[M]}\to\mathbb{C}^{[N]}$, with
  \begin{equation}
  (V_{2m+1})_{y_0x_{2m+1}} = \sum_{x_1,y_2,\dots,y_{2m}}
  \Bigl[\prod_{i=0}^{2m-1}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H^*_{y_0x_1}H_{x_1y_2}\cdots H^*_{y_{2m}x_{2m+1}},
  \end{equation}
  summing over $x_{2k+1}\in[N],\,y_{2k}\in[M]$.
\end{itemize}
We also set 
\begin{equation}
