\begin{cases}\mathcal{G} h(x)=0 & \text { in } \mathbb{R}_{+}^2, \\ R_i \cdot \nabla_x h(x)=0 & \text { if } x_i=0.\end{cases}

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:45:27.887641+00:00","domain":"probability theory","id":"claim_1b350a79ea6441af726d86f6a1f14a12df17d131dbd8fce1d1e0df329de369df","kind":"concept","schema_version":1,"statement":"[Proposition prop:restriction_chain_gap of arXiv:2607.02410, 'Polynomial mixing for polygonal side matchings'] The chain $P_S$ is irreducible for every $S \in \parallelsigs{n}{g}$. There exists a universal constant $C > 0$ such that for every $S \in \parallelsigs{n}{g}$, 
