\item ${\widehat\omega}\mapsto {\boldsymbol{\pi}}^{{\widehat B},u,{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}}({\widehat\omega})$ is an $\mathfrak{S}$-measurable, $\textup{D}_{\textup{LCRL}}([0,1],\mathbb{X}_u)$-valued random variable which almost surely takes values in $\textup{D}_{\textup{LCRL}}([0,1],\mathcal{G}_u^{\omega({\widehat\omega})})$.
\item 
For $\widehat\mathbb{P}$-almost every ${\widehat\omega}$ and all $s \in [0,1]$,
\begin{align}
{\boldsymbol{\pi}}^{{\widehat B},u,s}({\widehat\omega})=\inf\bigl\{\gamma\in\mathcal{G}_u^{\omega({\widehat\omega})}:\nu^{\omega({\widehat\omega})}(\phi_{}^{{\widehat B},u}\preceq \gamma)\geq s\bigr\}.
\end{align}
Consequently, ${\boldsymbol{\pi}}^{{\widehat B},u,r}({\widehat\omega})\preceq{\boldsymbol{\pi}}^{{\widehat B},u,s}({\widehat\omega})$ for $r\le s$ in $[0,1]$.
\item  
For $\widehat\mathbb{P}$-almost every ${\widehat\omega}$ and all $\gamma \in \mathcal{G}_u^{\omega({\widehat\omega})}$,
\begin{align}
\bigl\{s\in [0,1] : {\boldsymbol{\pi}}^{{\widehat B},u,s}({\widehat\omega}) \preceq \gamma\bigr\}=\bigl[0,\nu^{\omega({\widehat\omega})}(\phi_{}^{{\widehat B},u} \preceq \gamma)\bigr]. 

