{"assumptions":[],"created_at":"2026-10-27T20:09:43.678254+00:00","domain":"probability theory","id":"claim_1e7ef5174aea066a6e4d3b505bd1a2983e79e259c8da1e976995c044dbfd96af","kind":"definition","schema_version":1,"statement":"[Defn d.omegatmixing of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] \ 
 \begin{enumerate}[wide,label=(\roman*),labelindent=0pt]
\item  The  marks $U$ of the point process $\tilde \mathcal{P}=\sum_{x \in \mathcal{P}}
  \delta_{\tilde{x}}$, $\tilde{x}=(x,U)$, $x\in\mathbb{R}^d$,  $U\in\mathbb{K}$,
satisfy  {\em $\textnormal{BL}$-mixing correlations} if
there exists an increasing-decreasing family of  functions $\omega_k :  [0, \infty) \to [0,2]$, $k \in \mathbb{N}$, called correlation decay functions,  such that for all $p,q \in \mathbb{N}, x_1,\ldots,x_{p+q} \in \mathbb{R}^d$, and all $f \in \textnormal{BL}(\mathbb{K}^p)$, and
  $g \in \textnormal{BL}(\mathbb{K}^q)$ we have

\begin{align} 
\left|\mathbb {E} _{\bk x1{p+q}}[f(\bk U1{p})g(\bk U{p+1}{p+q})] - \mathbb {E} _{\bk x1p}[f(\bk U1p)]\mathbb {E} _{\bk x{p+1}{p+q}}[g(\bk U{p+1}{p+q})]\right|\le \omega_{p+q}(s),
\end{align}

where $s := d(\bk x1p,\bk x{p+1}{p+q})$ is at (equation defs of the paper).

\item  The marks $U$ have  {\em fast $\textnormal{BL}$-mixing correlations} if $(\omega_k)_{k \in \mathbb{N}}$ are fast decreasing.

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.429260+00:00","domain":"probability theory","id":"claim_1e83419c8a89d3202890070c042121eb79b78262a444488eea3650408c6f6897","kind":"theorem","schema_version":1,"statement":"[Proposition 194 of arXiv:2601.16377, '2601.16377'] For each $q\in[m]$, $k \geq 1$ and $x\in [-\hat{W}_q,0]$, the random variables
 \begin{equation}

 \int_{\amsmathbb{R}} \left(\mathsf{Ht}^{(q)}_\N(\N^{-1}\lfloor x \N \rfloor, y)-\E\big[\mathsf{Ht}^{(q)}_\N(\N^{-1}\lfloor x \N \rfloor, y)\big]\right) y^k\dd y
 \end{equation}
 are asymptotically Gaussian (in the sense that the joint moments of these random variables converge towards expressions satisfying the Wick formula) with asymptotic covariance for the triplets $(k_1,q_1,x_1)$ and $(k_2,q_2,x_2)$ given by
 \begin{equation}

 \frac{1}{\pi} \int_{\{y_1 \mid (x_1,y_1)\in\pounds_{q_1}\}}\int_{\{y_2 \mid (x_2,y_2)\in\pounds_{q_2}\}} \mathrm{Gr}\big(z^{(q_1)}(x_1,y_1),z^{(q_2)}(x_2,y_2)\big)\,y_1^{k_1}y_2^{k_2}\dd y_1\dd y_2,
 \end{equation}
 where the maps $z^{(q)}$ are as in Section~\ref{Section_complex_structure}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:17:13.075509+00:00","domain":"probability theory","id":"claim_1e85bdc231aaa84b233470a7927a3ef36080135fc018d480a7d4c5b0fc75ab67","kind":"theorem","schema_version":1,"statement":"[Proposition prop:bound-T_n-optimal of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Assume that all the variances in $\Lambda_n$ are unitary and all the other variances vanish. Then there exist some small enough universal constants $c_{1}>0$ such that
 	\begin{equation}
 		\mathbf{P}\Big[ \mathbf{T}_{\Lambda_n}\leq \frac{c_1}{n^\frac{2}{3}\log^{\frac{1}{3}}(n)} \Big] \leq O(\frac{1}{n^4}). 
 	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:38.605934+00:00","domain":"probability theory","id":"claim_1e91d5f3a86331f798a10cc5bfd93c1305fa558cb9386e6358ab8bc12e4b7595","kind":"theorem","schema_version":1,"statement":"[Proposition 9 of arXiv:2607.08129, '2607.08129'] The rate function $I_\theta$ is convex.  If $I_\theta(f)<\infty$, then $f$ is absolutely continuous and nondecreasing, satisfies $f(0)=0$, and obeys
\begin{equation}
 0\le f(t)\le t,
 \qquad 0\le t\le1.
\end{equation}
For every admissible representation $f=\mathcal T a$,
\begin{equation}
 f'(t)=\sum_{k\ge1}\frac1k a_k(t/k)
 \quad\text{for a.e. }t\in(0,1).
\end{equation}
The unique zero of $I_\theta$ is
\begin{equation}
 \bar f_\theta(t)=c_\theta t.
\end{equation}
Furthermore,
\begin{equation}
 I_\theta(0)=+\infty.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:19:06.721730+00:00","domain":"probability theory","id":"claim_1ea0ae358e37584eb81de78ce62dfa2e6243463f9aabcd3275b9fb382501dc00","kind":"concept","schema_version":1,"statement":"[Theorem thm2.2 of arXiv:2606.01944, 'Propagation of Chaos for Mean-field Mean Reflected Backward Stochastic Differential Equati'] Under Assumptions (H1)-(H4), the mean-field mean reflected BSDE associated with $(\xi,f,h)$ admits a unique solution $(Y,Z,K)\in \mathcal{S}^2\times\mathcal{H}^2\times I[0,T]$. Moreover, for each $t\in[0,T]$, we have 
 \begin{align*}
     K_T-K_t=\sup_{s\in[t,T]}L_s(\bar{Y}_s), 
 \end{align*}
 where
 \begin{align*}
\bar{Y}_s:=\mathsf{E}\left[\xi+\int_s^T f(r,Y_r,\mathsf{E}[Y_r],Z_r,\mathsf{E}[Z_r])ds\Big|\mathcal{F}_s\right].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:04.990695+00:00","domain":"probability theory","id":"claim_1ea33c84428bd863a81e15f420a460c9f6cf406d958a6cff9c0326c8876f1e30","kind":"theorem","schema_version":1,"statement":"[Theorem 17 of arXiv:2604.00882, 'On some extensions of generalized counting processes'] The probabilities ${p}^{\alpha,\rho}_n(t)=\Prob\{N(\mathcal{L}^{\alpha,\rho}(t))=n\}$ satisfy the following  equation
	\begin{equation}
		\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right) p_n^{\alpha,\rho}(t) = -\lambda(p_n^{\alpha,\rho}(t) - p_{n-1}^{\alpha,\rho}(t)), \quad n \ge 0,
	\end{equation}
	with the standard initial condition, and  the probability generating function $
	{G}_{\alpha,\rho}(u, t)$, $|u| \leq 1$, solves the equation
	\begin{equation*}
		\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right) G_{\alpha,\rho}(u, t) = \lambda(u - 1)G_{\alpha,\rho}(u, t), 
	\end{equation*}
	with $G_{\alpha,\rho}(u, 0) = 1$; the generalized fractional derivatives  in the C-D sense are defined in \eqref{exfDt}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:26:20.445899+00:00","domain":"probability theory","id":"claim_1ea8d8391a8baab5e91c8a1939109929528864767f6aa000b59066353a27bd8d","kind":"definition","schema_version":1,"statement":"[Defn embedded-map of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] An \textbf{embedded map} is a pair $M = (m,\psi)$ where
\begin{enumerate}
	\item $m=\{m_1,\dots,m_r\}$ is a multiset of $r$ maps (with or without boundary and of any genus) with the following two properties (see the top of Figure~(fig-embedded-maps-exemp of the paper)):
	\begin{enumerate}
		\item[(1a)] The dual graph of each component of $m$ is bipartite. The faces of $m$ in one partite class are called \textbf{blue faces} and those in the other class are called \textbf{yellow faces}.
		\item[(1b)] The external faces of each component of $m$ with boundary are yellow faces.
	\end{enumerate}
	We call a multiset of maps (with or without boundary and of any genus) with these two properties a \textbf{YB-bipartite maps family}.
	\item $\psi:m \to \Lambda$ is a graph homomorphism  with the following two properties (see the bottom of Figure~(fig-embedded-maps-exemp of the paper)):
	\begin{enumerate}
		\item[(2a)] $\psi$ sends each internal yellow face of $m$ isomorphically to an unoriented plaquette of $\Lambda$,
		\item[(2b)] $\psi$ sends each blue face of $m$ to a single unoriented edge of $\Lambda$.
	\end{enumerate}
	We call a graph homomorphism $\psi:m \to \Lambda$ with these two properties a \textbf{lattice embedding} of $m$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.828791+00:00","domain":"probability theory","id":"claim_1ea90d770eaa6a57661259393b090a87aa4076db06bc410890a2f23e2ae20746","kind":"theorem","schema_version":1,"statement":"[Theorem thm:discrete-bound of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Equip $T^{(m)}(\mathbb{R}^d)$ with the projective tensor norm summed over levels. Let
\begin{equation}
V=\sum_{i=1}^n\left\lVert z_i\right\rVert,
\qquad
\delta=\max_i\left\lVert z_i\right\rVert.
\end{equation}
Then
\begin{equation}
\norm{S_m^{\rm PL}(z)-S_m^{\rm disc}(z)}
\le
\exp(2V)\sum_{i=1}^n\sum_{k=2}^{m}\frac{\left\lVert z_i\right\rVert^k}{k!}.
\end{equation}
If $\delta\le 1$, then
\begin{equation}
\norm{S_m^{\rm PL}(z)-S_m^{\rm disc}(z)}
\le
\exp(2V+1)\,\delta V.
\end{equation}
In particular, for increments of a Lipschitz path sampled on a mesh of size $\Delta$, with $\left\lVert z_i\right\rVert\le L\Delta$, the error is $O(\Delta)$ at fixed total variation.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.214548+00:00","domain":"probability theory","id":"claim_1eb6892827cb4396bd3bff2c02ef1e78d28252c56c8403e14483f37263ce701d","kind":"concept","schema_version":1,"statement":"[Lemma lem:asympbiasvar of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{Steady state Bias-Variance}. Suppose assumptions (ass:Astable of the paper) and (ass:eigsymmA of the paper) holds along with $\mathbb{E}[\varepsilon_0] = 0$ and $C_0 = C_\infty$ where $C_\infty$ satisfies
\begin{align}

	0 = GC_\infty + C_\infty G^\top + \Sigma -rC_\infty H^\top \Xi^{-1} H C_\infty.
\end{align}
For $\nu_t, E_t$ as defined in (equation eq:defnnut of the paper) and (equation eq:defnEt of the paper) respectively,  $\nu_t \rightarrow \nu_\infty$ and $E_t \rightarrow E_\infty$ as $t \rightarrow \infty$, where
\begin{align}

	\nu_\infty &= \| A_\infty^{-1} b \|^2 \\


	E_\infty &=  \text{Tr}\left[ (\Sigma + (r-s) \left( G - A_\infty \right)C_\infty  - 2A_\infty^{-1} b b^\top) X_\infty \right] \\

    & \leq -\frac{1}{\alpha(A_\infty + A_\infty^\top)} \left( - 2 \text{Tr}[A_\infty^{-1}b b^\top] + \text{Tr}[\Sigma] + (r-s)^2 \alpha(H^\top \Xi^{-1}H) \|C_\infty\|_F\right)
\end{align}         
where $X_\infty$ is the unique solution of the Lyapunov equation  
\begin{align*}
	A_\infty^\top X_\infty + X_\infty A_\infty + I = 0.  
\end{align*}
In the scalar case $m=n=1$, $\nu_\infty$ and $E_\infty$ can be characterised entirely in terms of the system parameters $G, H, \Sigma, \Xi, b$, 
\begin{align}

	\nu_\infty &= \left(\frac{b}{A_\infty(r,s)} \right)^2 \\

	E_\infty = \tilde{P}_\infty &=  - \frac{1}{2}\left(\Sigma + \left( \frac{G - A_\infty(r,s)}{H} \right)^2 \Xi  \right)  \frac{1}{A_\infty(r,s)}  + \left(\frac{b}{A_\infty(r,s)} \right)^2
\end{align}
where 
\begin{align}

	A_\infty(r,s) &=  \frac{s}{r} G + \frac{(r-s)}{r} A_\infty(r,0) \\
	A_\infty(r,0) &= -\sqrt{G^2 + rH^2 \Xi^{-1} \Sigma}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.186880+00:00","domain":"probability theory","id":"claim_1eb74cb427407b4c1894b93609662fdf5926b7f4e81cf487fa805b906f31435f","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$ and $v_1,v_2,v_3\in \widetilde{\mathbb{Z}}^d$ with $|v_i-v_j|\ge d$ for all $i\neq j$, 
	\begin{equation}
		\bar{\mathbf{e}}_{v_1,v_2}(\{\widetilde{\eta}: v_3\in \mathrm{ran}(\{\widetilde{\eta}) \}) \lesssim \tfrac{|v_1-v_3|^{2-d}|v_3-v_2|^{2-d}}{|v_1-v_2|^{2-d}}. 
