{"assumptions":[],"created_at":"2026-10-27T12:13:31.923706+00:00","domain":"probability theory","id":"claim_1ee0a3f9339c8a1bab145b54f62e6e1fa1c7d49af76f3da86a93d36ad67ad5dd","kind":"concept","schema_version":1,"statement":"[Thm KP_generating_function of arXiv:2506.12171, 'The multinomial dimer model'] {KenyonPohoata}}]
