{"assumptions":[],"created_at":"2026-10-27T14:09:34.506830+00:00","domain":"probability theory","id":"claim_1fe611c956664b5cd3fdd9e8874a1d06e62820727b6fbe3c735503721ec30c34","kind":"definition","schema_version":1,"statement":"[Defn Radial ground solutions with spin of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] For each radial link pattern $\alpha$, we choose Pochhammer contours $\mathcal{C}_1, \ldots, \mathcal{C}_n$ along which to integrate out the $\boldsymbol{\xi}$ variables. The integration is well-defined since the conformal dimension of $\Phi_\kappa(\boldsymbol{z}, \boldsymbol{\xi},u)$ is 1 at the $\boldsymbol{\xi}$ points, i.e. since $\lambda_b(-2 a)=1$. This leads to a new function of $\boldsymbol{z}$ defined by
\begin{equation}
\mathcal{J}^{(m, n,\eta)}_{\alpha}(\boldsymbol{z},u):=\oint_{\mathcal{C}_1} \ldots \oint_{\mathcal{C}_m} \Phi_\kappa(\boldsymbol{z}, \boldsymbol{\xi},u) d \xi_m \ldots d \xi_1 .
\end{equation}

In angular coordinates, we obtain 
\begin{equation}
\mathcal{J}^{(m, n,\eta)}_{\alpha}(\boldsymbol{\theta}):=\oint_{\mathcal{C}_1} \ldots \oint_{\mathcal{C}_m} \Phi_\kappa(\boldsymbol{\theta}, \boldsymbol{\zeta}) d \zeta_m \ldots d \zeta_1 .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.440991+00:00","domain":"probability theory","id":"claim_1ff2c81d18e7dfe51a889cdf7a934d98489acdf036f9a7bdcab893e65abac628","kind":"lemma","schema_version":1,"statement":"[Lemma lem:vertex_split of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] There exists a map from the set of diagrams   with all unmarked vertices of degree at least $3$ to the set of typical connected diagrams 
\begin{equation}
    \phi : \mathscr{D}_{s;\beta}^* \to \mathcal{T}_{\ell, s}, \quad \Gamma \mapsto \phi(\Gamma)
\end{equation}
  such that  the following three conditions hold: 
\begin{itemize}
    \item[(i)] (Preserving $|E|-|V|$) 
    \begin{equation}
        |E(\phi(\Gamma))| - |V(\phi(\Gamma))| = |E(\Gamma)| - |V(\Gamma)|,
    \end{equation}

    \item[(ii)] (Monotonic decreasing) 
    \begin{equation}
        |E(\phi(\Gamma))| \ge |E(\Gamma)|, \qquad |V(\phi(\Gamma))| \ge |V(\Gamma)|,
    \end{equation}

    \item[(iii)] (Multiplicity controlling)  
       \begin{equation}
        |\phi^{-1}(\Gamma)| \le 2^{|E(\Gamma)|},\quad \forall \,\Gamma \in \mathcal{T}_{\ell, s}.
    \end{equation}

\end{itemize}","status":"unverified"}

