			N
			\wedge
			\inf\left\{
			t\ge0:
			\|v_n^{(R)}(t)\|_{H^s}
			\vee
			\|v_m^{(R)}(t)\|_{H^s}
			\ge N
			\right\},
			\quad n,m\ge1,\quad N\ge1.
			\]
			Then, for every $N>0$,
			\begin{equation}

				\lim_{n\to\infty}
				\sup_{m\ge n}
				\E\left[
				\sup_{t\in[0,\tau_N^{n,m}(R)]}
				\|v_n^{(R)}(t)-v_m^{(R)}(t)\|_{H^\theta}^2
				\Big|\F_0
				\right]
				=
				0.
			\end{equation}

			\item
			There exists an $\mathcal F_t$-progressively measurable $H^s$-valued process
			$v^{(R)}=(v^{(R)}(t))_{t\ge0}$
			satisfying, for every $T>0$,
			\begin{equation}

				\E\left[
				\sup_{t\in[0,T]}
				\|v^{(R)}(t)\|_{H^s}^2
				\Big|\F_0
				\right]
				\le
				2\|v_0\|_{H^s}^2
				\exp\left\{
				C
				\Big(
				1+2R
				+\|\partial_xv_0\|_{L^\infty}
				+\|\mathcal H\partial_xv_0\|_{L^\infty}
				\Big)T
				\right\}.
			\end{equation}
			Moreover, for a subsequence of $\{v_n^{(R)}\}_{n\ge1}$, still denoted by
			$\{v_n^{(R)}\}_{n\ge1}$, and for every $s'\in[\theta,s)$,
			\begin{equation}

				\lim_{n\to\infty}
				\sup_{t\in[0,T]}
				\|v_n^{(R)}(t)-v^{(R)}(t)\|_{H^{s'}}
				=
				0,
				\quad
				T>0.
			\end{equation}
		\end{enumerate}","status":"unverified"}

