    \begin{align}
         \mathbb{P}(|F_{A,\varepsilon} |\ge z)\le  C\exp\Big(-\frac{cz^2}{\varepsilon^2 |A|}\Big)\quad \text{and}\quad \mathbb{P}(|F_{A,\varepsilon} -F_{B,\varepsilon}|\ge z)\le C\exp\Big(-\frac{cz^2}{\varepsilon^2 |A  \ominus B|}\Big),
