{"assumptions":[],"created_at":"2026-10-28T00:32:56.084242+00:00","domain":"probability theory","id":"claim_2819bc640921024e62b98e741c2154016b8f7c19f8fe59b976bb8baaee12d961","kind":"theorem","schema_version":1,"statement":"[Theorem CompTheorem1 of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Let  $(V^i)_{i\in \mathcal{Z}}$ be the state-wise prospective reserves of  a canonical insurance model $(\alpha, \Lambda, \Phi, B, b)$.  Let  $\mathcal{Z}_0 \subset \mathcal{Z}$  and $\mathcal{Z}_1 = \mathcal{Z} \setminus \mathcal{Z}_0$ be any decomposition of the state space. 
	\begin{itemize}
		\item[(a)] \textbf{Irrelevant initial distribution:}   $(V^i)_{i\in \mathcal{Z}}$ is invariant with respect to  $\alpha$. 
		\item[(b)] \textbf{Irrelevant states:} Suppose that $\Lambda^{ij}=0$ for all $i \in \mathcal{Z}_0$, $j \in \mathcal{Z}_1$. Then $(V^i)_{i\in \mathcal{Z}_0}$ is invariant with respect to $b^{ij}$, $i \in \mathcal{Z}_0$, $j \in  \mathcal{Z}_1$, and $B^i$, $b^{ij}$, $\Lambda^{ij}$, $i \in \mathcal{Z}_1$, $j \in  \mathcal{Z}$, $i \neq j$.
	\item[(c)] \textbf{Irrelevant transition rate:} Suppose that  $b^{kl}+V^k-V^l=0$. Then $(V^i)_{i\in \mathcal{Z}}$  is invariant with respect to any changes of  $\Lambda^{kl}$  that preserve the reset points of $\Lambda^{k \raisebox{-0.25ex}{\scalebox{1.4}{$\cdot$}}}$. 
	\item[(d)]  \textbf{Shortened cash-flow:} Suppose that $\Lambda^{ji}=0$ for all $i \in \mathcal{Z}_0$, $j \in \mathcal{Z}_1$. 
	 Then $(V^i)_{i\in \mathcal{Z}_0}$ is invariant with respect to the modification 
	 \begin{align*}
	 	\bar b^{ij} &= b^{ij}+V^j,\quad i \in \mathcal{Z}_0,\, j \in \mathcal{Z}_1,\\
	 	\bar B^j &=0, \quad  j \in \mathcal{Z}_1, \\
	 	 \bar b^{ij} &= 0, \quad  i,j \in \mathcal{Z}_1, \, i \neq j .
	 \end{align*}
	\item[(e)]  \textbf{Cemeteries:} Suppose that $\Lambda^{ji}=0$, $b^{ij} = 0$, $B^j = 0$, and $b^{jk} = 0$ for all $i\in\mathcal{Z}_0$, $j,k \in \mathcal{Z}_1$, $k \neq j$. Further, suppose that $\Delta \Lambda^{i\ell} \leq 0$ for all $i,\ell \in \mathcal{Z}_0$, $\ell \neq i$, and $\Delta \Lambda^{ij} \geq 0$ for all $i\in\mathcal{Z}_0$, $j \in \mathcal{Z}_1$. Then $(V^i)_{i\in\mathcal{Z}_0}$ is invariant with respect to the changes {
	\begin{align*}
	\bar{\Phi}^i(\mathrm{d}t) &= \Phi^i(\mathrm{d}t) + \big(1+\Delta R^i(t)\big) \sum_{j \in \mathcal{Z}_1}\Lambda^{ij}(\mathrm{d}t), \quad  i \in \mathcal{Z}_0,\\
	\bar{\Lambda}^{ij} &= 0, \quad j\in\mathcal{Z}_1, \quad  i \in \mathcal{Z}_0,\\
	\bar{B}^i(\mathrm{d}t) &= B^i(\mathrm{d}t) - \Delta B^i(t)  \sum_{j \in \mathcal{Z}_1} \Lambda^{ij}(\mathrm{d}t), \quad  i \in \mathcal{Z}_0.
	\end{align*}}
	 		\item[(f)] \textbf{Reserve-dependent payments:}  {Suppose for $k,l \in \mathcal{Z}$, $k \neq l$, that
		 	\begin{align*} 
			b^{kl}&=a_0+ a_1 (V^k -V ^l), \\
			B^k(\mathrm{d} t) &= A_0(\mathrm{d} t ) +  V^k(t-) A_1(\mathrm{d} t)
			\end{align*}
			 for $\mathcal{F}^-$-adapted, jointly measurable processes $a_0, a_1, A_0,A_1$ such that
			 \begin{itemize}
			 \item $0 \leq a_1 \leq c_1 < 1$ and $0 \leq a_0 \leq c_2$ for deterministic constants $c_1$ and $c_2$,
			 \item $A_0,A_1 \in \mathbb{Y}$, $\Delta (\Phi - A_1) > -1$, and $\inf_{\omega \in \Omega} \big(R(\omega)-A_1(\omega)\big)$ is bounded on compacts.
			 \end{itemize}
			 Then $(V^i)_{i\in \mathcal{Z}}$  is invariant with respect to the changes
			 \begin{align*} 
			 \bar b^{kl}&=a_0/(1-a_1),\\
			 \bar B^k &= A_0,\\
			 \bar \Lambda^{kl}(\mathrm{d} t) &=(1-a_1(t)) \Lambda^{kl}(\mathrm{d} t),\\
			  \bar \Phi^k &=  \Phi^k - A_1. 
			\end{align*}}
	\end{itemize}","status":"unverified"}

