    \end{cases}
    \]
    The function \(f_0\) is defined for all \(t\geq 0\), and \(f_\ell\) is defined for all \(t\geq 0\) small enough so that \(f_{\ell-1}(t)\leq (\frac{\emm^{dp_\bad-1}}{dp_\bad})^{1/D}\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.856031+00:00","domain":"probability theory","id":"claim_29d9711f25ab7e8784290abfebdac6667af3abb998a8950588e8c5a065646167","kind":"theorem","schema_version":1,"statement":"[Proposition 21 ($H^1$-energy estimate) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d\in \{3,4\}$, $u_0\in L^0_{\F_0}(\Omega;H^1(\sO))$, and suppose that Assumption~\ref{assumption_weakened_setting} holds. Let $(u,\sigma)$ be the unique maximal solution to \eqref{eq:SCHtorus} and $(\sigma_m)_{m\ge 1}$ a localising sequence for $(u,\sigma)$. Let $C_\psi$ denote a constant that depends on the constants in Assumption~\ref{assumption_weakened_setting}. Then we have for all $t\in[0,T]$  $\mathbb{P}$-a.s.
    \begin{equation}
    \begin{aligned}
    \frac{1}{2}|u(t \land \sigma_m)|^2_{H^1}
    &\le \frac{1}{2}|u_0|^2_{H^1}
    - \inttm \intsO |\grad \Delta u|^2 \dx \ds
    + \inttm \intsO  (3u^2 \grad u- \grad u) \cdot \grad \Delta u \dx \ds  \\
    &\phantom{\le } + M_{t\land\sigma_m}
    +  C_\psi\inttm  \intsO  (1+|u|^2+|\grad u|^2 + |u|^2|\grad u|^2) \dx \ds  + C_\psi \inttm   |u|_{H^2}^2 \ds
    \end{aligned}
    \end{equation}
    for a continuous local martingale  $M$ with quadratic variation $[M]$ which satisfies for all $t\in[0,T]$  and $\varepsilon>0$
    \begin{equation}

    \begin{aligned}
    \E\big[ [M]^{1/2}_{t\wedge \sigma_m}\big] & \leq \varepsilon \E\bigg[\sup_{s\in[0,t\wedge \sigma_m]}  \|\grad u(s) \|^2_{L^2} \bigg]  +  \frac{C_\psi}{4\varepsilon}\E\Big[ \inttm  \intsO(1+|u|^2+|\grad u|^2 + |u|^2|\grad u|^2)\dx\ds\Big] \\
    &  \quad + \frac{C_\psi}{4\varepsilon}\E\Big[ \inttm  |u|_{H^2}^2 \ds\Big].
    \end{aligned}
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:35:10.781120+00:00","domain":"probability theory","id":"claim_29da8b659399ebd1a512a59c87eeb6c86d84a088f06b73fa64f7d1dd945f62d5","kind":"lemma","schema_version":1,"statement":"[Lem 8 of arXiv:2603.29549, 'Multitype PCR branching processes'] Let $H$ be the limit in \eqref{Hx}. Then as $n\to \infty$,
