{"assumptions":[],"created_at":"2026-10-28T00:48:45.305644+00:00","domain":"probability theory","id":"claim_2bd614b0d2ccce9e2a85350472d288339f548ee37f6103ae76d71463c17808dc","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] \mbox{}
            \begin{enumerate}

                \item  Suppose that there exist some $\mathbf{q} \in \mathcal{Q}$ {and} $k \in {\mathbb{N}}$ such that $q_{k} > 0$ and the following step-interpolation process, 
                    \begin{align}
                        t \mapsto \frac{1}{n} M^{{\left(0\right)}}_{k}\left(\eta, \left\lfloor n^2 t \right\rfloor \right) - t  \mathbb{E}_{\nu_{\mathbf{q}}}\left[ M^{{\left(0\right)}}_{k}\left( n \right) \right],
                    \end{align} 
                converges weakly {in $D\left([0,\mathbf{T}]\right)$, $\mathbf{T} > 0$} to the centered Brownian motion with variance $G_{k}\left(\mathbf{q}\right)$ under $\nu_{\mathbf{q}}$. Then, {for any $i \in {\mathbb{Z}}$,} the following step-interpolation process 
                    \begin{align}
                        t \mapsto 
                        \frac{1}{n} Y^{{i}}_{k}\left(\eta, \left\lfloor n^2 t \right\rfloor \right) - nt v^{\mathrm{eff}}_{k}\left( \mathbf{q} \right),
                    \end{align}
                also converges weakly {in $D\left([0,\mathbf{T}]\right)$, $\mathbf{T} > 0$} to the centered Brownian motion with variance $D_{k}\left(\mathbf{q}\right)$ under $\nu_{\mathbf{q}}$, where $D_{k}\left(\mathbf{q}\right)$ is given by 
                    \begin{align}
                        D_{k}\left(\mathbf{q}\right) := \frac{v^{\mathrm{eff}}_{k}\left(\mathbf{q}\right)^2 G_{k}\left(\mathbf{q} \right)}{v^{\mathrm{eff}}_{1}\left(\theta^{k-1}\mathbf{q}\right)^2}  + 4\sum_{\ell = 1}^{k-1} \frac{v^{\mathrm{eff}}_{\ell}\left(\mathbf{q}\right)^2 v^{\mathrm{eff}}_{k-\ell}\left(\theta^{\ell}\mathbf{q}\right) \beta_{\ell}\left(\mathbf{q}\right)}{v^{\mathrm{eff}}_{1}\left(\theta^{\ell-1}\mathbf{q}\right)^2},
                    \end{align}
                {and $\beta_{\ell}\left(\mathbf{q}\right)$ is defined in (equation def:beta of the paper)}.

                \item  Suppose that there exist some $\mathbf{q} \in \mathcal{Q}$, $k \in {\mathbb{N}}$ and $i \in {\mathbb{Z}}$ such that $q_{k} > 0$ and the following limit 
                    \begin{align}
                        \Lambda^{M {,i}}_{\mathbf{q},k}\left(\lambda\right) &:= \lim_{n \to \infty} \frac{1}{n} \log\left({\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ \exp\left( \lambda \left(n - M^{{i}}_{k}\left( n \right) \right) \right) \right] \right) \in {\mathbb{R}},
                    \end{align}
                exists for any $\lambda \in {\mathbb{R}}$, and $\Lambda^{M{,i}}_{\mathbf{q},k}\left( \ \cdot \ \right)$ is essentially smooth in the sense of [DZ]. Then, the following limit 
                    \begin{align}
                        \Lambda^{Y{,i}}_{\mathbf{q}, k}\left(\lambda\right) &:= \lim_{n \to \infty} \frac{1}{n} \log\left({\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ \exp\left( \lambda  Y^{{i}}_{k}\left( n \right) \right)  \right] \right) \in {\mathbb{R}} \cup \{\infty\},
                    \end{align}
                exists for any $\lambda \in {\mathbb{R}}$, and $\Lambda^{Y{,i}}_{\mathbf{q}, k}\left(\lambda\right)$ satisfies (equation eq:Lambda_Y of the paper).  In addition, we have   $\sup_{|\lambda| \le \delta} \left| \Lambda^{Y{,i}}_{\mathbf{q},k}\left(\lambda\right) \right| < \infty$ for sufficiently small $\delta > 0$, and
                $\Lambda^{Y{,i}}_{\mathbf{q},k}\left( \ \cdot \ \right)$ is also essentially smooth. Consequently, thanks to the G\"{a}rtner-Ellis theorem (cf. [DZ]), {under $\nu_{\mathbf{q}}$,} the sequence {$\left(Y^{{i}}_{k}\left(n\right) / n\right)_{n \in {\mathbb{N}}}$} satisfies the LDP with the good rate function $I^{Y{,i}}_{\mathbf{q},k}$, where 
                \begin{align}
                    I^{Y{,i}}_{\mathbf{q},k}\left(u\right) := \sup_{\lambda \in {\mathbb{R}}} \left\{ \lambda u - \Lambda^{Y{,i}}_{\mathbf{q},k}\left(\lambda\right) \right\}.
                \end{align}
            \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

