\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:02:11.287435+00:00","domain":"probability theory","id":"claim_2c6df48f8f000a614090e5f65260ad0d3de83788582db1512d5be4722045e341","kind":"theorem","schema_version":1,"statement":"[Theorem eq:mclt2 of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] Let $c_1, c_2 \in \mathbb{R}$ and $p \neq 7/8$ be such that $\lambda^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) < \lambda^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) = - \frac{1}{2}$ almost surely. 
 \begin{itemize}
    \item[i)] The following central limit theorem holds - 
    \begin{align}  &\sqrt{\frac{n}{\log n}}\left\{\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_n - \boldsymbol{\Gamma}^{(p)}\right)\right\} \stackrel{d}{\to} N\left(0, {\Sigma}^{(2)}_{c_1,c_2,p}\right),
    \end{align}
    where
    \begin{align}
        {\Sigma}^{(2)}_{c_1,c_2,p} = c^2_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)^{\top}\sigma\left(\boldsymbol{\Gamma}^{(p)}\right)\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right).
    \end{align}
    \item[ii)] The following law of iterated logarithms holds almost surely -  
    \begin{align}  &\limsup_{n \to \infty}\sqrt{\frac{n}{2\log n\log\log\log n}}\left\{\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_n - \boldsymbol{\Gamma}^{(p)}\right)\right\} \\ = - &\liminf_{n \to \infty}\sqrt{\frac{n}{2\log n\log\log\log n}}\left\{\left(c_1\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_n - \boldsymbol{\Gamma}^{(p)}\right)\right\} \nonumber \\ =\textcolor{white}{+}&\sqrt{{\Sigma}^{(2)}_{c_1,c_2,p}} . \nonumber 
    \end{align}
    \item[iii)] The following quadratic strong law holds almost surely -  
    \begin{align}  &\lim_{n \to \infty} \frac{1}{\log \log n}\sum_{k=2}^n\left(\frac{1}{\log k}\right)^2\left\{\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_k - \boldsymbol{\Gamma}^{(p)}\right)\right.\\ &\hspace{3cm}\times \left.\left(\boldsymbol{\Gamma}_k - \boldsymbol{\Gamma}^{(p)}\right)^{\top}\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)\right\} = {{\Sigma}^{(2)}_{c_1,c_2,p}}. \nonumber
    \end{align}
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:37.361221+00:00","domain":"probability theory","id":"claim_2c738660f031b4f2bbf2c45916c49cfed59cd34d6e01f5d626b3d7a9b7d338be","kind":"concept","schema_version":1,"statement":"[Proposition 28 of arXiv:2606.17859, 'Full $\Gamma-$expansion for the level-two large deviation rate functionals of non-reversib'] Let $\mu_\epsilon$ be the sequence of measures defined in \eqref{q:rev:recov_seq_2}. Then,
