Here, the functions on the left-hand side are coupled according to the patched coupling $\Ppatch$ for the underlying ASEPs in the definition of the patched ASEPs, while the functions on the right-hand side are coupled as in Definition~\ref{def:PeriodicKPZfixed} with respect to the same patched directed landscape $\Lpa$, taking values in $\mathcal{T}$ for the time component.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:35:04.166593+00:00","domain":"probability theory","id":"claim_2d711caac7dc309386d16b2585bbbaf54c4f0c74ba89a2df3103cbfd4d537f60","kind":"concept","schema_version":1,"statement":"[Theorem thLIL2 of arXiv:2608.30848, '\huge \bf Limit Laws of the Iterated Logarithm Under Sub-linear Expectations'] Assume ((eqLILmomentcondition1 of the paper)), ((eqLILmeanzerocondition of the paper)), ((eqLILmomentcondition2 of the paper)), ((eqLILmomentcondition3 of the paper)), and condition (CC) holds for the family of probability measures $\mathscr{P}$. Then
 \begin{description}
   \item[\rm (i)] For any continuous function $\sigma(x_1,x_2,\ldots)$ on $\mathbb R^{\mathbb N}$ taking values in $[\underline{\sigma},\overline{\sigma}]$, there exists $P\in\mathscr{P}$ such that
 \begin{align} 
 P\bigg(Cl\bigg\{\frac{S_n}{\sqrt{2n\log\log n}}\bigg\}=\Big[-\sigma(Y_1,Y_2,\ldots),\sigma(Y_1,Y_2,\ldots)\Big]\bigg)=1,
 \end{align}
 \begin{align}
 &P\bigg(\lim_{n\to \infty} \max_{k\le n} \frac{S_k}{\sqrt{2k\log\log n}}=\sigma(Y_1,Y_2,\ldots) \nonumber\\
 & \qquad \text{and } \lim_{n\to \infty} \min_{k\le n} \frac{S_k}{\sqrt{2k\log\log n}}=-\sigma(Y_1,Y_2,\ldots)\bigg)=1;
  \end{align}
   \item[\rm (ii)] For any finite-dimensional Borel-measurable function $\sigma(x_1,\ldots,x_d)$ taking values in $[\underline{\sigma},\overline{\sigma}]$, there exists $P\in\text{core}(\widehat{\mathbb E})$ such that ((eq:thLIL2:1 of the paper)) and ((eq:thLIL2:2 of the paper)) hold for $\sigma(x_1,x_2,\ldots)=\sigma(x_1,\ldots,x_d)$.
