{"assumptions":[],"created_at":"2026-10-27T13:12:09.045229+00:00","domain":"probability theory","id":"claim_2f00aa8de79bc5c32986170f724b00bf21766f62213a446e2fcc5527dc509ad6","kind":"lemma","schema_version":1,"statement":"[Lemma lem:gaussianTVrate of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let
\begin{equation*}
 Y_{n+1}=MY_n+G\xi_{n+1}
\end{equation*}
be a Gaussian autoregressive process on $\mathbb R^N$, with transition kernel $Q$, where $M\in\mathbb R^{N\times N}$ satisfies $\rho(M)<1$, $G\in\mathbb R^{N\times N'}$, the $\xi_n$ are i.i.d.\ standard Gaussian vectors in $\mathbb R^{N'}$, and the covariance $\Sigma_{n_0}$ of the $n_0$-step transition law is nonsingular for some $n_0\ge1$; this holds in particular when $GG^\top\succ0$, with $n_0=1$. Then the chain has a unique invariant law $\pi$, which is a centered Gaussian. Moreover,
\begin{equation}
 \limsup_{n\to\infty}\lVert \delta_zQ^n-\pi\rVert_{\mathrm{TV}}^{1/n}\le\rho(M)
 \qquad\text{for every initial state }z,
\end{equation}
and the limit exists and equals $\rho(M)$ for a suitable $z$. Finally, there are initial states $z,\widetilde z$ such that
\begin{equation}
 \lim_{n\to\infty}
 \norm{\delta_zQ^n-\delta_{\widetilde z}Q^n}_{\mathrm{TV}}^{1/n}=\rho(M).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.975637+00:00","domain":"probability theory","id":"claim_2f0747e0c81f72e03ab8f4677c10d7233c893095bfa41fc168ca5df15e5ba7cc","kind":"lemma","schema_version":1,"statement":"[Lemma lem:tricks of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For $\varphi\in C^\infty_c(\R^2)$ and $\psi\in C_c^\infty(\R)$, we define $A^\varphi (t_1,t_2,s_1,s_2)\eqdef\delta(t_1-s_1)\delta(t_2-s_2)\varphi(s_1,s_2)$, $B^\varphi(t_1,t_2,s_1)\eqdef\delta(t_1-s_1)\varphi(s_1,t_2)$, and $C^\psi(t_1,t_2,s_1)\eqdef\delta(t_1-s_1)\delta(t_2-s_1)\psi(s_1)$.

    Then, for every $N\geqslant1$, uniformly in $\varphi$, $\psi$ and $\mu\in(0,1]$, we have
    \begin{equs}
        \norm{K_{N,\mu}^{\otimes4}A^\varphi(t_1,t_2,s_1,s_2)}_{L^\infty_{t_1}L^1_{t_2}L^1_{s_1}L^1_{s_2}}&\lesssim \norm{K_{N,\mu}^{\otimes2}\varphi(s_1,s_2)}_{L^\infty_{s_1}L^1_{s_2}}\,,\\      \norm{K_{N,\mu}^{\otimes3}B^\varphi(t_1,t_2,s_1)}_{L^\infty_{t_1}L^1_{t_2}L^1_{s_1}}&\lesssim \norm{K_{N,\mu}^{\otimes2}\varphi(s_1,s_2)}_{L^\infty_{s_1}L^1_{s_2}}\,,\\\norm{K_{N,\mu}^{\otimes3}C^\psi(t_1,t_2,s_1)}_{L^\infty_{t_1}L^1_{t_2}L^1_{s_1}}&\lesssim \norm{K_{N,\mu}\psi(s_1)}_{L^\infty_{s_1}}\,.
    \end{equs}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.299559+00:00","domain":"probability theory","id":"claim_2f158abbabfd214a9f2f05e86725b2c4c29d7123f10f581f5b097f79424aff2f","kind":"definition","schema_version":1,"statement":"[Definition def:results:stationary of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] We say $\nu \in {\mathcal{M}_{\kappa, d}}$ is a \emph{stationary distribution} of the $\kappa$-MLFE{} with potentials $(U, W)$ if $\nu \in \mathcal{Q}_{\kappa, d}$ and there exists a linear growth solution $(\mu^\nu, \gamma)$ to the $\kappa$-MLFE{} on $[0, \infty)$ with potentials  $(U, W)$ and initial condition $\nu$ such that
    \begin{equation}

        \mu^\nu_t = \nu,\quad t \geq 0.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:09:59.300988+00:00","domain":"probability theory","id":"claim_2f1d7fe79b812ded0873e415f91e5042b41810d2556add4c0a8edad6a494c34b","kind":"lemma","schema_version":1,"statement":"[Lem of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] For any $\varepsilon,t,\delta>0$, and an $\alpha$-good potential $V$,
     there exists a local function
    $q_{\varepsilon}:\mathcal{G}_{[0,C],C}\times[0,1]\rightarrow\mathbb{R}^N$ which can be written
    as a finite sum

    \begin{align*}
    \text{\boldmath $q$}_{\varepsilon}(G;\beta) = \sum_{X\in\mathcal{S}} c_X(\beta) \text{\boldmath $t$}(X,G)\, ,
    \end{align*}
    such that $\mathcal{S}$ is a finite set, the coefficients $c_X(\beta)$
    are  polynomials in $\beta$ independent of $G$, and 
    for all $G\in\mathcal{G}_{[0,C],C}$ and $\beta\in[0,1]$, we have (for $K=t/\delta$)

    \begin{align*}
    \left| \frac{1}{N}\mathbb{E}[H(\text{\boldmath $\psi$}^{(K)})] - q_{\varepsilon} (G;\beta) \right| \le \varepsilon.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:14:57.701206+00:00","domain":"probability theory","id":"claim_2f223d627bc1487745ffecef58e063ef8e1aacc35177ef2310fce88b7d042a57","kind":"concept","schema_version":1,"statement":"[Thm main-use-result-cline-hsing of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] Let $\{Y_k\}_{k\geq 1}$ be an i.i.d. family of random variables with common distribution $F$ and $S_n = Y_1 + Y_2 + ...+ Y_n$. Assume that $\mathbb{P}[|Y_1| >x]$ is regularly varying with index $-2$ and $\sup_{x \geq 0} F(-x)/(1-F(x)) <\infty$. Assume $Y_1$ has mean zero\footnote{Note that the mean of $Y_1$ is well defined since the tail of $Y_1$ is regularly varying with index $-2$.} and let $t_n$ be a sequence such that 

    \[ \lim_{n\to \infty} n(1-F(t_n)) = \lim_{n\to \infty} \frac{n \log t_n \mathbb{E}[Y_1^2 1_{|Y_1| \leq t_n }]}{t_n^2}= 0.\]

Then, \[ \lim_{n\to \infty} \sup_{s \geq t_n} \biggl|\frac{\mathbb{P}[S_n >s]}{n (1 - F(s))} -1 \biggr| =0.\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:06:07.097956+00:00","domain":"probability theory","id":"claim_2f2287968a1739bce611cd4e39c25a8f1243b59c54dbfa1cb6189fd62c656ad3","kind":"concept","schema_version":1,"statement":"[Lemma 6 (Upper Bound for the Gaussian Mechanism) of arXiv:2608.28198, 'Performative Privacy: When Differential Privacy Maximizes Utility'] Substituting into Lemma \ref{lemm:Renyi_bound} the Rényi divergence of the Gaussian mechanism \eqref{eq:mecgau} between the outputs with and without the record $z$ conditioned on the entire dataset $Z_t$, namely
\begin{equation*}
D_\alpha(P^{\mathcal{M}}_{\text{in}}(\cdot|Z_t) \parallel P^{\mathcal{M}}_{\text{out}}(\cdot|Z_t))
=
\frac{\alpha N_t}{2\gamma^2 (N_t-1)^2}\|z-\mu_z\|^2
\end{equation*}
(see Lemma~\ref{lemm:tail_bound_gaussian_mech} in Appendix~\ref{app:gaussian_mia_proofs}), the tail bound on the leakage probability for a specific record $z$ specializes to:
\begin{equation}
    \Pr_{o_t \sim P^{\mathcal{M}}_{\text{in}}}(\Lambda(o_t|z) > \tau \mid Z_t)
    \le
    \exp \left(
    -(\alpha - 1)
    \left(
    \tau -
    \frac{\alpha N_t\|z-\mu_z\|^2}
    {2\gamma^2 (N_t-1)^2}
    \right)
    \right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:17:04.325262+00:00","domain":"probability theory","id":"claim_2f344a1c7a937a1f661a9532af5c904c3319969a4a9d11972817a982c690053a","kind":"theorem","schema_version":1,"statement":"[Proposition of arXiv:2606.01866, 'Phase Transition of a Semiflexible Membrane in Two Dimensions'] \label[proposition]{thm:fractionalnorm}
