\end{enumerate}
Then,
\[
\lim_{\delta\downarrow 0}\limsup_{n\to\infty}\mathbb P\pp{\sup_{\substack{s,t\in[0,1]\\
|t-s|\le \delta}}|G_n(t)-G_n(s)|\ge 9\eta\sigma_n}   = 0 \mbox{ for all } \eta>0.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

