{"assumptions":[],"created_at":"2026-10-26T19:44:17.162041+00:00","domain":"probability theory","id":"claim_3359b37b0d4f8210d83d08f93afecbba4e5941d97ced5d37879aa52150db52c0","kind":"concept","schema_version":1,"statement":"[Theorem 8 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Consider Scenario~\eqref{Scenario_1}. Assume that \eqref{contraction_criterion_H_{0}} holds, or that $g\in\mathcal{C}^{(1)}(\mathcal{S})$ and \eqref{contraction_criterion_g} holds. Let
\begin{equation}
\alpha^{*}=\frac{\partial H_{0}}{\partial x}\Big|_{(x^{*},y^{*})}, \quad \beta^{*}=\frac{\partial H_{0}}{\partial y}\Big|_{(x^{*},y^{*})}, \quad \rho=\min\left\{1,1-q_{1}\alpha^{*}+q_{2}\beta^{*}\right\}, \quad z^{*}=\frac{(1-q_{1})x^{*}}{q_{1}},
\end{equation} 
where $(x^{*},y^{*})$ is the unique root of $h$ in $\mathcal{S}$. We now define the matrices
\begin{equation}
\Gamma=\begin{bmatrix}
x^{*}(1-x^{*}) & -x^{*}y^{*} & -x^{*}z^{*}\\
-x^{*}y^{*} & y^{*}(1-y^{*}) & -y^{*}z^{*}\\
-x^{*}z^{*} & -y^{*}z^{*} & z^{*}(1-z^{*})
\end{bmatrix}, \quad T=\begin{bmatrix}
-\beta^{*} & 0 & -q_{1}\\
\alpha^{*} & 0 & q_{2}\\
0 & 1 & -1+q_{1}
\end{bmatrix}, \quad \overline{T}=\begin{bmatrix}
-q_{1} & -1/\alpha^{*} & 0\\
q_{2} & 0 & 0\\
-1+q_{1} & 0 & 1
\end{bmatrix}.
\end{equation}
Next, we define, writing $\kappa=q_{1}\alpha^{*}-q_{2}\beta^{*}$ for the sake of brevity:
\begin{align}
