{"assumptions":[],"created_at":"2026-10-27T13:12:09.051109+00:00","domain":"probability theory","id":"claim_3392cd5173f905f2483f1f41ba4e79b9df5199cffdb140d77e0b81cfd82661d7","kind":"lemma","schema_version":1,"statement":"[Lemma lem:drift of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $\mathsf M\in\mathbb R^{d_1\times d_1}$ satisfy $\rho(\mathsf M)<1$, let $\mathsf G\in\mathbb R^{d_1\times d_2}$, and let $F:\mathbb R^{d_1}\times\mathbb R^{d_2}\to\mathbb R^{d_1}$ be continuous with $B:=\sup_{z,\xi}\lvert F(z,\xi)\rvert<\infty$. Let $(\xi_k)_{k\ge1}$ be independent $\mathcal N(0,\mathrm{Id}_{d_2})$ variables, and consider the Markov chain on $\mathbb R^{d_1}$ defined by
\begin{equation}
 Z_{k+1}=\mathsf MZ_k+\mathsf G\xi_{k+1}+F(Z_k,\xi_{k+1}),
 \qquad k\ge0.
\end{equation}
Then the chain admits an invariant probability law $\pi$ satisfying
\begin{equation}
 \int\lvert z\rvert^2\,\pi(dz)
 \le8\lVert P\rVert^3\bigl(\operatorname{tr}(\mathsf G\mathsf G^\top)+B^2\bigr),
 \qquad
 P:=\sum_{j=0}^\infty(\mathsf M^\top)^j\mathsf M^j.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:45.028958+00:00","domain":"probability theory","id":"claim_3394a683735697ed1f114a4a15af66dfdd36a547fb8c365fc79a0cd2f96cfe41","kind":"theorem","schema_version":1,"statement":"[Theorem 4 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $W^\beta$ be an isotropic $\beta$-stable process with $\beta\in (0,2)$, $\kappa>0$ and let $u\in L^\infty([0,1];C^\alpha(\T^d))$ with\footnote{Compared to the majority of the literature on the topic, the notations for $\alpha$ and $\beta$ in~\eqref{eq:condition_stable_SWP} are reversed.}
    \begin{equation}
        \alpha>1-\frac{\beta}{2}.
    \end{equation}
    Then, for any $x\in\T^d$, there exists a strong, pathwise unique solution to the SDE
    \begin{equation}
        X^\kappa_t = x + \int_0^t u(r,X^\kappa_r) \dd r + \kappa W^\beta_t
    \end{equation}
    and the SDE admits a stochastic flow of diffeomorphisms $\{X^\kappa_{s,t}(x,\omega)\}$.
    Furthermore, for any $\mu_0\in\mathcal{M}(\T^d)$, the map
    \begin{equation}
        \mu^\kappa_t:=\E\big[(X^\kappa_{0,t})_\sharp \mu_0\big] \quad\forall\, t\in [0,1]
    \end{equation}
    is the unique solution in $C_w([0,1];\mathcal{M}(\T^d))$ (in the weak sense) to the PDE
    \begin{equation}
        \partial_t \mu^\kappa + \nabla\cdot (u\, \mu^\kappa) = - \kappa^\beta |\nabla|^\beta \mu^\kappa,\quad\mu^\kappa\vert_{t=0}=\mu_0.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.662787+00:00","domain":"probability theory","id":"claim_33955a2c60a13c6e6c9ce8d72e03538ebb83568d8c36f1465ce2b2bb5a8d6e1b","kind":"concept","schema_version":1,"statement":"[Lemma 38 (Support convergence from a uniform lower mass bound) of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] Let $\mu_n,\mu$ be finite Borel measures on $\R^d$ with
