      \end{eqnarray}
     and
             \begin{eqnarray}

            \partial^2_s \mathcal U^{h_0}_{q;a,b,c}(s+\mathfrak l_{q;a,b,c}(h_0))=\gamma''_s+\hat{\mathcal O}((\me_{z_s;q}/\md_{z_s})^{1/2})+\mathcal O((\me_{z_s;q}\md_{z_s})^{1/2}),
