{"assumptions":[],"created_at":"2026-10-27T07:58:01.571989+00:00","domain":"probability theory","id":"claim_35a921d25d8693219bc2c1a4896313445837908503ad846274f2d981b63033b3","kind":"lemma","schema_version":1,"statement":"[Lemma 23 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then there exist constants $\eps_*>0$ and $c,C>0$ such that
        \begin{align}
                \inf_{\substack{|z-E_*|<\eps_*  \\ \Im z>0}}|z+g(z)|\geq c,
                \qquad
                \sup_{\substack{|z-E_*|<\eps_*  \\ \Im z>0}}\|\Pi(z)\|\leq C. \nonumber
        \end{align}
        Moreover,
        \begin{align}
                \|\Pi(z_1)-\Pi(z_2)\| \leq C|z_1-z_2|^{1/3} \nonumber
        \end{align}
        for all $z_1,z_2\in\C^+$ satisfying $|z_1-E_*|,|z_2-E_*|<\eps_*$. Consequently, $\Pi$ extends uniquely and continuously to $\{z\in\C:|z-E_*|<\eps_*,\ \Im z\geq0\}$.
        In particular,
        \begin{align}
                \Pi(E_*) := \lim_{\eta\downarrow0}\Pi(E_*+\ii\eta) 
        \end{align}
        is well defined and is a real symmetric invertible matrix.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:23:58.621873+00:00","domain":"probability theory","id":"claim_35b0108f7c05e2f13102db1e7ad77a5c836ca2deb4d3c680ee7d43837ed66ebd","kind":"definition","schema_version":1,"statement":"[Definition 183 (Projection onto $\nullhyparg{u}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill
	\begin{enumerate}
		\item We define the type $\binom{1}{1}$ projection tensorfield $\Nullhypersurfaceproject$
		onto the characteristic hypersurfaces $\nullhyparg{u}$ as follows,
		where $\updelta_{\beta}^{\ \alpha}$ denotes the Kronecker delta and $\gfour(\Lunit,\uLunit) = - \MagnitueofinnerproductofLunitanduLunit$ is given as in \eqref{E:DEFOFINNERPRODUCTOFLUNITANDULUNIT}: 
		\begin{align}
			\Nullhypersurfaceproject_{\beta}^{\ \alpha}
			& 
			\eqdef 
			\updelta_{\beta}^{\ \alpha}
			+
			\frac{1}{\MagnitueofinnerproductofLunitanduLunit}
			\uLunit^{\alpha}
			\Lunit_{\beta}   \\
			& = 	\updelta_{\beta}^{\ \alpha}
			+
			\frac{1}{\MagnitueofinnerproductofnewLandnewuL}
			\newuL^{\alpha}
			\newL_{\beta} 
		\end{align}
		\item Given any type $\binom{m}{n}$ spacetime tensorfield $\upxi$, 
		we define its $\nullhyparg{u}$-projection $\Nullhypersurfaceproject \upxi$ 
		as follows:
		\begin{align}
			(\Nullhypersurfaceproject \upxi)_{\beta_1 \cdots \beta_n}^{\alpha_1 \cdots \alpha_m}
			& 
			\eqdef 
			\Nullhypersurfaceproject_{\widetilde{\alpha}_1}^{\ \alpha_1}
			\cdots 
			\Nullhypersurfaceproject_{\widetilde{\alpha}_m}^{\ \alpha_m}
			(\gfour^{-1})^{\widetilde{\beta}_1 \widetilde{\gamma}_1}
			\gfour_{\beta_1 \gamma_1}
			\Nullhypersurfaceproject_{\widetilde{\beta}_1}^{\ \gamma_1}
			\cdots 
			(\gfour^{-1})^{\widetilde{\beta}_n \widetilde{\gamma}_n}
			\gfour_{\beta_n \gamma_n}
			\Nullhypersurfaceproject_{\widetilde{\beta}_n}^{\ \gamma_n}
			\upxi_{\widetilde{\gamma}_1 \cdots \widetilde{\gamma}_n}^{\widetilde{\alpha}_1 \cdots \widetilde{\alpha}_m}.

		\end{align}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:35:10.780237+00:00","domain":"probability theory","id":"claim_35b3156608fef8e292af7501c2687ecdc0ba9db3dd5a57050f70f9fb0046bdb1","kind":"theorem","schema_version":1,"statement":"[Proposition 2 of arXiv:2603.29530, 'LINEAR RISK SHARING IN COMMUNITY-BASED INSURANCE: RUIN REDUCTION IN THE COMPOUND POISSON M'] Assume that, for every admissible sharing matrix $\Avec$, the convex-order comparison
\begin{equation}
    Z_i \lcx Y_i'
    \qquad\text{holds for all } i=1,\ldots,n,

\end{equation}
with $Z_i$ and $Y_i'$ defined by \eqref{BeyondScaleFamilies-Section4-Equation2} and
\eqref{BeyondScaleFamilies-Section4-Equation3}. Then, for every pair $(i,j)$ such that
$b_i\le b_j$,
\begin{equation}
    \frac{Y_j}{b_j}\lcx\frac{Y_i}{b_i}.

\end{equation}
Equivalently, if $b_{(1)}\le \cdots \le b_{(n)}$ denote the ordered means, then
\begin{equation}
    \frac{Y_{(n)}}{b_{(n)}}\lcx     \frac{Y_{(n-1)}}{b_{(n-1)}}\lcx    \cdots \lcx    \frac{Y_{(1)}}{b_{(1)}}.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:04.992372+00:00","domain":"probability theory","id":"claim_35b34d88dd2ab16f3d03836fc022046f6976f43c60bc695a41639b2dee8b9d74","kind":"concept","schema_version":1,"statement":"[Lemma 8 of arXiv:2604.01257, '2604.01257'] Under the conditions of {\hyperref[IIBLem4]{Lemma}~\ref{IIBLem4}} the ration function
