    \end{align*}
    and $\mathcal{M}$ is the set of minimizers of $I_{\gamma}[-,\hat{h}]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:48:24.321089+00:00","domain":"probability theory","id":"claim_3651065282f50365a5b102b8ab1005d8da1c610a124acd9068c6ac76a30f15a0","kind":"concept","schema_version":1,"statement":"[Lemma lem:exp prof of conv power of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $Q_{n}$ be a polynomial with real nonnegative roots of the form \begin{equation}
			Q_{n}(z)=\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}b_{k,n}^nz^k
		\end{equation} and suppose for every $u\in (0,1)$ \begin{equation}
			\lim\limits_{n\rightarrow\infty} b_{\lfloor un\rfloor,n}=e^{\tilde{g}(u)}
		\end{equation} for some function $\tilde{g}:(0,1)\rightarrow\mathbb{R}$. Then, $\llbracket Q_{n}\rrbracket$ converges weakly to the probability measure $\mu$ on $[0,\infty)$ with $S$-transform \begin{equation}
