{"assumptions":[],"created_at":"2026-10-26T19:32:15.350027+00:00","domain":"probability theory","id":"claim_36d4eda69daa7c7e5769c6153dbca00c3cc1264b1559a533a0464b209522655d","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2506.15736, 'Coming down from infinity for coordinated particle systems'] Fix a finite set of sites $V$, and let $\Lambda_v, D_v, M_{uv}$, and $R_{uv}$ be finite measures on $[0,1]$ for $u,v \in V$. Then there exists a probability space on which for each $\pi \in \mathcal{P}$ there exists a c\`adl\`ag Markov process $(X_\pi(t))_{t \geq 0}$ called the coordinated particle system with the following properties:

    \begin{enumerate}
        \item[(a)] $(X_\pi(t))_{t \geq 0}$ takes values in $\mathcal{P}$ and $X_\pi(0) = \pi$.

        \item[(b)] If $\pi_1, \pi_2 \in \mathcal{P}$ with $\pi_1 \leq \pi_2$, i.e. $\pi_1(v) \leq \pi_2(v)$ for all $v \in V$, then $X_{\pi_1}(t) \leq X_{\pi_2}(t)$ for all $t \geq 0$.

        \item[(c)] If $|\pi| < \infty$, i.e. $\sum_{v \in V} \pi(v) < \infty$, then the transition rates of $(X_\pi(t))_{t \geq 0}$ are given by \eqref{eq:rates}.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:55:27.268159+00:00","domain":"probability theory","id":"claim_36e4110f3b8b3b5cae711a2a0d67eb832b5b7bab0ce9c473a4d9df4a949911e9","kind":"concept","schema_version":1,"statement":"[Lemma S41L of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] Fix $p, \eta, M^{\mathsf{bot}}, M^{\mathsf{side}} \in (0, \infty)$, $k \in \mathbb{N}$ and $\delta_2 \in (0,1/2)$. There exist $N_5 \in \mathbb{N}$, $\delta^{\mathsf{sep}} > 0$ and $\Delta^{\mathsf{sep}} \in (0,\delta_2)$, depending on $p, \eta, M^{\mathsf{bot}}, M^{\mathsf{side}}, k , \delta_2$, such that the following holds for all $n \geq N_5$. If we assume:
\begin{itemize}
\item $\vec{x}, \vec{y}\in \mathfrak{W}_k$ as in ((DefSig of the paper)), and $|x_i| \leq M^{\mathsf{side}} \cdot n^{1/2}$, $|y_i - pn| \leq M^{\mathsf{side}} \cdot n^{1/2}$ for $i  \in \llbracket 1, k \rrbracket$;
\item $g: \llbracket 0, n \rrbracket \rightarrow [-\infty, \infty)$ is such that $g(s) \leq ps + M^{\mathsf{bot}} \cdot n^{1/2} $ for all $s \in \llbracket 0, n \rrbracket$;
\item the set $\Omega_{\mathsf{Inter}}(0,n,\vec{x},\vec{y}, \infty, g)$ is non-empty;
\item $t_0 \in [\delta_2, 1- \delta_2]$, and $F_n(t_0 n ) = \mathbb{Z} \cap [t_0n -\Delta^{\mathsf{sep}} \cdot n, t_0 n +\Delta^{\mathsf{sep}} \cdot n]$,
\end{itemize}
then the following inequality holds
\begin{equation}
\mathbb{P}_{\mathsf{Inter}, \operatorname{Geom}}^{0, n, \vec{x}, \vec{y}, \infty, g}\left( Q_k(t_0n) - pt_0n \geq g(s) - ps + \delta^{\mathsf{sep}} \cdot n^{1/2}  \mbox{ for all } s \in F_n (t_0 n)\right) > 1- \eta.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.040724+00:00","domain":"probability theory","id":"claim_36f009b24a8239423cb781357e8ed2923567606c14f831bb1ffc7bb5d9f2e251","kind":"concept","schema_version":1,"statement":"[Theorem 10 (Limiting invariant measure) of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] Let $X^N_t$ be a continuous time Markov chain with strongly connected transition graph $(V,E,r_N)$ satisfying Assumption \ref{FRL2}. 
Let $\pi_N$ be its unique invariant measure.
Then its limit exists, is a probability measure on $V$ and can be expressed as
\begin{equation}
	\pi:=
	\lim_{N \rightarrow \infty} \pi_N =
	\sum_{M\in \mathcal M} \bar \pi(M)\, \mu_M \;.
\end{equation}
In particular $\pi(x)=0$ for $x\in V\setminus \hat V$ and more explicitly:
\begin{equation}
	\pi(x)= \begin{cases} 
	\,\bar \pi(M)\;\mu_M(x) & \textrm{, }\, x\in M  \textrm{ for }M\in\mathcal M\\
	\,0 & \textrm{, }\,x\in Q  \textrm{ for }Q\in\mathcal Q \setminus \mathcal M \end{cases} \ .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

