{"assumptions":[],"created_at":"2026-10-26T19:33:46.767408+00:00","domain":"probability theory","id":"claim_3713ac1d73fd93547cf06d82805c90edfba9ecb4fdd11336b757761a4a0473ca","kind":"concept","schema_version":1,"statement":"[Lemma 10 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $k \in \mathbb{N}$, $\vec{x}, \vec{y} \in \weylc_k$, and $a,b \in \mathbb{R}$ with $a < b$. 
\begin{enumerate}
\item[(a)] Suppose $\vec{x}\,^n, \vec{y}\,^n \in \weyl_k$ satisfy $\lim_{n \rightarrow \infty} \vec{x}\,^n = \vec{x}$, $\lim_{n \rightarrow \infty} \vec{y}\,^n = \vec{y}$. Then, as $n \rightarrow \infty$, the measures $\mathbb{P}_{\mathrm{avoid}}^{a,b,\vec{x}\,^n,\vec{y}\,^n}$ converge weakly to a probability measure on $C(\llbracket 1, k \rrbracket \times [a,b])$. We denote this limiting measure by $\mathbb{P}_{\mathrm{avoid}}^{a,b,\vec{x},\vec{y}}$ and write $\mathbb{E}_{\mathrm{avoid}}^{a,b,\vec{x},\vec{y}}$ for the expectation with respect to this measure. 
\item[(b)] Suppose $\vec{x}\,^n, \vec{y}\,^n \in \weylc_k$ satisfy $\lim_{n \rightarrow \infty} \vec{x}\,^n = \vec{x}$, $\lim_{n \rightarrow \infty} \vec{y}\,^n = \vec{y}$. Then, $\mathbb{P}_{\mathrm{avoid}}^{a,b,\vec{x}\,^n,\vec{y}\,^n} \Rightarrow \mathbb{P}_{\mathrm{avoid}}^{a,b,\vec{x},\vec{y}}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:48:24.316239+00:00","domain":"probability theory","id":"claim_3714135d38a3783b0a25992e295065108e0264d9f14be2fb5a8217d763507f78","kind":"definition","schema_version":1,"statement":"[Definition def:finite boxplus of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $p_n$ and $q_n$ be degree $n$ monic polynomials with corresponding polynomials  $P_n$ and $Q_{n}$ of degree $n$ such that $p_n(z)=P_n(\partial_{z})z^{n}$ and $q_{n}(z)=Q_n(\partial_{z})z^n$, respectively.  
	Then, the finite free additive convolution  of $p_n$ and $q_n$ is the unique degree $n$ polynomial $p_n\boxplus_{n}q_n$ such that \begin{equation}
		p_n\boxplus_{n}q_{n}(z)=Q_n(\partial_{z})P_n(\partial_{z})z^n=Q_{n}(\partial_{z})p_n(z)=P_{n}(\partial_z)q_n(z).
	\end{equation}
	Equivalently, if $p_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(p_n)\binom{n}{k}z^{n-k}$ and $q_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(q_n)\binom{n}{k}z^{n-k}$, then \begin{equation*}
		p_n\boxplus_{n}q_n(z)=\sum_{k=0}^{n}z^{n-k}(-1)^{k}\binom{n}{k}\Bigg(\sum_{j=0}^k\binom k j  e_{j}(p_n)e_{k-j}(q_n)\Bigg) . 
	\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:11:44.391580+00:00","domain":"probability theory","id":"claim_37180e4f4b2b3aa8007806f69837a0b37dbdca73c0291bc16e9cff05b6be19a8","kind":"definition","schema_version":1,"statement":"[Defi 13 of arXiv:2609.03171, 'Factorization patterns and fields of definition of $\ell$-torsion points on the Jacobians '] The companion matrix of a monic polynomial $p(x)=a_0+a_1x+\ldots+a_{n-1}x^{n-1}+x^n$ is given by
