&+ \int_t^b \nu_u(s, t, \bar{Y}(t),\mathbb{E}\bar{Y}(t), \bar{u}(t))^\ast \aleph(s, t) \, ds \mid \mathscr{F}_t \bigg](u - \bar{u}(t))\Big\rangle_{U} \geq 0,\quad \forall u\in U, \quad  t\in [0,b]\, a.s.
