{"assumptions":[],"created_at":"2026-10-27T23:06:42.683773+00:00","domain":"probability theory","id":"claim_38fd69a7ecb9629bd49e425328e40d8fed9deb113efa9dde3e924eddb79cb311","kind":"concept","schema_version":1,"statement":"[Theorem thm2 of arXiv:2411.03942, 'Asymptotic expansions relating to the distribution of the product of correlated normal ran'] Let $\mu_X,\mu_Y\in\mathbb{R}$, $\sigma_X,\sigma_Y>0$, $-1<\rho<1$ and $n\geq1$. 

\vspace{2mm}

\noindent 1. Suppose that $r_X+r_Y\not=0$. Then, as $x\rightarrow\infty$,
\begin{align}\bar{F}(x)&\sim\frac{(1+\rho)C_n}{2\sqrt{2\pi }}\bigg(\frac{1+\rho}{|r_X+r_Y|\sqrt{n}}\bigg)^{(n-1)/2}\exp\bigg(\frac{n}{8}\bigg(\frac{1+\rho}{1-\rho}\bigg)(r_X-r_Y)^2\bigg)\nonumber \\
&\quad\times\bigg(\frac{x}{s}\bigg)^{(n-3)/4}\exp\bigg(\frac{|r_X+r_Y|}{1+\rho}\sqrt{\frac{nx}{s}}-\frac{x}{s(1+\rho)}\bigg)\sum_{p=0}^\infty \gamma_p(r_X,r_Y,\rho,n)\frac{s^{p/2}}{x^{p/2}}, 
\end{align}
where $\gamma_0(r_X,r_Y,\rho,n)=1$ and, for $p\geq1$,
\begin{align*}
\gamma_p(r_X,r_Y,\rho,n)&=\sum_{\substack{i,j,k,\ell\geq0 \\ i+2j+k+\ell=p}}(-1)^{j+i} c_\ell(r_X,r_Y,\rho,n) \binom{(n-1)/2-\ell}{k}\binom{(n-3)/2-\ell-k-2j}{i}\\
&\quad\times ((\ell+k)/2-(n-3)/4)_j(1+\rho)^j\bigg(\frac{|r_X+r_Y|\sqrt{n}}{2}\bigg)^{k+i},     
\end{align*}
with $c_\ell(r_X,r_Y,\rho,n)$, $\ell\geq0$, defined as in part 1 of Theorem (thm1 of the paper).

\vspace{2mm}

\noindent 2. Suppose that $r_X+r_Y=0$. Then, as $x\rightarrow\infty$,
\begin{align}\bar{F}(x)&\sim \frac{1+\rho}{2^{n/2}\Gamma(n/2)}\bigg(\frac{x}{s}\bigg)^{n/2-1}\exp\bigg(-\frac{nr_X^2}{2}-\frac{x}{s(1+\rho)}\bigg)\sum_{k=0}^\infty \delta_k(r_X,\rho,n)\frac{s^k}{x^k}, 
\end{align}  
where $\delta_0(r_X,\rho,n)=1$ and, for $k\geq1$,
\begin{align*}
\delta_k(r_X,\rho,n)=\sum_{j=0}^k (-1)^{k-j}d_j(r_X,\rho,n)  (k+1-n/2)_{k-j}(1+\rho)^{k-j},  
\end{align*}
with $d_j(r_X,\rho,n)$, $j\geq0$, defined as in part 2 of Theorem (thm1 of the paper).

\vspace{2mm}

\noindent 3. Suppose that $r_X-r_Y\not=0$. Then, as $x\rightarrow-\infty$,
\begin{align}F(x)&\sim\frac{(1-\rho)C_n}{2\sqrt{2\pi }}\bigg(\frac{1-\rho}{|r_X-r_Y|\sqrt{n}}\bigg)^{(n-1)/2}\exp\bigg(\frac{n}{8}\bigg(\frac{1-\rho}{1+\rho}\bigg)(r_X+r_Y)^2\bigg)\nonumber \\
&\quad\times\bigg(\frac{|x|}{s}\bigg)^{(n-3)/4}\exp\bigg(\frac{|r_X-r_Y|}{1-\rho}\sqrt{\frac{n|x|}{s}}+\frac{x}{s(1-\rho)}\bigg)\sum_{p=0}^\infty \gamma_p(r_X,-r_Y,-\rho,n)\frac{s^{p/2}}{x^{p/2}}. 
\end{align}
\noindent 4. Suppose that $r_X-r_Y=0$. Then, as $x\rightarrow-\infty$,
\begin{align}F(x)&\sim \frac{1-\rho}{2^{n/2}\Gamma(n/2)}\bigg(\frac{|x|}{s}\bigg)^{n/2-1}\exp\bigg(-\frac{nr_X^2}{2}+\frac{x}{s(1-\rho)}\bigg)\sum_{k=0}^\infty \delta_k(r_X,-\rho,n)\frac{s^k}{|x|^k}. 
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.250328+00:00","domain":"probability theory","id":"claim_38fda922d309460d9b8dc8dd3864d4b985ad7254b34b7c8cd1f9bdded4f12de1","kind":"concept","schema_version":1,"statement":"[Lemma eq: upper bound for length of beta of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] \begin{enumerate}[label=(\roman*)]
