{"assumptions":[],"created_at":"2026-10-27T11:29:35.088188+00:00","domain":"probability theory","id":"claim_39a9d4ea4b12ac3863f197e8b7ca9cb663a1658f4b6f628e2b934d12c03eb96d","kind":"theorem","schema_version":1,"statement":"[Thm 20 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that assumptions \ref{H0}, \ref{H0.5}, \ref{H1}, \ref{H2b}, \ref{H3} and conditions
\begin{align}
&\beta+\delta<\frac12\min\{\alpha,1-\alpha\},\\
&\theta>\max\left\{\frac23,\frac{2\delta+(2\alpha-1)\vee0}{2\delta+\alpha}
\right\},\\
&\phantom{a}\notag\\
&\begin{cases}
\vspace{5pt}
\displaystyle\sum_{k=1}^{ \infty}\mu_k^{2\beta+1-\alpha(1+3\theta)}<\infty, &{\rm if }\;\; \alpha\in \left(0,\frac12\right],\\[1mm]
\displaystyle\sum_{k=1}^{ \infty}\mu_k^{2\beta+1-2\alpha+(1-\alpha)(1-3\theta)}<\infty, &{\rm if }\;\; \alpha\in \left[\frac12, \frac34-\frac\delta2\right], \\[1mm]
\displaystyle\sum_{k=1}^\infty\mu_k^{2\beta-1+2\delta(1-\theta)+\alpha(1-\theta)}<\infty, &{\rm if }\;\; \alpha\in\left[\frac34-\frac\delta2,1\right),
\end{cases}
\end{align}
are satisfied. Then, there exists a constant $\mathfrak L>0$, depending only on the structural data $\alpha,\beta,\delta,\theta,T,C$, such that, for every weak mild solutions $(X,W)$ and $(Y,W)$ to \eqref{abstract_formulation} with initial data $x,y\in H$, respectively, in the sense of Definition \ref{def:mild-sol}, defined on the same probability space, it holds that 
\begin{equation}
\sup_{t\in [0,T]}\mathbb{E}\left[\norm{X(t)-Y(t)}^2\right]\leq \mathfrak{L}\norm{x-y}_H^2.
 \end{equation}
In particular, pathwise uniqueness holds for \eqref{abstract_formulation}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.281940+00:00","domain":"probability theory","id":"claim_39b5d545c8e6b8667eb787c369f6fb03be5090af559ca2852a8938dd3b8005ff","kind":"concept","schema_version":1,"statement":"[Lemma 1 of arXiv:2604.25336, 'Central limit theorem for slow-fast system under mixed fractional Brownian motion'] (Stochastic sewing Lemma)Let \(p\ge 2\) and \(\alpha>\frac{1}{2}\). One has \(A\in H_\eta^p\cap \bar H_{\bar \eta}^p\) with $\eta>1/2$ and $\bar \eta>1$. Then, for every $t\in[0,T]$, the limit
\begin{eqnarray}
I_{s,t}:=\lim_{| \mathcal{P}|\to 0} \sum_{[u,v]\in \mathcal{P}} A_{u,v}
\end{eqnarray}
exists in $L_p$-sense. Here $ \mathcal{P}$ is a partition of time interval $[s,t]$. Moreover, there exists a constant $C>0$ such that 
$$\|I_{s,t}(A)\|_{p}\le C \big(\vertiii{A}_{\eta,p}|t-s|^{\bar \eta}+\|A\|_{\eta,p}|t-s|^{ \eta}\big)$$
$$\|\mathbb{E}\big(I_{s,t}(A)-A_{s,t}|\mathcal{F}_t\big)\|_p\le C\vertiii{A}_{\eta,p}|t-s|^{\bar \eta}.$$
Furthermore, if $\|\mathbb{E}\big(A_{s,t}|\mathcal{F}_t\big)\|_p \le C\vertiii{A}_{\eta,p}|t-s|^{\bar \eta}$, then $I(A)\equiv 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:43:55.605798+00:00","domain":"probability theory","id":"claim_39bd9a38c0d2d086f45e3f8f7d129bce07598908c2e6a3740de331fe4d415c74","kind":"concept","schema_version":1,"statement":"[Theoremi thm_main_directed of arXiv:2604.04672, 'Connected components and topological ends of stationary planar forests'] Assume additionally that with probability one, $G$ is oriented with out-degree $1$, non-empty and all directed infinite path $(\pi_n)_{n\geq0}$ in $G$ satisfies $\lim_{n\to\infty}\pi_n\cdot e_2=+\infty$, where $e_2\coloneqq (0,1)\in\mathbb{R}^2$ and $\cdot$ denotes the standard scalar product. Then, exactly one of the following holds almost surely:
        \begin{itemize}
            \item $G$ is a single one-ended tree, or
            \item $G$ consists of infinitely many disjoint two-ended trees.
        \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:38:08.414157+00:00","domain":"probability theory","id":"claim_39c0bf6818247a3d6a83234599d7c2bfd387601d0d79349226bcc7b5ea1d22a2","kind":"theorem","schema_version":1,"statement":"[Corollary cor: estimates for km of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $(\lambda,C^2) \in S^0$.
  \begin{enumerate}
    \item[(i)] If $0\leq \lambda < \frac{p-1}{2}$ and $\gamma_p = \min\left(\frac{4p}{2p-2}-1, \frac{6p-4}{2p-2}-1\right)$, then there exist $B_{\lambda,p}, \varepsilon_{\lambda,p} \in (0,\infty)$ such that for all $C^2<\varepsilon_{\lambda,p}$
    \begin{equation*}
      \left(\frac{(p-1)(p-1-2\lambda)}{p^2} \right)^{\frac{1}{2-2p}} C^{\frac{2}{2p-2}} -B_{\lambda,p} C^{\gamma_p} < k_m < \left(\frac{(p-1)(p-1-2\lambda)}{p^2} \right)^{\frac{1}{2-2p}} C^{\frac{2}{2p-2}}.
    \end{equation*} 
    Moreover, for $0<\delta\ll 1$ fixed, if $\lambda \in [0,\frac{p-1}{2}-\delta]$, then $B_{\lambda,p} \in [m_{\delta,p}, M_{\delta,p}]$ for some constants $0<m_{\delta,p}, M_{\delta,p}$.

    \item[(ii)] If $\frac{p-1}{2}<\lambda < p-1$, then there exists $B_{\lambda,p}, \varepsilon_{\lambda,p} \in (0,\infty)$ such that for all $C^2<\varepsilon_{\lambda,p}$
    \begin{equation*}
      \left(\frac{2\lambda}{p-1}-1 \right)^{\frac{1}{p}}  < k_m < \left( \frac{2\lambda}{p-1}-1 \right)^{\frac{1}{p}} + B_{\lambda,p} C^{2}.
    \end{equation*}
    Moreover $\lambda \mapsto B_{\lambda,p}$ is continuous and $\lim_{\lambda\to p-1}B_{\lambda,p}=  \frac{5}{p-1}$. Also for $0<\delta\ll 1$ fixed, if $\lambda \in [\frac{p-1}{2}+\delta,p-1)$ then $B_{\lambda,p} \in [m_{\delta,p}, M_{\delta,p}]$ for some constants $0<m_{\delta,p}, M_{\delta,p}$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:10.193471+00:00","domain":"probability theory","id":"claim_39c13b52460bfc82acad3f34506b52c7046d23fa37ffebf4972526c1a9ab1534","kind":"definition","schema_version":1,"statement":"[Definition 13 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Reverse Shade, Shadow-Cutting Building.}

Let $(\alpha, \beta)\in \landsc$ be a building. We define its \textit{reverse shade} $\rs(\alpha, \beta)$ as the shade (on the left of a) of $(\alpha, \beta)$ from $\tau(\alpha, \beta)$ ($=(\alpha_b, \beta_b)$):
\[\rs(\alpha, \beta) :=  \left\{(x, y) \in \Half: x\leq \alpha \text{ and } \frac{\beta-y}{\alpha-x} \geq \frac{\beta_b-\beta}{\alpha_b-\alpha}\right\}.\]

From there, we further define the \textit{shadow-cutting building} $\rb$ of $(\alpha, \beta)$ as the closest building to the left of $(\alpha, \beta)$ that does not lie in $\rs(\alpha, \beta)$:
\[\rb := \max\left\{(x, y) \in L: x\leq \alpha \text{ and } \frac{\beta-y}{\alpha-x} < \frac{\beta_b-\beta}{\alpha_b-\alpha}\right\}.\]
        \begin{figure}[h]
            \centering
            \includegraphics[width=0.75\textwidth]{Figures/reverse_shade.ipe.png}
            \caption{The shadow-cutting building can be seen as the one on which the shadow of $b$ stops.}
        \end{figure}\\","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:32:28.955186+00:00","domain":"probability theory","id":"claim_39c20e249f8fc53940e9a04aaf795cefcc3cf8ae058ea94611a9bc76be560d23","kind":"concept","schema_version":1,"statement":"[Proposition prop:sharp-lri-4d of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] ([ShiraishiWatanabe2026])

Let $S^1$ and $S^2$ be independent simple random walks on $\mathbb Z^4$ started from
$0$.  For $k\ge1$, set
\begin{align*}
        f(n,k)=
        \mathbb P\bigl(S^1[0,n]\cap S^2[kn,(k+1)n]\ne\emptyset\bigr).
\end{align*}
Then, uniformly in the range of $k$ used in this paper,
\begin{equation}

        f(n,k)=
        \frac{1}{2\log n}
        \log\left(1+\frac{1}{k^2+2k}\right)
        \left\{1+O\left(\frac{1}{k(\log n)^{3/25}}\right)\right\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.369489+00:00","domain":"probability theory","id":"claim_39caba0c67676eb4469e24e4750e52b8b0fea2108a0f8525e4a713bac4471b01","kind":"definition","schema_version":1,"statement":"[Definition 12 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] The \textit{graph representation} of a measure $\mu \in \mathcal{N}_\mathcal{S}^{\#}$ is a graph $G=(V,E)$ describing the spatial embedding of $\mu$, defined as follows. Let 
    \begin{align*}
        V &= \Big\{ x \in X \, \Big| \, \exists \, (\omega,a) \in [\mu] \text{ s.t. } x = \omega(0) \text{ or } x=\hat{\omega}  \Big\} \,, \\
        E &= \Big\{ (x,y) \in V \times V \, \Big| \, \exists \, (\omega,a) \in [\mu] \text{ s.t. } \omega(0)=x \text{ and } \hat{\omega}= y  \Big\} \,.
    \end{align*}
    To an edge $(x,y) \in E$ we assign the corresponding path $\omega_{xy} \in \mathcal{W}$ to be the element $(\omega_{xy},a) \in [\mu]$ with $\omega_{xy}(0)=x$ and $\hat{\omega}_{xy} = y$. 
    This network is fully determined by $\mu$ and so defines a mapping $\mu \mapsto (V,E)$ from $\mathcal{N}_\mathcal{S}^\#$ into a space of networks. Denote this mapping by $G(\mu)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:19.042179+00:00","domain":"probability theory","id":"claim_39cc3f2829e2e8f5dafa9b06d6b14200be68e212522cd3705e7ad2d92a5972e1","kind":"theorem","schema_version":1,"statement":"[Thm thm-N1 of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Let $\Omega$ be a bounded Lipschitz domain in $\mathbb{R}^d$, $d\ge 2$.
Let $\phi \in C^1(\overline{\Omega})$  be a solution of (equation NP0 of the paper).
Then, 
\begin{equation}
\sup_{B(x, 2r)\subset \Omega}
\left(\fint_{B(x, r)} |\phi - \fint_{B(x, r)} \phi |^q \right)^{1/q}
\le C M_2 (g) (r)
\end{equation}
for any $2< q< \infty$. Moreover, 
for $x_0\in \partial\Omega$ and $0<r< r_0$,
\begin{equation}
\left(\fint_{B(x_0, r) \cap \partial\Omega}
|\phi -\fint_{B(x_0, r) \cap \partial\Omega} \phi |^p \right)^{1/p}
+
\left(\fint_{B(x_0, r) \cap \Omega}
|\phi -\fint_{B(x_0, r) \cap\partial \Omega} \phi  |^q \right)^{1/q}
\le C  M_p (g) (r), 
\end{equation}
where $2\le p< \infty$ and  $q=\frac{pd}{d-1}$. The constant $C$ 
depends only on $d$, $p$  and the Lipschitz character of $\Omega$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:47:07.705894+00:00","domain":"probability theory","id":"claim_39cdfc6f56d881c3fd88d2263d380e24e345eece8f6bf86c7948cda15af2723c","kind":"lemma","schema_version":1,"statement":"[Lemma 26 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] Assume that $\partial\colon\bN\to\bN$ is a generator.  Define
