{"assumptions":[],"created_at":"2026-10-26T19:47:01.667030+00:00","domain":"probability theory","id":"claim_3a1f105c3c35a5849c95d6f4edbb7db0cbc9e3946bc1f1fb529a4f6eb951c26d","kind":"definition","schema_version":1,"statement":"[Def 1 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] An $\R^m$-valued stochastic process $\{F_t\}_{t \geq 0}$ is called a \emph{chaotic process} (over the abstract Wiener space $(\Omega,\mathcal{F},\P,\mathfrak{H})$) if there exists $q \in \N$ such that, for every $t \geq 0$ and every $1 \leq \ell \leq m$, one can find $f_t^\ell \in \mathfrak{H}^{\odot  q}$ satisfying
\begin{equation}
F_t=(I_q(f_t^1),\dots,I_q(f_t^m)).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:09.854360+00:00","domain":"probability theory","id":"claim_3a2035e043bb40e1b704153239d28396e607ab5b2633d755aeb114f45abda26a","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2605.20026, 'Quasihelix properties\\ of selected Volterra Gaussian processes'] A Gaussian process $G=\{G_t,\ t\ge0\}$ is called
\begin{itemize}
    \item[$(i)$] a \emph{$\rho$-quasihelix} if there exist $\rho>0$ and constants $C_1,C_2>0$ such that, for all $t,s\in[0,\infty)$,
    \begin{equation*}
        C_1|t-s|^{\rho}
        \le
        \|G_t-G_s\|_2
        \le
        C_2|t-s|^{\rho};
    \end{equation*}

    \item[$(ii)$] a \emph{local $(\rho,T_1,T_2)$-quasihelix} on the interval $[T_1,T_2]$ if there exist $\rho>0$ and constants $C_1(T_1,T_2),C_2(T_1,T_2)>0$ such that, for all $t,s\in[T_1,T_2]$,
    \begin{equation}
        C_1(T_1,T_2)|t-s|^{\rho}
        \le
        \|G_t-G_s\|_2
        \le
        C_2(T_1,T_2)|t-s|^{\rho};
    \end{equation}

    \item[$(iii)$] a \emph{local $(\rho_1,\rho_2,T_1,T_2)$-generalized quasihelix} on the interval $[T_1,T_2]$ if there exist $\rho_1,\rho_2>0$ and constants $C_1(T_1,T_2),C_2(T_1,T_2)>0$ such that, for all $t,s\in[T_1,T_2]$,
    \begin{equation}
        C_1(T_1,T_2)|t-s|^{\rho_1}
        \le
        \|G_t-G_s\|_2
        \le
        C_2(T_1,T_2)|t-s|^{\rho_2}.
    \end{equation}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:25:05.832289+00:00","domain":"probability theory","id":"claim_3a21a9f8075ef308365eaa131c4876ff12ba90fc85362eeb67e8fa055ca31422","kind":"concept","schema_version":1,"statement":"[Corollary 5 (Regret under the logarithmic buffer) of arXiv:2608.22227, '\fontsize{18pt}{20pt}\selectfont \bf Risk-Sensitive Reinforcement Learning with Smoothed Q'] For each $t$ choose \(\beta_t = \frac{\tau} {\log(\mathrm e + t)},\) and define \(K_\tau \coloneqq \left\lceil \exp\!\left(\frac{\tau}{\rho_\tau}\right)-\mathrm e \right\rceil\). Then, under the conditions of Theorem~\ref{thm:UCB-BQRL-finite}, with probability at least \(1-2\delta\), $\Reg_\tau(T)\le\;2H K_\tau+ \allowbreak \frac{c\log(\mathrm e+T-1)}{\tau}\sqrt{SA TH^4\log\!\frac{2SATH}{\delta}} + \allowbreak\frac{c\log(\mathrm e+T-1)}{\tau}\sqrt{\frac{TH^4}{2}\log\!\frac{2SATH}{\delta}\log\!\frac{1}{\delta}} \allowbreak$. Consequently,
\(\Reg_\tau(T) = \widetilde{\mathcal O}\!\left(
\frac{1}{\tau}\sqrt{SATH^4}
\right) + O(K_\tau H)\). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

