where 
\begin{align} 
    c_1 = c_2 = \Theta(1)\,,\quad c_3 = \Theta\left(T + \frac{1}{\sqrt{\lambda_O}} \right)\,, \quad c_4 = \Theta\left(1 + \frac{1}{T \sqrt{\lambda_O}}\right)\,.
