            and 
                \begin{align}
                    &\varlimsup_{L \to \infty} \varlimsup_{n \to \infty}\nu_{\mathbf{q}}\left( \left| \frac{1}{n} \sigma^{\left( \left\lfloor n u \right\rfloor \right)}_{k,\ell}\left(n^2\right) - \frac{1}{n} \sigma^{\left( \left\lfloor n v \right\rfloor \right)}_{k,\ell}\left(n^2\right) - f_{k,\ell}\left(\mathbf{q}, u - v\right)  \right| > \frac{L}{\sqrt{n}} \right) = 0, \\  
                \end{align}
            where 
                \begin{align}
                    f_{k,\ell}\left(\mathbf{q}, u\right) := \frac{\bar{\Xi}_{\ell - k}\left(\theta^{k}\mathbf{q}\right) \bar{J}_{k}\left(\mathbf{q}\right)u}{\bar{s}_{\infty}\left(\theta^{k}\mathbf{q}\right) \bar{J}_{\ell}\left(\mathbf{q}\right)}.
                \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:48:45.307156+00:00","domain":"probability theory","id":"claim_4163fc9016bda5377f5dba7f9299f11d6f80577d4928b309a22452138328e55c","kind":"lemma","schema_version":1,"statement":"[Lemma lem:NM_kl of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Assume that $\eta \in \Omega$. Then, for any $k,\ell \in {\mathbb{N}}$, $i \in {\mathbb{Z}}$ and $n \in {\mathbb{Z}}_{\ge 0}$, we have 
            \begin{align}
                \sum_{m = 1}^{n} N^{{i}}_{k,\ell}\left(\eta,m\right) = \sum_{j = X^{{i}}_{k - \ell}\left(\Psi_{\ell}\left(\tilde{\eta}\right), 0 \right) + 1}^{X^{{i}}_{k - \ell}\left(\Psi_{\ell}\left(\tilde{\eta}\right), n \right)} \zeta_{\ell}\left(\tilde{\eta},j\right),
            \end{align}
        and 
            \begin{align}
                M^{(i)}_{k}\left(\eta,n\right) = \sum_{m = 0}^{n-1} \left( 1 - r\left( T^{m}\Psi_{k}\left(\tilde{\eta}\right), J_{k}\left(\tilde{\eta}, i\right) \right) \right),
            \end{align}
        where
            \begin{align}
                J_{k}\left(\eta, i\right) := 
                \begin{dcases}
                    \min\left\{ j \in {\mathbb{Z}}_{\ge 0} \ ; \ \sum_{h = 0}^{j} \mathbf{1}_{\left\{ \zeta_{k}\left(\eta, h\right) > 0 \right\}} = i \right\} \ & \ i \ge 1, \\
                    - \min\left\{ j \in {\mathbb{Z}}_{\ge 0} \ ; \ \sum_{h = -j}^{-1} \mathbf{1}_{\left\{ \zeta_{k}\left(\eta, h\right) > 0 \right\}} = - i + 1 \right\}  \ & \ i \le 0.
                \end{dcases}
            \end{align} 
        In addition, 
                \begin{align}
                \sum^{J_{\ell}\left( \eta, \sigma^{(i)}_{k, \ell}\left(\eta, 0 \right) \right) - 1}_{j = J_{\ell}\left( \eta, \sigma^{(i)}_{k, \ell}\left(\eta, n \right) \right)} \zeta_{\ell}\left(\eta, j \right) 
                \le M^{(i)}_{k,\ell}\left(\eta,n\right) 
                \le \sum^{J_{\ell}\left( \eta, \sigma^{(i)}_{k, \ell}\left(\eta, 0 \right) \right)}_{j = J_{\ell}\left( \eta, \sigma^{(i)}_{k, \ell}\left(\eta, n \right) \right) - 1} \zeta_{\ell}\left(\eta, j \right),
            \end{align}
        where 
            \begin{align}
