            \frac{1}{\epsilon_i}\,
        +
        \delta_{n,3}\,
        \frac{2}{u^2\epsilon_1^2\epsilon_2^2\epsilon_3^3} \,,
    \end{equation}
    where
    \begin{equation}

        \mathsf{U}(\epsvec{[n]};u)
        \coloneqq
        \begin{cases}
            \dfrac{1}{u}
            \dfrac{
                \varsigma(u\epsilon_2)\varsigma(u\epsilon_3)
            }{
                \varsigma(u\epsilon_1)
            }
