{"assumptions":[],"created_at":"2026-10-27T15:27:25.804257+00:00","domain":"probability theory","id":"claim_44af46ddcd44bb2f3cd7bfbb6ea6d2f477c482757ce04fa998f05d70c232c1e2","kind":"theorem","schema_version":1,"statement":"[Proposition prop:hypercube-entropy of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] As $n \to \infty$ with $k = \frac{n}{4}\log n + \alpha n$, the spectral entropy satisfies
\[
S_{\mathrm{spec}}(k) =
\begin{cases}
\Omega(\log n), & \alpha \to -\infty, \\[2pt]
e^{-4\alpha} + O(e^{-8\alpha}), & \alpha = O(1), \\[2pt]
e^{-4\alpha} + o(1) \to 0, & \alpha \to +\infty.
\end{cases}
\]
The collapse from $\Omega(\log n)$ to $0$ occurs continuously over the window $\alpha = O(1)$, corresponding to $\Delta k = O(n)$ steps---precisely the cutoff phenomenon.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:49:21.120313+00:00","domain":"probability theory","id":"claim_44b30651aca781c8cf32b6a919e4f48b09cda6a29c7965ecbaef3eeab47f92f1","kind":"concept","schema_version":1,"statement":"[Thm 3 of arXiv:2608.26642, '2608.26642'] There exists a function $\varphi^\mu$ such that
\begin{align}

\varphi^\mu(x)=\lim_{q\to 0+}r_q(0)\P_x\Big[\Gamma_{\bm{e}_q}^\mu\Big]\qquad \text{for}\ x\in \R
\end{align}
and
 \begin{align}

   \lim_{q\to 0+}\frac{\P_x[F_t\cdot \Gamma_{\bm{e}_q}^\mu]}{\P_x[\Gamma_{\bm{e}_q}^\mu]}=\P_x\left[F_t\cdot\frac{\varphi^\mu(X_t)\Gamma_t^\mu}{\varphi^\mu(x)} \right]\qquad \text{for}\ t\ge0,\ F_t\in b\F_t.
 \end{align}
Moreover, the function $\varphi^\mu$ satisfies
 \begin{align}
   \varphi^\mu(x)=C^\mu +\int_K \varphi^\mu(y)h(x-y)\,\mu(dy)>0\qquad \text{for}\ x\in \R
 \end{align}
 and the pair $(C^\mu,\varphi^\mu|_K)$ is the unique pair $(C,f)\in \R\times C(K)$ satisfying the Fredholm equation
 \begin{align}

   (I-T^\mu)f=C\qquad \text{for}\ f\in C(K),
 \end{align}
 with the normalization condition
 \begin{align}
 \mu[f]:=\int_K f(y)\,\mu(dy)=1.
 \end{align}
In particular, if $\mu=c\mu_K$ for $c>0$, then we have
\begin{align}
\varphi^{c\mu_K}(x)=\varphi_K(x)+\frac{1}{c}\qquad \text{for}\ x\in \R.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:48:49.852822+00:00","domain":"probability theory","id":"claim_44bc99eaa825059fbb22e62151661577f88c7f0aba377631cb216bc90fb32b53","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $\hat \beta \in [0,z_a)$. Then,
    \begin{equation} 
\lim_{N\to\infty} {\mathbb E}\left[W_{N}^2\right] = \lim_{N\to\infty} E\left[e^{\beta_N^2 \sum_{n=1}^N h(S_{2n})}\right] =  \tilde J_{\alpha}\big( \hat{\beta}\big)^{-1}\,.
\end{equation}

Moreover, for all $0\leq \zeta< \xi\leq 1$,
    \begin{equation} 
        \lim_{N\to\infty} {\mathbb E}\left[\Theta_{\zeta,\xi}^2\right] = \lim_{N\to\infty} E\left[e^{\beta_N^2 \sum_{n=N^{\zeta}+1}^{N^{\xi}} h(S_{2n})}\right] = \frac{\tilde J_{\alpha}\left( \hat{\beta}\zeta^{\frac{a+2}{2}}\right)}{\tilde J_{\alpha}\left( \hat{\beta}\,\xi^{\frac{a+2}{2}}\right)}\,.
    \end{equation}
Furthermore, for all $\delta >0$ and every $x_0\in [N^{\frac{\zeta - \delta}{2}},N^{\frac{\zeta+\delta}{2}}]\cap \mathbb{Z}_{even}^2$,
\begin{equation} 
{\mathbb E}\left[\Theta_\xi(x_0)\Theta_\xi(0)\right]= (1+o(1)) \frac{\tilde J_{\alpha}\Big( \hat{\beta}\zeta^{\frac{a+2}{2}}\Big)}{\tilde J_{\alpha}\Big( \hat{\beta}\xi^{\frac{a+2}{2}}\Big)},
\end{equation}
where $o(1)=\Delta_{\delta,N}(x_0)$ satisfies
\[
\limsup_{\delta\to 0} \limsup_{N\to\infty} \sup_{x_0\in [N^{\zeta - \delta},N^{\zeta+\delta}]\cap \mathbb{Z}_{even}^2} |\Delta_{\delta,N}(x_0)|=0.
\]

Finally, we have
\begin{equation} 
    \sup_{N\geq 1} \sup_{x_0\in \mathbb{Z}^2}{\mathbb E}[W_N(x_0)W_N(0)] < \infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:34:20.736014+00:00","domain":"probability theory","id":"claim_44bd676199304600b393aca6e4252b9251ffd6e38c404b659cef145aa2f15cde","kind":"definition","schema_version":1,"statement":"[Definition 20 of arXiv:2609.02197, '2609.02197'] Let $\left(f_1,f_2\right) \in \left(\mathscr{S}'\right)^2.$
\begin{enumerate}
\item For all $m \in \mathbb{N}^*,$ let
\begin{align*}
g_m:\mathscr{S}&\longrightarrow\mathbb{R}\\
\varphi&\longmapsto g_m\left(\varphi\right)=\sum_{n=1}^{m}\int_{\mathbb{T}^d}\varphi\left(x\right)\left(\delta_{n-2}f_1\right)\left(x\right)\left(\delta_{m}f_2\right)\left(x\right)\,\mathrm{d}x
\end{align*}
If $\left(\sum_{j=1}^qg_j\right)_{q \in \mathbb{N}^*}$ converges in $\mathscr{S}',$ then the limit is denoted by \gls{f3}$=$\gls{f4}$=\sum_{q \in \mathbb{N}^*}g_q$ and it is called the paraproduct of $f_2$ by $f_1.$
\item For every $m \in \mathbb{N},$ let
\begin{align*}
h_m:\mathscr{S}&\longrightarrow\mathbb{R}\\
\varphi&\longmapsto h_m\left(\varphi\right)=\sum_{n=0}^{\min\left(m+1,2\right)}\int_{\mathbb{T}^d}\varphi\left(x\right)\left(\delta_{n+\max\left(m-2,-1\right)}f_1\right)\left(x\right)\left(\delta_{m-1}f_2\right)\left(x\right)\,\mathrm{d}x
\end{align*}
If $\left(\sum_{j=0}^qh_j\right)_{q \in \mathbb{N}}$ converges in $\mathscr{S}',$ then the limit is denoted by \gls{f2}$=\sum_{q \in \mathbb{N}}h_q$ and it is called the resonant product of $f_1$ and $f_2.$
\item For all $\left(m_1,m_2\right) \in \mathbb{N}^2,$ let
\begin{align*}
\chi_{m_1,m_2}:\mathscr{S}&\longrightarrow\mathbb{R}\\
\varphi&\longmapsto \chi_{m_1,m_2}\left(\varphi\right)=\int_{\mathbb{T}^d}\varphi\left(x\right)\left(\delta_{m_1-1}f_1\right)\left(x\right)\left(\delta_{m_2-1}f_2\right)\left(x\right)\,\mathrm{d}x
\end{align*}
If $\left(\sum_{j_1=0}^q\sum_{j_2=0}^q\chi_{j_1,j_2}\right)_{q \in \mathbb{N}}$ converges in $\mathscr{S}',$ then the limit is denoted by $f_1f_2=\sum_{\left(q_1,q_2\right) \in \mathbb{N}^2}\chi_{q_1,q_2}$ and it is called the product of $f_1$ and $f_2.$
\end{enumerate}","status":"unverified"}

