{"assumptions":[],"created_at":"2026-10-27T21:31:49.907032+00:00","domain":"probability theory","id":"claim_44c616a3dcb99d7858d4de8ec2d348d9f9c11c889c1e1ed6e393bf16ddd128a4","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] Suppose (ass:xi,ass:alpha,ass:scale of the paper) hold.  Then, for every fixed $x>0$, the following limits hold.

\medskip
\noindent\textbf{Right tail.}
\begin{enumerate}[label=\textup{(R\arabic*)},leftmargin=3.2em]
\item If $\theta_N^+\to\infty$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^{3/2}}
 \log\mathbb P(Z_N>a_Nx)=-\frac43x^{3/2}.
\end{equation}

\item If $\theta_N^+\to\theta\in(0,\infty)$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^{3/2}}
 \log\mathbb P(Z_N>a_Nx)=-J_+^{(\theta)}(x).
\end{equation}

\item If $\theta_N^+\to0$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{\alpha_N^2a_N^2}
 \log\mathbb P(Z_N>a_Nx)=-\frac{x^2}{2\sigma^2}.
\end{equation}
\end{enumerate}

\medskip
\noindent\textbf{Left tail.}
\begin{enumerate}[label=\textup{(L\arabic*)},leftmargin=3.2em]
\item If $\theta_N^-\to\infty$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^3}
 \log\mathbb P(Z_N\le-a_Nx)=-\frac1{12}x^3.
\end{equation}

\item If $\theta_N^-\to\theta\in(0,\infty)$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^3}
 \log\mathbb P(Z_N\le-a_Nx)=-J_-^{(\theta)}(x).
\end{equation}

\item If $\theta_N^-\to0$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{\alpha_N^2a_N^2}
 \log\mathbb P(Z_N\le-a_Nx)=-\frac{x^2}{2\sigma^2}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:40.042691+00:00","domain":"probability theory","id":"claim_44c88fc8740de1bee0b9c10b0137c50b9bf12cd1279824386828dc8358fa36e3","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2510.24244, 'Statistical properties of Markov shifts: part II-LLT'] Under Assumptions \ref{MixAss} and \ref{Assss} the following conditions are equivalent.
\vskip0.2cm
(1) $\liminf_{n\to\infty}\text{Var}(S_nf)<\infty$;
\vskip0.2cm
(2) $\sup_{n\in\bbN}\text{Var}(S_n f)<\infty$;

\vskip0.2cm
(3) we can write 
$$
f_j=\bbE[f_j(X_j,X_{j+1},...)]+M_j(X_j,X_{j+1},...)+u_{j+1}(X_{j+1},X_{j+2},...)-u_j(X_j,X_{j+1}...),\,\ \text{a.s.}
$$
where $\sup_j\|u_j\|_{j,\om}<\infty,$\;
$\sup_j\|M_j\|_{j,\om}\!\!<\!\!\infty$, \, $u_j$ and $M_j$ have zero mean and $M_j(X_j,X_{j+1},...),j\geq 0$ is a reverse martingale difference  with respect to the reverse filtration $\cG_j=\sigma\{X_k: k\geq j\}$ and\footnote{Note that by the martingale convergence theorem we get that the sum $\sum_{k=0}^\infty M_k(X_k,X_{k+1},...)$ converges almost surely and in $L^p$ for all finite $p$.} 
$$
\sum_{j\geq 0}\text{Var}(M_j(X_j,X_{j+1},...))\!\!<\!\!\infty.
$$
\vskip0.1cm
(4) there exist measurable functions $H_j:\cX_{j,\infty}\to\bbR$ such that 
$$
f_j(X_j,X_{j+1},...)=H_{j+1}(X_{j+1},X_{j+2},...)-H_j(X_j,X_{k+1},...)\,\,\text{ a.s.}
$$
In fact, we must have $H_j\in L^s(\ka_j)$ for all finite $s\leq b$ and, in fact, $H_j=\mu_j(H_j)+u_j(X_j,X_{j+1},...)+\sum_{k\geq j}M_k(X_k,X_{k+1},...)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

