{"assumptions":[],"created_at":"2026-10-27T07:21:06.856718+00:00","domain":"probability theory","id":"claim_46fa89d7eb4c820b58b7c07d3d93ccd5054087e4f14a50c6e9ec32122faa59d2","kind":"theorem","schema_version":1,"statement":"[Theorem 30 (Transference of blow-up criteria) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $p\in (2,\infty),\kappa\in [0,p/2-1),q\in [2,\infty)$. Assume that one of the following settings holds:
		\begin{enumerate}
			\item $d\in \{1,2\}, X_0=\bpsn{-2-s,q}$, $X_1=\bpsn{2-s,q}$, $s\in [0,2)$,~\eqref{eq:lwp:rough:initial:data:1},~\eqref{eq:lwp:rough:initial:data:2}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg1} hold.
			\item $d\in \{1,2\}$, $ X_0=\bpsn{-2-s,q}$, $ X_1=\bpsn{2-s,q}$, $ s\in [0,1)$,~\eqref{eq:lwp:rough:initial:data:1},~\eqref{eq:lwp:rough:initial:data:2}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg2} hold.
			\item $d\in \{3,4\}$, $ X_0=\bpsn{-1-s,q}$, $ X_1=\bpsn{3-s,q}$, $ s\in [0,2)$,~\eqref{eq:lwp:rough:initial:data:3},~\eqref{eq:lwp:rough:initial:data:4}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg3} hold.
            \item $d\in \{3,4\}$,  $X_0=\bpsn{-1-s,q}$, $ X_1=\bpsn{3-s,q}$, $ s\in [0,1)$,~\eqref{eq:lwp:rough:initial:data:3},~\eqref{eq:lwp:rough:initial:data:4},
            and Assumption~\ref{Assumption:noise}\ref{assumption:hg4} hold. 
		\end{enumerate}

		\begin{itemize}
				\item 	Assume~\ref{it:gwp:rough:initial:data:1} or~\ref{it:gwp:rough:initial:data:2} with $d=1$ holds, let  $u_0\in L^0_{\F_0}(\Omega;\,_\nu B_{q,p}^{2-s-4\frac{1+\kappa}{p}}(\sO))$, and let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution granted by Theorem~\ref{lwp:rough:initial:data}. Then for all  $0<t_0<T<\infty$ it holds that
				\begin{equation}
				\P\bigg(t_0<\sigma<T, \sup_{t\in [t_0,\sigma)}\nrm{u(t)}_{L^2(\sO)}<\infty\bigg)=0.
				\end{equation}
                \item 	Assume~\ref{it:gwp:rough:initial:data:1} or~\ref{it:gwp:rough:initial:data:2} with $d=2$ holds, let  $u_0\in L^0_{\F_0}(\Omega; \,_\nu B_{q,p}^{2-s-4\frac{1+\kappa}{p}}(\sO))$, and let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution granted by Theorem~\ref{lwp:rough:initial:data}. Then for all  $0<t_0<T<\infty$ it holds that
				\begin{equation}
				\P\bigg(t_0<\sigma<T, \sup_{t\in [t_0,\sigma)}\nrm{u(t)}_{L^2(\sO)}+\nrm{u}_{L^2(t_0,\sigma; H^2(\sO))}<\infty\bigg)=0.
				\end{equation}
				\item Assume~\ref{it:gwp:rough:initial:data:3} or~\ref{it:gwp:rough:intial:data:4} with $d=3$  holds, let $u_0\in L^0_{\F_0}(\Omega; \,_\nu B_{q,p}^{3-s-4\frac{1+\kappa}{p}}(\sO))$, and let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution to \eqref{SCH} granted by Theorem~\ref{lwp:rough:initial:data}. Then for all $0<t_0<T<\infty$ it holds that 
				\begin{equation}
					\P\bigg(t_0<\sigma<T, \sup_{t\in [t_0,\sigma)}\nrm{u(t)}_{\bpsn{1}}<\infty\bigg)=0.
				\end{equation}
                \item Assume~\ref{it:gwp:rough:initial:data:3} or~\ref{it:gwp:rough:intial:data:4} with $d=4$ holds, let $u_0\in L^0_{\F_0}(\Omega;\,_\nu B_{q,p}^{3-s-4\frac{1+\kappa}{p}}(\sO))$, and let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution to \eqref{SCH} granted by Theorem~\ref{lwp:rough:initial:data}. Then for all $0<t_0<T<\infty$ it holds that 
				\begin{equation}
					\P\bigg(t_0<\sigma<T, \sup_{t\in [t_0,\sigma)}\nrm{u(t)}_{\bpsn{1}}+\nrm{u}_{L^2(t_0,\sigma; \bpsn{3})}<\infty\bigg)=0.
				\end{equation}
		\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:24.607915+00:00","domain":"probability theory","id":"claim_47014ff375a3d7eb4c90e199cb9c2896d3aeeae3644485c93e1adae8f874a14b","kind":"concept","schema_version":1,"statement":"[Thm 3 of arXiv:2506.08782, 'First to reach $n$ game\thanks{This version corrects a few minor typos which were in the p'] We have
