{"assumptions":[],"created_at":"2026-10-28T02:31:45.222234+00:00","domain":"probability theory","id":"claim_483377033be987176b354d394fc8c6d72f791aa4f68b02e67e47c25d584e627f","kind":"concept","schema_version":1,"statement":"[Theorem theorem1.56 of arXiv:2412.06246, 'The smallest singular value for rectangular random matrices with Lévy entries'] Fix $\alpha\in(0,2),$ $\delta>1$, and let $N=\lceil \delta n\rceil$. Let $\xi$ be a random variable with a symmetric distribution $\xi \overset{\operatorname{law}}{=}-\xi$ satisfying that, for some $C_u>C_\ell>0$ we have for any $t>0$,
\begin{equation}
C_\ell t^{-\alpha}\leq \mathbb{P}(|\xi|\geq t)\leq C_ut^{-\alpha}.
\end{equation}  Let $X=(x_{ij})_{1\leq i\leq N,1\leq j\leq n}$ be a rectangular random matrix with independent identically distributed (i.i.d.) entries having the distribution $\xi$. 
Then for any $D>0$ we can find $C_1,C_2>0$ and some $N_0\in\mathbb{N}_+$ such that, whenever $N\geq N_0$,
\begin{equation}
\mathbb{P}\left(C_1n^\frac{1}{\alpha}(\log n)^\frac{2(\alpha-2)}{\alpha}\leq \sigma_{min}(X)\leq C_2n^\frac{1}{\alpha}(\log n)^\frac{\alpha-2}{2\alpha}\right)\geq 1-n^{-D},
\end{equation}
 where the constants $C_1,C_2,N_0$ depend only on $C_\ell$,$C_u$,$\alpha$,$\delta$ and $D$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:57:30.993323+00:00","domain":"probability theory","id":"claim_4835393e11fa6cc374161c94712f37be62eed4d9527b722349f93ccadc215a21","kind":"theorem","schema_version":1,"statement":"[Theorem 33 (Subsequential convolution factorization) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Fix $Q,d<\infty$.  Let
\[
 X_{n,a}
 =\sum_{q=1}^{Q}I_q^{W_n}
 \left(\frac{x_{n,a,q}}{\sqrt{q!}}\right),
 \qquad
 \sup_n\sum_{a,q}\norm{x_{n,a,q}}^2\le R^2.
\]
There is a subsequence for which the factorization in
\eqref{overview:eq:noncanonical} holds.  More precisely, the feedback
construction gives
$
 X_n=A_n^J+B_n^J
$
such that, on one limiting probability space,
\begin{equation}
 A_n^J\Longrightarrow A^J\quad(J\text{ fixed}),
 \qquad
 A^J\longrightarrow A_*\quad\text{in }L^2,

\end{equation}
and, after extracting $\Cov(X_n)\to\Sigma$,
\begin{equation}
 C=\Sigma-\Cov(A_*)\succeq0.

\end{equation}
For every $t\in\R^d$,
\begin{align}
 &\limsup_{n\to\infty}
 \left|
 \E e^{it\cdot X_n}
 -\E e^{it\cdot A_*}e^{-\frac12t^{\mathsf T}Ct}
 \right|\notag\\
 &\quad\le
 \frac{\sqrt5}{2}|t|^2R^2
 \sqrt{\frac{\mu_Qa_Q}{J}}
 +|t|\norm{A^J-A_*}_2
 +\frac{|t|^2}{2}\norm{C^J-C}_{\op},

\end{align}
where $C^J=\Sigma-\Cov(A^J)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:45.030562+00:00","domain":"probability theory","id":"claim_483a7f069625eaedafec2a25326a7579cbb35efc6650e2329efe4c81510dffaa","kind":"concept","schema_version":1,"statement":"[Thm 2 (\cite{Quasi}, Theorem 1) of arXiv:2606.07194, 'Survival Probability of Markov Linear Reccurence Sequence in a Random Environment: Subcrit'] Let $\{X_n\}$ be a positive Markov chain with certain extinction.
Suppose that there exists a set $K\subset \mathbb{N}$ such that:
\begin{enumerate}
\item[QS1)] for some positive $C_1$, $\varepsilon$ and all $n\in \mathbb{N}$ 
$${\bf P}(X_i\not\in \{0\}\cup K, 1\le i\le n|X_0=j)\le C_1 (R+\varepsilon)^{-n},\ j\in K;$$
\item[QS2)] for some $j\in K$, $C_2>0$ and for all $i\in K$ and $n\in \mathbb{N}$
$${\bf P}(T>n|X_0=i)\le C_2 {\bf P}(T>n|X_0=j);$$
\item[QS3)] for some finite subset $K_1\subset \mathbb{N}$, a natural number $n_0$ and a positive constant $C_3$ for all $i\in K$ 
$${\bf P}(\exists j\le n_0:\ X_j\in K_1|X_0=i)\ge C_3.$$
\end{enumerate}
Then
\begin{enumerate}
\item[1)] $\pi P_{+} =  R^{-1} \pi$, where $\pi$ is a probability distribution on $\mathbb{N}$;
\item[2)] for some non-negative function $f:\mathbb{N}\to \mathbb{R}$ we have $P_{+} f = R^{-1} f$, and $\sum_{i>0} f(i) \pi_i=1$;
\item[3)] for all $i\in \mathbb{N}$ we have
\begin{equation}

\lim_{n\to\infty} R^{-n} {\bf P}(T>n|X_0=i)=f(i);
\end{equation}
\item[4)] for all $i,j\in \mathbb{N}$ we have
\begin{equation}

\lim_{n\to\infty} {\bf P}(X_n=j|X_0=i, T>n)= \pi_j.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.321255+00:00","domain":"probability theory","id":"claim_484091a624e2c265b4c6f9981cb949ebab2b5f58ed50425e32220a6734d70e44","kind":"definition","schema_version":1,"statement":"[Definition def:results:gibbs of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] For $n \in \ensuremath{\mathbb{N}}$, $n > 2$, define the \emph{Gibbs measure} $\theta^n \in \mathcal{P}((\ensuremath{\mathbb{R}}^d)^{V_n})$ by
\begin{equation}
    \theta^n(d\mathbf{x}^{(n)}) := \frac{1}{\mathcal{Z}^n} \exp\bigg( - \frac{1}{2}\sum_{(u, v) \in E_n} Q(x_u, x_v)\bigg)  d\mathbf{x}^{(n)},

\end{equation}
where $Q$ is given by  
\begin{equation}
    Q(x, y) := U(x) + U(y) + 2W(x - y), \quad x, y \in \ensuremath{\mathbb{R}}^d,

\end{equation}
and $\mathcal{Z}^n$ is the associated normalization constant or \emph{partition function}:
\begin{equation}
    \mathcal{Z}^n := \int_{(\ensuremath{\mathbb{R}}^d)^{V_n}} \exp\bigg( - \frac{1}{2}\sum_{(u, v) \in E_n} Q(x_u, x_v)\bigg) d\mathbf{x}^{(n)}.

\end{equation}
Note that if $(U, W)$ satisfy Assumption (as:results:invMeasure of the paper), then $\mathcal{Z}^n$ is finite and $\theta^n$ has finite moments of all orders.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:34:20.727314+00:00","domain":"probability theory","id":"claim_48456aaf6ff05a8117a0c6ad8de5d188ca5d19113f3213add8dd0fd547020109","kind":"definition","schema_version":1,"statement":"[Definition 9 of arXiv:2609.02197, '2609.02197'] For all $j \in \mathbb{N},$ let
\begin{align*} 
\left\Vert\cdot\right\Vert_{j,\mathscr{S}}: C^{\infty}\left(\mathbb{T}^d,\mathbb{R}\right)&\longrightarrow \mathbb{R}_+ \\ \varphi & \longmapsto \left\Vert \varphi\right\Vert_{j,\mathscr{S}}=\max_{\substack{q \in \mathbb{N}^d\\ \left|q\right|\leq j}}\sup_{x \in \mathbb{T}^d}\left|\partial^q\varphi\left(x\right)\right|
\end{align*}
\begin{enumerate}
\item The Schwartz space is the vector space \gls{pc2}$:=C^\infty\left(\mathbb{T}^d,\mathbb{R}\right)$ equipped with the topology generated by the family of semi-norms $\left(\left\Vert\cdot\right\Vert_{n,\mathscr{S}}\right)_{n \in \mathbb{N}}.$
\item The space of tempered distributions is the vector space
\\
\gls{pc1}$:=\left\{f \in \mathbb{R}^{\mathscr{S}},\exists (\mu,r) \in \mathbb{R}_+\times \mathbb{N},\forall \varphi \in \mathscr{S},\left|f\left(\varphi\right)\right|\leq \mu\left\Vert\varphi\right\Vert_{r,\mathscr{S}}\right\}$
\\
$\cap\left\{f \in \mathbb{R}^{\mathscr{S}},\forall \left(\alpha,\varphi_1,\varphi_2\right) \in \mathbb{R}\times\mathscr{S}^2,f\left(\alpha\varphi_1+\varphi_2\right)=\alpha f\left(\varphi_1\right)+f\left(\varphi_2\right)\right\}$ equipped with the weak$^*$ topology $\sigma\left(\mathscr{S}',\mathscr{S}\right).$
\item Let $\left(f_n\right)_{n \in \mathbb{N}}$ be a sequence in $\mathscr{S}'.$ We say that $\left(f_n\right)_{n \in \mathbb{N}}$ converges in $\mathscr{S}'$ if and only if there exists $f \in \mathscr{S}'$ such that for all $\varphi \in \mathscr{S},\lim_{m\to+\infty}f_m\left(\varphi\right)=f\left(\varphi\right).$
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:38:17.790355+00:00","domain":"probability theory","id":"claim_48486742384eb497f727ea925153b5e64a918a670e92e98937426729e49bb066","kind":"concept","schema_version":1,"statement":"[Theorem thm:upper_bd_local_time_bdry_PushTASEP of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] Let $\partial \mathbb{S}^{d}:=\{ x\in \mathbb{Z}^{d}\,:\, \text{$x_{1} < \cdots < x_{d}$ and $x_{i+1}-x_{i}=1$ for some $i=1,\dots,d-1$}\}$. 

