\end{equation}
and 
\begin{equation}
E_{wj}=E^{1/2}_{w}A^{\left(j\right)}_{w}E^{1/2}_{w}.
\end{equation}

Conversely, suppose that $E_{\varnothing}=I$, and that the cylinder
values are defined recursively by positive contractions $A^{\left(j\right)}_{w}\in B\left(H_{w}\right)$
satisfying \prettyref{eq:2-13} and \prettyref{eq:2-14}. Then there
is a unique POVM $E$ on $\Omega_{m}$ with these cylinder values.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.227068+00:00","domain":"probability theory","id":"claim_48c36c9402e61efd5c5af938973856cc32522e1ec3ec5c5e805d1ecd01682521","kind":"definition","schema_version":1,"statement":"[Definition def-lacunary of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] \begin{enumerate}
    \item A point process $\theta$ is called \textbf{lacunary} on $(0,\infty)$ if there exist constants $c,d \in (0, \infty)$, $c<d$, such that  
    \begin{equation} 
        \theta([cx, d x ]) \overset{\mathbb{P}}{\rightarrow} 0
    \end{equation} 
    as $x \rightarrow \infty $\footnote{The intuitive meaning of this definition is that atoms of the point process $\theta$ in $(0,\infty)$ are extremely spaced out and have large gaps, hence the choice of the word \textbf{lacunary}.}. 

    \item A point process $\theta$ is called \textbf{exponentially-lacunary} on $(0,\infty)$ if there exist constants $c,d \in (0, \infty)$, $c<d$, such that 
    \begin{equation}
         \theta([c \log x, d x ]) \overset{\mathbb{P}}{\rightarrow} 0
    \end{equation}
    as $x \rightarrow \infty $. 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.967278+00:00","domain":"probability theory","id":"claim_48c95674441ada222b47eb7a44b1e71650b4e1d2a87644d9f330889d56643922","kind":"concept","schema_version":1,"statement":"[Proposition 10 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] Let \(\mathbf{Y} : [0, T] \to \CH^*_{N - 1}\) be a controlled rough path against the \(\gamma\)-H\"older 
