{"assumptions":[],"created_at":"2026-10-26T19:33:46.777178+00:00","domain":"probability theory","id":"claim_4994efc837f057e022f63bda295a6b5d92c24a919159a805cf3756d2d381d2ed","kind":"concept","schema_version":1,"statement":"[Lem 8 of arXiv:2603.25459, 'Cram\'{e}r-type moderate deviation for double index permutation statistics'] Let $\pi$ and $\sigma$ be two independent random permutations, chosen uniformly from $S_n$. Suppose $i\neq j$ and $k\neq l$ are elements of $[1,\dots,n]$ and denote $\tau_{i,j}$ the transposition of $i$ and $j$, then
\begin{align}
    \sigma^{i}_{k}: = \mathcal{P}^{i}_{k}\sigma = \begin{cases}
        \sigma, & \sigma(i) = k,\\
        \sigma\circ\tau_{i,\sigma^{-1}(k)}, & \sigma(i) \neq k,
    \end{cases}
\end{align}
\begin{align}
    \sigma^{ij}_{kl}: = \mathcal{P}^{ij}_{kl}\sigma = \begin{cases}
        \sigma\circ\tau_{i,\sigma^{-1}(k)}\circ\tau_{j,\sigma^{-1}(k)}, & \sigma(i) = l, \sigma(j) \neq  k,\\
        \sigma\circ\tau_{j,\sigma^{-1}(l)}\circ\tau_{i,\sigma^{-1}(l)}, & \sigma(i) \neq l, \sigma(j) = k,\\
        \sigma\circ\tau_{i,\sigma^{-1}(k)}\circ\tau_{j,\sigma^{-1}(l)}\circ \tau_{i,j}, &\sigma(i) = l, \sigma(j) = k,\\
        \sigma\circ\tau_{i,\sigma^{-1}(k)}\circ\tau_{j,\sigma^{-1}(l)}, & otherwise,
    \end{cases}
\end{align}
are two permutations that satisfy
\begin{align}
    \mathcal{L}\left(\sigma^{i}_{k}\right) \overset{d}{=}\mathcal{L}\left(\pi\mid \pi(i) = k\right),
\end{align}
and
\begin{align}
    \mathcal{L}\left(\sigma^{ij}_{kl}\right) \overset{d}{=}\mathcal{L}\left(\pi\middle|\substack{\pi(i) = k\\ \pi(j) = l}\right).
\end{align}
And for any elements $p\neq q, u\neq v$ of $[n]$ satisfying $p,q\notin\{i,j\}$, $u,v\notin\{k,l\}$, we have
\begin{align}

    \mathcal{L}\left(\mathcal{P}^{p}_{q}\sigma^{ij}_{kl}\right) \overset{d}{=}\mathcal{L}\left(\pi\middle| \substack{\pi(i) = k\\ \pi(j) = l\\ \pi(p) = q}\right), \quad \mathcal{L}\left(\mathcal{P}^{pq}_{uv}\sigma^{ij}_{kl}\right)\overset{d}{=}\mathcal{L}\left(\pi\middle|\substack{\pi(i) = k\\\pi(j) = l\\\pi(p) = u\\\pi(q) = v}\right).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:48:43.520402+00:00","domain":"probability theory","id":"claim_4995893133f96de69aaf2b45ad7e4ca3fefbc674a62cadea1422ea233dd04b7a","kind":"concept","schema_version":1,"statement":"[Lemma 3 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] For any $s\ge t$, let $G$ be the wave kernel given by~\eqref{E:Kernel}. We have the following identity
