{"assumptions":[],"created_at":"2026-10-26T19:20:33.747889+00:00","domain":"probability theory","id":"claim_4a04adbd11226be07b60fdfb412ea532e87b3726b1ebc7c5d7fb51fd7110e428","kind":"concept","schema_version":1,"statement":"[Lem 10 (Generalized pivot regeneration blocks) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Let
$
    0<\rho_1<\rho_2<\rho_3<\cdots
$
be the generalized pivots, and let $\gk_n$ be as in~\eqref{eq:kappa-def}.  We use the interval edge set $\cE[x,y]$ and the interval environment $\Env[x,y]$ defined in~\eqref{eq:interval-env-notation}, and the block notation~\eqref{eq:block-variable-notation}. Then the following holds.

\begin{enumeratei}
\item \textbf{Generalized pivot renewal-block localization.}
If $\rho_i<\rho_j$ are two generalized pivots, then there
exists a minimum-hop geodesic from $\rho_i$ to $\rho_j$ using only
edges in $\cE[\rho_i,\rho_j]$.  Consequently,
$T(\rho_i,\rho_j)\text{ and }H(\rho_i,\rho_j)
$ are measurable with respect to $\Env[\rho_i,\rho_j]$.

\item \textbf{Renewal-block i.i.d.~structure.}
The block sequence
\begin{align}
    \left\{
        \left(
            \sfP_i,\,
            \Env[\rho_i,\rho_{i+1}]
        \right)
    \right\}_{i\ge1}
\end{align}
is i.i.d.~In particular,
$
    \{(\sfP_i,\sfT_i,\sfH_i)\}_{i\ge1}
$
is i.i.d.

\item \textbf{Geometric domination of the gaps.}
Generalized pivots occur infinitely often almost surely, and if
$
    \fs_{\ell,k}:=(k+1)\ell-1,
$
then
\begin{align}
    \sfP_i
    \preceq
    \fs_{\ell,k}\,\mathrm{Geom}(p_{\mathrm{gen},\ell}),
    \quad i\ge1.
\end{align}
In particular, $\sfP_1$ has finite moments of all orders.  Consequently,
\begin{align}
    \frac{\gk_n}{n}
    \to
    \frac{1}{\E\sfP_1}
    \quad\text{a.s.}
\end{align}

\item \textbf{Deterministic bounds for bounded weights.}
All moments of $\sfT_i$ and $\sfH_i$ are finite, and
\begin{align}
    \left\lceil\frac{\sfP_i}{\ell}\right\rceil
    \le
    \sfH_i
    \le
    \sfT_i
    \le
    2\left\lceil\frac{\sfP_i}{\ell}\right\rceil,
    \qquad
    \sfH_i\le \sfP_i,
    \quad i\ge1.
\end{align}
\end{enumeratei} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:45:05.588497+00:00","domain":"probability theory","id":"claim_4a0ae1fd23327b091e0302a6ae45004bf8ca03e24b541ef552e78ca92b99b144","kind":"theorem","schema_version":1,"statement":"[Proposition 5 of arXiv:2608.05842, 'Asymptotic Expansion of the Kallianpur–Striebel Formula under Perturbations of Linear Mode'] For any $0\leq t\leq T$, it holds
