  \qquad \rho=O(|z|+|w|),
\end{equation}
with all higher derivatives of $\rho$ uniformly bounded on smaller coordinate balls, and
\begin{equation}
  \omega=\ddbar\bigl(|z|^2+|w|^2+\Phi(z,w)\bigr),
\end{equation}
where
\[
  \nabla^j\Phi=O(|z|^{3-j}+|w|^{3-j})\quad(0\le j<3),
\]
and all higher derivatives are uniformly bounded. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

