{"assumptions":[],"created_at":"2026-10-26T19:36:44.553089+00:00","domain":"probability theory","id":"claim_4b98ca3ddb263c30a51cfb65c27d0fbe81aa63d26aa5233f96a3bc1ac0d14e9b","kind":"theorem","schema_version":1,"statement":"[Prop 7 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution to~\eqref{eq:abc-slow},\eqref{eq:intro-InfFriction-withFD-Fast} with corresponding initial data $(Q^i_0,P^i_0)$ for $i=1,2$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} for any  parameter value $\alpha\geq 0$. Further let $T\geq 1$ be fixed.
    \begin{enumerate}[label=(\roman*)]
        \item
        For any $t\geq 0$ we have
        \begin{align}
        \E\Bigl[|Q_t^{1} - Q_0^{1}|^2 \Bigr] &\leq 
        \begin{dcases}
        C_1 \Bigl(  \eps t+ \eps^2 |P_0^{1}|^2   \Bigr) \ \ &\text{if $\alpha=0$,}\\
         C_2 \Bigl( \eps t+ \eps^2 \Bigl(   (1+t^2) |Q_0^{1}|^2 + |P_0^{1}|^2  \Bigr) \Bigr) \ \ &\text{if $\alpha>0$,}
        \end{dcases}
        \\
        \E \Bigl[  \bigl| P^1_t \bigr|^2 \Bigr] & \leq 
        \begin{dcases}
        C_3 \Bigl( \eps^2+  e^{-\frac{C_4}{\eps}t}  |P^1_0|^2   +\beta^{-1} \Bigr) \ \ &\text{if $\alpha=0$,}\\
        C_5 \Bigl(\eps^2+ \eps^2 \left|Q^1_0\right|^2 +  \Bigl(e^{-\frac{C_6}{\eps}t} + \eps^4\Bigr) |P^1_0|^2   +\beta^{-1} \Bigr) &\text{if $\alpha>0$,}
        \end{dcases}

        \end{align}
    where the constants $C_i>0$ for $i\in\{1,\ldots 6\}$ are independent of $\eps$ and $t$.
        \item 
    Let $(q_t,p_t)\in \R^{2(d-k)}$ with initial data $(q_0,p_0)=(Q_0^2,P_0^2)$ evolve according to~\eqref{eq:limit-gen} with $\hat q=Q^1_0 \in \R^k$. We have 
    \begin{align}
        \E\biggl[\sup_{t\in [0,T]}\biggl|\begin{pmatrix}q_t - Q^{2}_t \\ p_t - P^{2}_t\end{pmatrix}\biggr|^2\biggr] \leq 
        \begin{dcases}
             \eps C_7 e^{C_8 T} T^2 \Bigl( T+\eps |P_0^{1}|^2\Bigr) \ \ &\text{if $\alpha=0$}, \\
             \eps C_9 T  \Bigl(T+\eps  \left|Q^1_0\right|^2  + \eps |P_0^{1}|^2  \Bigr)   &\text{if $\alpha>0$},
        \end{dcases} 
    \end{align}
        where $C_7,C_8,C_9>0$ are independent of $\eps$ and $T$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:37:25.879943+00:00","domain":"probability theory","id":"claim_4ba0d6906bb3b0621d1e52207f4813b247923a6df02a3bc6d03dc4f776d0e14a","kind":"theorem","schema_version":1,"statement":"[Proposition 3 of arXiv:2608.29554, 'Limiting Behavior of a Class of Hermitian Yang--Mills Metrics, II: Exponential Approximati'] For any nonnegative integer $k$, there exist constants $C_k,c_k>0$, independent of $\epsilon$, such that for all sufficiently small $\epsilon>0$,
