{"assumptions":[],"created_at":"2026-10-27T15:46:00.392972+00:00","domain":"probability theory","id":"claim_4ebd30cfc1fa66032ae173ee9b6b9cd3b2e413b511eb92d1af18e983545dad6d","kind":"lemma","schema_version":1,"statement":"[Lemma lem:martingale-decomposition of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $1/2<\lambda<1$ and $\phi\in\ensuremath{\mathcal C}_b^\infty(\mathbb{R})$. Then,
	for every $N\in\mathbb{N}$,
	\begin{equation}
		\ensuremath{\mathcal Y}_{\lambda,N}(t,\phi)
		=
		\phi(0)
		+
		\int_0^t
		\ensuremath{\mathcal Y}_{\lambda,N}
		(s,\tfrac12\partial_z^2\phi)
		{\rm d} s
		+
		\ensuremath{\mathcal M}_{\lambda,N}(t,\phi)+ \ensuremath{\mathcal R}_{\lambda,N}(t,\phi)\; \text{.}
	\end{equation}
	Here, 
	$(\ensuremath{\mathcal M}_{\lambda,N}(t,\phi))_{t\ge0}$ is a martingale (with respect to the natural filtration of $(\eta_{tN})_{t\ge 0}$) with
	predictable quadratic variation given by
	\begin{equation}
		\langle\ensuremath{\mathcal M}_{\lambda,N}({\,\cdot\,},\phi)\rangle
		(t)
		=\frac{N^{2\lambda-1}}{4}\int_0^t \varGamma_{\lambda,N}(s,\phi)\,{\rm d} s + \ensuremath{\mathcal S}_{\lambda,N}(t,\phi)\; \text{,}\;\;
	\end{equation}
	where	
	\begin{equation}
		\varGamma_{\lambda,N}(t,\phi)\coloneqq \sum_{x\in \mathbb{Z}} \vartheta_{\lambda,N}(t,x)^2\,[\nabla \eta_{sN}(x)]^2\, \phi_{\lambda,N}(t,x)^2\; \text{.}
	\end{equation}
	The error terms $\ensuremath{\mathcal R}_{\lambda,N}(t,\phi)$ and $\ensuremath{\mathcal S}_{\lambda,N}(t,\phi)$ satisfy, for some $C=C(\phi)>0$, 
	\begin{equation}
		|\ensuremath{\mathcal R}_{\lambda,N}(t,\phi)|\le 
		 CN^{\lambda-1}\int_0^t \ensuremath{\mathcal Y}_{\lambda,N}(s,1)\,{\rm d} s	\; \text{,}\;\;
	\end{equation}
	\begin{equation}
		|\ensuremath{\mathcal S}_{\lambda,N}(t,\phi)|\le C N^{\lambda-1/2}
		\int_0^t
	\varGamma_{\lambda,N}(s,1)
		\,{\rm d} s\; \text{.}
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:18:27.571840+00:00","domain":"probability theory","id":"claim_4ec81f6f3ba7113b516d655fd7a0c7e6e9e98b415fccf909512dfcde81049dcc","kind":"concept","schema_version":1,"statement":"[Thm 9 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d=4$. There exist $c,C>0$ such that, for every $n\geq 2$,
