{"assumptions":[],"created_at":"2026-10-28T00:52:17.581814+00:00","domain":"probability theory","id":"claim_5059eeb2cac673940aac9c5c30b0bb1db01590798242905d6f07fbb8b2016566","kind":"concept","schema_version":1,"statement":"[Proposition Prop.503 of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] For each $p\geq 1$, there exists a constant $C>0$ independent of $n $ and $t $ such that 
 \begin{eqnarray*}
  \mathbf{E}\bigg[\Big| \frac{\ell^\Lambda_{n,1}}{n} \wedge t\Big|^p \bigg]  \leq C\cdot \bigg(\frac{1}{n^p}+ \frac{t^{p-1}}{n(1-p_n)} \cdot \int_0^\infty   (y\wedge t) \cdot  \bar\nu(y) \, dy    \bigg)   .
 \end{eqnarray*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.391526+00:00","domain":"probability theory","id":"claim_505d790759a4eba3dc45f5b800207d39be8265c3d27a72f6de605dbf07977a14","kind":"concept","schema_version":1,"statement":"[Lemma l:independent_cousins of arXiv:2606.11503, 'Percolation on hierarchical lattices'] Fix $0 \leq j < k$, $p \in [0,1]$, and a consistent set of labels $\mathcal{L} = (l^w)_{w \in \mathcal{E}_{1}^j}$.
  Then
  \begin{enumerate}[\quad a)]
  \item ``The families produced by individuals at generation $j$ are independent'':
    \begin{equation}

      \big( L^{we_1}, \dots, L^{we_{|\mathcal{E}_{1}|}} \big)_{w \in \mathcal{E}_{1}^{j}}
      \text{, are independent under }
      \mathbb{P}^{k}_{p} \big[ \cdot \big|
      L^w = l^w; \text{ for $w \in \mathcal{E}_{1}^{j}$} \big],
    \end{equation}
    see (r:cousins of the paper).
  \item ``The type of your father is the only relevant information about your previous generation'':\\
    Fixed $w_0 \in \mathcal{E}_{1}^{j}$ and some function $f: \{0, 1\}^{3 \times |\mathcal{E}_{1}|} \to \mathbb{R}$,
    \begin{equation}

      \begin{split}
        \mathbb{E}_{p}^{k} \Big[ f \big( L^{w_0e_1}, & \dots, L^{w_0e_{|\mathcal{E}_{1}|}} \big)
                                                 \Big| L^w = l^w; \text{ for all $w \in \mathcal{E}_{1}^{j}$}
                                                 \Big]\\
        = & \mathbb{E}_{p}^{k} \Big[
            f \big( L^{w_0e_1}, \dots, L^{w_0e_{|\mathcal{E}_{1}|}} \big)
            \Big| L^{w_0} = l^{w_0} \Big],
      \end{split}
    \end{equation}
    see again (r:cousins of the paper) for a discussion.
  \item ``The offspring distribution is homogeneous across generations at the critical point $p_{\star}$'':
    \begin{equation}

      \mathbb{E}_{p_{\star}}^{k} \Big[
      f \big( L^{w_0e_1}, \dots, L^{w_0e_{|\mathcal{E}_{1}|}} \big)
      \Big| L^{w_0} = l^{w_0} \Big]
      = \mathbb{E}_{p_{\star}}^{k - j} \Big[
      f \big( L^{e_1}, \dots, L^{e_{|\mathcal{E}_{1}|}} \big)
      \Big| L^{\varnothing} = l^{w_{0}} \Big].
    \end{equation}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:48:49.853079+00:00","domain":"probability theory","id":"claim_505e9236a67078f59ff125c5225cf6070fc41863a790a9835932e2630d04851e","kind":"concept","schema_version":1,"statement":"[Lemma lem:second_moment of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $0\leq s<t \leq N$ and $x,y\in\mathbb{Z}^2$. Then
\begin{equation}
    {\mathbb E}[W_{s,t}(x)W_{s,t}(y)]=E_{x-y}\left[e^{\beta_N^2\sum_{n=s+1}^{t} h(S_{2n})}\right].
\end{equation}
Furthermore, with $\bar \sigma_N^2 := e^{\beta_N^2 } \beta_N^2$,
    \begin{equation} 
