{"assumptions":[],"created_at":"2026-10-27T09:48:30.921252+00:00","domain":"probability theory","id":"claim_536cd7177761f221607d4cba637366bdcde0f99077914c7b8753ded678e6d8b1","kind":"lemma","schema_version":1,"statement":"[Lemma 14 of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] Let $k$ be a perfect field. 

    \begin{enumerate}
        \item Let $f\in k(x)$. Then the inclusion $k(x)\to k((x))$ preserves the value of $\widetilde{[x^{n}]}f$.
        \item Let $f\in k((x))$ and $n\in \{0,1,\ldots,p-1\}$, then if $f=\sum_{n\in \mathbb{Z}} a_n x^n$, then
        \begin{equation}
            \widetilde{[x^{n}]}f = \sum_{\substack{m=pk+n,\\ k\in \mathbb{Z}}} x^{pk}a_m.
        \end{equation}
        Consequently, for any $f,g\in k((x))$ we have $\widetilde{[x^{n}]}f+\widetilde{[x^{n}]}g=\widetilde{[x^{n}]}(f+g)$.
        \item Let $f\in k((x)), g\in k((x))^p$, and $n\in \{0,1,\ldots,p-1\}$, then
        \begin{equation}
        \widetilde{[x^{n}]}(gf)=g \cdot \widetilde{[x^{n}]}f.
        \end{equation}
        In particular, if $f\ne0$, then we have
        \begin{equation}
        \widetilde{[x^{p-1}]}f^{p-1}=f^p \cdot \widetilde{[x^{p-1}]}\frac{1}{f}.
        \end{equation}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:23.371808+00:00","domain":"probability theory","id":"claim_536d1f0dd5cf03f421f21007bb04e9de0c25dcef08f1d9ad819d30f3a2ee5bf5","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] Let $\Omega\subset\R^d$ be a bounded open set with $C^{1,1}$ boundary. Then there exists a bounded $C^{1,1}$ function $\phi:\R^d\to\R$ such that 
