	\begin{align}
		\deformarg{\muX}{L}{L} & = 0, & & \deformarg{\muX}{\muX}{X}  = 2 \muX \upmu, & & \deformarg{\muX}{L}{\muX} = -  \muX \upmu, \\
		 \angdeformarg{\muX}{\Lunit} & = - \angrmD \upmu - 2 \zetatrans - 2 \upmu \zetatan, & & \angdeformarg{\muX}{\muX}  = 0 & & \\
		\angdeform{\muX} & = - 2 \upmu \upchi + 2 \angktrans + 2 \upmu \angktan,
	\end{align}
\end{subequations}
\begin{subequations}
	\begin{align}
		\begin{split} 
			\angdeform{\Yvf{A}} & = 2 \Speed^{-2} X^A \upchi + \angG \diamond \Yvf{A} \wavearray -  \Speed^{-2} X^A \angG \diamond \Lunit \wavearray \\
			& \ \ +  \Speed^{-2} X^A \angG_L \otimesarray \angrmD \wavearray + \Speed^{-2} X^A \angrmD \wavearray \otimesarray \angG_L  +  \Speed^{-2} X^A \angG_X \otimesarray \angrmD \wavearray + \Speed^{-2} X^A \angrmD \wavearray \otimesarray \angG_X.
