{"assumptions":[],"created_at":"2026-10-26T20:53:11.415164+00:00","domain":"probability theory","id":"claim_57806c473a112a811baa3e999cc01fb7dc27ea4d7c84b2855d06bcc8bbe5310d","kind":"theorem","schema_version":1,"statement":"[Prop 26 of arXiv:2606.08115, '2606.08115'] Let $\left\{\ov{Z}_n\right\}$ be a group of $N$ branching processes in a joint random environment. Then,
\begin{itemize}
\item the following expressions
\begin{equation}

\prf\left(Z_n^{(i)} > 0 \right) = \left(\exp\left(-S_n^{(i)}\right) + \sum_{k = 0}^{n-1}\exp\left(-S_k^{(i)}\right) g_{k}^{(i)}\left( f_{k+2, n}^{(i)}(0)\right)\right)^{-1}, \quad i = 1, \ldots, N,
\end{equation}
are valid, where
\begin{align*}
&f_{k, n}^{(i)} (t): = f_k^{(i)} \circ f_{k+1}^{(i)} \circ \ldots \circ f_n^{(i)}(t), \quad k = 1, 2, \ldots, n, \quad f_{n+1, n}^{(i)}(t) := t, \quad i = 1, \ldots N,
\\&g_k^{(i)}(t) := \frac{1}{1 - f_{k+1}^{(i)}(t)} - \frac{1}{\left(f_{k+1}^{(i)}\right)'(1) \cdot (1 - t)}, \quad t \in [0, 1), \; i = 1, \ldots, N;
\end{align*}
\item the inequalities
\begin{equation}

\prf \left(Z_n^{(i)} > 0\right) \ge \left(\mathrm{exp} \left(-S_n^{(i)}\right) + \sum_{k = 0}^{n-1} \xi_k^{(i)} \mathrm{exp} \left(-S_k^{(i)}\right)\right)^{-1}, \quad i = 1, \ldots, N
\end{equation}
hold.
