{"assumptions":[],"created_at":"2026-10-26T19:37:51.460291+00:00","domain":"probability theory","id":"claim_5a69b38e94caf4de4ff036bcc2a63349a34c560190bd82e55c190cea329d0290","kind":"theorem","schema_version":1,"statement":"[Prop 49 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $(k_j)_{j \in \mathbb{Z} } \subset \mathbb{Z}$ be such $k_j - k_{j-1} >0$, for any $j \in \mathbb{Z}$. Moreover, for any $j \in \mathbb{Z}$ let $F_j: [0, T] \times \Omega \mapsto \mathbb{R}$ be such that, for every $s \in [0, \; T]$, $\supp \big( F_j(s, \cdot) \; \big) \subset \{k_{j-1}+1, \ldots ,  k_j\}$, and $\mathbb{E}_{\nu_{\rho}} \big[ F_j(s, \eta) \big]=0$. Therefore, there exists some universal constant $\kappa$ such that
	\begin{align*}
		\forall t \in [0, T], \quad \mathbb{E}_{\nu_{\rho}} \Bigg[ \sup_{s \in [0,t] } \Bigg(  \int_{0}^s \sum_{j} F_j(r, \; \eta_r^n) \; \dd r \Bigg)^2  \Bigg] \leq  \kappa \int_0^{t}  \sum_{j}   \frac{(k_j - k_{j-1})^{\gamma}}{\Theta(n)} \mathbb{E}_{\nu_{\rho}} \big[ \big\{ F_j(s, \eta) \}^{2} \big] \dd s.
	\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:28:53.744299+00:00","domain":"probability theory","id":"claim_5a6bc9dd629b1385cf26ba6b767ef65f8ed0dde2af70869561073388ff3b8856","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2605.13727, 'Stochastic evolution equations\\ driven by arbitrary cylindrical Lévy processes'] Let $L$ be a cylindrical L\'evy process in $U$, and let $\Psi$ be a predictable, $L_2(U,H)$-valued process that is integrable with respect to $L$. Then the integral process $(Y(t):\, t\in [0,T])$, defined by $Y(t):=\int_{(0,t]} \Psi\,{\rm d}L$, satisfies the following properties: 
	\begin{enumerate}
        \item [{\rm (a)}] Let $V$  be a separable Hilbert space  and $B \in L(H,V)$. Then, for all $0\leq p<q\leq T$ and $S \in \mathcal{F}_{p}$, we have that $\mathbb{1}_S B\Psi$ is $L$-integrable and
        	\begin{equation}
        		\mathbb{1}_{S}B \left(\int_{(p,q]} \Psi(s)\,{\rm d}L(s)\right)=\int_{(p,q]} \mathbb{1}_S B\Psi(s)\,{\rm d}L(s).
        \end{equation}
		\item [{\rm (b)}] Let $\Phi:\Omega\times[0,T]\rightarrow H$ be a uniformly bounded, adapted, càglàd process. Then, for each fixed $t>0$,  it follows that $\langle \Psi^\dagger \Phi, \cdot \rangle$ is $L$-integrable and
		\[\int_{(0,t]} \langle\Phi(s),\cdot\rangle \, {\rm d}Y(s)=\int_{(0,t]} \big\langle \Psi^\dagger(s)\Phi(s),\cdot\big\rangle \, {\rm d}L(s).\]
		\item [{\rm (c)}] For every stopping time $\tau$, we have that $\1_{(0,\tau]}\Psi$ is $L$-integrable and
		\[Y(\tau \wedge T)=\int_{(0,T]} \1_{(0,\tau]}(s)\Psi(s)\,{\rm d}L(s).\]
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:25:40.221838+00:00","domain":"probability theory","id":"claim_5a792abc2edb739db7ac721dc9187a5c86ecbeb7f72d2d9aa64dc0c727afe40f","kind":"theorem","schema_version":1,"statement":"[Proposition prop:master-generating of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] A geodesic Leech labeling satisfies the following identity.
\begin{equation}
  \sum_{r=1}^{N}z^r
  =P_A(z)+P_B(z)+C_B(z)
  +\frac{P_A(z)^2-P_A(z^2)}2-C_A(z).
