{"assumptions":[],"created_at":"2026-10-27T23:13:49.899415+00:00","domain":"probability theory","id":"claim_5bb0bd0c200bc7bdad51de95ca29ca3bf37c162982b29b15769150532d8ef2af","kind":"theorem","schema_version":1,"statement":"[Prop graph of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] For any $d \geq 2$, there exist constants $c_{\mathrm{reg}} , C_{\mathrm{reg}}, C_{\mathrm{S}_1}, C_{\mathrm{P}}\in (0, \infty)$ that depend at most on $d$,  
  such that for any $x \in \mathbb{Z}^d$, $n\in \mathbb{N}$ the following holds true:

  \begin{enumerate}[(i)]
  \item (Volume regularity) 

    \begin{align}
      c_{\mathrm{reg}}\, n^d \;\leq\; |B(x, n)| \;\leq\; C_{\mathrm{reg}}\, n^d.
    \end{align}

  \item (Sobolev inequality) 
  For every function $u\colon \mathbb{Z}^d \to\mathbb{R}$ with $\supp{u} \subset B(x, n)$,

    \begin{align} 
      \Norm{u}{d/(d-1), B(x, n)}
      \;\leq\;
      C_{\mathrm{S_1}}\, \frac{n}{\abs{B(x, n)}}\, \sum_{\{y, y'\} \in E_d} |u(y) - u(y')|.
    \end{align}


  \item (Weak Poincar\'{e} inequality) 

    For every function $u\colon \mathbb{Z}^d \to\mathbb{R}$

    \begin{align}
      \Norm{u - (u)_{B(x, n)}}{1, B(x, n)}

      \;\leq\;
      C_{\mathrm{P}}\, \frac{n}{\abs{B(x, n)})} 
      \sum_{\substack{y, y' \in B(x, n)\\ \{y, y'\} \in E_d}}
      \mspace{-24mu}|u(y) - u(y')|,
    \end{align}

    where $(u)_{B(x, n)} \ensuremath{\mathrel{\mathop:}=} \frac{1}{|B(x, n)|} \sum_{y \in B(x, n)} u(y)$.
  \end{enumerate}","status":"unverified"}

