    \end{align*}
    Equivalently
    \begin{align*}
        \left\lVert\nabla f\right\rVert_2^2\geq &\,\frac{N-1}{N(q-2)}\Big(-\left\lVertf\right\rVert_2^2+\left\lVertf\right\rVert_2^{\frac{2N+2}{N-1}}\left\lVertf\right\rVert_1^{-\frac{4}{N-1}}\Big)\nonumber\\
        >&\,c_2N\Big(-\left\lVertf\right\rVert_2^2+\left\lVertf\right\rVert_2^{\frac{2N+2}{N-1}}\left\lVertf\right\rVert_1^{-\frac{4}{N-1}}\Big)\,,
    \end{align*}
    for $c_2$ a constant independent of $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.048817+00:00","domain":"probability theory","id":"claim_5d2cc46c0926e738ae98b45a4adbd6876ed00b225427f9a65848ca3bbaedd33c","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2606.16083, 'Eyring--Kramers asymptotics for infinite-dimensional stochastic gradient systems'] Assume that Assumptions~1 and~2 hold, that $\eta_x\in\mathcal K_A$ for every
$x\in \mathcal T_h$, and that $U\in C^3(B)$. Then the following asymptotics hold  as $\beta\to \infty$.

If $F(x_-)=F(x_+)$, then
\begin{align}

   \lambda_\beta^{(1)}
