{"assumptions":[],"created_at":"2026-10-26T19:25:12.197239+00:00","domain":"probability theory","id":"claim_5f354f01f55ff02ac4526734b28f109094edee69caae19ff31f2ef3ac68d92cd","kind":"concept","schema_version":1,"statement":"[Lem 38 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] With all assumptions in Proposition \ref{prop:new-firstmoment}, we have for all $y\in \tal,z\in \tar$ and $x \in A_{y,z}^{\stable}$, the following holds.
        \begin{enumerate}[label=(\roman*)]
            \item 

            If $c_L(x)\geq 2\delta$, we have
        \begin{equation}
            \sum_{i=1}^{N-1}\mathbb P[(i,i+1)\in E(G_{B_x})]^2\leq C N^{4 c_L(x)- c_F(x)+2c_E( x)+O(\delta)} + e^{-\Omega(N^{\delta-o(1)})}.
        \end{equation}
            \item

            If $ c_L(x)< 2\delta$, $ c_F\geq\delta-(\log N)^{-1/2}$ and $A_{y,z}^{\stable}\neq\{y\vee z\}$, we have
              \begin{equation}
                  \sum_{i=1}^{N-1}\mathbb P[(i,i+1)\in E(G_{B_x})]^2\leq C N^{- c_F(x)+2c_E( x)+O(\delta)} + e^{-\Omega(N^{\delta-o(1)})}.
              \end{equation}
            \item 

            If $c_L(x)<2\delta$ and $ c_F(x)<\delta-(\log N)^{-1/2}$, then $x=y\vee z$ and $A_{y,z}^{\stable}=\{y\vee z\}$.
            \item 

            If $A_{y,z}^{\stable}=\{y \vee z\}$ and $c_L(y \vee z)<2\delta$, 
            we have $x=y\vee z$ and
            \begin{equation}
                \sum_{i=1}^{N-1}\mathbb P[(i,i+1)\in E(G_{B_{x}})]^2\leq C N^{2c_L(x)+2c_E(x)+O(\delta)} + e^{-\Omega(N^{\delta-o(1)})}.
            \end{equation}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:22:01.673047+00:00","domain":"probability theory","id":"claim_5f3814beac86689ae28c18a7190b6b7405b396e9250a76ad4b056ae090aba729","kind":"concept","schema_version":1,"statement":"[Proposition SI_subshift_cocycle of arXiv:2605.02226, 'Finitely Dependent Processes on Subshifts'] Let $ X \subset \mathcal{A}^{\mathbb{Z}^d}$ be a strongly irreducible subshift for $ d \geq 2$. Let $G$ be a finitely generated group and $c:X\times \mathbb{Z}^d\to G$ be a continuous cocycle. For all $x\in X$, consider the map $c_x:\mathbb{Z}^d\to G$ given by $c_x(v)=c(x,v)$. Then there exists a constant $K$ such that
    \begin{enumerate}
            \item For all $x,y\in X$ and $u\in \mathbb{Z}^d$, there are group elements $g_1, g_2\in G$ such that $|g_1|, |g_2|<K$ and $c_x(u)=g_1c_y(u)g_2$.
        \item For all $x\in X$ and $v,w\in \mathbb{Z}^d$, there are group elements $g_1, g_2\in G$ such that $|g_1|, |g_2|<K$ such that $c_x(v+w)=c_x(v)g_1c_x(w)g_2$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.585482+00:00","domain":"probability theory","id":"claim_5f38b5876da82e5489fede3eeb88135a2ea729a0e14839652a837a2b12f47c48","kind":"concept","schema_version":1,"statement":"[Theorem Thm.StrongUniqueness of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] If $\bar{\bar{\nu}}(0+)<\infty$, the stochastic Volterra equation (equation MainThm.SVE of the paper) has a unique strong solution. Moreover, the solution is a semimartingale with the following representation
 	\begin{eqnarray}
 	\left\{ \begin{split}
 	X_\zeta(t) 
 	&= \zeta \cdot c\cdot W'(t)  
 	+  \int_0^\zeta\int_0^\infty \big( W(t) -W(t-y)\big) \, N_0(dz, dy) \cr
 	&\quad + \int_0^t \Big( W''(0+) \cdot M(s) +  \int_0^s W'''(s-r)M(r)\,dr \Big) \, ds + \frac{1}{c}\cdot M(t),\cr
 	M(t) &= \int_0^t   \int_0^r \int_0^{X_\zeta(s)} \int_{r-s}^\infty    \widetilde{N}_\nu(ds,dz,dy)\,dr + \int_0^t \int_0^{X_\zeta(s)} \, B_c(ds,dz).
 	\end{split}
 	\right.
 	\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:04:41.037859+00:00","domain":"probability theory","id":"claim_5f3c99b28d9bdd54a8eef406b0a2407100fd346ab07473aaf12e849fb7dac3cc","kind":"concept","schema_version":1,"statement":"[Lemma l2-02 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Fix a cylinder function $f$. Then, there exists a finite constant
