			+\lambda\,\exp(\lambda\alpha(z,\xi_t^{\lambda,z}))\displaystyle\int_t^{\infty}g(r)p(r-t,z-\xi_t^{\lambda,z},\lambda(r-t))\mathrm{d}r\,\mathbb{I}_{\{\xi_t^{\lambda,z}\neq z \}},
