\[\zone (a, b) := \{(x, y)\in \Half : \exists n\in \N : \tau^{(n)}(x, y) = (a, b).\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:00:22.782228+00:00","domain":"probability theory","id":"claim_61c4bec160dfa5695a8bec8eeb20ace262d7b0963c984bd4c99d48049e63adea","kind":"lemma","schema_version":1,"statement":"[Lm of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] Define 
