{"assumptions":[],"created_at":"2026-10-27T07:21:06.856443+00:00","domain":"probability theory","id":"claim_6473b1000a975eabe9792ce032249eca1a8af8285aa17938d24678506fcce370","kind":"concept","schema_version":1,"statement":"[Theorem 27 (Local well-posedness) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d\in \N, s\in \R$, and assume that one of the following holds:
		\begin{enumerate}
			\item[i)] $p\in (2,\infty)$, $\kappa\in [0,p/2-1)$, and $q\in [2,\infty)$.
			\item[ii)] $p=q=2$ and $s=\kappa=0$.
		\end{enumerate} 
		Assume that one of the following settings holds:
		\begin{enumerate}
			\item $X_0=\bpsn{-2-s,q}$, $X_1=\bpsn{2-s,q}, s\in [0,2\wedge d)$, and Assumption~\ref{Assumption:noise}\ref{assumption:hg1} holds.
			Moreover, assume the (sub)criticality condition
		\begin{equation}
			\frac{1+\kappa}{p}\le \frac{3}{4}-\frac{1}{4}\left(s+\frac{d}{q}\right), 
		\end{equation}
		and assume that, if $\psi^2=0$,
		\begin{equation}
			\max\left\{\frac{d}{3-s},\frac{d}{d-s}\right\}< q <2\frac{d}{s},
		\end{equation}
        otherwise assume 
        \begin{equation}
            \max\left\{\frac{d}{3-s},\frac{d}{d-s}\right\}<q<\frac{d}{s}.
        \end{equation}
        \item $X_0=\bpsn{-2-s,q}, X_1=\bpsn{2-s,q}, s\in [0,1)$, \eqref{eq:lwp:rough:initial:data:1}, \eqref{eq:lwp:rough:initial:data:2}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg2} holds.
			\item $X_0=\bpsn{-1-s,q}, X_1=\bpsn{3-s,q}, s\in [0,2)$, and Assumption~\ref{Assumption:noise}\ref{assumption:hg3} holds. Moreover, assume the (sub)criticality condition
            \begin{equation}
                \frac{1+\kappa}{p}\le 1-\frac{1}{4}\left(s+\frac{d}{q}\right),
            \end{equation}
            and assume that 
            \begin{equation}
                \max\left\{\frac{d}{4-s},\frac{d}{d-s}\right\}<q<\frac{d}{1+s/2}.
            \end{equation}
            \item
             $X_0=\bpsn{-1-s,q}$, $X_1=\bpsn{3-s,q}$,
            $s\in[0,1)$, \eqref{eq:lwp:rough:initial:data:3}, \eqref{eq:lwp:rough:initial:data:4}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg4}
            holds.
		\end{enumerate}
		Then for all $u_a\in L^0_{\F_a}(\Omega; X_{1-\frac{1+\kappa}{p},p})$ there exists a maximal solution $(u,\sigma)$ to \eqref{SCH} with $\sigma>a$ a.s.\ Moreover, for each localising sequence $(\sigma_n)_{n\ge 1}$ for $(u,\sigma)$, one has 
		\begin{itemize}
			\item if $p>2$ and $\kappa\in [0,p/2-1)$, then for all $n\in \N$ and all $\theta\in [0,1/2)$
				\[u\in H^{\theta,p}((a,\sigma_n),w^a_\kappa; X_{1-\theta})\cap C([a,\sigma_n];X_{1-\frac{1+\kappa}{p},p})\quad \text{a.s.}\]
			and we have the instantaneous regularity
			\[u\in H_{\loc}^{\theta,p}((a,\sigma), w^a_\kappa; X_{1-\theta})\cap C((a,\sigma); X_{1-\frac{1}{p},p})\quad \text{a.s.}\]
			\item if $p=2$, then for all $n\in \N$
			\[u\in L^2(a,\sigma_n;X_1)\cap C([a,\sigma_n];X_{1/2})\quad \text{a.s.}\]
		\end{itemize}
		In addition, if equality holds in~\eqref{eq:lwp:rough:initial:data:1} (or in~\eqref{eq:lwp:rough:initial:data:3}) the critical space is $ X_{p,\kappa}^{\textup{Tr}}= \,_\nu B_{q,p}^{\frac{d}{q}-1}(\sO)$. We call $(u,\sigma)$ the $(p,\kappa,s,q)$-solution to \eqref{SCH}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.421850+00:00","domain":"probability theory","id":"claim_6475d0b45826958db1b5f9cf408d37a7351f87f1bb2e0fb8cfac73fc2b54be9b","kind":"lemma","schema_version":1,"statement":"[Lemma 138 of arXiv:2601.16377, '2601.16377'] Choose $\theta > 0$, real parameters $\hat{a},\mathfrak{a},\hat{b},\mathfrak{b}$, and a twice continuously differentiable function $f$ in the range required by the formulae below. We introduce shifted parameters
\[
\hat{a}' = \hat{a} + \frac{\frac{1}{2} - \theta}{\N},\qquad \mathfrak{a}' = \mathfrak{a} + \frac{\frac{1}{2} - \theta}{\N},\qquad \hat{b}' = \hat{b} + \frac{\theta - \frac{1}{2}}{\N},\qquad \mathfrak{b}' = \mathfrak{b} + \frac{\theta - \frac{1}{2}}{\N}.
\]
If $\N(\mathfrak{a} - \hat{a})$ is $\theta$ times a positive integer $M$, we have
\begin{equation}

\begin{split}
& \quad \sum_{i = 0}^{M - 1} f\bigg(\hat{a} + \frac{i\theta}{\N}\bigg) - \frac{\N}{\theta} \int_{\hat{a}'}^{\mathfrak{a}'} f(x)\dd x \\
& = \frac{\theta -1}{2\theta}\big(f(\mathfrak{a}') - f(\hat{a}')\big) + \frac{2\theta^2 - 6\theta + 3}{24\theta \N}\big(f'(\mathfrak{a}') - f'(\hat{a}')\big) + O\bigg(\frac{1}{\N^2}\bigg).
\end{split}
\end{equation}
If $\N(\hat{b} - \mathfrak{b})$ is $\theta$ times a positive integer $M$, we have
\begin{equation}

\begin{split}
& \quad \sum_{i = 1}^{M} f\bigg(\mathfrak{b} + \frac{i\theta}{\N}\bigg) - \frac{\N}{\theta} \int_{\mathfrak{b}'}^{\hat{b}'} f(x)\dd x \\
& = \frac{\theta -1}{2\theta}\big(f(\mathfrak{b}') - f(\hat{b}')\big) + \frac{2\theta^2 - 6\theta + 3}{24\theta \N}\big(f'(\hat{b}') - f'(\mathfrak{b}')\big) + O\bigg(\frac{1}{\N^2}\bigg).
\end{split}
\end{equation}
If $\N(\mathfrak{a} - \mathfrak{b})$ is $\theta$ times a positive integer $M$, we have
\begin{equation}

\begin{split}
& \quad \sum_{i = 1}^{M - 1} f\bigg(\mathfrak{b} + \frac{i\theta}{\N}\bigg) - \frac{\N}{\theta} \int_{\mathfrak{b}'}^{\mathfrak{a}'} f(x)\dd x \\
& = \frac{\theta -1}{2\theta}\big(f(\mathfrak{b}') + f(\mathfrak{a}')\big) + \frac{2\theta^2 - 6\theta + 3}{24\theta\N}\big(f'(\mathfrak{a}') - f'(\mathfrak{b}')\big) + O\bigg(\frac{1}{\N^2}\bigg).
\end{split}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.856258+00:00","domain":"probability theory","id":"claim_6475d8f8104ee94a23be4eb363860fc8b0204281d348326ff9130e8882e4fc37","kind":"concept","schema_version":1,"statement":"[Lemma 24 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d=4$ and suppose that the assumptions of Theorem~\ref{thm:localWP_weakened} hold. Moreover, let $u_0\in L^0_{\F_0}(\Omega;H^1(\sO))$ and $T>0$. Let $(u,\sigma)$ be the unique maximal solution to \eqref{eq:SCHtorus} and $\mu$ the associated chemical potential from Definition~\ref{def:chemPotential}. Then the following three estimates hold a.s.\ for a.e.\ $0\le s <\sigma \land T$
    \begin{align}
        \|\Delta u(s)\|_{L^2}^2  & \le \|\mu(s)\|_{L^2}^2 + 2\| \grad u(s)\|_{L^2}^2 , \\
         \|u^2(s)\nabla u(s)\|_{L^2}^2 & \lesssim
        \|u(s)\|^3_{H^1}
        \left(\|\Delta u(s)\|_{L^2}^2
        +\|u(s)\|^2_{H^1}  \right)
        \left( \|\grad \Delta u(s)\|_{L^2}
        +\|u(s)\|_{H^1}\right),
         \\
        \|\mu(s)\|_{L^2}^4 & \lesssim \|\nabla\mu(s)\|_{L^2}^2 \left(\|u(s)\|_{H^1}^6 + 1\right) + 1
        + \|u(s)\|_{H^1}^{12}. 
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:55.644410+00:00","domain":"probability theory","id":"claim_6479d1833b6088cd209b27d81490af55c3d541267798ad7ff5761f2eddce1178","kind":"concept","schema_version":1,"statement":"[Theorem 18 (\citet{GLSS}) of arXiv:2605.24445, 'Matrix concentration inequalities for time-inhomogeneous Markov chains'] Let \(H_{1},\dots,H_n\in\Hm\). Then, there exists a probability measure $\nu$ on  $[-\pi/2,\pi/2]$ such that
