{"assumptions":[],"created_at":"2026-10-27T13:52:23.567220+00:00","domain":"probability theory","id":"claim_6487ab1e408adf34d49560766185d21773b6a8ba10fed427300a8643135c7b44","kind":"theorem","schema_version":1,"statement":"[Theorem T:SLND of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Assume Hypothesis (H:para of the paper) and the Dalang condition~(equation E:main of the paper). Let $0<S<T<\infty$.
  \begin{enumerate}[\rm (i)]

    \item \emph{(SLND in time)}\index{strong local nondeterminism (SLND)!temporal}
          \begin{enumerate}[\rm (a)]

            \item If $\beta = 1$, $\gamma \ge 0$; or $\beta = 2$, $\gamma \in [0,
                      1]$, then there exist constants $C > 0$ and $\delta>0$ such that for
                  all $x \in \mathbb{R}^d$, for all $n \ge 1$, and for all $t, t_1, \dots, t_n
                    \in [S, T]$ with $\max_{1\le j \le n}|t-t_j| \le \delta$,
                  \begin{align}
                    \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \big) \ge C \min_{1 \le j \le n} |t-t_j|^{2\rho}.
                  \end{align}

            \item If $\beta \in (0, 2)$, $\gamma \ge 0$, then there exists a constant $C>0$ such
                  that for all $x \in \mathbb{R}^d$, for all $n \ge 1$, and for all $t, t_1,
                    \dots, t_n \in [S, T]$ with $\max\{t_1, \dots, t_n \} \le t$,
                  \begin{align}
                    \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \big) \ge C \min_{1 \le j \le n} (t-t_j)^{2\rho}.
                  \end{align}

          \end{enumerate}

    \item \emph{(SLND in space)}\index{strong local nondeterminism (SLND)!spatial} If $\beta \in (0, 2]$, $\gamma \ge 0$, then
          for any $M>0$, there exists a constant $C>0$ such that for all $t \in [S,
              T]$, for all $n \ge 1$, and for all $x, x_1, \dots, x_n \in B(0, M)$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t, x_1), \dots, u(t, x_n) \big) \ge C \min_{1 \le j \le n} |x-x_j|^{2\tilde\rho}.
          \end{align}

  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:42:16.243897+00:00","domain":"probability theory","id":"claim_64938c62be3637b2074489182ef03122e56ac333126f6ae2e5c22c859acee0e8","kind":"concept","schema_version":1,"statement":"[Lemma firstlemma of arXiv:2607.01463, 'Two Multi--Draw Coupon Collector models with different retention rules'] Let $\phi(s)$ be analytic in a domain that contains the half--line $[n_{0},\infty)$. Then, the differences of the sequence $\left\{\phi(k)\right\}$ admit the integral representation
\begin{equation}
\sum_{k=n_{0}}^{N}\binom{N}{k}\left(-1\right)^{k+1}\phi(k)=\frac{\left(-1\right)^{N+1}}{2i \pi } \int_{\mathcal{C}} \phi(s)\frac{N!}{s\left(s-1\right)\cdots\left(s-N\right)}\,ds,
\end{equation}
where $\mathcal{C}$ is a positively oriented closed curve that lies in the domain of analyticity of $\phi(s)$, encircles $[n_{0}, N]$, and does not include any of the integers $0,1,\cdots,n_{0}-1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:57:28.723675+00:00","domain":"probability theory","id":"claim_6499132c268dfc8947cac101acd1fc1105f315faaf8aafcfe60d91a6bca68b73","kind":"concept","schema_version":1,"statement":"[Theorem 20 of arXiv:2609.01190, 'Rough differential equations on manifolds via natural bundles'] Let $[S,T]\subseteq\Rsf$ be an interval and let $m,n\in\Nsf$. Let $p\in [1,3)$, let $\omega$ be a control function on interval $[S,T]$, and let $X$ be an $n$-dimensional branched rough path on interval $[S,T]$ with regularity $p$ and control $\omega$. Let $f: \Rsf^m\to R_n^2\Rsf^m$ be a compactly supported admissible rough velocity field and $(f^i_\tau)$ its global coordinate representation. Then for each $Y_0\in\Rsf^m$, there exists a function $Y: [S,T]\to \Rsf^m$ satisfying $Y(S)=Y_0$ for which there exists a constant $C\in (0,\infty)$ such that the inequality 
	\begin{equation}

		\left|
			Y^i(t) - Y^i(s) 
			- \sum_{\tau\in\Fcal_n^2} \frac{1}{\sigma(\tau)} f_{\tau}^i(Y(s)) X^\tau(s,t)
		\right|
		\leq C \omega(s,t)^\frac{3}{p}
	\end{equation}
holds for every $i\in \llbracket 1,m\rrbracket$ and $(s,t)\in \Delta[S,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.055074+00:00","domain":"probability theory","id":"claim_649dbb02024ad8540f871d57bacfadc88252aad4912260285943ab97dbaf2589","kind":"lemma","schema_version":1,"statement":"[Lemma 7 (Cole--Hopf differentiation) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $g : \R \to \R$ be a twice differentiable function with $g$ of at most linear growth and $g'$, $g''$ of at most exponential growth, and let $m \ge 0$. For every $t \ge 0$ and $x \in \R$, let $u(t,x)=T_{m,t}g(x)$.
We have
\begin{equation}

    \dr_x u=\mathcal L_{mg,t}g',
\end{equation}
\begin{equation}

    \dr_t u
    =\dr_x^2 u+m (\dr_x u)^2
    =\mathcal L_{mg,t}\bigl(g''+m(g')^2\bigr),
\end{equation}
and
\begin{equation}

    \left.
    \frac{d}{d\varepsilon}
    T_{m,t}(g+\varepsilon h)(x)
    \right|_{\varepsilon=0}
    =
    \mathcal L_{mg,t}h(x).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:48:02.399232+00:00","domain":"probability theory","id":"claim_64a6871db4946770df0dbac416da484b9d920b9c640e297d3a64cb081cdc74f5","kind":"theorem","schema_version":1,"statement":"[Theo lichlap of arXiv:2608.25865, 'Instability of Böhm's Einstein metrics'] In the basis $(e_0,e_i,e_\alpha)$, the Lichnerowicz Laplacian of the tensor $T=a(t)dt^2+\phi(t)f(t)^2g^k+\psi(t)h(t)^2g^l\in \mathscr{T}^G_{TT}(M)$ (where $M=S^{k+1}\times S^l$ or $S^{k+l+1}$) is diagonal, with
\begin{align*}
  (\Delta_L T)_{00}&=-a''(t)-Ha'(t)+2k\left(\frac{f'^2}{f^2}-\frac{f''}{f}\right)(a(t)-\phi(t))+2l\left(\frac{h'^2}{h^2}-\frac{h''}{h}\right)(a(t)-\psi(t)),
\\
  (\Delta_L T)_{ii}&=-\phi''(t)-H\phi'(t)-2\left(\frac{f'^2}{f^2}-\frac{f''}{f}\right)(a(t)-\phi(t))+2\frac{f'h'}{fh}l(\psi(t)-\phi(t)),
\\
  (\Delta_L T)_{\alpha\alpha}&=-\psi''(t)-H\psi'(t)-2\left(\frac{h'^2}{h^2}-\frac{h''}{h}\right)(a(t)-\psi(t))+2\frac{f'h'}{fh}k(\phi(t)-\psi(t)),
\end{align*}
where $\displaystyle H=k\frac{f'}{f}+l\frac{h'}{h}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.620652+00:00","domain":"probability theory","id":"claim_64a6b1ded1c975af5463c8651708102eb43b77bda0157ba92fa85a48a8059a73","kind":"theorem","schema_version":1,"statement":"[Prop prop_boundary_regular_odes of arXiv:2606.23648, '\textsc{Optimal Stopping for a Diffusion with Unobserved Bernoulli Drift}'] Let \(x_0\in\mathcal I\).

    \noindent \textbf{(i)} \quad Suppose first that \(a(x_0)>-x_0\) and
    \(
        H(x_0,a(x_0))H(x_0,b(x_0))\neq0.
    \)
    Then there exists a neighborhood \(J\) of \(x_0\) in \(\mathcal I\) such that \(a(\cdot)\) and \(b(\cdot)\) are \(C^1\) on \(J\). Moreover, with
    \begin{equation}
        M(x; a, b)
        \coloneqq
        \frac{k'(x+b)-k'(x+a)}
             {G(b)-G(a)},
    \end{equation}
    we have, for \(x\in J\), the system of coupled ordinary differential equations
    \begin{equation}
    \begin{split}
        a'(x)
        &=
        \frac{G'(a(x))}{2H(x,a(x))}
        \left(
            M\big(x; a(x), b(x)\big)-\frac{k''(x+a(x))}{G'(a(x))}
        \right),
        \\
        b'(x)
        &=
        \frac{G'(b(x))}{2H(x,b(x))}
        \left(
            M\big(x; a(x), b(x)\big)-\frac{k''(x+b(x))}{G'(b(x))}
        \right).       
    \end{split}
    \end{equation}

    \noindent \textbf{(ii)} \quad Suppose next that \(J\subset\mathcal I\) is an open interval on which \(a(x)=-x\), and that
    \(
        H(x,b(x))\neq0,\, x\in J.
    \)
    Then \(b(\cdot)\) is \(C^1\) on \(J\). Moreover, with
    \begin{equation}
        M_0(x; b)
        \coloneqq
        \frac{
            k'(x+b)-k'(0+)
            +
            \big(\Phi(x,-x)-\Phi(x,b)\big)G'(-x)
        }
        {G(b)-G(-x)},
    \end{equation}
    we have, for \(x\in J\), the differential equation
    \begin{equation}
        b'(x)
        =
        \frac{G'(b(x))}{2H(x,b(x))}
        \left(
            M_0(x; b(x))-\frac{k''(x+b(x))}{G'(b(x))}
        \right), \qquad x \in J
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.895330+00:00","domain":"probability theory","id":"claim_64a9528b7f9d4749fe41fd8ca1a56045aa0f098da31b55aeb9de8744dc1ce6bb","kind":"theorem","schema_version":1,"statement":"[Prop u_R_L_x^2_priori_esti of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Assume $u_0\in L_x^2$ and $ k\in L_x^\infty L_y^2$. For any fixed $ R,T>0$, let $u_R$ be the solution constructed in Proposition (localwellres of the paper). Then for any stopping time $0\leq \sigma\leq \sigma_R^T(u_R)$ almost surely, we have
