			& \ \ + \frac{\upmu X^i}{\Speed^2}  \mytr_{\gtorus} \angk - \frac{\upmu X^i}{\Speed^2} \mytr_{\gtorus}\upchi,
		\end{split}
	\end{align}
where $\angularcoeffinmuweightedspatialcartesian_i^A$ are the $3\times 2$ matrices from \eqref{E:ANGULARCOEFFINMUWEIGHTEDCARTESIAN}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:48:49.882068+00:00","domain":"probability theory","id":"claim_661603b384a5e0464b3a578038351ee89c87477b1801a8a6885aa3b627849de2","kind":"theorem","schema_version":1,"statement":"[Prop branching-rules of arXiv:2510.23430, 'On the Martin boundary for discrete TASEP'] There exist symmetric functions $G^{(\mathfrak a,\mathfrak b)}_{\lambda/\mu}\in\hat\Lambda$, $g^{(\mathfrak a,\mathfrak b)}_{\lambda/\mu}\in\Lambda$ satisfying the following properties:
\begin{itemize}
\item One variable specializations $G^{(\mathfrak a,\mathfrak b)}_{\lambda/\mu}(x), g^{(\mathfrak a,\mathfrak b)}_{\lambda/\mu}(x)$ coincide with (equation Gone of the paper), (equation gone of the paper);

\item $G^{(\mathfrak a,\mathfrak b)}_{\lambda/\varnothing}=G^{(\mathfrak a,\mathfrak b)}_{\lambda}$, $g^{(\mathfrak a,\mathfrak b)}_{\lambda/\varnothing}=g^{(\mathfrak a,\mathfrak b)}_{\lambda}$;

\item The following branching rules hold for any sets of variables $\mathbf{x}, \mathbf{y}$
$$
G_{\lambda/\mu}^{(\mathfrak a,\mathfrak b)}(\mathbf{x}, \mathbf{y})=\sum_{\nu}G^{(\mathfrak a,\mathfrak b)}_{\lambda/\nu}(\mathbf{x})G^{(\mathfrak a,\mathfrak b)}_{\nu/\mu}(\mathbf{y}),
$$
$$
g_{\lambda/\mu}^{(\mathfrak a,\mathfrak b)}(\mathbf{x}, \mathbf{y})=\sum_{\nu}g^{(\mathfrak a,\mathfrak b)}_{\lambda/\nu}(\mathbf{x})g^{(\mathfrak a,\mathfrak b)}_{\nu/\mu}(\mathbf{y}),
$$
\end{itemize}","status":"unverified"}

