			\sup_{z\in\mathbb R}
			\left\|
			\partial_y
			\left[
			\sigma(\cdot)
			\partial_y\mathsf K_\sigma(z,\cdot)
			\right]
			\right\|_{L_y^1} \le
			\frac12
			\|\sigma'\|_{L^\infty}
			\|\sigma^{(3)}\|_{L^1}
			+
			\frac16
			\|\sigma\|_{L^\infty}
			\|\sigma^{(4)}\|_{L^1}.

		\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:47:07.704893+00:00","domain":"probability theory","id":"claim_68ef4cc2c7883cfc16b9ad09b0961aaea730703468a09c5c6bb8fd7b1390e394","kind":"concept","schema_version":1,"statement":"[Corollary 16 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] For $B\in\cX_0$ we have
  \begin{equation}

    \BE \partial\eta(B)^{(2)}
    =\BE \lambda_{[\eta]^c}(B)^2
    -2 \,\BE \int_B \I\{x\notin[\eta]\}
    \lambda_B\big([\eta+\delta_x]\setminus[\eta]\big)\,\lambda(dx).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:57:28.219676+00:00","domain":"probability theory","id":"claim_68f4e0b07f269caa378ed72f9b8f177c05ee5915aae896452a0d85094996f3fd","kind":"theorem","schema_version":1,"statement":"[Thm 6 of arXiv:2607.17576, 'How much randomness is needed to symmetrize a random variable?'] Let $0<p<1$ and write $q:=1-p$. Let $X\sim\text{Geom}(p)$ be a geometric random variable with the probability mass function $f_X(k)=pq^k$ for $k\in \mathbb{Z}_{\ge 0}$. Let $Y$ be an integer-valued independent symmetrizer of $X$. Then we have for all $\alpha>0$ that
\begin{equation}
H_\alpha (Y)\ge H_\alpha(X)
\end{equation}
and
\begin{equation}
T_\alpha (Y)\ge T_\alpha(X).
\end{equation}
Equality holds if and only if $Y$ is an independent copy of $-X$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.414160+00:00","domain":"probability theory","id":"claim_68f94e6c733819a85a5314410a660730f66afe3471f55e5a172cd6c93d54886f","kind":"lemma","schema_version":1,"statement":"[Lemma eq:connection-to-far of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:exp_deg_geq_r}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and let $J : V \times V \to \mathbf{R}_+$ be a transitive kernel with $J(x,y) = O(d_G(x,y)^{-d \alpha})$ with $\alpha > 1$. 

    Then there exist $c = c(G,J)$ and $C = C(G,J) > 0$ such that for all $x \in G$ and $r \in \mathbf{N}$

    \begin{equation}
        c
        \beta
        r^{d(1-\alpha)}
        \leq 
        \sum_{L = r}^{\infty}
        \expdegrad{x}{L}
        \leq 
        C
        \beta
        r^{d(1-\alpha)}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:06.328668+00:00","domain":"probability theory","id":"claim_68fc605d9fe81cecfa41f6ee2bdaf9f5f2f5aa544aa98fec85f88715af2a3d69","kind":"definition","schema_version":1,"statement":"[Definition 3 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] {\em (Spectral density)}
    Let $(\mathbf{x}_t)_{t\geq 0}$ be a (weakly) stationary $n$-dimensional stochastic process with
    $$\int_\R V(\tau)~\txtd\tau<\infty.$$ Then the spectral density is defined as 
    \begin{align}
        S_\mathbf{x}(\omega):= \mathcal{F}(V(\tau))(\omega)=\frac{1}{2\pi}\int_\R e^{-i\omega \tau} V(\tau)~\txtd \tau,
    \end{align}
    where the Fourier transform $\cF$ is interpreted componentwise.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:45:02.089628+00:00","domain":"probability theory","id":"claim_68fcfa4c892a8c0763f0968f330390f26315de96c1c06a052f7e5bce2fab36cf","kind":"theorem","schema_version":1,"statement":"[Prop size-to-length_estimate of arXiv:2601.00119, 'The largest common subtree of two random trees'] For all $\varepsilon\in (0,1/4)$, $\delta>0$, and $m\geq 1$, there exists an integer $N\geq 3$ such that for all $n$ large enough, it holds that
\begin{multline*}
\mathbf{P}\big(\#\tau\vee\#\tau'\leq n\, ;\, \mathrm{Ht}(\tau)\leq n^{1/2+\varepsilon} \, ;\, \Delta(\tau)\leq n^{1/2-2\varepsilon}\, ;\, \Delta(\tau')\leq n^{1/2+\varepsilon}\, ;\,\\
\big|\operatorname{LCS}(\tau,\tau')-c_{\mu,\mu'}\operatorname{LCS}_N(\tau,\tau')\big|>\delta\sqrt{n}\big)\leq n^{-m}.
\end{multline*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.655971+00:00","domain":"probability theory","id":"claim_6902bd5e202cb2d888b17e79cd072976d920f62218585a923ca90a5742e44815","kind":"lemma","schema_version":1,"statement":"[Lem 10 of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] Let $\Lambda>3$. There exist positive constants $c$ and $C_{\Lambda}$ such that, for all sufficiently large $K$, if $z \in Q_{0,\Lambda r}\setminus Q_{0,3r}$, $\varepsilon>0$,  $i \in \{1, \cdots, \varepsilon^{-1}\}$, $r\geq1$, $\alpha>0$ and $\delta'>0$ satisfy $\alpha>2\delta'$, then
