			\end{align*}
			Let
			\begin{align*}
				h(t)=\frac{C}{{z^2(t,\omega)}}\|\nabla v^\varepsilon(t) \|_{L^2}^{2} ( \| \nabla \rho(t)\|_{L^2}^{2} + \|\nabla \sigma(t)\|_{L^2}^{2}).
			\end{align*}
			Applying Lemma (lem (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

