    p^J=(p^J_{ij})_{i,j\in J}:=p_{JJ}+\sum_{l=0}^\infty p_{JI}p_{II}^lp_{IJ},
  \end{align}
  which is a convergent series with $p_{ij}^J=Q^{C,\Lambda}_i(X^J_1=j)$.
  Furthermore, we define
  \begin{align}
    C^J=(C^J_{ij}:=C_ip^J_{ij})_{i,j\in J}, \quad
    q^J=\left(q^J_{ij}:=\frac{C_i}{\pi_i}p^J_{ij}\right)_{i,j\in J}.
  \end{align}
  The notation $p^{J\neq}$, $q^{J\neq}$, and $C^{J\neq}$ means that the two
  operations $\mbox{}^J$ and $\mbox{}^{\neq}$ have been applied successively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.058506+00:00","domain":"probability theory","id":"claim_6e8b41d59c42b020828d82e79be82938e180193f55e1ede30776958a88237e1e","kind":"lemma","schema_version":1,"statement":"[Lemma 43 (Explicit balanced models) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Assume that $\xi$ has the expansion
\begin{equation}

    \xi(a)=\sum_{p\geq1}\sum_{s_1,\ldots,s_p\in\sS}\Delta^2_{s_1,\ldots,s_p}a_{s_1}\cdots a_{s_p},\qquad a\in\R^\sS,
