{"assumptions":[],"created_at":"2026-10-27T19:55:37.878974+00:00","domain":"probability theory","id":"claim_6fded08b5009a0bdea22cd32ef49b5c9f24a4cd8a94da1ff5a0b2ffff447d0b0","kind":"concept","schema_version":1,"statement":"[Lem l:weakM1transf of arXiv:2605.08983, 'A functional limit theorem for self-normalized linear processes with random coefficients a'] Let $(A_{n}, B_{n})$, $n=0,1,2,\ldots$, be stochastic processes in $D^{2}$ such that, as $n \to \infty$,
\begin{equation}
(A_{n}, B_{n}) \xrightarrow{d} (A_{0}, B_{0})
\end{equation}
in $D^{2}$ with the weak $M_{1}$ topology. Suppose $x_{n}$ and $y_{n}$, $n=0,1,2,\ldots$, are elements of $D^{1}$ with $x_{0}$ and $y_{0}$ being continuous, such that, as $n \to \infty$,
$$x_{n}(t) \to x_{0}(t) \qquad \textrm{and} \qquad y_{n}(t) \to y_{0}(t) $$
uniformly in $t$. Then
$$ (A_{n} +x_{n}, B_{n} + y_{n}) \xrightarrow{d} (A_{0} + x_{0}, B_{0} + y_{0})$$
in $D^{2}$ with the weak $M_{1}$ topology. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:50:30.568397+00:00","domain":"probability theory","id":"claim_6fe6ab3db734c1b18972c108bb62aca14522f397eadbd838b1ac0dc46fffea26","kind":"concept","schema_version":1,"statement":"[Pro 5 of arXiv:2605.30779, '2605.30779'] Let \(\{a_{\beta,j}\}_{j\ge1}\) be the Airy\(_\beta\) point process, arranged in decreasing order, and let \(\{\xi_{\beta,j}\}_{j\ge1}\) be independent and identically distributed (i.i.d.) random variables, independent of \(\{a_{\beta,j}\}_{j\ge1}\), with \(\xi_{\beta,j}^2\sim\chi_\beta^2\). Then, almost surely, the Airy-Green function for general $\beta>0$
\begin{equation}
    \mathcal G^{(\beta)}(w)
    :=
    \lim_{x\to-\infty}
    \left[
      \sum_{j:\,a_{\beta,j}>x}
      \frac{\beta^{-1}\xi_{\beta,j}^2}{w-a_{\beta,j}}
      -\frac{2}{\pi}\sqrt{-x}
    \right]
  \end{equation}
  exists for every \(w\in\mathbb C\setminus\{a_{\beta,j}:j\ge1\}\), uniformly on compact subsets avoiding the poles. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:42:57.182537+00:00","domain":"probability theory","id":"claim_6fe7f4c65a4665faf48e918d03fc2b1147ab0bcb211441cd1aeea9e7d9dd1382","kind":"definition","schema_version":1,"statement":"[Definition def:weak_axioms of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] We define a \emph{geodesic CLE$_4$ metric coupling} to be a family of couplings
	\begin{equation*}
		D = \left\{\left( \Gamma_U, D_{\Gamma_U}^U \right)\right\}_U
	\end{equation*}
	where $U \subsetneq \BC$ ranges over all simply connected domains and $\Gamma_U$ is a non-nested CLE$_4$ in $U$, such that the following conditions are satisfied for every such $U$ and all deterministic choices of the auxiliary data below:
	\begin{enumerate}[label=(\Roman*), ref=\Roman*]
		\item {\bfseries (Geodesic metric)} $D_{\Gamma_U}^U$ is a.s.\ a metric on $\Gamma_U$ such that the following hold.
		\begin{enumerate}[label=(\roman*), ref=\roman*]
			\item For each $\SCL_1, \SCL_2 \in \Gamma_U$, there exists an admissible path $P$ (which we refer to as a \emph{$D_{\Gamma_U}^U$-geodesic}) connecting $\SCL_1$ and $\SCL_2$ such that $D_{\Gamma_U}^U(\SCL_1, \SCL_2) = \len(P; D_{\Gamma_U}^U)$. The same is true with a deterministic connected arc (resp.\ two deterministic and disjoint connected arcs) of $\partial U$ in place of $\SCL_1$ (resp.\ $\SCL_1$ and $\SCL_2$).
			\item Let $\phi\colon U \to \BD$ be a conformal mapping. For each $\SCL \in \Gamma_U$, the process $(\phi(\SCB_t(\SCL; D^U_{\Gamma_U}){)})_{t\ge 0}$ is c\`adl\`ag for the Hausdorff distance (with the convention of (subsec:setup of the paper)), and the same is true with a deterministic connected arc of $\partial U$ in place of $\SCL$.
			\item For all $t, s\ge 0$, if $\SCB_t(\SCL_1; D^U_{\Gamma_U}) \cap \SCB_s(\SCL_2; D^U_{\Gamma_U}) \neq \emptyset$, then $D^U_{\Gamma_U} (\SCL_1, \SCL_2) \le t+s$. The same is true with a deterministic connected arc (resp.\ two deterministic and disjoint connected arcs) of $\partial U$ in place of $\SCL_1$ (resp.\ $\SCL_1$ and $\SCL_2$).
		\end{enumerate}
		Note that $\len(P; D_{\Gamma_U}^U) \ge D_{\Gamma_U}^U(\SCL_1,\SCL_2)$ for every admissible path $P$ connecting $\SCL_1$ and $\SCL_2$, by the triangle inequality along the chains in the definition of $\len$; a path attaining equality is thus length-minimizing, which is what the term geodesic refers to. 
		\item {\bfseries (Locality)} Let $V \subset U$ be a deterministic simply connected subdomain. Let $I \subset \partial U$ be a deterministic connected arc. Let $\{V_j\}_j$ be the connected components of $V^\star$. Then, conditionally on the $\sigma$-algebra generated by
		\begin{multline}
			\bigl\{\SCL \in \Gamma_U : \SCL \not\subset V\bigr\}, \quad \bigl\{\SCB_t(\SCL; D_{\Gamma_U}^U) : \SCL \in \Gamma_U, \ \SCL \not\subset V, \ t \in [0, D_{\Gamma_U}^U(\SCL, \partial V^\star)]\bigr\}, \\
			\text{and} \quad \bigl\{\SCB_t(I; D_{\Gamma_U}^U) : t \in [0, D_{\Gamma_U}^U(I, \partial V^\star)]\bigr\},
		\end{multline}
		the $(\Gamma_U|_{V_j}, D_{\Gamma_U}^U(\bullet, \bullet; V_j))$'s are independent and their conditional laws are those of $(\Gamma_{V_j}, D_{\Gamma_{V_j}}^{V_j})$, respectively. 
		\item {\bfseries (Conformal invariance)} Let $\phi \colon U \to \phi(U)$ be a deterministic conformal mapping. Then,
		\begin{equation*}
			\left(\phi(\Gamma_U), \left( D_{\Gamma_U}^U\left(\phi^{-1}(\SCL_1), \phi^{-1}(\SCL_2) \right) \right)_{\SCL_1, \SCL_2 \in \phi(\Gamma_U)} \right)
			\overset{(\mathrm{d})}{=} \left( \Gamma_{\phi(U)}, \left(D_{\Gamma_{\phi(U)}}^{\phi(U)}(\SCL_1, \SCL_2) \right)_{\SCL_1, \SCL_2 \in \Gamma_{\phi(U)}} \right).
		\end{equation*}
		The equality in law is understood as in (def:weak_axioms of the paper).\item {\bfseries (Uniform exploration)} The collection $\{(\SCL, D_{\Gamma_U}^U(\SCL, \partial U))\}_{\SCL \in \Gamma_U}$ has the law of a uniform exploration of $\Gamma_U$ (cf.~[CoInCLEExpl]), in the sense of (def:weak_axioms of the paper).
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.531203+00:00","domain":"probability theory","id":"claim_6feca7c4a6f25cd1a90a23c65367d1b13722992af8c49a019aad857df35b6cb9","kind":"concept","schema_version":1,"statement":"[Thm SIR-thm of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Suppose either: \begin{itemize}
        \item $\tilde \lambda > 0$ and $\alpha_1, \alpha_2$ are small enough.
        \item $\Lambda < 0$, where 
        \begin{equation}
             \begin{aligned}
        \Lambda \coloneqq \sup_{\mu \in P_{inv}(\mathcal{M}_0)} \mu\Big(-\int_D \frac{\beta \tilde S}{1 + c_1 \tilde S}\tilde I\Big) + \eta + \delta + \sigma + \frac{1}{2}\alpha_2^2
    \end{aligned}
        \end{equation}
 and $P_{inv}(\mathcal{M}_0)$ denotes the set of all invariant measures of the process $(\tilde S_t, \tilde I_t / \|\tilde I_t\|_{L^1})$ on
    $$\mathcal{M}_0 \coloneqq \{(S,I) \in C(\overline D;\mathbb{R}^2) \mid \|I\|_{L^1} = 1, S \geq 0, I \geq 0\} \,,$$
    where $(\tilde S_t, \tilde I_t)$ solves (equation SIR-linearized of the paper).
    \end{itemize} 

    Then the disease is stochastically persistent in the sense that
    \begin{itemize}
        \item There is an invariant measure $\mu_+$ for (equation SIR of the paper) with $\mu_+(\{I = 0\}) = 0$.
        \item For all $\delta > 0$ there are $0 < b < B < \infty$ such that for any nonnegative initial condition $(S_0,I_0)$ with $I_0 \neq 0$, $$
        \liminf_{T \to \infty} \frac{1}{T}m\Big(\Big\{t \leq T \mid b \leq \int_D I_t \leq B\Big\}\Big) \geq 1 - \delta$$ 
        almost surely, where $m$ is the Lebesgue measure.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:40:22.274675+00:00","domain":"probability theory","id":"claim_6fed29d8ab95e624bce47d9756459c04a0d66e3d000cc62116cd47bcc44918bb","kind":"concept","schema_version":1,"statement":"[Thm some.precise.degrees.biased of arXiv:2609.02588, 'Ramsey-type results for Maker-Breaker games'] Let $b\geq 1$, then the following holds:
\begin{enumerate}
