{"assumptions":[],"created_at":"2026-10-27T08:02:08.150356+00:00","domain":"probability theory","id":"claim_70feb00165c821248f3c2290b9c286f4aa8b6d38a9a56239f5ee5e6962c4d641","kind":"theorem","schema_version":1,"statement":"[Proposition 38 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] Let $a,b>0$, and $Z=(L,R)$ be a sample from 
     $a B^{\gamma, \bH}_{0, -a+ib}$ of (random) duration $T$ such that $L_T=-a$. Let $L_{\mathrm{inf}}=\inf_{0\leq u\leq T}L_u$, and $c$ be sampled from the uniform probability measure on $(-L_{\mathrm{inf}}-a,-L_{\mathrm{inf}})$. Let $\tau = \inf\{u\in[0,T]:L_u=-c\}$. Let $Z^1 = Z|_{[0,\tau]}+c$ and $Z^2(t) = Z(t+\tau)-Z(\tau)$ for $t\in[0,T-\tau]$. Then for some constant $C_\gamma>0$ depending only on $\gamma$, $(Z^1,Z^2) = ((L^1,R^1),(L^2,R^2))$ has the joint law 
    \begin{equation}
          C\int_0^\infty \int_0^\infty \mathds{1}_E\big(B_{c,id}^{\gamma,\bbR_+^2}\times B^{\gamma,\bC}_{0,(c-a)+(b-d)i}\big)\,\d d\,\d c,
    \end{equation}
    where   $$E=\{L_{T_2}^2- \inf_{t\in [0,T_2]} L_t^2< c \}\cap \{-\inf_{t\in[0,T_2]}R_t^2\leq d \}; \ \ T_2 \text{ is the duration of }Z^2.  $$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:06:39.355145+00:00","domain":"probability theory","id":"claim_7104970676ad221fc47131b19a06310bdb81b75007c794126fe8cecd76d72541","kind":"concept","schema_version":1,"statement":"[Theorem t:suboptimal_Lq_finite_time of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Fix $r\in (1,\infty)$ and an interval $I=(0,T)$ for some $T<\infty$. Let $p,q\in (2,\infty)$ be such that the Sobolev index $\mathtt{Sob}\stackrel{{\rm def}}{=}1-\frac{2}{p}-\frac{d}{q}$ satisfies
\begin{equation}

-\frac{d}{2}\leq \mathtt{Sob} <0, \qquad \text{ and }\qquad p<\frac{d}{-\mathtt{Sob}},
\end{equation}
Moreover, set $q_{{\rm max}}\stackrel{{\rm def}}{=}-\frac{d^2}{d-2}\frac{1}{\mathtt{Sob}}$, 
with the convention $q_{{\rm max}}=\infty$ if $d=2$.
Then for all $p_0\in (2,\infty)$ and $q_0\in (2,q_{{\rm max}})$ satisfying 
\begin{equation}

-\frac{2}{p_0}-\frac{d}{q_0}<\mathtt{Sob},
\end{equation}
there exists a constant $C_0$ such that, for all $N\geq 1$, 
\begin{equation}

w_0\in L^r_{{\mathscr F}_0}(\Omega;\mathbb{B}^{1-2/p}_{q,p}(\mathbb{T}^d))\qquad \text{ and }\qquad F\in L^r_{\mathscr{P}}(\Omega;L^p(I ;L^q(\mathbb{T}^d;{\mathbb R}^{d\times d}))),
\end{equation}
the unique energy solution $w^N$ to the oscillating stochastic Stokes system (equation eq:turbulent_Stokes_scaling_uniform_estimates of the paper) provided by Lemma (l:global_energy_estimate of the paper) satisfies
\begin{align}

\big({\mathbf E}\|w^N\|_{L^{p_0}(I;L^{q_0} (\mathbb{T}^d))}^{r} \big)^{1/r}
&\leq C_0 \big({\mathbf E}\|w_0\|_{B^{1-2/p}_{q,p}(\mathbb{T}^d)}^r\big)^{1/r}\\
\nonumber
& + C_0  \big({\mathbf E}\|F\|_{L^p(I;L^q(\mathbb{T}^d))}^r\big)^{1/r}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:10:05.677182+00:00","domain":"probability theory","id":"claim_710c32ceb3a495428f70baa2f94b06a9151f0a67bf6a08e489a4d8748d689152","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $K\subset\R^{d}$ be a nonempty compact convex set and let $v\in \R^d$, $v\neq0$. Let $\pi$ be the orthogonal projection onto $v^{\perp}$. Then
\begin{equation}
    \mathbb{1}_{\{0\in\Conv(K\cup\{v\})\}}
   +\mathbb{1}_{\{0\in\Conv(K\cup\{-v\})\}}
   =\mathbb{1}_{\{0\in K\}}+\mathbb{1}_{\{0\in\pi K\}} .
\end{equation}
 If additionally $0\notin\partial K$ and $0\notin\partial_{v^{\perp}}(\pi K)$, where the latter boundary is taken in $v^{\perp}$, then
\begin{equation}
    \mathbb{1}_{\{0\in\Conv(K_{+}\cup\{v\})\}}
   +\mathbb{1}_{\{0\in\Conv(K_{-}\cup\{-v \})\}}
   =\mathbb{1}_{\{0\in K\}}+\mathbb{1}_{\{0\in\pi K\}},
\end{equation}
whenever $K_{+}$ and $K_{-}$ are nonempty compact convex sets in $\R^d$
whose Hausdorff distance to $K$ is smaller than $\eps$, where $\eps>0$ is a sufficiently small number  depending only on $K$ and $v/\|v\|$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:37:20.363070+00:00","domain":"probability theory","id":"claim_71180d273287b678456bed24cd77c6e8608d76eab64886ef3529bc2c1ae516d6","kind":"concept","schema_version":1,"statement":"[Lemma L:ZPL of arXiv:2411.13257, '\titlefont \vspace{-5ex} Inference by Multiple Identical Observers'] For $F \in {{\mathcal F}_W}$ and $y \in {\mathcal Z}$, 
\begin{equation} 
 P_L( F \cap \{Z_S=y\}) 
  =  {\mathbb E} \Big(  \frac{ 1_F L_y}{X} \Big | X\ge 1 \Big), 
