{"assumptions":[],"created_at":"2026-10-27T07:51:44.768266+00:00","domain":"probability theory","id":"claim_71210da40a416015853e5ff185f3562cd0f1e190f8b0289d4650ca0eac970d34","kind":"theorem","schema_version":1,"statement":"[Prop 23 of arXiv:2608.26803, 'On bubbling of Fueter maps'] Let $K$ be a compact smooth manifold of dimension $k$ and let $\cR \subset W$ be a codimension $n$ Fredholm $C^1$-rectifiable subset of a Banach space $W$. If $k < n$, then the exceptional locus
  \begin{equation*}
    \cE_K (\cR) \coloneq \{ f \in C^1(K, W) \, | \, f(K) \cap \cR \neq \emptyset \}
  \end{equation*}
  is Fredholm $C^1$ rectifiable of codimension $n-k$ in $C^1(K, W)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.603514+00:00","domain":"probability theory","id":"claim_7123c7860ca92ce2e3712cde9675066e1e6eb2c8ae281044cd82766fbf1321d7","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2606.13264, 'Interference Queueing Networks: A Replica Mean-Field Approach in the Symmetric Setting'] We say that $Q$ is associated if for any $f$ and $g$ increasing real function for the partial order on $\mathbb{N}^N$, and $t \in \mathbb{R}^+ $
    \begin{align}
        &\mathbb{P}^{Q(t)}(fg)\geq \mathbb{P}^{Q(t)}(f)\mathbb{P}^{Q(t)}(g) \Leftrightarrow \mathbb{E}[f(Q(t))g(Q(t))]\geq\mathbb{E}[f(Q(t))]\mathbb{E}[g(Q(t))]
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.591313+00:00","domain":"probability theory","id":"claim_712777358549484e877935d3b548699d72b310a44a655f3fc10311f988daeba8","kind":"definition","schema_version":1,"statement":"[Definition A1 of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] Consider a sequence of $\mathbb{H}^\#$-semimartingales $\{Y_n\}_{n\geq 1}$.
 \begin{enumerate}
 	\item[(1)] It is {\rm uniformly tight} if for each  $t\geq 0$, the family $\{\mathcal{H}_{n,t}\}_{n\geq 1}$ is uniformly stochastically bounded, where $\mathcal{H}_{n,t}$ is defined as in ((eqn.Ht of the paper)) with $Y$ replaced by $Y_n$.

 	\item[(2)] We say $Y_n$ {\rm converges weakly} to $Y$ and write $Y_n \Rightarrow Y$ if for any $m\geq 1$ and $f_1,\cdots,f_m\in\mathbb{H}$,
 	\begin{eqnarray*}
 	(Y_n(f_1),\cdots, Y_n(f_m))\overset{\rm d}\to(Y(f_1),\cdots, Y(f_m))\quad \mbox{in }D([0,\infty),\mathbb{R}^m).
 	\end{eqnarray*}
 	In addition,
 	we also write $(X_n,Y_n) \Rightarrow (X,Y)$ if
 	\begin{eqnarray*}
 	(X_n, Y_n(f_1),\cdots,Y_n(f_m))\overset{\rm d}\to(X,Y(f_1),\cdots, Y(f_m))\quad \mbox{in }D([0,\infty),\mathbb{H}\times\mathbb{R}^m).
 	\end{eqnarray*}
 \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.668454+00:00","domain":"probability theory","id":"claim_7127e5b858369cb9a459e63d54fad629cb92c4245ddf03fa51569aee7c98ebd2","kind":"theorem","schema_version":1,"statement":"[Thm 15 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Under the conditions of Theorem \ref{thm:MallDiff}, we have, for all $1 \leq k \leq d$ and $t\in (0,T]$
\begin{enumerate}[(a)]
	\item 	
	\begin{align}
		D X_t^k &=  \sum_{\ell=1}^{m} \int_{0}^{t} \Theta_{t}^{k l}(r) d DF^l(r)\nonumber\\
		&:=\lim_{|\mathcal{P}|\to 0}\sum_{\ell=1}^{m}\sum_{[u,v]\in \mathcal{P}} \Theta_{t}^{k l}(u) (DF^l(v)-DF^l(u)),
	\end{align}
	where $\Theta^{k,\ell}_t$ is given by \eqref{eq:Theta} and the above limit is in $\HHH$, along an arbitrary sequence of partitions of $[0,t]$ with mesh tending to zero.
	Furthermore, for any $\beta\in (0, H-\frac{1}{2})$ there exists a constant $C>0$ such that
	\begin{align}
		&\left\|\sum_{\ell=1}^{m} \int_{s}^{t} \Theta_{t}^{k l}(r) d DF^l(r)- \sum_{\ell=1}^{d}\Theta_{t}^{k l}(s)\big(DF^l(t)-D^{(l)}F(s)\big)\right\|_{\HHH}\\
		&\leq C \sum_{\ell=1}^{m}\|\Theta_{t}^{k l}\|_{\mathcal{C}^{H-\beta_1}} \|DF^l\|_{\mathcal{C}^{H-\beta_2}} |t-s|^{2(H-\beta)};\nonumber
	\end{align}	
	uniform in $s,t\in [0,T]$. 
	\item for all $h \in \mathfrak{H}$, 
	\begin{align}
		&\left<D X_t^k, h\right>_{\HHH} =  \sum_{\ell=1}^{m} \int_{0}^{t} \Theta_{t}^{k l}(s) d \left<DF^l(s), h\right>_{\HHH}\nonumber\\
		&:=\lim_{|\mathcal{P}|\to 0}\sum_{\ell=1}^{m}\sum_{[u,v]\in \mathcal{P}} \Theta_{t}^{k l}(u) \left<DF^l(v)-DF^l(u),h\right>_{\HHH},	
	\end{align}
	where the limit is along an arbitrary sequence of partitions of $[0,t]$ with mesh tending to zero.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:38.633104+00:00","domain":"probability theory","id":"claim_71294a0dd404783fc3ef3bf6c9aed6b7b76ee16dc05e8d4faa4051f8cc3873a1","kind":"concept","schema_version":1,"statement":"[Lemma 6 (Eichelsbacher and L\"{o}we \cite{eichelsbacher2010stein}) of arXiv:2506.17061, 'Non-uniform bounds for non-normal approximation via Stein's method with applications to th'] Let $z\in\R$ and let $P_k$, $f_z$ and $g_z$ be defined as above. The following statements hold.
		\begin{itemize}
			\item[(i)] For $x>0$, we have
			\begin{equation}
				1-P_k(x) \le \min \left(\frac{1}{2}, \frac{b_k}{2 k a_k x^{2 k-1}}\right) \exp \left(-a_k x^{2 k}\right),
			\end{equation}
and therefore, for $x<0$, we have
			\begin{equation}
				P_k(x)=1-P_k(-x) \le \min \left(\frac{1}{2}, \frac{b_k}{2 k a_k |x|^{2 k-1}}\right) \exp \left(-a_k x^{2 k}\right).
			\end{equation}
			\item[(ii)] The explicit formular for $f_z$ is
			\begin{equation}
				f_z(x) =
				\begin{cases}
					(1-P_k(z))P_k(x)\exp({a_kx^{2k}})b_k^{-1} &\text{if }\ x < z,\\
					P_k(z)(1-P_k(x))\exp({a_kx^{2k}})b_k^{-1} &\text{if }\ x \ge z.
				\end{cases} 
			\end{equation}
			\item[(iii)] The explicit formular for $f_{z}'$ is
			\begin{equation}
				f_{z}'(x) =
				\begin{cases}
					(1-P_k(z))\left[1 + 2ka_kx^{2k-1}P_k(x)\exp({a_kx^{2k}})b_k^{-1}\right] &\text{if }\ x < z,\\
					P_k(z)\left[(1-P_k(x))2ka_kx^{2k-1}\exp({a_kx^{2k}})b_k^{-1}-1\right] &\text{if }\ x \ge  z. 
				\end{cases} 
			\end{equation}
			\item[(iv)] 
			For all $x\in\R$, we have
			\begin{equation}
				0 < f_z(x) \le \dfrac{1}{2b_k}, \text{ and }
				|f_{z}'(x)| \le 1.
			\end{equation}
			\item[(v)] For $x< z$, we have
			\begin{equation*}
				g_z(x)=(1-P_k(z))\left[b_{k}^{-1}P_k(x)\exp(a_kx^{2k}) \left((4k^2-2k)a_kx^{2k-2} + 4k^2a_k^2x^{4k-2}\right) + 2ka_kx^{2k-1}\right].
			\end{equation*}
