{"assumptions":[],"created_at":"2026-10-26T19:41:33.837877+00:00","domain":"probability theory","id":"claim_73f7e51b3406e3a827739436fc6090473f9f45a55a9e35e04b24043deb9614b7","kind":"concept","schema_version":1,"statement":"[Lem 9 of arXiv:2604.11489, '2604.11489'] \cite{C-R}
