{"assumptions":[],"created_at":"2026-10-27T13:52:23.564345+00:00","domain":"probability theory","id":"claim_78389630b30c334a2ba8dc73f7fad4f789a73876c09e4fa0cd61a7fa5db1d116","kind":"concept","schema_version":1,"statement":"[Theorem T:LND_t of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] \index{conditional variance}
  Assume $\alpha > 0$, $\beta \in (0, 2]$, $\gamma \ge 0$,
  $H \in (0, 1)$, and $\ell \in (0, 2d)$. 
    Assume the Dalang condition~(equation E:main of the paper), i.e., $\rho>0$ and $\ell < 2\alpha$. 
    Then, for all $0 < S < T < \infty$,
  there exist positive finite constants $C$ and $C'$ depending on $S, T, \alpha,
    \beta, \gamma, H, d, \ell$ such that the following statements hold.
  \begin{enumerate}[\rm (i)]

    \item If $\beta \in (0,2)$,\index{strong local nondeterminism (SLND)!one-sided} then for all $x \in \mathbb{R}^d$, for all integers $n
            \ge 1$, and for all $t, t_1, \dots, t_n \in [S, T]$ with $\max\{ t_1,
            \dots, t_n\} \le t$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\left( u(t, x)\big|u(t_1, x), \dots, u(t_n, x) \right) \ge C \min_{1 \le j\le n} (t-t_j)^{2\rho}.
          \end{align}
          Consequently, for all $t, t' \in [S, T]$, for all $x \in \mathbb{R}^d$,
          \begin{align}
            \mathbb{E} \left[ \left(u(t, x) - u(t', x)\right)^2 \right] \ge C |t'-t|^{2\rho}.
          \end{align}
          In addition, there exists $\delta > 0$ such that for all $t, t' \in [S, T]$ with
          $|t'-t| \le \delta$, for all $x \in \mathbb{R}^d$,
          \begin{align}
            \mathbb{E} \left[ \left(u(t', x) - u(t, x)\right)^2 \right] \ge \begin{cases}
                                                                      C' |t'-t|^2 (1+|\log(t'-t)|) & \text{if } \rho = 1, \\
                                                                      C' |t'-t|^2                  & \text{if } \rho > 1.
                                                                    \end{cases}
          \end{align}

    \item If $\beta = 1$, then (equation LNDt:CondVar of the paper) can be strengthened\index{strong local nondeterminism (SLND)!two-sided} as
          follows: for all $x \in \mathbb{R}^d$, for all integers $n \ge 1$, and for all $t,
            t_1, \dots, t_n \in [S, T]$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\left( u(t, x)\big|u(t_1, x), \dots, u(t_n, x) \right) \ge C \min_{1 \le j\le n} |t-t_j|^{2\rho}.
          \end{align}

    \item If $\beta = 2$, $\gamma \in [0, 1]$, and $H \in [1/2, 1)$, then
          for all $x \in \mathbb{R}^d$, for all integers $n \ge 1$, and for all $t, t_1,
            \dots, t_n \in [S, T]$ with $\max_j |t-t_j| \le S$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\left( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \right) \ge C \min_{1\le j \le n}|t-t_j|^{2(\gamma+H+\frac{1}{2}-\frac{\ell}{\alpha})}.
          \end{align}
          and for all $t, t' \in [S, T]$, for all $x \in \mathbb{R}^d$,
          \begin{align}
            \mathbb{E}\left[ \left( u(t', x) - u(t, x) \right)^2 \right] \ge \begin{cases}
                                                                       C' |t'-t|^{2(\gamma+H+\frac{1}{2}-\frac{\ell}{\alpha})} & \text{if } \gamma + H + \frac12 - \frac\ell\alpha < 1, \\
                                                                       C'|t'-t|^2 (1+|\log(t'-t)|)                             & \text{if } \gamma + H + \frac12 - \frac\ell\alpha = 1, \\
                                                                       C' |t'-t|^2                                             & \text{if } \gamma + H + \frac12 -\frac\ell\alpha > 1.
                                                                     \end{cases}
          \end{align}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:10:05.676859+00:00","domain":"probability theory","id":"claim_783df14a3733a6fb1326c90b9018a924086b4b177fe37d951f1c585f0be8834f","kind":"concept","schema_version":1,"statement":"[Theorem 14 (Absorption probability for a random bridge) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $d\geq 1$,  $n\geq d+2$ and let $\xi_1,\dots,\xi_n$ be (in general, dependent) random vectors in $\R^d$ with partial sums
$$
S_i = \xi_1 + \dots + \xi_i,\quad  1\leq i\leq n,\quad  S_0=0.
$$
We impose the following assumptions on the increments $\xi_1,\dots,\xi_n$:
\begin{itemize}
\item[(i)] \emph{Bridge property:} $S_n=\xi_1+\dots+\xi_n = 0$ a.s.
\item[(ii)] \emph{Exchangeability:} For every permutation $\sigma$ of the set $\{1,\dots,n\}$, we have the distributional equality
$$
(\xi_{\sigma(1)},\dots,  \xi_{\sigma(n)}) \stackrel{d}{=} (\xi_1,\dots,\xi_n).
$$
\item[(iii)] \emph{General position of partial sums:}
For every $1\leq i_1 < \dots < i_d \leq n-1$, the probability that the vectors $S_{i_1}, \dots, S_{i_d}$ are linearly dependent is $0$.
\end{itemize}
Then
\begin{align}
    \pbridge{n}{d}
    &:=
    \pr[0 \in \Conv(S_1,\dots,S_{n-1})]
    =
    \frac{2}{n!}
    \sum_{r\geq 0}
    \stirling{n}{d+2+2r},

    \\
    \qbridge{n}{d}
    &:=
    \pr[0 \notin \Conv(S_1,\dots,S_{n-1})]
    =
    \frac{2}{n!}
    \sum_{r\geq 0}
    \stirling{n}{d-2r}.

\end{align}
Here, $\stirling{n}{k}$ with $n\in \{1,2,\dots\}$ and $k\in \mathbb Z$ denotes the unsigned Stirling number of the
first kind defined by the generating function
\begin{equation}
\sum_{k\in \mathbb Z} \stirling nk x^k = x(x+1)(x+2)\dots (x+n-1).
\end{equation}
In particular, $\stirling nk= 0$ for $n\in \{1,2,\dots\}$ and $k\notin\{0,\dots,n\}$, so that the sums appearing above terminate after finitely many nonzero terms. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:31:20.595066+00:00","domain":"probability theory","id":"claim_7847c70177432e9bc3bbd3c977af747587c880fcad7f9e08634ae8f15386a327","kind":"concept","schema_version":1,"statement":"[Theorem 12 (Minimax lower bound) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] If $\widehat p_t(\cdot|X_t,\cG_{t-1})$ ranges over all sequential predictive densities that may use the revealed context $X_t$ and past history $\cG_{t-1}$, then
