{"assumptions":[],"created_at":"2026-10-27T13:52:23.575947+00:00","domain":"probability theory","id":"claim_7857ded702b28238c99992e1410cdad22430648c617e0f970b17773de48fffa9","kind":"lemma","schema_version":1,"statement":"[Lemma L:intml of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let $T > 0$, and let $0 < s_1 \leq s_2 < T$. Denote by
    \begin{align*}
      I (s_1,s_2) \coloneqq \int_0^{\infty} \ensuremath{\mathrm{d} } x \; x^{\theta} E_{a,b} (- s_1 x) E_{a,b}(- s_2 x),
  \end{align*}
  where the parameter $\theta \in (-1,1)$.
  \begin{enumerate}[\rm (i)]
    \item Assume either $(a,b) \in (0,2) \times [a,\infty)$; or $a = 2$ and $b \in [3,\infty)$. Then, it holds that
          \begin{align}
            I (s_1, s_2)  \lesssim
            \begin{dcases}
              s_1^{-\theta} s_2^{-1},                   & \theta \in (0,1),  \\
              s_2^{-1} (1 + \log \left(s_2/s_1\right)), & \theta = 0,        \\
              s_2^{- \theta - 1},                       & \theta \in (-1,0).
            \end{dcases}
          \end{align}
    \item In case $a = 2$, $b \in (1,2) \cup (2,3]$, such that $b - \theta > 3/2$, then the next inequality is true,\footnote{The condition $b - \theta > 3/2$ is necessary to ensure the integrability of $I_{3,1,1}$ and $I_{3,1,2}$ in~(equation E_:intml-a=2-3-1-1 of the paper) and~(equation E_:intml-a=2-3-1-2 of the paper).}
          \begin{align}
            I (s_1, s_2)  \lesssim
            \begin{dcases}
              s_1^{b/2 - \theta - 3/2} s_2^{- \frac{b-1}{2}} + s_1^{-\frac{b-1}{2}} s_2^{-\frac{b-1}{2}} \left(\sqrt{s_2} - \sqrt{s_1}\right)^{2b - 2\theta -4}, & b < 2 + \theta ,               \\
              s_1^{-(b-1)/2} s_2^{-(b-1)/2} \left(1 + |\log \left((\sqrt{s_2} - \sqrt{s_1})/\sqrt{s_2}\right)| \right) ,                                         & b = 2 + \theta,                \\
              s_1^{b/2 - \theta - 3/2} s_2^{-(b-1)/2},                                                                                                           & 2 + \theta < b < 3 + 2\theta , \\
              s_2^{- \theta - 1} \big(1 + \log (s_2/s_1 )\big),                                                                                                  & b = 3 +  2\theta,              \\
              s_2^{- \theta - 1},                                                                                                                                & b > 3 + 2\theta.
            \end{dcases}
          \end{align}
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:49:17.503254+00:00","domain":"probability theory","id":"claim_785c32e6ac5fca280e996b38e9533e1752728eede4ccd649b5bb1d86654656cc","kind":"concept","schema_version":1,"statement":"[Proposition 31 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] Consider boundary conditions~$\xi\leq \xi'$ on~$G$. 
    Let~$\mathbf{T} = \left(e_1,(\psi_t)_{2\leq t\leq n}\right)$ be a decision tree and~$(U_e)_{e\in E}$ be a set of i.i.d.~uniform random variables on~$[0,1]$ under some probability measure~$\P_\mathbf{T}$. Define~$\omega,\omega'\in\{0,1\}^E$ inductively by
    \begin{align*}
        \omega_{e_{t+1}} &:=\one\big(U_{e_{t+1}}\geq \rcP_{G_t}^{\xi_t}[e_{t+1}\text{ closed}]\big),\\
        \omega'_{e_{t+1}} &:= \one\big(U_{e_{t+1}}\geq \rcP_{G_t}^{\xi'_t}[e_{t+1}\text{ closed}]\big),\quad\forall 0\leq t<n,
    \end{align*}
where~$\xi_t$ and~$\xi'_t$ are the boundary conditions on~${G_t}$ induced by~$\omega^\xi_{[t]}$ and~$\big(\omega'_{[t]}\big)^{\xi'}$ respectively. When~$t=0$, these are~$\xi$ and~$\xi'$. 

Then, $\omega$ and~$\omega'$ have laws~$\rcP^{\xi}_{G}$ and~$\rcP^{\xi'}_{G}$, respectively, and~$\omega\leq \omega'$~$\P_\mathbf{T}$-almost surely.

The same procedure may be applied to couple increasingly~$\phi_G^{\xi}$ to~$\phi_G^{\xi}[\cdot\,|\,A]$ for an increasing event~$A$. We will also use it to couple (finite restrictions of) infinite volume measures. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.255114+00:00","domain":"probability theory","id":"claim_78609124beb71859b03a3317ea240bc018a295110782ed7a1a0e69c2465560d0","kind":"definition","schema_version":1,"statement":"[Dfn 30 (Resistance form, {\cite[Definition 3.1) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {Kig12}}]
Let $F$ be a non-empty set.
A pair $(\calE,\calF)$ is called a resistance form if it satisfies the following conditions.
\begin{itemize}[leftmargin=3.5em, labelsep=0.3em]
  \item [(RF1)]$\calF$ is a linear subspace of $\R^F$ containing the constant functions.
  $\calE$ is a non-negative symmetric quadratic form on $\calF$ satisfying
  \begin{align*}
    \calE(u,u)=0\iff \text{$u$ is a constant.}
  \end{align*}
  \item[(RF2)]Let $\sim$ be an equivalence relation on $\calF$ defined by $u\sim v$ if and only if $u-v$ is constant.
  Then $(\calF/\sim,\calE)$ is a Hilbert space.
  \item[(RF3)] If $x\neq y\in F$, then there exists $u\in\calF$ such that $u(x)\neq u(y)$.
  \item[(RF4)]For any $x,y\in F$,
  \begin{align*}
    R(x,y)
    :=&\sup\left\{ \frac{|u(x)-u(y)|^2}{\calE(u,u)}:u\in\calF,\calE(u,u)>0 \right\}\\
    =&\inf\{\calE(u,u):u(x)=1,u(y)=0,u\in\calF\}^{-1}
  \end{align*} 
  is finite.
  \item[(RF5)]For $u\in \calF$, set $\bar{u}:=0\vee(u\wedge 1)$. 
  Then $\bar{u}\in\calF$ and $\calE(\bar{u},\bar{u})\leq \calE(u,u)$ hold. 
\end{itemize}
The function $R:F\times F\to[0,\infty)$ defined by (RF4) is a metric on $F$ (see \cite[Theorem 2.3.4]{Kig01}) and called the resistance metric associated with $(\calE,\calF)$.","status":"unverified"}

