    \frac{\partial}{\partial t} \mathbb P_{\lambda, t}(\mathbf{0} \xrightarrow[]{} \Lambda^c) \ge \frac{\lambda e^{-t}}{ t} \inf_{\substack{  S \ni \mathbf{0}  \\ S \subseteq \Lambda}} \phi_{\lambda, t}(S) \left( 1 - \mathbb P_{\lambda, t}(\mathbf{0} \xrightarrow[]{}\Lambda^c) \right).
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:06.330271+00:00","domain":"probability theory","id":"claim_7ad027533f206438b1b585071bf32d49df6fd12c8a59dd7b9c24ae33d76d6836","kind":"lemma","schema_version":1,"statement":"[Lemma 21 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $(\mathbf{x}_t)_{t\geq 0}$ be the stationary solution of \eqref{eq:fast system} in the setting \nameref{S2}. Then, the SD of $\mathbf{x}$ denoted by $ S_{\mathbf{x}\mathbf{x}}$ is given for all $H\in(0,1)$ by
    \begin{align}
    S_{\mathbf{x}\mathbf{x}}(\omega) = C_H\left(M(\lambda)-i\omega I\right)^{-1}Q\left(M(\lambda)^*+i\omega I\right)^{-1}|\omega|^{1-2H}.
