{"assumptions":[],"created_at":"2026-10-27T11:07:35.030678+00:00","domain":"probability theory","id":"claim_7f547af7b7b34be3733790dfd7c2a9027beadc6aa47fd339f5cad9b30a85e735","kind":"theorem","schema_version":1,"statement":"[The 31 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Suppose $H$ is a Tonelli Hamiltonian on $\T^n$, $\phi\in \SCL(\T^n)$, and $u$ is the viscosity solution of \eqref{eq:HJephi pre}. Let $\gamma: [0,T] \to \T^n$ be a $(u,H)$-calibrated curve with dual arc $p(t) = L_v(\gamma(t),\dot{\gamma}(t))$ for $t \in [0,T]$. The following statements are true:

	\begin{enumerate}
		\item 	If $\gamma(t_0)\in\operatorname{Alex}(u(t_0,\cdot))$ for some $t_0\in[0,T)$, then $\gamma(t)\in\operatorname{Alex}(u(t,\cdot))$ for all $t\in[t_0,T)$. Moreover, the map $t\mapsto Q(t)=D^2_xu(t,\gamma(t))$ is of class $C^1$ on $[t_0,T)$ and $Q(t)$ satisfies the following matrix Riccati equation
		\begin{equation}
			\dot{Q}(t)+Q(t)\cdot H_{pp}(\gamma(t),p(t))\cdot Q(t)+Q(t)\cdot H_{px}(\gamma(t),p(t))+H_{xp}(\gamma(t),p(t))\cdot Q(t)+H_{xx}(\gamma(t),p(t))=0. \tag{Ricc}
		\end{equation}		
		\item  If $\gamma(t_0)\in\operatorname{Alex}(u(t_0,\cdot))\cap \operatorname{supp}_{C^{1,1}}(u(t_0,\cdot))$ for some $t_0\in[0,T)$, where $\text{supp}_{C^{1,1}}(u(t_0,\cdot))$ is the $C^{1,1}$ support of $u(t_0,\cdot)$ (see the definition before Theorem \ref{thm:close_cut}), then $\gamma(t)\in\operatorname{Alex}(u(t,\cdot))$ for all $t\in[0,T)$. Moreover, the map $t\mapsto Q(t)=D^2_xu(t,\gamma(t))$ is of class $C^1$ on $[0,T)$ and $Q(t)$ satisfies \eqref{eq:Ricc}.
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:35:05.829749+00:00","domain":"probability theory","id":"claim_7f6be38595c353fbb9150653452c2d08110b5e6c25752e8557b8cf717288deca","kind":"concept","schema_version":1,"statement":"[Thm lem:conv_muN_detailed of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] Suppose that (A1 of the paper)-(A8 of the paper) hold true. Let $({\mathcal X}(t),{\boldsymbol{\lambda}}(t))$ be the unique strong solution to (equation system2 of the paper) in ${\mathcal{M}}_{\rm ad}^2(\hat{\mathscr Y}^N)$ with initial condition $\overline{{\boldsymbol Y}}_{0}\in L^{2}(\hat{{\mathscr Y}}^{N})$. Then there exists a unique measure-valued process
\begin{align}
\mu_{\cdot} \in C([0,T]; {\mathscr{P}}_1({\mathscr Y})\cap {\mathscr{P}}_{2}({\mathscr Y}))    
\end{align}
satisfying the nonlinear McKean--Vlasov SDE
\begin{align}
\begin{dcases}
{\rm d} Y(t) &= H(Y(t), \Lambda(t), \mu(t)) \, {\rm d} t + \sqrt{2\sigma_x} \, {\rm d} B(t),\\
{\rm d} \Lambda(t) &= {\mathbb R}(Y(t), \Lambda(t), \mu(t)) \, {\rm d} t + \sqrt{2\sigma_\lambda} \, \Pi_{\Lambda(t)} \, {\rm d} W^Q(t),\\
\mu(t)&={\rm law}(Y(t),\Lambda(t)),
\end{dcases}
\end{align}
with initial law $\mu_0 = \mathcal L(\overline{X}^1_0, \overline{\lambda}^1_0)$. Moreover, the empirical measure $\mu^N_t$ converges in expectation of the Wasserstein-1 distance to $\mu(t)$:
\begin{align}
\lim_{N\rightarrow +\infty}\sup_{t \in [0,T]} {\mathbb E} \big[{\mathcal W}_1(\mu^N(t), \mu(t)) \big] =0.
\end{align}
In particular, the system (equation system2 of the paper) is \emph{chaotic with limit law $\mu(t)$ in the sense of (defn:propchaos of the paper)}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:07:48.568578+00:00","domain":"probability theory","id":"claim_7f6d7255a026383fb3cc040ee19936c9196e2c6fa7791c35d016a4a98114d885","kind":"theorem","schema_version":1,"statement":"[Corollary 44 (Functional Santal\'o inequalities on $\operatorname{RCD}(K, \infty)$-spaces) of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,d,\mu)$ be an $\operatorname{RCD}(K,\infty)$ probability space for some $K > 0$. For any pair of measurable functions $f, g: X \to [0,\infty)$ and any non-decreasing measurable function $W: \R_+ \to (0, \infty)$ satisfying the pointwise relation
    \begin{equation}

    f(x)^{\frac{1}{2}} g(y)^{\frac{1}{2}} \leq W\left(\frac{d(x,y)}{2}\right) \quad \text{for all } x, y \in X,
    \end{equation}
    one has the functional inequality
    \begin{equation}

    \left( \int_X f(x) \, d\mu(x) \right)^{\frac{1}{2}} \left( \int_X g(y) \, d\mu(y) \right)^{\frac{1}{2}} \leq  \int_{\R} W\left(\frac{|r|}{\sqrt{K}}\right) \, d\gamma(r).
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:35:04.095511+00:00","domain":"probability theory","id":"claim_7f731aa284b12477a3ab3240b3ad80f08669a4b30ad1f80df71d05e55fb7c971","kind":"lemma","schema_version":1,"statement":"[Lemma lem:circuit-output of arXiv:2608.29403, 'Kac's Walk on Rotation Matrices Mixes in $\boldsymbol{\Theta(n^2)}$ Steps:\\ A Proof Disco'] For every $\zeta\in\mathscr P_\tau$,
\[
 \left\|n^{-F(\tau)}
 \operatorname{Contr}^{\rm raw}_{\Gamma,\tau}(\zeta)
 \right\|_{\tau,\varepsilon}
 \le \|\zeta\|_{\mathscr P_\tau},
 \qquad
 \operatorname{Contr}^{\rm raw}_{\Gamma,\tau}
 =n^{F(\tau)}\operatorname{Contr}^{\rm norm}_{\Gamma,\tau}.
\tag{2.3.17}
\]
The same estimate holds with arbitrary typed gaps and retained output
ports.  Inserting prescribed maps multiplies the right side by at most
the product of their operator norms, provided they contain no hidden
unnormalized cup or cap.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:47:32.875879+00:00","domain":"probability theory","id":"claim_7f86aaeb4a0d5f50e22cc106c01448aee3e0c508d1fe7ae375a2a399ef22f832","kind":"lemma","schema_version":1,"statement":"[Lemma 18 (Asymptotic negative support along a relation direction) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] Let $\Lambda\in\mathfrak{L}_{\bm{\beta}}$, $\bm{\gamma}\in\Lambda$, and $\bm{g}\in L\setminus\{\bm{0}\}$.
