{"assumptions":[],"created_at":"2026-10-26T20:54:34.577870+00:00","domain":"probability theory","id":"claim_7facb228d04771e016619a2badcd24e39887a0f99e191349dd49825bef9cad68","kind":"concept","schema_version":1,"statement":"[Lemma 21 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N=I_p(f_N), N\geq 1)$ 
		satisfy \eqref{c1}. Let $Y_N=I_q(g_N)$ with 
		$ap\leq q<(a+1)p$ for some integer $a\geq 1$, and 
		$\sup_N\|g_N\|_{H^{\otimes q}}<\infty$. Define 
		recursively $h_{0,N}:=g_N$ and, for $r=1,\ldots,a$:
		\begin{equation}
			h_{r,N} := \frac{f_N\otimes_p h_{r-1,N}}
			{\|f_N\|^2_{H^{\otimes p}}}\in H^{\odot(q-rp)},
		\end{equation}
		and
		\begin{equation*}
			g_{r,N}^{(2)} := h_{r-1,N} 
			- \frac{(q-(r-1)p)!}{p!(q-rp)!}
			f_N\widetilde\otimes h_{r,N},
			\qquad
			\varepsilon_{r,N} := I_{q-(r-1)p}(g_{r,N}^{(2)}),
		\end{equation*}
		so that $f_N\otimes_p g_{r,N}^{(2)}=0$ for each 
		$r=1,\ldots,a$. Then for every $N\geq 1$, in the 
		\textbf{non-critical case} $ap<q<(a+1)p$:
		\begin{equation}
			Y_N = \sum_{r=1}^a \frac{X_N^r}{p^r\sigma^{2r}}
			Y_{r,N} + \varepsilon_N + r_N,
		\end{equation}
		and in the \textbf{critical case} $q=ap$:
		\begin{equation}
			Y_N = \sum_{r=1}^{a-1}\frac{X_N^r}{p^r\sigma^{2r}}
			Y_{r,N} + \frac{\rho_a}{p^a\sigma^{2a}}X_N^a 
			+ \varepsilon_N + r_N,
		\end{equation}
		where in both cases $\varepsilon_N$ is asymptotically 
		independent of $X_N$ and $r_N\to 0$ in $L^2(\Omega)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:10.187456+00:00","domain":"probability theory","id":"claim_7fbcab51ed9c39f0b27b47e271bef5596babca233f75a7807d80c28017997154","kind":"concept","schema_version":1,"statement":"[Theorem 134 (Theorem 6.4 \cite{Kr_26_1}) of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $ \alpha>0,q_{1},q_{2}\in(1,\infty),q>\max(q_{1},q_{2})$, $k>0$, $b(t,x)\geq0$. Then for any $f(t,x)\geq0$
\begin{equation}

\|bP_{\alpha,k}f\|_{L_{q_{1},q_{2}}}
\leq N\|b\|_{\dot E_{q,q,\alpha} }
\|f\|_{L_{q_{1},q_{2}}},
\end{equation}
where $N$ depends only on $d,q_{i},q,\alpha,k$.
In particular, for any $u\in C^{\infty}_{0}$
\begin{equation}

\|b Du \|_{L_{q_{1},q_{2}}}
\leq N\|b\|_{\dot E_{q,q,1} }K,
\quad \| b u\|_{L_{q_{1},q_{2}}}
\leq N\|b\|_{\dot E_{q,q,2} }K,
