{"assumptions":[],"created_at":"2026-10-27T21:42:57.240927+00:00","domain":"probability theory","id":"claim_8315338b5ef83b11915bbf4309257766fcdf24135204a5af34fa4c174d8ee2fa","kind":"concept","schema_version":1,"statement":"[Theorem thm:honest-region of arXiv:2608.20295, 'Physical-Support Confidence Sets for Highly Coherent Dictionaries'] Under Assumption~(ass:frozen-shell of the paper) and the calibration coverage condition
in Equation~(equation eq:training-rectangle of the paper), the totalized correspondence
$\widehat{\mathfrak C}_{q,r,s}^{p}$ is measurable, nonempty, and
compact-valued. Uniformly over $\mathfrak P^p_{q,r}(s)$,
\begin{equation}
\mathbb P_{p_\star,\nu_\star,D_\star}^N
\left[
\mathbb P_{\mu_\star,\sigma_\star}^T
\left\{
    \vartheta_\star
    \in
    \widehat{\mathfrak C}_{q,r,s}^{p}
    \mid Y_{1:N}
\right\}
\ge1-\alpha_T
\right]
\ge1-\alpha_D.

\end{equation}
Consequently, by independence of the calibration and deployment experiments,
with
\[
    \alpha
    =
    1-(1-\alpha_D)(1-\alpha_T),
\]
\begin{equation}
\inf_{\xi\in\mathfrak P^p_{q,r}(s)}
\mathbb P_\xi^{N,T}
\left\{
    \vartheta(\xi)
    \in
    \widehat{\mathfrak C}_{q,r,s}^{p}
\right\}
\ge1-\alpha.

\end{equation}

For $N$ above the fixed block threshold of the robust calibration-moment
construction, define
\begin{equation}
\rho_N(s)
=
C\left[
    (s\wedge\epsilon_N)
    +
    \left(s\wedge\frac{\epsilon_N}{s}\right)
    +
    \left(s\wedge\frac{\epsilon_N}{s^2}\right)
\right].

\end{equation}
Any two dictionaries retained by the same nonempty calibration region have
quotient-dictionary distance at most $\rho_N(s)$.  If
$\epsilon_N\le CN^{-1/2}$, then
\begin{equation}
    \rho_N(s)
    \le
    C\left(
        s\wedge\frac{1}{\sqrt N\,s^2}
    \right).

\end{equation}
Below the block threshold, retaining the full compact shell yields the same
order after adjustment of fixed constants.

For every realization,
\begin{align}
\operatorname{diam}_{\mathrm{pr}}
\left(
    \widehat{\mathfrak C}_{q,r,s}^{p}
\right)
\le{}&
C\rho_N(s)
\notag\\
&+
Cs\,
\mathbf 1
\left\{
    2\tau_{T,q}\ge m_S(\rho_N(s))
\right\}
\notag\\
&+
C\,
\mathbf 1
\left\{
    2\tau_{T,q}\ge m_G(\rho_N(s))
\right\}.

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:54:57.590804+00:00","domain":"probability theory","id":"claim_8316e3da084db1a08d4169a28416b2db3d0329e1effbcedcc50baf81e870ce95","kind":"concept","schema_version":1,"statement":"[Prop pro:limit_thm_2.2 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Recall $\tilde{x}_n(0)=x_n^f$ and suppose $\{x_n^f, n \in \mathbb{N}\}$ fulfils Assumption~(assumpt:2.9 of the paper). Then, it holds 
	\begin{equation}
	\begin{aligned} 
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > g_\alpha T - S T^{1/3})
	&= \mathbb{P} \left( \sup_{\tau \in \mathbb{R}} \{ \mathcal{A}_2(\tau) - \tau^2 - y(-\tau) \} < c_1^{-1} S \right)
	\end{aligned}  
	\end{equation}
	with $g_\alpha = 1-d^{-1}-d\alpha$ and $c_1 = (1-d^{-1})^{2/3} d^{1/3}$. 

	Suppose $\{x_n^f,n \in \mathbb{N}\}$ fulfils Assumption~(assumpt:2.7 of the paper). Then, we have $g_\alpha = 1-2\sqrt{\alpha}$. If $d = \tfrac{1}{\sqrt{\alpha}}$, then it holds
	\begin{equation}
	\begin{aligned} 
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > g_\alpha T - S T^{1/3})
	&= \mathbb{P} \left( \sup_{\tau \leq 0} \{ \mathcal{A}_2(\tau) - \tau^2 - y(-\tau) \} < c_1^{-1} S \right).
	\end{aligned}   
	\end{equation}
	If $d < \tfrac{1}{\sqrt{\alpha}}$, then it holds
	\begin{equation}
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > g_\alpha T - S T^{1/3}) = F_{\textup{GUE}}(c_1^{-1} S).    
	\end{equation}
	In both cases, we have $c_1 = (1-\sqrt{\alpha})^{2/3} \alpha^{-1/6}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.528856+00:00","domain":"probability theory","id":"claim_831865e0b263e43e9bb741cb9c5395b9c331e13a0808530a4d401c202e282561","kind":"concept","schema_version":1,"statement":"[Proposition 9 (Damped super-Brownian motion) of arXiv:2604.01852, 'The on/off Brownian snake'] Recall the processes $(\Tilde{\mathcal{Z}}_y^{(\varepsilon)})_{y \geq 0}$, $\varepsilon>0$ from Corollary \ref{corollary bbm extra killing} on the probability space $(\Omega, \mathcal{F}, \mathbb{P}_{(\mu_{\rm d},\mu_{\rm a})})$. Then, for $s>0$, we have the existence of a scaling limit $\Tilde{\mathcal{Z}}_s$ given by 
    \begin{equation*}
        \varepsilon \Tilde{\mathcal{Z}}^{(\varepsilon)}_s \xrightarrow[\varepsilon \rightarrow 0]{a.s.} \Tilde{\mathcal{Z}}_s.
    \end{equation*}
    Furthermore, for any continuous bounded function $\Phi: \mathbb{R}^d \rightarrow [0,\infty)$, we have 
    \begin{equation}
        \langle \Tilde{\mathcal{Z}}_s, \Phi \rangle \coloneqq \int_x \Phi(x) \Tilde{\mathcal{Z}}_s(dx) = \sum_{i \in \Tilde{I}} \int_{r=0}^{\sigma(f^i)} \Phi(\hat{w}^i_r)\mathbbm{1}_{\hat{\Tilde{v}}^i_r =0}dL^i_s(r)
    \end{equation}
    where, for $i \in \Tilde{I}$, $L^i_s(\cdot)$ are the local times for the excursions $f^i$ defined in \eqref{equation normalised local time}. Furthermore this measure-valued process $(\Tilde{\mathcal{Z}}_s)_{s \geq 0}$ has the finite dimensional distributions of a superprocess with continuous sample paths and with initial state $\Tilde{\mathcal{Z}}_0 = \mu_{\rm a}$. We call this superprocess \emph{damped super-Brownian motion with parameter $4$ and damping rate $c$} or \emph{$\text{DSBM}(4, c)$}. 
    \par
    Finally, when the prelimiting processes $\Tilde{\mathcal{Z}}^{(\varepsilon)}_s$ which are $\text{BBM}(2/\varepsilon, 2/\varepsilon+c)$ are replaced by $\text{BBM}(\gamma/2\varepsilon, \gamma/2\varepsilon + c)$ then the limit in distribution is another superprocess that we call \emph{damped super-Brownian motion with parameter $\gamma$ and damping rate $c$} or \emph{$\text{DSBM}(\gamma, c)$}. 
    \begin{proof}
        We can apply Lemma \ref{lemma snake exit open set general} to the Brownian snakes that form the damped Brownian snake of Definition \ref{definition damped Brownian snake}. For the snakes process $(w^i, t^i, \Tilde{v}^i)$, $i \in \Tilde{I}$, we let the exit set $D$ be given by $\mathbb{R}^d \times [0, y) \times \{0\}$. It is elementary to show that the exit local time in this case has associated Lebesgue-Steiltjes measure given by $\mathbbm{1}_{\hat{\Tilde{v}}^i_r =0}dL^i_s(r)$. By the analogous arguments that were given in Theorem \ref{theorem ooSBM ffd convergence} we obtain the a.s. convergence and the representation for $\Tilde{\mathcal{Z}}_y$.
        \par
        The scaling limit here is analogous to the standard scaling limit result for SBM given in Proposition \ref{proposition SBM existence} and it is an instance of the general result given in \cite[Chapter II]{le1999spatial} which shows the existence of superprocesses as scaling limits.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.056406+00:00","domain":"probability theory","id":"claim_831b9cca3aab9fb8e6034b344f9baa69bf3841a5b7e27a67bf5f2d7d2d33a66c","kind":"lemma","schema_version":1,"statement":"[Lemma 23 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $\gamma = 1/16$. For every $R>0$, there is a constant $C>0$ such that
\begin{align}
    \sup_{t\leq R,\ |q|_{L^1}\leq R,\ x\in[0,3]^{\N^4}}\Ll|\tilde F^x_N(t,q) - \bar F^x_{N+1}(t,q)\Rr|\leq CN^{-\gamma},\quad\forall N\in\N.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:59:45.560935+00:00","domain":"probability theory","id":"claim_831ed51ab72bdec25a06ff14c38928236e63bdb66571192df3feb1e247e67302","kind":"concept","schema_version":1,"statement":"[Theorem thm: applications in information theory of arXiv:2411.17109, 'On the maximal correlation of some stochastic processes'] Let $X_1,X_2,\ldots,X_n$ be independent real-valued continuous random variables. Let $S\subset T$ be two nested non-empty random subsets of $[n]=\{1,2,\ldots,n\}$, which are independent of $X=(X_1,X_2,\ldots,X_n)$. Let $R$ be the maximal correlation coefficient between $(S,X_S)$ and $(T,X_T)$ given by (equation eq: R Y Z of the paper), where $X_{S}=(X_i)_{i\in S}$ and $X_{T}=(X_j)_{j\in T}$. Denote by $I(Z)=\int_{-\infty}^{\infty}\frac{(f'(z))^2}{f(z)}\,\mathrm{d}z$ the Fisher information of the continuous random variable $Z$ with the density $f(z)$. Then we have that
\begin{equation}
\sum_{t\subset[n]}P(T=t)I(\sum_{j\in t}X_j)\mu_t^2\leq R^2\sum_{s\subset[n]}P(S=s)I(\sum_{i\in s}X_i)\lambda_s^2,
\end{equation}
where $\mu_t=\sum_{s\subset[n]}P(S=s|T=t)\lambda_s$ for $t\subset[n]$ and $(\lambda_s)_{s\subset[n]}$ is an arbitrary real vector. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:58:01.553016+00:00","domain":"probability theory","id":"claim_8321896471927ec299c8479b2d1278dcaeed607179b2720678b61ec97383c497","kind":"concept","schema_version":1,"statement":"[Corollary 10 of arXiv:2608.27143, 'An approximate zero bias transformation for random sums: Applications to sampling with out'] Let $n_1, n_2, n_3\in \mathbb{N}$ be such that $n_1< n_2< n_3$. Let $X_1,X_2,\ldots$ be mean zero random variables with finite variances.
Suppose that
$X_1,\ldots,X_{n_1}$, $X_{n_1+1},\ldots X_{n_2}$, $X_{n_2+1},\ldots X_{n_3}$    and  $X_{n_3+1}, X_{n_3+2}, \ldots $ 
form four independent groups of i.i.d.\ random variables, where the distributions may differ among the four groups. Let $W=\sum_{i=1}^N X_i$, where $N$ is a Poisson random variable  with parameter $\lambda$, independent of $\{X_i\}_{i=1}^\infty$, and let
 $\sigma^2$ be defined as in \eqref{TH:AI1}. Then
			\begin{align}
				d_1\!\left(\mathcal{L}(W/\sigma), \mathcal{L}(Z) \right)
				&\le \frac{1}{\sigma^3} \sum_{i=1}^{n_{1}} 
				\left(\mathbb{E}|X_1|^3 + 2\,\mathbb{E} X_1^2 \,\mathbb{E}|X_1|\right) P^2(N \ge i) \nn\\[4pt]
				&\quad + \frac{1}{\sigma^3} \sum_{i=n_{1}+1}^{n_2} 
				\left(\mathbb{E}|X_{n_{1}+1}|^3 + 2\,\mathbb{E} X_{n_{1}+1}^2  \,\mathbb{E}|X_{n_{1}+1}|\right) P^2(N \ge i)\nn \\[4pt]
				&\quad + \frac{1}{\sigma^3} \sum_{i=n_{2}+1}^{n_3} 
				\left(\mathbb{E}|X_{n_{2}+1}|^3 + 2\,\mathbb{E} X_{n_{2}+1}^2  \,\mathbb{E}|X_{n_{2}+1}|\right) P^2(N \ge i)\nn \\[4pt]
				&\quad + \frac{1}{\sigma^3} \sum_{i=n_{3}+1}^{\infty} 
				\left(\mathbb{E}|X_{n_{3}+1}|^3 + 2\,\mathbb{E} X_{n_{3}+1}^2  \,\mathbb{E}|X_{n_{3}+1}|\right) P^2(N \ge i) \nn\\[4pt]
				&\quad + \frac{2\sqrt{2}}{\sqrt{\pi}} 
				\Bigg(1 -\sum_{i=1}^{n_1}\frac{1}{\lambda^2_1\sigma^2} \, {P}^2(N \ge i) -\sum_{i=n_1+1}^{n_2}\frac{1}{\lambda^2_2\sigma^2} \, {P}^2(N \ge i)\nn\\&\quad\quad\quad\quad  -\sum_{i=n_2+1}^{n_3}\frac{1}{\lambda^2_3\sigma^2} \, {P}^2(N \ge i)-\sum_{i=n_3+1}^{\infty}\frac{1}{\lambda^2_4\sigma^2} \, {P}^2(N \ge i)\Bigg).
			\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.042535+00:00","domain":"probability theory","id":"claim_8324f55c88c2315f748c9d382041d145d9ff2aeb3bfa72bd403cabaeb89f48b6","kind":"theorem","schema_version":1,"statement":"[Thm 2 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta\subseteq\mathbb{R}^d\times\mathbb{S}_+^d\times\mathcal{L}$ be closed, convex, and satisfy Assumptions~\ref{B} and~\ref{J}. Moreover, let the cost function $L$ satisfy Assumption~\ref{L}. Then we have
