{"assumptions":[],"created_at":"2026-10-27T19:48:47.286518+00:00","domain":"probability theory","id":"claim_87bb2e0f26021dd711a73ec3bfb43d1d40e5f730e4d151be7f17ffdbd3504e91","kind":"definition","schema_version":1,"statement":"[Definition def:matchlaw of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Fix $n\geq 2$. Let $\zeta$ be a probability measure on $[0,1]$ with
		$(n+1)$-atom prefix $\{0,q_1,\ldots,q_n\}$ as in Definition~(def:nprefix of the paper);
		the tail $\mathrm{supp}(\zeta)\cap(q_n,1]$ may be nonempty.
		Let $(X_t)_{t\in[0,1]}$ be the Auffinger--Chen process~(equation eq:AuffingerChen of the paper),
		and write $U:=\partial_x\Phi_\zeta(q_{n-1},X_{q_{n-1}})$.
		Define $\mathrm{Test}:=\{\chi_1,\ldots,\chi_5\}$, where each $\chi_i:[-1,1]\to\mathbb{R}$ is given by
		\begin{align}
			\chi_1(m) &:= \mathbb{E}\!\left[(\partial_x\Phi_\zeta(q_n,X_{q_n}))^2 \;\middle|\; U=m\right], \\
			\chi_2(m) &:= \mathbb{E}\!\left[\partial_x\Phi_\zeta(q_n,X_{q_n})\,X_{q_n} \;\middle|\; U=m\right], \\
			\chi_3(m) &:=\mathbb{E}[\partial_x\Phi_\zeta(q_n,X_{q_n})\mid U=m]=m, \\
			\chi_4(m) &:= \mathbb{E}\!\left[X_{q_n} \;\middle|\; U=m\right], \\
			\chi_5(m) &:= \mathbb{E}\!\left[\Phi_\zeta(q_n,X_{q_n}) \;\middle|\; U=m\right]. 
		\end{align}
		For $\varepsilon\in(0,1)$, let $\delta_\varepsilon=\varepsilon^{\frac{1}{2}}$ and define $\mathrm{LawMatch}_{n-1}(\zeta,\varepsilon)$ as the set of
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)})\in([-1+\delta_\varepsilon,1-\delta_\varepsilon]^N)^{n-1}$ such that, for every
		$\chi\in\mathrm{Test}$ and $k\in[n-1]$,
		\begin{equation}
			\left|\frac{1}{N}\sum_{i=1}^N\chi(m_i^{(n-1)})\,m_i^{(k)}
			-\mathbb{E}\!\left[\chi(U)\,\partial_x\Phi_\zeta(q_k,X_{q_k})\right]\right|\leq\varepsilon,
		\end{equation}
		\begin{equation}
			\left|\frac{1}{N}\sum_{i=1}^N\chi(m_i^{(n-1)})\,\partial_m h_\zeta(q_k,m_i^{(k)})
			-\mathbb{E}\!\left[\chi(U)\,X_{q_k}\right]\right|\leq\varepsilon,
		\end{equation}
		\begin{equation}
			\left|\frac{1}{N}\sum_{i=1}^N\chi(m_i^{(n-1)})
			-\mathbb{E}\!\left[\chi(U)\right]\right|\leq\varepsilon
		\end{equation}
		and, for every $k\in[n-1]$,
		\begin{equation}
			\left|\frac{1}{N}\sum_{i=1}^N \Phi_\zeta\!\Bigl(q_k,\partial_m h_\zeta(q_k,m_i^{(k)})\Bigr)
			-\mathbb{E}\!\left[\Phi_\zeta(q_k,X_{q_k})\right]\right|\leq\varepsilon.
		\end{equation}","status":"unverified"}

