\mathcal W := \left\{  w \in \mathbb R^{r + |\Omega_c|} : \sum_{\rho=1}^{r } w(\rho) S_\rho + \sum_{ k \in \Omega_c } w(k ) =0 \right\}. 
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:37:08.314113+00:00","domain":"probability theory","id":"claim_8944c7b6c89c23d44860c46aaf943240a352301a06e38a18fb3ea962418912f9","kind":"concept","schema_version":1,"statement":"[Cor mr of arXiv:2608.30777, 'Inhomogeneous nonlinear Schr\"odinger equation \\ in Fourier-Lebesgue and modulation space'] Let $1<\alpha <5-2b, 0<b< 1/4, \; r$ and $p_{0}$ be as given in (equation rvalues of the paper) and (equation pminloc of the paper), respectively,
