{"assumptions":[],"created_at":"2026-10-28T01:29:08.520907+00:00","domain":"probability theory","id":"claim_899898bc6cdf01fe456d40cc12df032067ff86fe5342e6a510c3934f4fc75870","kind":"concept","schema_version":1,"statement":"[Proposition prop:radial-flowline of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Fix {$\kappa\in(0,4)$,}  $\alpha>\chi,\beta\in\mathbb{R}$, and suppose that $h_{\alpha\beta} = h +\alpha\arg(\cdot)+\beta\log|\cdot|$ has boundary conditions on $\partial\mathbb{D}$ as depicted in Figure~(fig:radial-gff of the paper) where $h$ is a Dirichlet GFF on $\mathbb{D}$. Let 
	\begin{equation}
	   2\pi(1-\frac{\alpha}{\chi})<\theta_2<\theta_1<\frac{2\lambda}{\chi}, \ \ \theta_1-\theta_2<2\pi(\frac{\alpha}{\chi}-1); \ \ \rho = \kappa-6+\frac{2\pi\alpha}{\lambda} . 
	\end{equation}
	Let $(\eta_1,\eta_2)$ be the flow lines of $h_{\alpha\beta}$ with angles $(\theta_1,\theta_2)$ from $-i$ to 0. Then:
	\begin{enumerate}[(i)]
	    \item For $i=1,2$, $\eta_i$ is a radial $\mathrm{SLE}_\kappa^\beta(-\frac{\theta_i\chi}{\lambda};\rho+\frac{\theta_i\chi}{\lambda})$ process;
	    \item $\eta_1$ and $\eta_2$ do not cross each other;
	    \item $\eta_1,\eta_2$ are continuous near 0;
	    \item  
	   {Conditioned on $\eta_1$, the curve $\eta_2$ is the union of independent curves in certain connected components of $\mathbb{D}\backslash\eta_1$, as follows. 
	   \begin{itemize}
	       \item If $\eta_1$ first touches itself at time $\sigma_1<\infty$, let $D_{\eta_1}$ be the component having $\eta_1(\sigma_1)$ on its boundary whose boundary contains a segment of $\partial \mathbb{D}$. Otherwise let $D_{\eta_1}$ be the component having $0$ on its boundary. 
	       Let $a_{\eta_1}$ and $b_{\eta_1}$ be the first and last points on $\partial D_{\eta_1}\cap\partial \mathbb{D}$ when one views $\partial \mathbb{D}$ as a counterclockwise curve from $(-i)^+$ to $(-i)^-$.  Then in $D_{\eta_1}$, $\eta_2$ is a chordal $\mathrm{SLE}_\kappa(\frac{(\theta_1-\theta_2)\chi}{\lambda}-2;\rho+\frac{\theta_2\chi}{\lambda},-\frac{\theta_1\chi}{\lambda})$ process from $a_{\eta_1}$ to $\eta(\sigma_1)$ with force points $a_{\eta_1}^-;a_{\eta_1}^+,b_{\eta_1}$.

	       \item In each remaining component whose boundary contains a segment of the counterclockwise boundary arc of $\partial\mathbb{D}$ from $-i$ to $a_{\eta_1}$, $\eta_2$ is a chordal $\mathrm{SLE}_\kappa(\frac{(\theta_1-\theta_2)\chi}{\lambda}-2;\rho+\frac{\theta_2\chi}{\lambda})$ process from the first to the last boundary point hit by $\eta_1$.

	       \item In each remaining component whose boundary does not contain a segment of $\partial \mathbb{D}$, $\eta_2$ is a chordal $\mathrm{SLE}_\kappa(\frac{(\theta_1-\theta_2)\chi}{\lambda}-2;\rho+\frac{(\theta_2-\theta_1)\chi}{\lambda})$ process from the first to the last boundary point hit by $\eta_1$.
	   \end{itemize}
	   Similarly, given $\eta_2$, defining $D_{\eta_2}, a_{\eta_2}, b_{\eta_2}$ as above with $\eta_1$ replaced by $\eta_2$ and counterclockwise replaced by clockwise, the curve $\eta_1$ is $\mathrm{SLE}_\kappa(-\frac{\theta_1\chi}{\lambda},\rho+\frac{\theta_2\chi}{\lambda};\frac{(\theta_1-\theta_2)\chi}{\lambda}-2)$ in  $D_{\eta_2}$, $\mathrm{SLE}_\kappa(-\frac{\theta_1\chi}{\lambda};\frac{(\theta_1-\theta_2)\chi}{\lambda}-2)$ in each other connected component of $\mathbb{D}\backslash\eta_2$ whose boundary contains a segment of the  clockwise boundary arc of $\partial\mathbb{D}$ from $(-i)^-$ to $a_{\eta_2}$, and $\mathrm{SLE}_\kappa(\rho+\frac{(\theta_2-\theta_1)\chi}{\lambda};\frac{(\theta_1-\theta_2)\chi}{\lambda}-2)$ in each remaining component whose boundary does not contain an interval of $\partial \mathbb{D}$. }
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:49.288625+00:00","domain":"probability theory","id":"claim_8998e092eeea70ccf1ccb9643ac544e7803ae7249cb62ec723b552bc4a7bc7c9","kind":"definition","schema_version":1,"statement":"[Definition 3 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Let $X$ be a path-dependent process taking values in $S$.
    We call  $X$ \emph{affine} (up to time $T$), if there exist
    \begin{align*}
        \phi & : \{(t,T,\mu) \in [0,T]^2 \times \cU(T) : t \leq T\} \to \C,                \\
        \Psi & : \{(t,T,\mu) \in [0,T]^2 \times \cU(T) : t \leq T\} \to \ccM([0,T], \C^d),
    \end{align*}
    with $\phi(\cdot,T,0) = 0$ and $\Psi(\cdot,T,0) =0$
    such that
    \begin{enumerate}
        \item[(i)] for each fixed $\mu$, $t \mapsto \phi(t,T,\mu)$ is absolutely continuous on $[0,T]$ and the pair $(\Psi, X)$ satisfies Assumption~\ref{ass:sm-diff-Psi},
        \item[(ii)] for each fixed $(t,T)$, the mappings $\mu \mapsto \phi(t,T,\mu)$ and $\mu \mapsto \Psi(t,T,\mu)$ are continuous in the $weak^\ast$-topology, and
        \item[(iii)] the following affine transform formula holds:
              \begin{equation}
                  E[e^{\, \mu \cdot X_{[0,T]} } \mid \ccF_t] = \exp\bigl( \phi(t,T,\mu) + \Psi(t,T,\mu) \cdot X_{[0,t]} \bigr)
              \end{equation}
              for all $ 0 \leq t \leq T $ and all $\mu \in \cU(T)$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:26:52.654162+00:00","domain":"probability theory","id":"claim_89b506bda712d9b2991e86fb1eb668d54436054a292b3bf2d0f3507178043590","kind":"concept","schema_version":1,"statement":"[Prop 2 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $p\in (2d,\infty)$ and assume that the initial value $(u^0,w^0)$ satisfies~\eqref{a1}. Then the corresponding solution $(u,w)$ to~\eqref{E} satisfies
