{"assumptions":[],"created_at":"2026-10-27T16:22:59.732192+00:00","domain":"probability theory","id":"claim_8afc86b85f3b9f3210b1d201321f30252e304424751a8cbd488f9b0c84ec0ffc","kind":"definition","schema_version":1,"statement":"[Defn boundarysignature of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\Sigma \subset M$ be a compact planar surface with $\partial \Sigma \subset \partial M$. Define
\begin{align*}
    b_{nd}(\Sigma) &\coloneqq \text{the number of nondegeneracy boundary components of } \Sigma, \\
    b_{-\infty}(\Sigma) &\coloneqq \text{the number of $-\infty$ degeneracy boundary components of } \Sigma, \\
    b_{+\infty}(\Sigma) &\coloneqq \text{the number of $+\infty$ degeneracy boundary components of } \Sigma.
\end{align*}
We also define the \textbf{degeneracy signature} of $\Sigma$,
$$\bm{b}(\Sigma) \coloneqq \big(b_{nd}(\Sigma), b_{-\infty}(\Sigma), b_{+\infty}(\Sigma)\big).$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:04:40.975438+00:00","domain":"probability theory","id":"claim_8affca9814554b267863a19d106def06630e1be3582cd3da9f9862d4e19d1798","kind":"theorem","schema_version":1,"statement":"[Proposition prop_2 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $A$ be positive-semidefinite and 
\begin{eqnarray}

\alpha=\|A\|,\,\,\,\,\,\beta=\|A\|_2^2.
\end{eqnarray}
For $\frac{2}{3}<a<1$, let 
\begin{eqnarray}

b=\frac{3a-2}{a(2a-1)},\,\,\,\,\,c=\frac{3a-2}{2(1-a)^2}.
\end{eqnarray}
 Then 
\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq e^{\Lambda(t, a)},
\end{eqnarray}
where 
\begin{eqnarray}

\Lambda(t, a)=\left\{\begin{array}{cc}
    -\frac{t}{2a\alpha}+\frac{\beta}{2a^2\alpha^2}\Big(\sqrt{1+\frac{2a\alpha t}{\beta}}-1\Big)  & \frac{\alpha t}{\beta}\leq c   \\
    -\frac{bt}{2\alpha}+\frac{b^2\beta}{4(1-ab)\alpha^2}  &  \frac{\alpha t}{\beta}> c 
\end{array}\right..
\end{eqnarray}","status":"unverified"}

