\end{equation}
where the index \(2m-2r\) records the order of the Wiener chaos to which each term \(T_{2m-2r}\) belongs, and
\begin{multline}
T_{2m-2r} = \\  N^{2H'-1}\alpha(\varepsilon,H^*(m))^2I_{2m-2r}\left(\sum_{k=0}^{N-1}\int_{k\delta}^{(k+1)\delta}(\tau_s K^{\varepsilon})^{\otimes m}ds\otimes_r \int_{k\delta}^{(k+1)\delta}(\tau_s K^{\varepsilon})^{\otimes m}ds\right),
\end{multline}
and
\begin{equation}
c_m^2T_0 = \mathbb{E}[C_{\varepsilon, \delta}].
\end{equation}
The combinatorial weights \(\bigl(\tfrac{c_m m!}{(m-r)!\sqrt{r!}}\bigr)^2\) are the normalisation constants from the product formula for multiple Wiener--Itô integrals.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:59:58.431722+00:00","domain":"probability theory","id":"claim_8c2b0d7474433290c7250449d0e082b2f2ca4ba5cdfc4c2c75e5a02c1704633b","kind":"theorem","schema_version":1,"statement":"[Theorem thm:unrestricted-FG-mgle-barycenter-final of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] Let
\[
\mathbb{X}^k:=\mathbb{G}^{L^k}\in\mathcal{FG}_{\mathrm{mgle}}(T,d),
\qquad k\in[K].
\]
Then the unrestricted adapted barycenter problem
\begin{equation}

\inf_{\mathbb{Y}\in\mathrm{FP}_2}
\sum_{k=1}^K\lambda_k\mathcal{AW}_2^2(\mathbb{X}^k,\mathbb{Y})
\end{equation}
admits a representative \(\mathbb{G}^{
\accentset{\overline{\hphantom{L}}}{L}
}\in\mathcal{FG}_{\mathrm{mgle}}(T,d)\).  It may be chosen
as follows.  For every \(t\in[T]\), choose orthogonal matrices
\( Q_t^1,\ldots, Q_t^K\in\mathscr O(d)\) minimizing
\begin{equation}

\sum_{k=1}^K\lambda_k\|L^k_{t,t}\|_F^2
-
\left\|\sum_{k=1}^K\lambda_kL^k_{t,t} Q_t^k\right\|_F^2.
\end{equation}
Set
\begin{equation}

\accentset{\overline{\hphantom{L}}}{L}
_{t,t}:=\sum_{k=1}^K\lambda_kL^k_{t,t}\mathbf Q_t^k,
\qquad

\accentset{\overline{\hphantom{L}}}{L}
_{r,t}:=
\accentset{\overline{\hphantom{L}}}{L}
_{t,t},\quad r\ge t.
\end{equation}
Then \(\mathbb{G}^{0,
\accentset{\overline{\hphantom{L}}}{L}
}\) solves (equation eq:unrestricted-mgle-input-problem-final of the paper).  Equivalently,
its one-step covariance blocks are characterized by
\begin{equation}

\accentset{\overline{\hphantom{L}}}{L}
_{t,t}
\accentset{\overline{\hphantom{L}}}{L}
_{t,t}^{\intercal}
\in
\argmin_{\Sigma\in\mathscr S_+(d)}
\sum_{k=1}^K\lambda_k
\mathrm{dist}_{\mathrm{BW}}^2\!\left(
L^k_{t,t}(L^k_{t,t})^{\intercal},\Sigma
\right),
\qquad t\in[T].
\end{equation}
The barycenter value is
\begin{equation}

\sum_{t=1}^T(T-t+1)
\min_{\Sigma\in\mathscr S_+(d)}
\sum_{k=1}^K\lambda_k
\mathrm{dist}_{\mathrm{BW}}^2\!\left(
L^k_{t,t}(L^k_{t,t})^{\intercal},\Sigma
\right).
\end{equation}
In particular, for every martingale candidate \(\mathbb{G}^{0,M}\in\mathcal{FG}_{\mathrm{mgle}}(T,d)\),
\begin{equation}

\mathcal{AW}_2^2(\mathbb{G}^{0,L^k},\mathbb{G}^{0,M})
=
\sum_{t=1}^T(T-t+1)
\mathrm{dist}_{\mathrm{BW}}^2\!\left(
L^k_{t,t}(L^k_{t,t})^{\intercal},
M_{t,t}M_{t,t}^{\intercal}
\right).
\end{equation}
If the minimizer in (equation eq:mgle-local-BW-covariance-final of the paper) is unique for every
\(t\), then the barycenter is unique at the level of one-step increment covariances.
This uniqueness holds, for instance, whenever for each \(t\) at least one matrix
\(L^k_{t,t}(L^k_{t,t})^{\intercal}\) is positive definite.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:35:19.874049+00:00","domain":"probability theory","id":"claim_8c2b36f10da49c6878eea32f2405b23359faee61e3dfbacc5594f36fb84e58c2","kind":"definition","schema_version":1,"statement":"[Defn ent of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Given a discrete representation $\rho:\pi_1(S) \to \mathrm{PSL}_n(\mathbb{C})$, we define its Hilbert entropy to be:
\begin{equation}
H(\rho) =  \limsup\limits_{L\to \infty} \displaystyle\frac{\log \#\{[\gamma] \text{ a conjugacy class in } \pi_1(S)\ \vert\ l^H_\rho(\gamma) \leq L\}}{L}
\end{equation}
where $l^H_\rho(\gamma)$ is the Hilbert length of $\gamma$ with respect to $\rho$.  The \textit{translation length entropy} $E(\rho)$ is defined by the same expression, replacing $l^H_\rho(\gamma)$  by   the \textit{translation length} $\ell_\rho(\gamma)$ of $\rho(\gamma)$.","status":"unverified"}

