	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.217355+00:00","domain":"probability theory","id":"claim_8df385a7379543450fa968e7fd6a91a73744d13c6aefd0e66f1c2e80de591342","kind":"lemma","schema_version":1,"statement":"[Lemma le:projection-geometry of arXiv:2608.19358, 'An optimal Poincaré inequality\\for the complex Ginibre log-gas'] The following properties hold.
  \begin{enumerate}
  \item
    $\mathcal{H}_n^{\mathrm{div},0}$ and
    $\overline{\mathcal{H}_n^{\mathrm{div},0}}$ are orthogonal.
  \item For every symmetric $f\in L^2(\mu_n)$,
    \begin{equation}
      \|Pf\|_{L^2(\mu_n)}^2+\|Qf\|_{L^2(\mu_n)}^2
      \leq
      \|f\|_{L^2(\mu_n)}^2+\|P_0f\|_{L^2(\mu_n)}^2.
    \end{equation}
  \item If $f\in L^2(\mu_n)$ is real-valued, symmetric, and centered, then
    $h=Pf$, its pointwise complex conjugate $\overline h$, and
    $r=f-h-\overline h$, are three pairwise orthogonal functions in $L^2(\mu_n)$, and
    \begin{align}
      \|f\|_{L^2(\mu_n)}^2
      &=2\|h\|_{L^2(\mu_n)}^2+\|r\|_{L^2(\mu_n)}^2,
      \\
      \operatorname{dist}_{L^2(\mu_n)}
      \bigl(f,\mathcal{H}_n^{\mathrm{div}}\bigr)^2
      &=\frac{1}{2}\|f\|_{L^2(\mu_n)}^2
        +\frac{1}{2}\|r\|_{L^2(\mu_n)}^2.

    \end{align}
    In particular, we have the half-distance estimate 
    \begin{equation}
      \operatorname{dist}_{L^2(\mu_n)}
      \bigl(f,\mathcal{H}_n^{\mathrm{div}}\bigr)^2
      \geq\frac{1}{2}\|f\|_{L^2(\mu_n)}^2.
    \end{equation}
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.473798+00:00","domain":"probability theory","id":"claim_8df4656cb5469fc3cc9221a20d7456feab94c965501cf22edd68ebf05b16cdf2","kind":"theorem","schema_version":1,"statement":"[Corollary LemmaCondExpII of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $(u_{n})_{n \in \mathbb{N}}$ be any admissible ordering of $\mathcal{I}$ and let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C2 of the paper). Then, for $t \in \mathbb{R}$ and $k=0, \dots, h+1$, 
\begin{align}  
\mathbb{E}[\varphi_{u_{1}}(t-S(u_{1})) \mid \mathcal{G}^{(k)}_{0}] \stackrel{a.s.}{=}  \varphi^{(0)}_{u_{1}}(t-S(u_{1})),
\end{align} 
\noindent while for $i \geq 2$,
\begin{align} 
\mathbb{E}[\varphi_{u_{i}}(t-S(u_{i})) \mid \mathcal{G}^{(k)}_{i-1}] \stackrel{a.s.}{=}  \varphi^{(k)}_{u_{i}}(t-S(u_{i})).
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:38:08.415168+00:00","domain":"probability theory","id":"claim_8df7f53932b98b8c7e712235faae751aa3f98795e332aa72eade4b8117547728","kind":"lemma","schema_version":1,"statement":"[Lemma condition for rm=0 of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] If $(\lambda,C^2)\in S$, then $r_\mathcal{C}(\lambda,C^2)=0$ if and only if $\lambda\geq 0$ and

  \begin{equation*}
   C^2 = \frac{(p-1-\lambda)^2}{p^2} \frac{1}{1-\left(\frac{\lambda}{p-1}\right)^{\frac{2p-2}{p}}} \left(\frac{\lambda}{p-1}\right)^\frac{2p-2}{p}.
  \end{equation*}
  The set $\{r_\mathcal{C}=0\}$ is a smooth curve in $S^0 \subset S$ connecting $(0,0)$ to $(p-1,0)$ and $(p-1)k_m^p-\lambda=0$ along that curve.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.117739+00:00","domain":"probability theory","id":"claim_8df93691b3f7ea4331e9b1951a261204450e4ce7332e933292f00a7f226b1867","kind":"theorem","schema_version":1,"statement":"[Proposition prop:invariance of arXiv:2608.17022, 'Sharp hypocoercive convergence estimates for underdamped Langevin dynamics with specular r'] Let $f,g\in\mathscr C$. Then
\begin{equation}
\int_{\Omega\times\mathbb{R}^d}\mathscr{L} f\,\mathrm{d}\mu=0,
\end{equation}
so that $\mu$ is invariant for (equation eq:sde of the paper) and $\Lmuz$ is preserved by the flow; and along any solution of (equation eq:bke of the paper) in $\mathscr C$,
\begin{equation}
\frac{\mathrm{d}}{\mathrm{d} t}\,\frac12\nrm{f(t)}^2=-\gamma\nrm{\nabla_vf(t)}^2\le0 ,
\end{equation}
so the flow is an $\Lmu$-contraction. Moreover $\mathscr{L}$ is reversible up to velocity reversal: writing $(\mathcal Sf)(x,v):=f(x,-v)$, one has $\mathcal S^2=\mathrm{Id}$, $\mathcal S\mathscr C=\mathscr C$, and
\begin{equation}
\mathscr{L}^*=\mathcal S\,\mathscr{L}\,\mathcal S\qquad\text{on }\mathscr C,
\end{equation}
where $\mathscr{L}^*$ is the $\Lmu$-adjoint.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.741211+00:00","domain":"probability theory","id":"claim_8dfdf4ab5f85d638a7c6e93271e25f1b349409e649e33a6bd32910131ea44f5a","kind":"theorem","schema_version":1,"statement":"[Prop 51 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Suppose that $(Z_m)_m$ is locally bounded in $\cM_{\mathrm{adm}}(\cV^{\bar{\zeta}})$ and $f_m\in\cD^{\gamma,\delta}_{T}(Z_m)$ is locally bounded uniformly in $m$.
Then, after passing to a subsequence, there exist $Z\in\cM_{\mathrm{adm}}(\cV^{\bar{\zeta}})$ and $f\in\cD^{\gamma,\delta}_{T}(Z)$ such that
\begin{align*}
    \iota^{\cM}_{\zeta,\bar\zeta}Z_m
    &\longrightarrow
    \iota^{\cM}_{\zeta,\bar\zeta}Z,\qquad
    Q^\zeta_{<\gamma'}
    \iota_{\zeta,\bar\zeta}f_m
    \longrightarrow
    Q^\zeta_{<\gamma'}
    \iota_{\zeta,\bar\zeta}f
\end{align*}
locally in the corresponding model and singular modelled-distribution topologies corresponding to the shift $\zeta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:57:49.913025+00:00","domain":"probability theory","id":"claim_8e05bcf9bbba462359d4278f6b006585562b0fb29a290d136c99ef336acb1b17","kind":"concept","schema_version":1,"statement":"[Theorem thm:sub for noninvariant of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},P)$ be a probability space (not necessarily standard), and $T:\Omega\to \Omega$ be an invertible measurable transformation. Suppose that the limit $\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P\circ T^{i}$ exists, denoted by $Q$. 	Suppose that $\{f_n\}_{n\in\mathbb{N}}$ is a sequence of $\mathcal{F}$-measurable functions satisfying the following conditions:
	\begin{longlist}
		\item there exists $\lambda >0$ such that $-\lambda n\le f_n(\omega)\le \lambda n$ for any $n\in\mathbb{N}$, and $\omega\in\Omega$;
		\medskip
		\item for each $k,n\in\mathbb{N}$, $f_{n+k}\le f_n+f_k\circ T^n$.
	\end{longlist} 
	If $Q$ is ergodic, then there exists a constant $c\in\mathbb{R}$ such that 
	\[\lim_{n\to\infty}\frac{1}{n}f_n=c,\text{ }P\text{-a.s.}\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:18:27.573523+00:00","domain":"probability theory","id":"claim_8e150e503809ef8373b9abb906dd540fce3eaee2ca64f99653a371eb9fc1b7b6","kind":"concept","schema_version":1,"statement":"[Thm 29 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$. There exists $c_{\textup{mag}}=c_{\textup{mag}}(d)> 0$ such that, for every $h\in [0,1]$,
		\begin{equation}
			m(\beta_c,h)\geq c_{\textup{mag}}h^{1/3}.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:43:45.381791+00:00","domain":"probability theory","id":"claim_8e165c9fc06cdfc66075637d99f47f459cceb3f53e2072b07d3037e8e59481a0","kind":"definition","schema_version":1,"statement":"[Definition 39 of arXiv:2609.04033, 'From configuration spaces to graph complexes via $\mathbf{FA}$-modules'] Let $r\geq 2$.  
Define a chain complex $\mathsf{A}(n,r)$ as follows.  The underlying graded vector space is $$\mathsf{A}(n,r)= \mathsf{L}(n,r)\oplus  \Sigma^{-1}\mathsf{TT}(n,r)$$		





	The differential $d_\mathsf{A}$ has the form $d_{\mathsf{L}}+d_{\mathsf{TT}}+\eta$ where the first two are the component-wise differentials on the direct sum and where $\eta$ contracts even cycles, as above.","status":"unverified"}

