{"assumptions":[],"created_at":"2026-10-27T13:52:23.570854+00:00","domain":"probability theory","id":"claim_902ebd864b45686f0a35450356f0a45abbc863180e1219a19c892acbd103afd2","kind":"concept","schema_version":1,"statement":"[Corollary C:Chung of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Assume condition~(equation E:main of the paper) holds. For part (i) below, further assume $\ell < \alpha(\gamma+1/2)$ if $\beta = 2$ and
  $\gamma \in (0, 2]$.
  \begin{enumerate}[\rm (i)]

    \item If $\rho \in (0, 1)$, then for any compact interval $I$ in $(0,
            \infty)$ and any $x_0 \in \mathbb{R}^d$, there exist constants $C_5, C_5' \in [0,
              \infty]$ such that for each $t_0 \in I$,
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \sup_{t:\, |t-t_0|
              \le \varepsilon} \frac{|u(t, x_0) - u(t_0, x_0)|}{\varepsilon^\rho(\log\log(1/\varepsilon))^{-\rho}}
            = C_5 \quad \text{a.s.}
          \end{align}
          and
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \inf_{t_0 \in I} \sup_{t: |t-t_0|
              \le \varepsilon} \frac{|u(t, x_0) - u(t_0, x_0)|}{\varepsilon^\rho(\log(1/\varepsilon))^{-\rho}}
            = C_5' \quad \text{a.s.}
          \end{align}
          Moreover, when $\beta = 1$, $\gamma \ge 0$; or $\beta = 2$, $\gamma=[0,1]$, $\ell<\alpha(\gamma+1/2)$, we
          have $C_5>0$, $C_5'>0$, and $t \mapsto u(t, x_0)$ is a.s.\ nowhere
          differentiable on $(0, \infty)$.\\
          When $\gamma \in [0,1-\beta]$, we have $0 < C_5 < \infty$.

    \item If $\tilde\rho \in (0, 1)$, then for any $t_0 > 0$ and any compact
          rectangle $J$ in $\mathbb{R}^d$, there exist constants $C_6 \in (0,\infty)$ and
          $C_6' \in (0, \infty]$ such that for each $x_0 \in J$,
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \sup_{x:\, |x-x_0|
              \le \varepsilon} \frac{|u(t_0, x) - u(t_0, x_0)|}{\varepsilon^{\tilde\rho}(\log\log(1/\varepsilon))^{-\tilde\rho/d}}
            = C_6 \quad \text{a.s.}
          \end{align}
          and
          \begin{align}
            \liminf_{\varepsilon \to 0^+} \inf_{x_0 \in J} \sup_{x:\, |x-x_0|
              \le \varepsilon} \frac{|u(t_0, x) - u(t_0, x_0)|}{\varepsilon^{\tilde\rho}(\log(1/\varepsilon))^{-\tilde\rho/d}}
            = C_6' \quad \text{a.s.}
          \end{align}
          In particular, $x \mapsto u(t_0, x)$ is a.s.\ nowhere differentiable on
          $\mathbb{R}^d$.
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.473747+00:00","domain":"probability theory","id":"claim_902f5fc803aef32312e4c41952b4938b9e1b0766db2cfabb7409c42925a3eca8","kind":"lemma","schema_version":1,"statement":"[Lemma lem:overdam of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $\mathcal{L}_\gamma = \mathcal{L}_H + \gamma \mathcal{L}_S$, with $\mathcal{L}_H$ in (equation Hamiltonianterm of the paper) and $\mathcal{L}_S$ in (equation def:lsbip of the paper), be the QMS generator given as above. Suppose that Conditions~(asspA2 of the paper), (asspB2 of the paper), and~(condeq:php of the paper) hold. Then, we have 
\begin{enumerate}[label=(\roman*)]
    \item  The generator $\mathcal{L}_O$ of the overdamped limit of $\exp(t \mathcal{L}_\gamma)$ is given by
    \begin{align} 
        \mathcal{L}_O(X^B) = - \sum_{j \ge 1} \frac{1}{\lambda_j} \Gamma_{\sigma^B}^{-1}\left[(G_j^B)^*, \Gamma_{\sigma^B}\left(\left[G_j^B, X^B \right]\right) \right],
    \end{align}
    where the operators $G_j^B$ are from the decomposition (equation eq:decomHab of the paper), and $\Gamma_{\sigma^B}$ is defined as in (equation def:weighting of the paper).  
    \item $\mathcal{L}_O$ is self-adjoint with respect to the KMS inner product $\langle \cdot, \cdot \rangle_{\sigma^B,1/2}$ on $\mathcal{M}_B$ with invariant state $\sigma^B$. The fixed-point subspace of $\exp(t \mathcal{L}_O)$ is 
    \begin{align} 
        \ker(\mathcal{L}_O) = \left\{X^B \in \mathcal{M}_B\,;\ \left[G_j^B, X^B\right] = 0 \ \text{for all $j \ge 1$}  \right\}\,.
    \end{align}
    Thus, $\sigma^B$ is the unique invariant state of $\exp(t \mathcal{L}_O^\dag)$ if and only if 
    \begin{align}  
        \ker(\mathcal{L}_O) = {\rm Span}\{{\bf 1}^B\}\,.
    \end{align}
    \item The fixed-point algebra of $\exp(t \mathcal{L}_\gamma)$ satisfies
    \begin{align} 
        \mathcal{F}(\mathcal{L}_\gamma) = {\bf 1}^A \otimes \ker(\mathcal{L}_O)\,.
    \end{align}
    Thus, $\mathcal{L}_\gamma$ is primitive if and only if (lokernel of the paper) holds.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.300508+00:00","domain":"probability theory","id":"claim_903131b92ccea9c62cf972e8cddc2da4377e7ec9a62d3ac567f5f298b1e583a5","kind":"lemma","schema_version":1,"statement":"[Lem theo: decoupling ineq of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $n,$ $T$ and $N$ be as in Corollary~(coro: advanced geographic ineq coupling map of the paper). Let 
	\begin{align*}
		A_n^{(1)}(\delta)&=\{u\in \widetilde{\mathcal{W}}_n\ |\ d_{\mathrm{LP}}(L[u],\mu_1)\leqslant \delta\},\\
		A_n^{(2)}(\delta)&=\{u\in \widetilde{\mathcal{W}}_n\ |\ d_{\mathrm{LP}}(L[u],\mu_2)\leqslant \delta\},\\
