\end{equation*}

\item[(3)] There exists a constant $C_{23}>0$, which depends on $\delta$, $T$, $\|v_0\|_{H^1(\Omega)}$ and $\|w_0\|_{H^1(\Omega)}$, such that

\begin{equation*}
\int_0^T \|w_{\text{{\tiny $\delta$}}}'(t)\|_{L^2(\Omega)}^2dt+\left( \sup_{0 \le t \le T} \|w_{\text{{\tiny $\delta$}}}(t)\|_{H^1(\Omega)} \right)^2
+\int_0^T \|w_{\text{{\tiny $\delta$}}}(t)\|_{H^2(\Omega)}^2 dt \le C_{23}.
\end{equation*}

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:38:25.224670+00:00","domain":"probability theory","id":"claim_936a5796dc9ba38e672dc255a1a44c144bc94403fd984c90e9cb70a50b3fed61","kind":"theorem","schema_version":1,"statement":"[Proposition Propositio:Stabilitytrace of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $\gamma \in (0,1)$ and $a= 1-2\gamma$. Then, there exists a constant $C>0$ such that for any $U\in \dot{W}^{1,2}(\mathbb{R}_{+}^{n+1}, y^a )$ with trace $TU =w$
