where 	for $1 \leq k \leq d$, $1 \leq \ell \leq m, \, 0 \leq s \leq t \leq T, s \mapsto \Theta_{t}^{k,\ell}(s)$ satisfies
\begin{align}
	\Theta_{t}^{k,\ell}(s)=\sigma_{k,\ell}\left(X_s\right) &+ \sum_{p=1}^{d} \int_{s}^{t} \partial_{p} b_{k}\left(X_u\right) \Theta_{u}^{p, \ell}(s) \mathrm{d} u \nonumber \\
