 \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:24.614395+00:00","domain":"probability theory","id":"claim_9522bc3790555b79a743388bbea2dcb5505da1997d94a44c2c6641bc1205c254","kind":"definition","schema_version":1,"statement":"[Definition 6 of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] The \textbf{\(AB\)-transition starting point distribution} on \(A^c \cap (\partial A + 1)\) and the \textbf{\(BA\)-transition starting point distribution} on \(B^c \cap (\partial B + 1)\) are defined as follows:
    \begin{equation}
        \begin{aligned}
            \eta_A^{*}(x) &= v_A^{*-1} \int_{\bar{A} \cap (\partial A + 1)} \int_{|r| < 1} \mathbf{1}_{\{\mathrm{dist}(y, A^c) \leq F(y, r)\}} \nu(\d r) \eta_A^-(y)\d y, \quad x \in A^c \cap (\partial A + 1), \\
            \eta_B^{*}(x) &= v_B^{*-1} \int_{\bar{B} \cap (\partial B + 1)} \int_{|r| < 1} \mathbf{1}_{\{\mathrm{dist}(y, B^c) \leq F(y, r)\}} \nu(\d r) \eta_B^-(y)\d y, \quad x \in B^c \cap (\partial B + 1),
        \end{aligned}
    \end{equation}
    where \(v_A^*\) and \(v_B^*\) are normalization constants, ensuring that \(\eta_A^*\) and \(\eta_B^*\) define probability measures on \(A^c \cap (\partial A + 1)\) and \(B^c \cap (\partial B + 1)\), respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.584704+00:00","domain":"probability theory","id":"claim_9524240a41b47fb228be0f8d7b55caec58f4cd57c221437b11ade03e8bdaeee8","kind":"theorem","schema_version":1,"statement":"[Prop eq:FE_h_right of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] For $(x,y)\in\mathbb C^2$ such that $\Re x>0$ and $\Re y>0$, we have
\begin{equation}

K^*(x,y)\,\widehat h^\rightarrow(x,y)
=
k_1^*(x,y)\,\widehat h^\rightarrow_1(y)
+
k_2^*(x,y)\,\widehat h^\rightarrow_2(x)
+
c\,h^\rightarrow(0,0),
\end{equation}
where
\begin{equation}

    \left\{
    \begin{array}{rcl}
    K^*(x,y) & = & \frac{1}{2}(x^2+y^2+2\rho xy)-\mu_1x-\mu_2y,\\
    k_1^*(x,y) & = & \frac{1}{2} (x-r_1 y)+\rho y +\mu_1,\\
    k_2^*(x,y) & = & \frac{1}{2} (y-r_2 x)+\rho x +\mu_2,\\
    c & = & \frac{1}{2}(r_1+r_2)-\rho.
    \end{array}
    \right.
\end{equation}","status":"unverified"}

