{"assumptions":[],"created_at":"2026-10-27T11:26:52.654731+00:00","domain":"probability theory","id":"claim_9a8a724e5730e6b57d24a7203ce995676609d7cf5ba4131013f2e5c0eb8d4151","kind":"lemma","schema_version":1,"statement":"[Lem 11 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $a>0$, $M=a|\mathbb{B}_R|$ and consider $u\in \Sigma_a$. Then
\begin{equation}
	|\partial_r \phi'(u(r))| \le \frac{\|u\|_\infty}{d}r\,,\quad r\in (0,R]\,,
\end{equation}
and
\begin{equation}
	|\phi'(u(r))-\langle\phi'(u)\rangle| \le \frac{M}{\sigma_d(m-1)}\left(\frac{r^{2-d}}{d}+\frac{R^{2-d}}{2}\right)\,,\quad r\in (0,R]\,.
\end{equation}
Moreover,
\begin{equation}
	0<u(r)\le  \left( a R^d + \frac{a^2 R^d r^2}{d^2 m}\right) r^{-d}\,,\quad r\in (0,R]\,,
\end{equation}
and
\begin{align}
	\partial_r u(r)\le  \frac{a}{dm} u(r) r\,,\quad r\in (0,R]\,.
\end{align}
In fact,
\begin{equation}
	|\partial_r u(r)| \le \min\{u(r),u(r)^{2-m}\}\|u\|_\infty\frac{r}{dm}\,,\quad r\in (0,R]\,,
\end{equation}
and 
\begin{equation}
	|\partial_r u(r)| \le \frac{M}{m\sigma_d}\min\{u(r),u(r)^{2-m}\}r^{1-d}\,,\quad r\in (0,R]\,.
\end{equation}","status":"unverified"}

