{"assumptions":[],"created_at":"2026-10-27T18:40:26.999011+00:00","domain":"probability theory","id":"claim_9b83791738f9c1bd5c6bb085644d84c9ac66b1bf489c86b0dd2f548c7350807f","kind":"concept","schema_version":1,"statement":"[Corollary cor:polynomial_decay of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] Assume that the following conditions hold:
\begin{itemize}
\item \textbf{(Related to initial data in Fourier space)} 
Let $\rho$ and $\kappa$ be as in (equation eq:decay of the paper) and (thm:poly of the paper), respectively. Assume that
\[
\rho_{j,j'} - \kappa_{j,j'} > 2, \quad j=1,\dots,d,\; j'=1,\dots,\nu_j.
\]

\item \textbf{(Size of initial data with respect to $\varepsilon$)} 
Let $\omega \notin \Omega_{\delta}$ with $\delta\sim\varepsilon^{1+\eta}$, where
\begin{equation}
0 \le \eta < \min\left\{ 2\Bigl(\frac{1}{\nu}-\mu_1\Bigr)\eta_2-\mu_2,\; \eta_3\right\}. 
\end{equation}
Here $0<\mu_1 \ll 1/\nu, 0<\mu_2 \ll 1$, $\eta_2$ and $\eta_3$ are given by
\begin{align}
\eta_2 &= \sum_{j=1}^{d} \sum_{j'=1}^{\nu_j}
\bigl(\rho_{j,j'} - \kappa_{j,j'} - 1\bigr), \\
\eta_3 &= \frac{2}{3}(\alpha-1)-\frac{\mu_3}{3}, 
\quad 0<\mu_3 \ll 1.

\end{align}
\end{itemize}
 Then the randomized Fourier coefficients satisfy the following almost sure polynomial decay estimates:
\begin{align}
\bigl|c(\boldsymbol{n}) g_{\boldsymbol{n}}(\omega)\bigr|
\le \varepsilon^{-\frac{1}{2}-\frac{\eta}{2}} \,\tnorm{\boldsymbol{n}}_{-(\rho-\kappa)},\quad\omega\notin\Omega_\delta,
\end{align}
where
\begin{align}
\rho - \kappa 
= \bigl( \rho_{1,1}-\kappa_{1,1}, \dots, \rho_{1,\nu_1}-\kappa_{1,\nu_1}; \dots; \rho_{d,1}-\kappa_{d,1}, \dots, \rho_{d,\nu_d}-\kappa_{d,\nu_d} \bigr).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:32:28.955792+00:00","domain":"probability theory","id":"claim_9b8586954c0d9626a153204c711d07728a7268624f1653fded880e8fedf8db70","kind":"lemma","schema_version":1,"statement":"[Lemma lem:prim of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] For every $q>1$ there is $C=C_{\varepsilon,q}<\infty$ such that
\begin{equation}

\mathbb{P}\Bigl(\exists (j,k)\in\mathcal E_{\mathrm{RW}}:
S(J_j^{\rm R}(q))\cap S(J_k)\ne\emptyset\Bigr)
\le C\delta^{-1}|\log\delta|(\log n)^{-(q-1)}.
\end{equation}
The same bound holds with $J_j^{\rm R}(q)$ replaced by any of
$J_j^{\rm L}(q)$, $J_k^{\rm L}(q)$, or $J_k^{\rm R}(q)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.725215+00:00","domain":"probability theory","id":"claim_9b8637e62d9b3761fd13e6ce3d1a8a2f1777bc1278089008f7a06fe376650afe","kind":"definition","schema_version":1,"statement":"[Definition 3 of arXiv:2609.02732, 'Conservation of mass for solutions of Leibenson's equation on Riemannian Manifolds'] \normalfont
		We say that a non-negative function $u=u(x, t)$ is a \textit{weak
			subsolution} of (\ref{dtv}) in $\Omega\times I$, if 
		\begin{equation}  
			u\in C\left(I; L^{q+1}(\Omega)\right)\quad \textnormal{and}\quad 
			u^{q}\in L_{loc}^{ p}\left(I; W^{1, p}(\Omega)\right),
		\end{equation} where (\ref{dtv}) holds weakly in $\Omega\times I$, which means that for all $t_{1}, t_{2}\in I$ with $t_{1}<t_{2}$, and all non-negative \textit{test functions} 
		\begin{equation}  
			\psi\in W_{loc}^{1, 1+\frac{1}{q}}\left(I;
			L^{1+\frac{1}{q}}(\Omega)\right)\cap L_{loc}^{p}\left(I; W_{0}^{1,
				p}(\Omega)\right),
		\end{equation}
		we have 
		\begin{equation}  
			\left[\int_{\Omega}{u\psi }\right]_{t_{1}}^{t_{2}}+\int_{t_{1}}^{t_{2}}{
				\int_{\Omega}{-u\partial_{t}\psi+|\nabla u^{q}|^{p-2}\langle\nabla u^{q},
					\nabla \psi\rangle}}\leq 0.
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:29:14.932607+00:00","domain":"probability theory","id":"claim_9b891b51bf254369a00e42265f4a435768451328b7b5ab3c8bac35ecd8240707","kind":"lemma","schema_version":1,"statement":"[Lemma lem flow of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] There exists a flow $\phi_\ell$ connecting $\delta_0$ to $p_\ell$ satisfying the following conditions.
		\begin{itemize}
			\item $\phi_\ell (x,y) = 0$ unless $x,y \in \Lambda_\ell$;
			\item There exists a finite positive constant $C_0 (d)$ such that
			\[\sum_{x \sim y} \phi_\ell (x,y)^2 \leqslant C_0 g_d (\ell),\]
			where
			\[g_d (\ell) = \begin{cases}
				\ell, \quad&\text{if } \;d=1,\\
				\log \ell, \quad&\text{if } \;d=2,\\
				1, \quad&\text{if } \;d\geqslant 3.
			\end{cases}\]
		\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:26:02.502747+00:00","domain":"probability theory","id":"claim_9b8ab72fe6de7262d60e2021bbbb8c1e835665d7143b464b8e266945ef417f35","kind":"theorem","schema_version":1,"statement":"[Thm resolvealeph of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Suppose $\Phi$ is $\aleph$-unobstructed. With the previous notation, there exists $\varepsilon > 0$ such that
\begin{align} 
    U^\varepsilon_\flat \times U^\varepsilon_\sharp \times U^\varepsilon_- \times U^\varepsilon_+ \times \{(w_1, \dots, w_{k_\circ})\} \times \mathbb{R}^{k_\aleph} \subset \mathcal{Z}(\Phi).
