{"assumptions":[],"created_at":"2026-10-27T21:28:49.113715+00:00","domain":"probability theory","id":"claim_9eb399b4802d8d8668575644774a8e5e69098f12ad8ea4579f26450da02b6e65","kind":"lemma","schema_version":1,"statement":"[Lemma lem:pole-mixed-hermite-coupling of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Assume (equation eq:pole-coefficient-class of the paper).  Fix
$\alpha,K\geq0$, $0<r\leq T$, $N_{\mathrm H}\geq1$, and
$C_{\mathrm{cmp}}>0$.  Let
$J\subset(0,1]$ be an interval with $\inf J>0$,
and let $q_{\mathrm{lo}}=\Pi_{\mathrm{lo}}q_{\mathrm{lo}}$ belong to the graph
class $W^{1,2}(J;L^2(\gamma_d))\cap L^2(J;\mathscr D_\gamma)$.  There exists a constant
$C_0=C_0(N_{\mathrm H},T,\lambda,\Lambda)>0$ such that, with all norms restricted to $J$,
\begin{align}
 \norm{(\mathcal P_r-\mathcal P_{\mathrm{Br}})q_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}}
 +\norm{(\mathcal J_r-\mathcal J_{\mathrm{Br}})q_{\mathrm{lo}}}_{\mathscr Y_{\alpha,K,r}}
 \leq C_0\mathcal M_d(a)r
       \norm{(I+\mathcal N)q_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}},
 \\
 \norm{\Pi_{\mathrm{hi}}\mathcal P_rq_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}}
 \leq C_0\mathcal M_d(a)r
       \norm{(I+\mathcal N)q_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}}.

\end{align}
If, in addition, $q_{\mathrm{hi}}=\Pi_{\mathrm{hi}}q_{\mathrm{hi}}$ belongs to
the same graph class and satisfies the ellipticity-controlled comparison
\begin{equation}
 \norm{q_{\mathrm{hi}}}_{\gamma_d}
 +s^{-1}\norm{Dq_{\mathrm{hi}}}_{\gamma_d}
 +s^{-1}\norm{D^2q_{\mathrm{hi}}}_{\gamma_d}
 \leq C_{\mathrm{cmp}}\norm{\mathcal J_rq_{\mathrm{hi}}}_{\gamma_d}
 \quad\text{for a.e. }s\in J,

\end{equation}
then there exists a constant
$C=C(N_{\mathrm H},T,\lambda,\Lambda,C_{\mathrm{cmp}})>0$ such that
\begin{align}
 \norm{\Pi_{\mathrm{lo}}\mathcal P_rq_{\mathrm{hi}}}_{\mathscr X_{\alpha,K,r}}
 &\leq C\mathcal M_d(a)r
       \norm{\mathcal J_rq_{\mathrm{hi}}}_{\mathscr Y_{\alpha,K,r}},
 \\
 \left|\inner{\mathcal J_rq_{\mathrm{lo}}}
                   {\mathcal J_rq_{\mathrm{hi}}}_{\mathscr Y_{\alpha,K,r}}\right|
 &\leq C\mathcal M_d(a)r
       \norm{(I+\mathcal N)q_{\mathrm{lo}}}_{\mathscr X_{\alpha,K,r}}
       \norm{\mathcal J_rq_{\mathrm{hi}}}_{\mathscr Y_{\alpha,K,r}}.

\end{align}","status":"unverified"}

