        \limsup_{n \to \infty}\Exp{\exp\left(s_n\frac{Y_n(C,x)}{\sqrt{n}}\right)}\leq K <\infty.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.057062+00:00","domain":"probability theory","id":"claim_9ffb0e9378c96ee01aef28e39bdc3b842c1e5e23040f325179c20e0c047ce5f6","kind":"lemma","schema_version":1,"statement":"[Lemma 30 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] There exists a sequence $(x_N,y_N)_{N\in\N}$ such that
\begin{gather}
    \liminf_{N\to\infty}A_N(x_N,y_N)\leq \liminf_{N\to\infty}\E_{x,y} A_N(x,y), \\
    \lim_{N\to\infty}\Delta_N(x_N,y_N)=0, \\
    \lim_{N\to\infty} \mcl D_N(x_N,y_N) = 0. 
