{"assumptions":[],"created_at":"2026-10-27T11:26:52.678424+00:00","domain":"probability theory","id":"claim_a0e3f63449e019cae603edc7cbd0b59665e4982469788af22ddbe942842566b8","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3}, \ref{PEeqAssum-2.4} and \eqref{PETNs-3.01} hold. Let $\tau\in\mathbb{R}$, $T>0$, and let $\mathfrak{B}(\tau)>0$ be a given constant. Then, for every $\zeta\in L^4(\Omega,\mathscr F_\tau;\mathcal H)$ satisfying $\mathbb E[|\zeta|^4+|\partial_z\zeta|^4]\leq\mathfrak B^4(\tau)$,
	\begin{align}
		\lim_{\epsilon\to0}\sup_{\substack{\mathbb E\left[|\zeta|^4+|\partial_z\zeta|^4\right]\leq \mathfrak{B}^4(\tau)}}
		\mathbb E\left[\sup_{t\in[\tau,\tau+T]}
		|v^\epsilon(t,\tau,\zeta)-v^0(t,\tau,\zeta)|^2\right]=0.
	\end{align}
	Consequently, for the admissible moment ball
	\[
	\mathbb B_{4,z}(\mathfrak B(\tau))
	:=
	\left\{\mu\in\mathcal P_{4,z}(H):
	\int_H\bigl(|\zeta|^4+|\partial_z\zeta|^4\bigr)\mu(d\zeta)
	\le\mathfrak B^4(\tau)\right\},
	\]
	and every $t\in[\tau,\tau+T]$,
	\begin{align}
	\lim_{\epsilon\to0}
	\sup_{\mu\in\mathbb B_{4,z}(\mathfrak B(\tau))}
	d_{\mathcal P(H)}
	\bigl(S_\epsilon(t,\tau)\mu,S_0(t,\tau)\mu\bigr)=0.
	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.255664+00:00","domain":"probability theory","id":"claim_a0f281140273d0273ebeea8decce898befc96d428bda4b55ec73c3f373e37dde","kind":"concept","schema_version":1,"statement":"[Thm 39 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] The following hold.
  \begin{itemize}
    \item [$\mathrm{(i)}$]For any $x\in F$, a non-empty open set $U\subsetneq F$ and its complement $A:=F\setminus U$, 
    $g_A^{\alpha}(x,\cdot)$ is $2$-Lipschitz. 
    \item [$\mathrm{(ii)}$]For any $x\in F$, $g^{\alpha}(x,\cdot)$ is a Lipschitz continuous function.
    Moreover, there exists $\g{c}{continuity,1}\in (0,\infty)$ such that
    \begin{align}
      \|g^{\alpha}(x,\cdot)\|_{\Lip^1}\lesssim 
      \g{c}{continuity,1}(1+\alpha^{-1}),\qquad x\in F,\;\alpha\in (0,\infty),
    \end{align}
    and $\g{c}{continuity,1}$ is given by 
    \begin{align}
    \g{c}{continuity,1}=\frac{1}{1-E_{x_0}[e^{-\sigma_{x_0,x_1}}]}  
    \end{align} 
    for any distinct points $x_0,x_1\in F$.
    \item [$\mathrm{(iii)}$]Let $t_0\in (0,\infty]$. Suppose that the heat kernel $p$ satisfies
    \begin{equation*}
      \begin{aligned}
        c_{\rm{LHK}}t^{-\theta_l}\leq p(t,x,x),\quad t\in (0,\infty),\;
        \rm{and}\;\;
         p(t,x,x)\leq c_{\rm{UHK}}t^{-\theta_u},\quad t\in (0,t_0).
      \end{aligned}
    \end{equation*}
    with constants $c_{\rm{LHK}},c_{\rm{UHK}},\theta_u>0$, and $\theta_l\in (0,1)$.
    Then $p(t,x,\cdot)$ is Lipschitz continuous for $t<t_0$, and it holds that
    \begin{align}
       \|p(t,x,\cdot)\|_{\Lip^1}\lesssim \g{c}{continuity,2}(1+t)t^{-\left(\frac{\theta_u-\theta_l}{2}+1\right)},\qquad x\in F,\;t\in (0,t_0),
    \end{align}
    where $\g{c}{continuity,2}=\g{c}{continuity,1}\left( \frac{c_{\rm{UHK}}}{c_{\rm{LHK}}\Gamma(1-\theta_l)} \right)^{1/2}$.
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.065506+00:00","domain":"probability theory","id":"claim_a0f667bba0d65146ebe9b96169192e720cf5ac92f2162fcaa2b2be27930085e7","kind":"concept","schema_version":1,"statement":"[Cor 27 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Assume $\mu_0=\delta_1$ and that $\mu_1\in\mathcal{P}(\mathbb{R}^d)$ has finite first moments.  Set $L(t,\omega,b,c,F)=G(\omega)$, where $G:\Omega\to[0,+\infty)$ is lower semicontinuous. Let
