{"assumptions":[],"created_at":"2026-10-26T19:37:51.454752+00:00","domain":"probability theory","id":"claim_a14c3f3aeda5a2a3e9bb3dca8f938f19a91dfd09a2936deb277513da30e96db3","kind":"definition","schema_version":1,"statement":"[Definition 3 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $(\mathcal{Z}_t)_{0 \leq t \leq T}$ be a given $\mathcal{S}'(\mathbb{R})$-valued stochastic process defined on some probability space $(X, \mathcal{F}, P)$. 
We say that $(\mathcal{Z}_t)_{0 \leq t \leq T}$ satisfies an \textit{Energy Estimate} (EE) if there exist $\kappa_0 >0$, $\omega >0$ such that for every $H \in \mathcal{S}(\mathbb{R})$, any $0 < \delta < \varepsilon < 1/2$ 
and any $0 \leq s < t \leq T$, we have 
\begin{equation} 
\mathbb{E}_P \big[ \big( \mathcal{B}_{s,t}^{\varepsilon}(H) - \mathcal{B}_{s,t}^{\delta}(H)  \big)^2 \big] \leq \kappa_0 \varepsilon^{\omega} (t-s) \| \nabla H \|^2_{L^2(\mathbb{R})}, 
\end{equation}
where, for any $\varepsilon \in (0, 1/2)$, $0 \leq s \leq t \leq T$ and $H \in \mathcal{S}(\mathbb{R})$, 
the process $\mathcal{B}_{s,t}^{\varepsilon}(H)$ is defined as 
\begin{equation} 
\mathcal{B}_{s,t}^{\varepsilon}(H):= \int_s^t \int_{\mathbb{R}} \nabla H (u)  \mathcal{Z}_r \big(\overleftarrow{\iota}^u_{\varepsilon}\big) \mathcal{Z}_r \big( \overrightarrow{\iota}_{\varepsilon}^u \big) \; \dd u \; \dd r,
\end{equation}
and $\overleftarrow{\iota}_{\varepsilon},\,\overrightarrow{\iota}_{\varepsilon}$ 
are the normalised indicator functions 
\begin{align} 
\overleftarrow{\iota}_{\varepsilon}(v):=\frac{1}{ \varepsilon } \mathbbm{1}_{ \{  [- \varepsilon, \; 0)  \}  } (v), \quad \overrightarrow{\iota}_{\varepsilon}(v):=\frac{1}{ \varepsilon } \mathbbm{1}_{ \{  (0, \; \varepsilon ]  \}  } (v)\,,\qquad  v \in \mathbb{R}
\end{align}
while, for $u \in \mathbb{R}$ fixed, and a function $h$, the shifted function $h^{u}$ 
is 
\begin{align} 
 h^{u}(v):=h(v-u)\,,\qquad  \,v \in \mathbb{R}\,.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.851010+00:00","domain":"probability theory","id":"claim_a15060d207907f66179b63c45f05f4f6b1e881c5e0404ffe3411cba6adfdd26b","kind":"theorem","schema_version":1,"statement":"[Proposition 5 of arXiv:2511.11189, 'Sharp asymptotics for the maximal distance from the boundary to the nucleus of a typical P'] For every $t>0$, we have
		\begin{equation}
			\E[\Card(\VOMR)] = (d\kappa_d)^d C_d \sum_{i=0}^{d-1} t^{di} \kappa_d^{i-d+1} \frac{(d-1)!}{i!} e^{-\kappa_d t^d} 
		\end{equation}
		where \(\kappa_d\) is given at \eqref{eq:defkappad}. Therefore,
		\begin{equation}
			\E[\Card(\VOMR)] \underset{t\rightarrow\infty}{\sim} (d\kappa_d)^d C_d t^{d(d-1)} e^{-\kappa_d t^d}
		\end{equation}
		where, denoting by \(\m U_0,...,\m U_d\) $(d+1)$ i.i.d. uniform random variables on the \((d-1)\)-dimensional unit sphere \(\Sp_{\R^d}\) and by \(\Delta_{d}(\m U_0,...,\m U_d) = \Vol_d(\Conv(\m U_0,...,\m U_d))\) the \(d\)-dimensional Lebesgue measure of the \(d\)-dimensional simplex having these random points as vertices,
		\begin{equation}
			C_d = \E\left[ \Delta_{d}(\m U_0,...,\m U_d)  \1_{0\in\Conv(P_{\m U_0^\perp}(\m U_1),... ,P_{\m U_0^\perp}(\m U_d))} \right].
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.850374+00:00","domain":"probability theory","id":"claim_a1520c3b5f6bb0d9100f4929af8aa59b17ed3c7dd6461857399315f2c9927f47","kind":"concept","schema_version":1,"statement":"[Theorem 29 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let $A,~ B \in  \mathcal{M}_{n}(\mathbb{R})$  be symmetric and let $S \in  M_{n,m}$. Then

\begin{enumerate}
\item  if $A \geqm B$, then $S^\top AS \geqm  S^\top BS$;
\item  if $\rank S = m$, then $A \gm B$ implies $S^\top AS \gm  S^\top BS$
\item if $m = n$ and $S \in M_n$ is nonsingular, then $A \gm B $ if and only if $S^\top AS \gm  S^\top BS$;
									$A \geqm B $  if and only if $S^\top AS \geqm  S^\top BS$;
\item  $I_m \gm S^\top S$ (respectively, $I_n\gm SS^\top$) if and only if $S$ is a strict contraction; $I_m \geqm S^\top S$ (respectively, $I_n\geqm SS^\top$) if and only if $S$ is a  contraction;

										\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

