{"assumptions":[],"created_at":"2026-10-26T20:46:26.256072+00:00","domain":"probability theory","id":"claim_a15968b52272354f2323674feb7c3d7a35cc678a2174522c0c84dae1e7958613","kind":"lemma","schema_version":1,"statement":"[Lem 45 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $(F,R,\mu)$ be in $\bbF^{\circ}$.
Fix $\alpha\in (0,1]$. Suppose that there exists a constant $C=C(\alpha)\in (0,\infty)$ such that $\int_F |g^{\alpha}(x,z)-g^{\alpha}(y,z)|^2\mu(dz)\leq CR(x,y)^2$ for any $x,y,z\in F$.
Then it holds that
\begin{align}
  \|(\alpha-\Delta)^2P_th\|_{\Lip^{1}}\leq C^{1/2}t^{-3}\|h\|_{L^2(F,\mu)}, \qquad t\in (0,1],\;h\in L^2(F,\mu).
\end{align}
In particular, we have the following:
\begin{itemize}
  \item [$\rm{(i)}$]If $F$ is compact, then it holds that
  \begin{align}
     \|(\alpha-\Delta)^2P_th\|_{\Lip^{1}}\lesssim \mu(F)^{1/2}\g{c}{continuity,1}\alpha^{-1} t^{-3}\|h\|_{L^2(F,\mu)},
  \end{align}
  for $\alpha,\;t\in (0,1]$ and $h\in L^2(F,\mu)$.
  \item [$\rm{(ii)}$]If $(F,R,\mu)$ satisfies $\rm{(A2)}$, then it holds that
  \begin{align}
    \|(\alpha-\Delta)^2P_th\|_{\Lip^{1}}\lesssim \g{c}{continuity,1} \left[c_{\rm{A2}}\Gamma\left(1-\frac{s_1}{(1+s_0)\theta}\right)\right]^{-1/2}\alpha^{-(1+\frac{s_1}{(1+s_0)\theta})}t^{-3}\|h\|_{L^2(F,\mu)},
  \end{align}
  for $\alpha,\;t\in (0,1]$ and $h\in L^2(F,\mu)$.
  \item [$\rm{(iii)}$]If $(F,R,\mu)$ satisfies $\rm{(A3)}$, then it holds that
  \begin{align}
     \|(\alpha-\Delta)^2P_th\|_{\Lip^{1}}\lesssim \g{c}{continuity,1} \left[c_{\rm{A3}}\Gamma\left(1-\frac{s_1}{(1+s_0)\theta}\right)\right]^{-1/2}\alpha^{-(1+\frac{s_1}{(1+s_0)\Theta})}t^{-3}\|h\|_{L^2(F,\mu)}, 
  \end{align}
  for $\alpha,\;t\in (0,1]$ and $h\in L^2(F,\mu)$. Here, $\Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)}$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:11:11.693217+00:00","domain":"probability theory","id":"claim_a15ec6093f22a55c5b5406ca6aae0dcab3396a85f326623f43e763f410736331","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2609.00645, 'Global persistence of nearly radial concentrated vortices in a bounded domain'] Let $\mathbf a_*\in D$ be a strict local minimum point of $H$, and choose
$\rho>0$ such that
\begin{equation}
  B_\rho(\mathbf a_*)\Subset D,
\end{equation}
and
\begin{equation}
  H(\mathbf b)>H(\mathbf a_*)
  \quad
  \bigl(
  \mathbf b\in\overline{B_\rho(\mathbf a_*)}
  \setminus\{\mathbf a_*\}
  \bigr).
\end{equation}
Fix $\kappa,M,R>0$.  Then there exist positive constants
$C$, $\eta_0$, and $\varepsilon_0$, depending only on
$D,\mathbf a_*,\rho,\kappa,M$, and $R$, such that the following holds.

For every $0<\varepsilon<\varepsilon_0$, let
$\mathbf a_\varepsilon\in B_\rho(\mathbf a_*)$, and let
$\omega_{\varepsilon,0}\in L^\infty(D)$ be nonnegative and satisfy
\[
  \int_D\omega_{\varepsilon,0}\,\mathrm d\mathbf x=\kappa,
  \qquad
  \|\omega_{\varepsilon,0}\|_\infty\leq M\varepsilon^{-2},
  \qquad
  \operatorname{supp}\omega_{\varepsilon,0}
  \subset B_{R\varepsilon}(\mathbf a_\varepsilon).
\]
Let $\omega_{\varepsilon,t}$, $t\in\mathbb R$, be the corresponding Yudovich
solution of (equation eq:euler-intro of the paper).  If
\begin{equation}
  \eta_{\varepsilon,0}
  :=\mathcal D(\omega_{\varepsilon,0})
  +\kappa^2[H(\mathbf a_\varepsilon)-H(\mathbf a_*)]
  +\varepsilon
  \leq\eta_0,
\end{equation}
then, for every $t\in\mathbb R$,
\begin{equation}
  \mathsf C(\omega_{\varepsilon,t})\subset B_\rho(\mathbf a_*)
\end{equation}
and
\begin{equation}
  \mathcal D(\omega_{\varepsilon,t})
  +\kappa^2\sup_{\mathbf b\in\mathsf C(\omega_{\varepsilon,t})}
  [H(\mathbf b)-H(\mathbf a_*)]
  \leq C\eta_{\varepsilon,0}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:56:36.592269+00:00","domain":"probability theory","id":"claim_a15ed236f8f05bff08ad3924b295747093c685ce2fd27cafab3a86f5690f94ec","kind":"concept","schema_version":1,"statement":"[Lemma WPD-WIEJDUHFJ-HUD of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Suppose that $m$ and $n$ are two non-negative integers. Then, there exists a bounded function $\mathfrak{f}\left( t \right)$ on $\left[ 0,T \right]$ such that
