{"assumptions":[],"created_at":"2026-10-27T21:01:39.504322+00:00","domain":"probability theory","id":"claim_a4e8cfcdd83337439c9d3c9b193500d12193e20ec1eb8025b78b356ba81d2fa4","kind":"theorem","schema_version":1,"statement":"[Proposition prop:comparing_moments of arXiv:2607.22480, 'Distinguishability threshold for random geometric graphs'] Let $\boldsymbol{u}_i(s)$ be random variables sampled according to the \hyperref[setup:star]{Setup ($\star$)}{}. Let $g_i$ be a $\mathcal{N}(0, 1/d)$ truncated above $z_p/\sqrt{d}$ if $si\in E(H)$ and below $z_p/\sqrt{d}$ if $si\notin E(H)$, where $z_p=\Phi^{-1}(1-p)$.
\begin{enumerate}[label=(\roman*)]
    \item 
    We then have
    \begin{equation}
        \mathbb{E}\big[\boldsymbol{u}_i(s)\big]=\mathbb{E}[g_i]+\lambda_{si}(z_p-\lambda_{si})\langle \pi_{s-1} (\boldsymbol{v}_i), \pi_{s-1} (\boldsymbol{v}_s)\rangle + \widetilde O\Big(\frac{n}{d^{3/2}}\Big).
    \end{equation} In particular, since $\mathbb{E}[g_i]=\frac{\lambda_{si}}{\sqrt{d}}$, we have $\mathbb{E}[\boldsymbol{u}_i(s)]=\frac{\lambda_{si}}{\sqrt{d}}+ \widetilde O\Big(\frac{|\lambda_{si}|\sqrt{n}}{d}\Big)$.
    \item 
    We also have \begin{equation}
    \big|\mathbb{E}[g_i^2]-\mathbb{E}[\boldsymbol{u}_i(s)^2]\big|\leq \widetilde O\Big(\frac{|\lambda_{si}|\sqrt{n}}{d^{3/2}}\Big), \text{ and so} \Var(\boldsymbol{u}_i(s))=\Big(1+\widetilde O\Big(\frac{\sqrt{n}}{\sqrt{d}}\Big)\Big)\frac{1+\lambda_{si}(z_p-\lambda_{si})}{d}.
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:53:00.814571+00:00","domain":"probability theory","id":"claim_a4f7d27ceae957fa982c3560b19ef76e524c63d1d6df7a79b978854fa0bd8819","kind":"definition","schema_version":1,"statement":"[Definition def:psi of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] For any fixed $i \in I$, corresponding to $M_i,N_i$, and corresponding to the tree $\mathbb T(v;\pi)$ induced by the ray $\pi$, we want to construct a (random) map $\psi_i$ such that $\psi_i(\mathbb T(v;\pi))$ is another (random) tree, defined as follows:
    \begin{itemize}
    \item If $C(e;\pi_{(M_i+1)})=C(e;s_0\rightarrow s_0s_1 \rightarrow \dots \rightarrow s_0s_1\dots s_{M_i+1})=\emptyset$, declare $\psi_i(\mathbb T(v;\pi))=\mathbb T(v;\pi)$.
    \item Otherwise, if $C(e;\pi_{(M_i+1)})\neq \emptyset$, there is an $x \in C(e;\pi_{(M_i+1)})$. Let $p(x)$ be its parent. Note that $x$ is a leaf at height $M_i$ in the tree $\mathbb T(v;\pi_{(M_i+1)})$. Consider the following set of descendants of $x$ in $\mathbb T(v;\pi)$,
    \begin{align*}
    &C((p(x),x);(\pi_{(N_i+1)})^{(M_i)})\\&=C((p(x),x);s_{M_i}\rightarrow s_{M_i}s_{M_i+1}\rightarrow \dots \rightarrow s_{M_i}s_{M_i+1}\dots s_{N_i}s_{N_i+1}).    
    \end{align*}
    If $C((p(x),x);(\pi_{(N_i+1)})^{(M_i)})=\emptyset$ for all such $x$ in $\mathbb T(v;\pi_{(M_i+1)})$, then drop i.i.d. copies of the tree $\mathrm{BP}_{\pi^{(N_i)}}$, independent from $\mathbb T$, from all such leaves $x$ at distance $M_i$ in the tree $\mathbb T(v;\pi_{M_i+1})$. This just means, for each such leaf $x$, we take a copy of the tree $\mathrm{BP}_{\pi^{(N_i)}}$, and identify the root of this tree with $x$ (note that the type $T_x$ of any such leaf $x$ is $s_{M_i+1}=s_{N_i+1}$, so that we are identifying two individuals of the same type, even though they live in independent processes). Declare the resulting tree to be $\psi_i(\mathbb T(v;\pi))$.  
    \item Otherwise, if for some $x \in C(e;\pi_{(M_i+1)})$, $C((p(x),x);(\pi_{(N_i+1)})^{(M_i)})\neq \emptyset$, choose arbitrarily some $y \in C((p(x),x);(\pi_{(N_i+1)})^{(M_i)})$, and let $p(y)$ be the parent of $y$. Note that $T_{p(x)}=s_{N_i}=s_{M_i}=T_{p(y)}$ and $T_{x}=s_{N_i+1}=s_{M_i+1}=T_{y}$. Consider the tree $\mathbb T(y;\pi^{(N_i)})=\mathbb T(y;\pi_{N_i}\rightarrow \pi_{N_i+1}\rightarrow \cdots)$. Take this tree and drop it from $x$ in the tree $\mathbb T(v;\pi_{(M_i+1)})$, i.e., \emph{graft} the root $y$ of $\mathbb T(y;\pi^{(N_i)})$ at $x$ in $\mathbb T(v;\pi_{(M_i+1)})$. Again observe that we are grafting a vertex on another with identical type. Do this procedure for every $x \in C(e;\pi_{(M_i+1)})$, for which $C((p(x),x);(\pi_{(N_i+1)})^{(M_i)})\neq \emptyset$, each time choosing an $y \in C((p(x),x);(\pi_{(N_i+1)})^{(M_i)})$ in some arbitrary fashion. For those $x \in C(e;\pi_{(M_i+1)})$ for which $C((p(x),x);(\pi_{(N_i+1)})^{(M_i)})=\emptyset$, simply drop i.i.d. copies of the tree $\mathrm{BP}_{\pi^{(N_i)}}$ from such $x$ in $\mathbb T(v;\pi_{(M_i+1)})$. Call the resulting tree $\psi_i(\mathbb T(v;\pi))$. 
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.288732+00:00","domain":"probability theory","id":"claim_a4fe7a66447f19974b70fb867f0f666b6f1cb13776f5924a9e416f1e31f64798","kind":"concept","schema_version":1,"statement":"[Proposition prop:results:energyBound of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:invMeasure of the paper). 


