{"assumptions":[],"created_at":"2026-10-27T20:38:36.829054+00:00","domain":"probability theory","id":"claim_a68fc722ed8e80477d93bb2432beb202352757be5d23aaa644cc8de491637cb0","kind":"theorem","schema_version":1,"statement":"[Proposition prop:kernel-mmd of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Let $X,X'$ be independent with law $\mu$ and let $Y,Y'$ be independent with law $\nu$, all with level-$N$ square-integrable signatures.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.25em]
\item
\begin{equation}
\mathbb{E}_\mu[k_N(X,X')]=\norm{\mathbb{E}_\mu\mathrm{Sig}^{(N)}}^2,
\end{equation}
and the diagonal excess
\begin{equation}
\mathbb{E}_\mu[k_N(X,X)]-\mathbb{E}_\mu[k_N(X,X')]=
\sum_{|w|\le N}\Var_\mu\inner{\mathrm{Sig}(X)}{w}

\end{equation}
is exactly the total coordinate defect mass from (thm:geo-defect of the paper)\textup{(ii)}.
\item
\begin{equation}
\operatorname{MMD}_N(\mu,\nu)^2=\norm{\mathbb{E}_\mu\mathrm{Sig}^{(N)}-\mathbb{E}_\nu\mathrm{Sig}^{(N)}}^2.
\end{equation}
Thus the level-$N$ signature MMD is the Euclidean distance between truncated expected signatures and separates laws up to their level-$N$ expected-signature coordinates.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:02:11.270367+00:00","domain":"probability theory","id":"claim_a693219d0b34b3c90083b6ccc7d7fb70f7f4024d426cf28b19735bd727af2695","kind":"theorem","schema_version":1,"statement":"[Theorem eq:mclt1 of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] Let $c_1, c_2 \in \mathbb{R}$ and $p \neq 7/8$ be such that $\lambda^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) < - \frac{1}{2}$ almost surely. 
 \begin{itemize}
    \item[i)] The following central limit theorem holds - 
    \begin{align}  &\sqrt{n}\left\{\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_n - \boldsymbol{\Gamma}^{(p)}\right)\right\} \stackrel{d}{\to} N\left(0, {\Sigma}^{(1)}_{c_1,c_2,p}\right),
    \end{align}
    where
    {\begin{align}
        {\Sigma}^{(1)}_{c_1,c_2,p} := \left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^{\top}\left\{\int_{0}^{\infty}e^{t\left(\boldsymbol{J}_p\left(\boldsymbol{\Gamma}^{(p)}\right)+\frac{1}{2}\boldsymbol{I}\right)}\sigma\left(\boldsymbol{\Gamma}^{(p)}\right)e^{t\left(\boldsymbol{J}_p\left(\boldsymbol{\Gamma}^{(p)}\right)+\frac{1}{2}\boldsymbol{I}\right)^{\top}} dt\right\}\nonumber\\\times\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right).
    \end{align}}
    \item[ii)] For some absolute constant $C > 0$, almost surely  
    \begin{align}  &\limsup_{n \to \infty}\sqrt{\frac{n}{2\log\log n}}\left\|\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_n - \boldsymbol{\Gamma}^{(p)}\right)\right\| \leq C,
    \end{align}
    and, almost surely, \begin{align}  &\limsup_{n \to \infty}\sqrt{\frac{n}{2\log\log n}}\left\{\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_n - \boldsymbol{\Gamma}^{(p)}\right)\right\} \\ = - &\liminf_{n \to \infty}\sqrt{\frac{n}{2\log\log n}}\left\{\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_n - \boldsymbol{\Gamma}^{(p)}\right)\right\} = \sqrt{{\Sigma}^{(1)}_{c_1,0,p}}, \nonumber
    \end{align}
    and, also, almost surely, \begin{align}  &\limsup_{n \to \infty}\sqrt{\frac{n}{2\log\log n}}\left\{\left(c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_n - \boldsymbol{\Gamma}^{(p)}\right)\right\} \\ = - &\liminf_{n \to \infty}\sqrt{\frac{n}{2\log\log n}}\left\{\left(c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_n - \boldsymbol{\Gamma}^{(p)}\right)\right\} = \sqrt{{\Sigma}^{(1)}_{0,c_2,p}}. \nonumber
    \end{align}
    \item[iii)] The following quadratic strong law holds almost surely -  
    \begin{align}  &\lim_{n \to \infty} \frac{1}{\log n}\sum_{k=2}^n\left\{\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)^\top\left(\boldsymbol{\Gamma}_k - \boldsymbol{\Gamma}^{(p)}\right)\right. \\ &\hspace{3cm}\times\left.\left(\boldsymbol{\Gamma}_k - \boldsymbol{\Gamma}^{(p)}\right)^{\top}\left(c_1\boldsymbol{\nu}^{(1)}_p\left(\boldsymbol{\Gamma}^{(p)}\right) + c_2\boldsymbol{\nu}^{(2)}_p\left(\boldsymbol{\Gamma}^{(p)}\right)\right)\right\} = {\Sigma}^{(1)}_{c_1,c_2,p}. \nonumber
    \end{align}
    \end{itemize}","status":"unverified"}

