{"assumptions":[],"created_at":"2026-10-27T11:32:18.864111+00:00","domain":"probability theory","id":"claim_a6ac313c3ab2e3437b465d1ad600821b95c7c1156c40c98896b10e1929636a88","kind":"theorem","schema_version":1,"statement":"[Proposition 54 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\mf A$ be an HOTM and $\mu$ and $\nu$ be $\mf A$-valued premeasures such that $\q{\mu}=\q{\nu}$. 
  \begin{enumerate}
  \item[(i)]  $\mu\dotleq\nu$ if and only if $\as[\mf A]{\mu}\dotleq\as[\mf A]{\nu}$.
  \item[(ii)] Suppose $\mu$ and $\nu$ are measures. If $\mu\dotleq\nu$ and $\nu\dotleq\mu$, then $\mu=\nu$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:25:44.969042+00:00","domain":"probability theory","id":"claim_a6ac5e03bd4612fd380cd53f2afa6008a83791f7e20003e7443cd59880ca453c","kind":"lemma","schema_version":1,"statement":"[Lemma 8 (Fourth moments for the cross-polytope) of arXiv:2605.11451, '2605.11451'] Let $X\sim \nu_{1,n}$ be uniform on $B_1^n$ and let $i\neq j$. Then
\begin{align}
 \E X_i^4
 &=\frac{24}{(n+1)(n+2)(n+3)(n+4)},\notag\\
 \E X_i^2X_j^2
 &=\frac{4}{(n+1)(n+2)(n+3)(n+4)}.
\end{align}
Consequently, for every $\theta\in\sphere$,
\begin{equation}
 \E\langle\theta,X\rangle^4
 =
 3\,\E X_1^2X_2^2+\bigl(\E X_1^4-3\,\E X_1^2X_2^2\bigr)\sum_{i=1}^n\theta_i^4,
\end{equation}
and the coefficient $\E X_1^4-3\,\E X_1^2X_2^2$ is strictly positive.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.615112+00:00","domain":"probability theory","id":"claim_a6b9c4c19b126c03935d1afc6e103b19145debe60a9d4bca422120300dad6a3e","kind":"theorem","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.22644, '2604.22644'] Let the scale function defined for $k \ge 1$ be
\begin{align}
    S(k;p) = \sum_{i=0}^{k-1} \prod_{j=1}^{i} \frac{1 - r^j p}{r^j p}
\end{align}
where the empty product for $i=0$ is defined as $1$. Then, the probability that the first excursion $e_1$ does not reach $N$ is given by:
\begin{align}
    P(e_1 \text{ does not reach } N) = 1 - \int_0^1 \frac{p}{S(N;p)} dp.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:00.763485+00:00","domain":"probability theory","id":"claim_a6c5add227785d19a4f1c5c178907e0e398bbfee89594055cbd50ec595393501","kind":"theorem","schema_version":1,"statement":"[Theorem 5 (Finite 2D $\rho$-variation) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] Let $H > 1/4$ and $\rho = 1/(2H)$. Then
\begin{equation}

V_\rho(R_{H,\lambda})
\le C(H,\lambda,T)
:= V_\rho(R_H)
  + K_1(H)\,\lambda^{2H\rho}\,T^{2\rho-2}
  + \frac{K_2(H,\lambda)}{\lambda^{2H\rho}}
< \infty,
\end{equation}
where $K_1(H)$ and $K_2(H,\lambda)$ are explicit constants, and
$C(H,\lambda,T) \to C_{\rm fBm}(H,T)$ as $\lambda \to 0^+$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:36.727881+00:00","domain":"probability theory","id":"claim_a6c6760c2edf99c609c278726b7cc25ce23832a5feefb1d030b7a7e29207eda3","kind":"concept","schema_version":1,"statement":"[Theorem 5 of arXiv:2511.14740, 'Marking and re-marking'] Let $\mathbf X$ be a random variable taking values in $\mathbb N^c$, $\mathsf A \in [0,1]^{c\times d}$ with columns $|\mathbf a_i| \leq 1$, and let $\mathbf Y = \mathsf A \circ X$ be the multinomial re-marking of $\mathbf X$ with parameters $\mathsf A$. Then we have the following.
\begin{enumerate}
\item  $\mathbb E \mathbf Y = \mathsf A \,\mathbb E \mathbf X$.
\item $\DispM( \mathbf Y) = \mathsf A \DispM(\mathbf X)\, \mathsf A^\top$.
\item $\Phi_{\mathbf Y}(\mathbf t) = \Phi_{\mathbf X}(\mathsf A^\top \mathbf t)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:24:20.990159+00:00","domain":"probability theory","id":"claim_a6d772f9a9fa82b983c2d3f7ba68478e19d74c20c398fceb7ca04d92c958965b","kind":"lemma","schema_version":1,"statement":"[Lemma lem:modulation_ineq of arXiv:2509.02074, 'On the Kolmogorov-Feller weak law of large numbers for the Fr\'{e}chet mean on non-compact'] Suppose that $(M,d)$ is a non-compact symmetric space and Condition (C) holds.
\begin{enumerate}
    \item[(a)] If, for each $1\le i\le n$, $\mathbb{P}_{X_{i}}$ has finite variance, i.e., $\mathbb{E}[d^2(X_{i}, \mu)] < \infty$, then 
     \begin{equation}
        \mathbb{E}[d^2(\mu_n, \mu)]\le \frac{1}{n^2}\sum_{i=1}^{n}\mathbb{E}[d^2(X_i, \mu)].
     \end{equation}

    \item[(b)] In particular, if $X_i$'s are identically distributed and $\mathbb{P}_{X}$ has finite variance, then
    \begin{equation}
        \mathbb{E}[d^2(\mu_n, \mu)]\le \frac{1}{n}\mathbb{E}[d^2(X_1, \mu)].
    \end{equation}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:20:55.609647+00:00","domain":"probability theory","id":"claim_a6d98622c41eca89078bfaa74f82d5f6821a7464265b8e05ce34368cc61857a0","kind":"lemma","schema_version":1,"statement":"[Lemma residual-bound of arXiv:2411.07737, 'On Asymptotic Behavior of Extinction Moment of Critical Bisexual Branching Process in Rand'] There is a constant $c > 0$ such that, for all $n \geq 1$,
