{"assumptions":[],"created_at":"2026-10-27T22:52:32.341984+00:00","domain":"probability theory","id":"claim_aa036fc41bfabd30d7a15019a46a3495166887afcac82d22264bd164e8462755","kind":"concept","schema_version":1,"statement":"[Cor bertini cor of arXiv:2609.04023, 'Characterizing Contractions and Weighted Blowdowns'] {MR360616}}]

