{"assumptions":[],"created_at":"2026-10-27T15:07:17.292191+00:00","domain":"probability theory","id":"claim_aabbd768b2e10ef76af6b07fb6209944ee064496841a11c9f073128f3e457189","kind":"theorem","schema_version":1,"statement":"[Theorem incrementalstrong of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] {AvedCos24game}}]

Assume that ${\mathbb {X}}$ satisfies (equation C of the paper) and 
\begin{description}
\item[\namedlabel{S1}{S1}]\emph{(Polynomial decay)} There is a
  $\delta>0$ such that for all $\epsilon>0$ there is a $C = C(\epsilon)$ for
  which
\begin{equation}\notag
\sup_k{\mathbb {P}}\left(\abs{X^{(k)}_m/m}>\epsilon\right)<\frac{C}{m^\delta}.
\end{equation}
\item[\namedlabel{S2}{S2}] \emph{(Uniform domination)} There is a random variable $X_*$ and $\gamma>0$ such  that ${\mathbb {E}}(\left\vert X_*\right\vert^{2 +\gamma })<\infty$ and for all $x \in {\mathbb {R}}$
\begin{equation}\notag
\sup_{k,m}{\mathbb {P}}(|X^{(k)}_m/m|)>x)\leq {\mathbb {P}}(X_*>x). \end{equation}  
\end{description}

Let $X_t = X_t(\mathfrak{X},\tau)$ be given by  (equation cooling-general-tau of the paper). Then,
\begin{equation}
{\mathbb {P}}\prt{\lim_{t\to\infty}X_t/t= 0} = 1.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:27:25.800725+00:00","domain":"probability theory","id":"claim_aabfa70788c8b78041c3eff82d9c629537b34e49d3fab1af6776445c22192293","kind":"theorem","schema_version":1,"statement":"[Theorem thm:sharp-rigidity of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] Let $g_k = P^k g_0$ with $g_0 \perp \mathbf{1}$ and $c_2 = \langle g_0, \phi_2 \rangle_\pi \neq 0$. Assume the spectral separation condition $\lambda_2 > \lambda_3$. Define $R_0 := \sum_{i=3}^n |c_i|^2 = \|g_0 - c_2 \phi_2\|_\pi^2$.

For any $\delta \in (0, 1/2)$, define the \emph{rigidity time}
\begin{equation}
T_{\mathrm{rigid}}(\delta) := \min\{\, k \ge 0 : \alpha_2(k) \ge 1 - \delta \,\}.
\end{equation}
Then
\begin{equation}
L(\delta) \;\le\; T_{\mathrm{rigid}}(\delta) \;\le\; L(\delta) + 1,
\end{equation}
where
\begin{equation}
L(\delta) := \frac{\log\!\bigl(R_0 / (|c_2|^2 \delta)\bigr)}{2 \log(\lambda_2 / \lambda_3)}.
\end{equation}","status":"unverified"}

