{"assumptions":[],"created_at":"2026-10-27T21:01:39.421359+00:00","domain":"probability theory","id":"claim_ab6c09e6641ddefc0be08ba7877151f4b7fc6a31852c14ce4970612a95b6b46c","kind":"definition","schema_version":1,"statement":"[Definition traffic freeness of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] We say that $\mathbf{A}_{N}^{(1)},\cdots,\mathbf{A}_{N}^{(L)}$ are \emph{asymptotically traffic independent} whenever $\mathbf{A}_{N}:=\mathbf{A}_{N}^{(1)}\cup\cdots\cup\mathbf{A}_{N}^{(L)}$ converges in traffic distribution and for any *-test graph $T=(V,E,\gamma,\epsilon)$,
        \begin{equation}
            \tau_{N}\left(T(\mathbf{A}_{1}^{(N)},\cdots,\mathbf{A}_{L}^{(N)})\right)\underset{N\rightarrow\infty}{\longrightarrow}\sum_{\substack{\pi\in\mathcal{P}(V) \\ \mathrm{s.t.}\mathcal{GCC}(T^{\pi}) \\ \text{is a tree}}}\prod_{S\in\mathcal{CC}(T^{\pi})}\lim_{N\rightarrow\infty}\tau_{N}^{0}\left(S(\mathbf{A}_{N}^{(\ell(S))})\right),
        \end{equation}
    where $\ell(S)$ is the index of the family of the labels of the colored component $S$. Since the injective traces in the product can also be written in terms of (non-injective) traces, asymptotic traffic independence entirely characterizes the limiting traffic distribution of $\mathbf{A}_{N}=\mathbf{A}_{N}^{(1)}\cup\cdots\cup\mathbf{A}_{N}^{(L)}$ in terms of the traffic distributions of the $\mathbf{A}_{N}^{(l)}$'s.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:47:22.250455+00:00","domain":"probability theory","id":"claim_ab7156b3f8f5ed8d6ba6a6256db92acb82659f3e4828e40b349937e223c895ab","kind":"concept","schema_version":1,"statement":"[Lem 51 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $A,D$ satisfy \eqref{eq:costanti}. Also let $q$ be a real number and $k \ge 0$ be an integer satisfying 
		\begin{equation}

			q \in [N^{A\delta-1}, \varepsilon_0], \quad k \le \ell_0 (q) + 5.
		\end{equation}

		\noindent Further let $q' \ge 0$ satisfy
		\begin{flalign}

			q' \in [q - 2^k N^{(D+2)\delta-1}, q - 2^{k}  N^{(D-2) \delta-1}]; \qquad \mathsf{t} = q'^{-1} k 2^k N^{1+6A\delta}.
		\end{flalign} 

		\noindent Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu \in \mathcal P^+$ (recall Definition \ref{def:P+}) and assume that, w.o.p. under $\mu$, 
		\begin{flalign}

			\begin{aligned} 
				& H_0 (w) \le \mathcal{H}_{q} (w) + N^{\delta-1}, \qquad  \text{for each $w \in \bigcup_{\ell=1}^{k+1} \mathcal{A}_{\ell}^{q}$ }. 
			\end{aligned}
		\end{flalign}

		\noindent Then we have w.o.p. that
		\begin{flalign}

			H_t (z) \le \mathcal{H}_{q'} (z), \qquad \text{for each $z \in \bigcup_{\ell = 1}^k \mathcal{A}_{\ell}^{q'}$ and $t \in [\mathsf{t}, N^5]$}.
		\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:02:08.116577+00:00","domain":"probability theory","id":"claim_ab719bbff76ab96cdd58eb12a272791bc6d9a46c6d3140276ade301116f537f0","kind":"concept","schema_version":1,"statement":"[Proposition 5 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] Assume $k>2$.  For all sufficiently small $\eps>0$, the form $\omega_\eps$ defined by \eqref{gt:eq:approximate-metric} extends to a smooth K\"ahler metric on $\widetilde X$, and
\begin{equation}
  [\omega_\eps]=\pi^*[\omega]-\eps^2[E].
\end{equation}
Moreover:
\begin{enumerate}[label=\textup{(\roman*)}]
\item on the exterior region, \(\omega_\eps=\omega\);
\item on the outer annulus, for every fixed $j\ge0$,
\begin{equation}
  \abs{\nabla^j\left[
  \eps^2\gamma_2\psi_k(\eps^{-2}d^2)
  \right]}
  \le C_j\eps^{2k-2}r_\eps^{4-2k-j};
\end{equation}
\item on the inner annulus, potentials for $\eps^{-2}\omega_\eps$ and $\omega_k$ in the rescaled coordinates are respectively
\begin{align*}
  F&=|Z|^2+|W|^2
      +\eps^{-2}\Phi(\eps Z,\eps W)
      +\psi_k(\eps^{-2}d^2),\\
  F_{\mathrm{prod}}&=|Z|^2+|W|^2+\psi_k(|Z|^2),
\end{align*}
and, on the rescaled coordinate balls specified above,
\begin{equation}
  \abs{\nabla_{Z,W}^j(F-F_{\mathrm{prod}})}
  \le C_j\eps^{j-2}d^{3-j}
  \qquad(2\le j\le6).
\end{equation}
In particular, $\eps^{-2}\omega_\eps$ is uniformly equivalent to $\omega_k$ there;
\item on the blowup region, in the coordinates
\eqref{gt:eq:blowup-coordinates},
\[
  \eps^{-2}\omega_\eps=\omega_k+O(\eps)
\]
in $C^\ell$ on compact subsets of each blowup chart, for every fixed $\ell$.  In particular, $\eps^{-2}\omega_\eps$ converges locally smoothly to $\omega_k$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.340639+00:00","domain":"probability theory","id":"claim_ab7236edd0383819aebe5baed95c562e13d808876b71f7ac4b7cba38e2424c00","kind":"lemma","schema_version":1,"statement":"[Lemma lem:lyap:symLemma of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $(\mu,\gamma, \mathbf{X})$ be a solution to the $\kappa$-MLFE{} on $[0, T]$ with potentials $(U, W)$ and initial condition $\lambda \in \mathcal{Q}_{\kappa, d}$. Let $f : \ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}^d$ be a measurable function such that for almost every $s \in \ensuremath{\mathbb{R}}_+$ we have
\begin{equation}
    \mathbb E\Big[\big|f\big(X_0(s), X_v(s)\big)\big|^2 + \big|f\big(X_v(s), X_0(s)\big)\big|^2 \Big] < \infty.

\end{equation}
Then the following properties hold:
\begin{enumerate}
    \item For $u \in \{0, \ldots, \kappa\}$, let $\bar{u} = 0$ when $u = 0$ and $\bar{u} = 1$ otherwise. Given any $v \in \{1, \ldots, \kappa\}$ and $u \in \{0, v\}$, for almost every $s \in \ensuremath{\mathbb{R}}_+$ we have 
    \begin{equation}
        \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{u} \log \mu_s\big(\mathbf{X}(s)\big)\Big] = \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{\bar{u}} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big].

    \end{equation}
    \item For all $v \in \{1, \ldots, \kappa\}$ and $s \in \ensuremath{\mathbb{R}}_+$ we have
    \begin{equation}
        \mathbb E\Big[f\big(X_0(s), X_v(s)\big) \nabla_{0} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big] = \mathbb E\Big[f\big(X_v(s), X_0(s)\big) \nabla_{1} \log \bar{\mu}_s\big(X_0(s), X_v(s)\big)\Big].

    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.757394+00:00","domain":"probability theory","id":"claim_ab76c8f859ae4f80d493e4f1e5566cdbe4bac66886b153e19a0571200dd5263a","kind":"lemma","schema_version":1,"statement":"[Lemma lem:massive-massless-continuous-correction of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Fix a disk $U\Subset\mathbb R^2$ and $m_0>0$.  Write $\Delta_U$ for the
Dirichlet Laplacian on $U$ and set $L_0^U:=-(2\pi)^{-1}\Delta_U$.  Consider
a centered Gaussian field $Z_U$ with covariance operator
\begin{equation}
 \Cov(Z_U)=C_U^{(m_0)}
 :=(L_0^U)^{-1}-(L_0^U+m_0^2)^{-1}
 =m_0^2(L_0^U)^{-1}
   (L_0^U+m_0^2)^{-1}.

\end{equation}
Then $Z_U$ has a continuous version.  More precisely, for every $K\Subset U$
there is $C_{K,U,m_0}<\infty$ such that
\begin{equation}
 \mathbb E|Z_U(z)-Z_U(z')|^2
 \le C_{K,U,m_0}r^2
 \left(1+\log\frac1r\right),
 \qquad
 z,z'\in K,\quad 0<r:=|z-z'|\le\frac12.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:44.955632+00:00","domain":"probability theory","id":"claim_ab7878b4be96b605d77ac6dc12ae0602a3c7e8700cabdeb92d6ebaa0bc6e5877","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] (\cite{Gordon85,Slep62})
 Let $X_{i}$ and $Y_{i}$, $1\leq i\leq n$, be two centered Gaussian processes which satisfy the following inequalities for all choices of indices
\begin{enumerate}
\item $\mE(X_{i}^2)=\mE(Y_{i}^2)$
\item $\mE(X_{i}X_{l})\leq \mE(Y_{i}Y_{l}), i\neq l$.
\end{enumerate}
 Then
\begin{equation*}
\mE(\min_{i} X_{i})\leq \mE(\min_i Y_{i}) \quad  \Longleftrightarrow \quad \mE(\max_{i} X_{i})\geq \mE(\max_i Y_{i}).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:33:21.477716+00:00","domain":"probability theory","id":"claim_ab87d2815d3334421edcefd8ffd319ce5ebce47b63d7188067c668b5fc5528a9","kind":"definition","schema_version":1,"statement":"[Definition def:moment-constraints of arXiv:2606.21391, 'Extreme points and faces in the moment problem'] Let $\mathbf{p}\colon X\to\mathbb{R}^d$ be measurable with respect to $\mathcal{F}$ and let
\begin{align*}
P\!_\mathrm{a.i.}  & \textstyle 
:=\{ \mu\in P\!_\mathrm{fin} : 
\text{$\mu$ is concentrated on a finite subset $\{x_1,\dots,x_k\}\subset X$}\\
& \textstyle \hspace{\widthof{$:=\{$}}
\text{such that $\mathbf{p}(x_1),\dots,\mathbf{p}(x_k)$ are affinely independent}\,\}.
\end{align*}
We refer to the measures in $P\!_\mathrm{a.i.}$ as finitely atomic measures having the 
affine independence property. Let $C\subset\mathbb{R}^d$ be a  convex subset and let
\begin{align*}
G_\mathrm{fin}(C) & \textstyle
:= \{\mu\in P\!_\mathrm{fin} : \int\mathbf{p}\mathrm{d}\mu\in C\},\\

G_\mathrm{a.i.}(C) & \textstyle
:= \{\mu\in P\!_\mathrm{a.i.} : \int\mathbf{p}\mathrm{d}\mu\in C\}.
\end{align*}
Let $Q\subset P$ be a convex set of probability measures. Denoting the components of 
$\mathbf{p}=(p_1,\ldots,p_d)$ by $p_i\colon X\to\mathbb{R}$, $i=1,\ldots,d$, we define
\begin{align*}
Q^\mathbf{p} & \textstyle 
:= \{\mu\in Q : \text{$p_i$ is $\mu$-integrable $\forall i=1,\dots,d$}\,\},\\

G(C) & \textstyle
:= \{\mu\in Q^\mathbf{p} : \int\mathbf{p}\mathrm{d}\mu\in C\}.
\end{align*}
We abbreviate $G_\mathrm{fin}(\mathbf{q}):=G_\mathrm{fin}(\{\mathbf{q}\})$, etc., for singletons 
$\{\mathbf{q}\}$ with elements $\mathbf{q}\in\mathbb{R}^d$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:33:11.958749+00:00","domain":"probability theory","id":"claim_ab898deeb30f3e10d31152295698cabbb0ad055130fbec7df44ce906cfff0d7d","kind":"concept","schema_version":1,"statement":"[Problem Universal lower-orthant thresholds of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[problem]{prob:threshold-vectors}
