        +3\inttm\int_{\sO} |u|^2 \grad u \cdot [\grad\Delta u- \grad(u^3-u)]\dx\ds\\
        &\phantom{= } + \sum_{n \geq 1} \inttm \int_{\sO}|u|^2 u \,\psi_n(u,\grad u) \dx \dWsn + \frac{3}{2} \inttm\int_{\sO} |u|^2 \|\psi(u,\grad u)\|_{\ell^2}^2 \dx \ds. \nonumber
