        d(w,\mathcal{M}_{\mathbb{S}^n}) := \frac{\inf \{\|w - v \|_{H^{\gamma} (\mathbb{S}^n) } : \mathcal{P}v \in \mathcal{M}_{\mathbb{R}^n} \}}{\|w\|_{ H^{\gamma} (\mathbb{S}^n)  }}.
