\end{equation*}
Moreover, for every $\varepsilon\in(0,1)$, the same underlying class satisfies
\begin{equation*}
\bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^\tau=[\Theta_\tau B]_\tau\in \mathfrak C^{1-\varepsilon}(\Delta^2_{\tau};B_\alpha).
