{"assumptions":[],"created_at":"2026-10-26T19:17:42.313341+00:00","domain":"probability theory","id":"claim_b263f3586f0e0edff40729a215bb8d4deab57fa5b648c03bbd38f2e29ec5b353","kind":"lemma","schema_version":1,"statement":"[Lemma 34 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] There exists $C(d)>0$ such that the following holds. Let $V,v : [0,1] \times \R^d \to \R^d$ be random vector fields such that $V \in L^1_\omega\mathcal{C}^0_t\mathcal{C}^1_x$ and $v \in \mathcal{C}^0([0,1] \times \R^d)$. Let $\mathcal{F}_t$ be a filtration such that for all $t \in [0,1]$, $V|_{[0,t] \times \R^d}, v|_{[0,t] \times \R^d}$ are $\mathcal{F}_t$-measurable. Let $h \in (0,1]$ and suppose that for all $t \in [0,1]$, 
    \begin{equation}

    v|_{[t+h,1] \times \R^d} \indep \mathcal{F}_t \quad\text{and}\quad \E v|_{[h,1] \times \R^d} =0.
    \end{equation}
    For a fixed $y \in \R^d,$ let $Z_t$ be the (random, almost surely uniquely defined) solution to 
    \[\begin{cases}\dot Z_t = V(t,Z_t),\\ Z_0 =y.\end{cases}\]
    We split
    \begin{equation}

        \int_0^t v(r,Z_r+x)\,dr = M(t,x) + F(t,x),
    \end{equation}
    with
    \begin{equation}

        F(t,x):= \sum_{\ell=2}^{\infty} \E\Big[\int_{(\ell-1) h}^{\ell h \land t} v(r,Z_r+x)\,dr \,\Big|\, \mathcal{F}_{(\ell-2)h}\Big],
    \end{equation}
    where $\int_a^b f(r)\,dr$ is taken to be zero when $b<a$. Then $M$ and $F$ obey the following estimates: for all $\nu \in [0,1)$ there exists a constant $C(\nu)>0$ such that for all $p \geq 2$, sigma algebras $\mathcal{G} \subseteq \mathcal{F}_0$, $\lambda \in [0,1],$ and $n \in \N$,
    \begin{align}

        \|M\|_{\mathcal{C}^{1/2}_t \mathcal{C}^0_x L^p_\omega} &\leq  C h^{1/2} \|v\|_{L^p_\omega \mathcal{C}^0_{t,x}} +  C h^{1/2} \min\big(p^{1/2} \|v\|_{L^p_\omega \mathcal{C}^0_{t,x}}, p^{\lambda \lor 1/2} \sup_{q \geq 2} q^{-\lambda} \|v\|_{L^q_\omega \mathcal{C}^0_{t,x}}\big),
        \\

        \|F\|_{\mathcal{C}^1_t \mathcal{C}^0_x L^p_\omega} &\leq C h \|\nabla v\|_{L^{2}_\omega \mathcal{C}^0_{t,x}}\Big(  \big\|V - \E[V \mid \mathcal{G}]\big\|_{L^{p}_\omega \mathcal{C}^0_{t,x}} \lor h^{\frac{\nu}{1-\nu}} \|V\|_{L^{\frac{p}{1-\nu}}_\omega \mathcal{C}^0_t \mathcal{C}^\nu_z}^{\frac{1}{1-\nu}} \Big),\\
          \|M\|_{L^p_\omega \mathcal{C}^1_t \mathcal{C}^n_x }&\leq C \|\nabla^n v\|_{L^p_\omega \mathcal{C}^0_{t,x}},
          \\\|F\|_{L^p_\omega \mathcal{C}^1_t \mathcal{C}^n_x }&\leq C \|\nabla^n v\|_{L^p_\omega \mathcal{C}^0_{t,x}}.

    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:18:27.579516+00:00","domain":"probability theory","id":"claim_b26af5f3503d925d5904299e56ce8eedf8ecb7145c296e4e13cf62271ba72d86","kind":"theorem","schema_version":1,"statement":"[Proposition 7 (Spectral form of many-to-one) of arXiv:2608.15987, 'Threshold cascades of interacting diffusions on unimodular random trees: a conditional bra'] Let $F:D\times D\to[0,\infty)$ be a type-pair edge functional and set $(A_F)_{d,d'}:=q(d')\,F(d,d')$. Then
\begin{equation}
\E\Big[\sum_{|v|=n}\prod_{e\in o\to v}F(e)\Big]=m_*^n\,q^\top A_F^n\one,
\end{equation}
whose exponential growth rate is $\rho(m_*A_F)$. In particular, with $F=p$, the annealed growth rate of the expected failed population is $\rho(M)$, where $M=m_*A_p$ is the mean matrix \eqref{eq:M}. The scalar identity $\E[\sum_{|v|=n}\prod_eF(e)]=(m_*\E_{q\otimes q}[F])^n$ holds if and only if $d'\mapsto\E_{d\sim q}[F(d,d')]$ is constant on $\supp q$ (e.g.\ $m=1$, or product-form $F(d,d')=a(d)b(d')$ with $q$-constant $\E_q[a]b(\cdot)$); in general $\rho(M)$ and $m_*\E_{q\otimes q}[p]$ are not comparable in a fixed direction.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:09:49.785966+00:00","domain":"probability theory","id":"claim_b270cfd633db74b6ef3cf61126c461d6bd812ab2e1e20d7982b8145ec1af72d6","kind":"theorem","schema_version":1,"statement":"[Thm 20 of arXiv:2609.03054, 'The classes of bivariate Schur and Herglotz matrix-valued rational functions: realizations'] A scalar valued symmetric polynomial $g(z,\zeta) \in {\mathbb R}[z,\zeta]$ of degree $(n,n)$ has no roots in ${\mathbb D}^2$ if and only if $g$ has a determinantal representation
\begin{equation} g(z,\zeta ) = g(0,0) \det \left( I - \begin{pmatrix} A_1 & A_2\cr A_2 & A_1\end{pmatrix} \begin{pmatrix} zI & 0\cr 0 & \zeta I \end{pmatrix} \right)  \end{equation}
with 

a real contraction 
\begin{equation} 
    \begin{pmatrix} A_1 & A_2\cr A_2 & A_1\end{pmatrix}.
\end{equation} In addition, $g(z,\zeta)$ has no roots in $\overline{\mathbb D}^2$ if and only if $g$ has a determinantal representation \eqref{dr2} with \eqref{contrDetBidiskReal} a real strict contraction. In both cases the matrices $A_1$ and $A_2$ can be chosen to be of size at most $2n\times 2n$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.974366+00:00","domain":"probability theory","id":"claim_b2732244a217a926d807a9e98beb068aff19797162d9fe1d7d832655256611e6","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For $N\geqslant1$ and $\mu \in (0,1]$ we write, for any  $W^{{\boldsymbol{\tau}}} \in {\mcb{C}}[{\boldsymbol{\tau}}]$, 
\begin{equs}
K_{N,\mu}^{\otimes\text{\scriptsize{$\mathfrak{l}$}} (\text{\scriptsize{${\boldsymbol{\tau}}$}})}    &W^{{\boldsymbol{\tau}}}( t_{\boldsymbol{\tau}},s^{\boldsymbol{\tau}})\eqdef (K_{N,\mu}\otimes\dots\otimes K_{N,\mu})*W^{{\boldsymbol{\tau}}}\text{$( t_{\boldsymbol{\tau}},s^{\boldsymbol{\tau}})$}
\end{equs}
for the convolution of $\text{$\text{{\Large $\kappa$}}$}_{\eps,\mu}^{{\boldsymbol{\tau}}}$ with $K_{N,\mu}$ at the level of all its $\mathfrak{l}({\boldsymbol{\tau}})$ arguments $t_{\boldsymbol{\tau}}$ and $s^{\boldsymbol{\tau}}$.

We also endow $\text{${\mcb{C}}$}[\text{{${\boldsymbol{\tau}}$}}]$ with the norm 
\begin{equs}   
\text{$\nnorm{W^{\text{\scriptsize{${\boldsymbol{\tau}}$}}}}_{N,\mu}$}&\eqdef\|\text{$K_{N,\mu}^{\otimes \text{\scriptsize{$\mathfrak{l}$}}(\text{\scriptsize{${\boldsymbol{\tau}}$}})}$}W^{\text{\scriptsize{${\boldsymbol{\tau}}$}}}\|_{L^\infty_{t_{\tau_1}}L^1_{t_{\tau_2}}\cdots L^1_{t_{\tau_{p(\text{\tiny{${\boldsymbol{\tau}}$}})}}}((-\infty,1]^{p(\text{\tiny{${\boldsymbol{\tau}}$}})})
L^1_{s^{\text{\tiny{${\boldsymbol{\tau}}$}}}}(\R^{\mathfrak{s}(\text{\tiny{${\boldsymbol{\tau}}$}})})}\\
&\equiv \sup_{t_{\tau_1}\leqslant1}
\int_{(-\infty,1]^{p(\text{\tiny{${\boldsymbol{\tau}}$}})-1}\times\R^{\text{\tiny{$\mathfrak{s}$}}(\text{\tiny{${\boldsymbol{\tau}}$}})}}
| K_{N,\mu}^{\otimes \text{\scriptsize{$\mathfrak{l}$}}(\text{\scriptsize{${\boldsymbol{\tau}}$}})}    \text{{\Large $\kappa$}}_{\eps,\mu}^{\text{\scriptsize{${\boldsymbol{\tau}}$}}}( t_{\text{\scriptsize{${\boldsymbol{\tau}}$}}},s^{\text{\scriptsize{${\boldsymbol{\tau}}$}}})|\text{$\mathrm{d}$} s^{\text{\scriptsize{${\boldsymbol{\tau}}$}}}\mathrm{d} t_{\tau_2}\cdots\mathrm{d} t_{\tau_{{p({\boldsymbol{\tau}})}}}
\,.
