\begin{equation} 
\begin{split}
  \varphi_{n+1}(r(n+1))> 1, \quad \forall n\geq 0, \quad \mbox{if } r(0)>0;\\
  \varphi_{n+1}(r(n+1))< 1, \quad \forall n\geq 0, \quad \mbox{if } r(0)<0.
\end{split}

\end{equation}
where $\varphi$ is as in (equation e:defphi of the paper). Then, $\mathbb E^x[T_A]<\infty$ if both the following conditions hold:
\begin{enumerate} \setlength{\itemsep}{0.75em}
  \item $\sup_n \varphi_n(r(n))<\infty$ and $\sup_n r(n)<\infty$, and
  \item $\inf_{n\geq 1}|\varphi_n(r(n))-1|>0$.
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:42:55.318381+00:00","domain":"probability theory","id":"claim_b3249c609ebc1340829d0a5e4433db6344f11712a148d796b1e814117332ab59","kind":"lemma","schema_version":1,"statement":"[Lem 25 (Three spread bounds) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $p \in (0,1)$, $\nu > 0$, and suppose $Y_{p,\nu} \in \SG(1,a)$. Then
\begin{align}
    \nu &\le \frac{1}{\sqrt{p(1-p)}},
    \\
    (1-p)\,\nu &\le a\ell + \sqrt{2\ell}.

\end{align}
For $p < 1/2$ one also has the quadratic bound
\begin{align}
    \nu \le a\beta_p + \sqrt{a^2\beta_p^2 + \frac{2\beta_p}{1 - 2p}}.

\end{align}
At $p = 1/2$ the last expression is interpreted by continuity, via \eqref{eqn:lhopital}, where it equals $2$; the bound holds there as well, reducing to \eqref{eqn:sgvariance}.","status":"unverified"}

