{"assumptions":[],"created_at":"2026-10-27T18:51:26.589624+00:00","domain":"probability theory","id":"claim_b675103ee2eb1a6f9d7ef1af780e92f11a921748d22ad628867e0723a4670d1c","kind":"definition","schema_version":1,"statement":"[Definition def:complex-SaS of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] A \emph{complex isotropic S$\alpha$S random measure}
$\widetilde{M}_\alpha$ on $\mathbb{R}$ with Lebesgue control measure
is a complex random measure such that, for every
$f \in L^\alpha(\mathbb{R},\mathbb{C})$:
\begin{equation}

\mathbb{E}\!\left[\exp\!\left(
i\,\mathrm{Re}\int_\mathbb{R} f(\xi)\,d\widetilde{M}_\alpha(\xi)
\right)\right]
= \exp\!\left(-c_\alpha\int_\mathbb{R}|f(\xi)|^\alpha\,d\xi\right),
\end{equation}
where
\begin{equation}

c_\alpha
:= \frac{1}{2\pi}\int_0^{2\pi}|\cos\theta|^\alpha\,d\theta
= \frac{\Gamma\!\left(\frac{\alpha+1}{2}\right)}
{\sqrt{\pi}\;\Gamma\!\left(\frac{\alpha}{2}+1\right)}.
\end{equation}
The measure $\widetilde{M}_\alpha$ is \emph{isotropic}: for every
$\phi \in \mathbb{R}$, $e^{i\phi}\widetilde{M}_\alpha(\cdot)
\overset{d}{=} \widetilde{M}_\alpha(\cdot)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:43:16.154020+00:00","domain":"probability theory","id":"claim_b675e1c8cf70ec856eb5be1431af5e6d6147920f0170a66235f1158b11bce556","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2604.13819, 'Convolution, cumulants and infinitesimal generators in the formal power series ring'] \begin{enumerate}[\rm (1)]
\item (\textit{Law of large numbers for $\boxplus^t$})\ For $t\in \mathbb{R}^\times$, let us consider $A\in U$ such that $\kappa_1^t(A)=\lambda$. Then
\begin{align*}
D_{1/m}\bigl[A^{\boxplus^t m}\bigr] (z) \to B_\lambda^{(t)}(z), \qquad m\to \infty.
\end{align*}
\item (\textit{Central limit theorem for $\boxplus^t$})\ For $t\in \mathbb{R}^\times$, let us consider $A\in U$ such that $\kappa_1^t(A)=0$ and $\kappa_2^t(A)=1$. Then
\begin{align*}
D_{1/\sqrt{m}} \bigl[A^{\boxplus^t m} \bigr] (z)  \to H^{(t)}(z), \qquad m \to\infty.
\end{align*} 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:25:44.969447+00:00","domain":"probability theory","id":"claim_b679596acd04494544329c9c5003c9790d6cf1c57c2dbafdf5a68bce84b08398","kind":"theorem","schema_version":1,"statement":"[Proposition 13 (Fourier representation of the endpoint constants) of arXiv:2605.11451, '2605.11451'] For every $1\le p<\infty$ and every $k\ge1$,
\begin{equation}
 b_{p,k}
 =
