{"assumptions":[],"created_at":"2026-10-26T19:21:10.900154+00:00","domain":"probability theory","id":"claim_b69182dbc5559f2951196b60e3efb3f7b47ae56a477180547b86f12ba4cc8400","kind":"definition","schema_version":1,"statement":"[Definition 30 of arXiv:2601.16377, '2601.16377'] Let $n \geq 1$ and $h_1,\ldots,h_n \in [H]$. The \emph{$n$-point correlator} is defined as \emph{joint cumulant} of the $n$ random variables $\Delta
G_{h_1}(z_1),\ldots,\Delta G_{h_n}(z_n)$.
\begin{equation*}
\begin{split}
W_{n;h_1,\ldots,h_n}(z_1,\ldots,z_n) & = \E^{(\textnormal{c})}\big[\Delta
G_{h_1}(z_1),\ldots,\Delta G_{h_n}(z_n)\big] \\
& =\partial_{s_1}\cdots\partial_{s_n}\log \E\Bigg[ \exp\bigg(\sum_{i=1}^n s_i \Delta G_{h_i}(z_i)\bigg)\Bigg]\Bigg|_{s_1 = \cdots = s_n = 0}.
\end{split}
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.462130+00:00","domain":"probability theory","id":"claim_b691ee803d2ec2d9ee6ea0faef69a0ad79eff421692747ae127c436b253d2054","kind":"concept","schema_version":1,"statement":"[Proposition 4 of arXiv:2606.28678, '2606.28678'] For the SOU process defined in \eqref{eq:SOU.process}, we have
\begin{equation}
\mathfrak{Y}_t \mid \{\mathfrak{Y}_0 = Y\} \sim \mathcal{SN}_{d\times d}\big(M + e^{-t}(Y-M),\sqrt{1-e^{-2t}}\,\Psi,\sqrt{1-e^{-2t}}\,\Sigma\big), \qquad t > 0,
\end{equation}
and
\begin{equation}
\mathfrak{Y}_{\infty} \sim \mathcal{SN}_{d\times d}(M,\Psi,\Sigma).
\end{equation}
In particular, let $(\mathcal{P}^{\mathrm{SOU}}_t)_{t\geq0}$ be the transition semigroup with kernel $P_t(Y, \, \rd Z)$, so that, for every bounded Borel measurable function $h:\mathcal{S}^d\to\R$,
\[
(\mathcal{P}^{\mathrm{SOU}}_t h)(Y) \leqdef \int_{\mathcal{S}^d}h(Z)P_t(Y, \, \rd Z) = \EE\big[h(\mathfrak{Y}_t)\mid \mathfrak{Y}_0 = Y\big].
\]
For $\mathfrak{G}$ a $d\times d$ random matrix such that all its entries are independent standard normals, the above shows
\begin{equation}
\mathcal{P}^{\mathrm{SOU}}_t h(Y) = \EE\bigg[h\bigg(M + e^{-t}(Y-M) + \sqrt{1-e^{-2t}} \, \frac{\Psi^{1/2}\mathfrak{G}\Sigma^{1/2} + \Sigma^{1/2}\mathfrak{G}^{\top}\Psi^{1/2}}{2}\bigg)\bigg].
\end{equation}
Moreover, given a probability measure $\mu$ on $\mathcal{S}^d$, the pushed-forward measure $\mu\mathcal{P}^{\mathrm{SOU}}_t$ is defined by
\[
(\mu\mathcal{P}^{\mathrm{SOU}}_t)(A) \leqdef \int_{\mathcal{S}^d}P_t(Y,A) \, \mu(\rd Y), \qquad A\subseteq\mathcal{S}^d \text{ Borel}.
\]
Hence, for $\gamma_{M,\Psi,\Sigma} \leqdef \mathcal{SN}_{d\times d}(M,\Psi,\Sigma)$, we have the invariance
\begin{equation}
\gamma_{M,\Psi,\Sigma}\mathcal{P}^{\mathrm{SOU}}_t = \gamma_{M,\Psi,\Sigma}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:36:23.136726+00:00","domain":"probability theory","id":"claim_b69386c78470da6cd1ba41dcda567b1211ad6a17a7803220d14944fa5645d3fe","kind":"concept","schema_version":1,"statement":"[Theorem thm:applications of arXiv:2507.01236, 'Disintegration theorem for multifunctions, \\ with applications to empirical Wasserstein d'] Suppose that $(\mathfrak{X},\mu)$ is asymptotically disintegrable with rate $(\epsilon,r)$. For $n$ sufficiently large, let $X_1,\dots,X_n$ be i.i.d.\ samples from $\mu$ with empirical measure $\hat{\mu}:=\frac{1}{n}\sum_{i=1}^n\delta_{X_i}$. Then:
    \begin{enumerate}
        \item[{\rm (i)}] For any $p\in[1,\infty)$, with probability at least $1-\epsilon(n)$, one has
        \begin{equation}
        W_p(\mu,\hat{\mu}_n)\leq r(n),
        \end{equation}
        where $W_p$ is the Wasserstein $p$-distance.  (See Proposition (prop:wasserstein of the paper) for details.)
        \item[{\rm (ii)}] With probability at least $1-\epsilon(n)$, one has
        \begin{equation}
        \bigg|\int\!f(x)\,\mu(dx)-\int\!f(x)\,\hat{\mu}_n(dx)\bigg|\leq r(n)\cdot\frac{1}{n}\sum_{i=1}^n\|f\|_{\text{Lip},B(X_i,r(n))}
        \end{equation}
        for any Lipschitz function $f:\mathfrak{X}\rightarrow\mathbb{R}$.  (See Proposition (prop:averagecase of the paper) for details.)
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:20:15.583798+00:00","domain":"probability theory","id":"claim_b69ad6b5e0479cc7f7d4ab28e4602fb0d6a7f47de83d17628da3ca5776200b2a","kind":"concept","schema_version":1,"statement":"[Conjecture conjUniversal of arXiv:2609.00777, 'Universal murmuration and Hecke augmentation'] Let $\mathcal F$ be a self-dual family of primitive $\operatorname{GL}_2$ forms, with root numbers in $\{-1,1\}$, ordered by analytic conductor $C(f)$, and write
\begin{equation*}
\mathcal F_{X,Y}=\{f\in\mathcal F:X\leq C(f)\leq X+Y\}.
\end{equation*}
Let $Y=Y(X)>0$ be a family-specific regime in which $|\mathcal F_{X,Y}|\to\infty$.
Assume that $\mathcal F$ is specified by fixed local and archimedean conditions, with no selection based on Fourier coefficients or root signs.
Let $\varepsilon(f)$ denote the root number.  At an unramified prime $p$, write the local factor in unitary normalization as
\begin{equation*}
L_p(s,f)=\bigl(1-\alpha_{f,p}p^{-s}\bigr)^{-1}
\bigl(1-\beta_{f,p}p^{-s}\bigr)^{-1}
\end{equation*}
and set
\begin{equation*}
\lambda_{f,k}(p)=\sum_{j=0}^{k}
\alpha_{f,p}^{k-j}\beta_{f,p}^{j}.
\end{equation*}
At a ramified prime, let $\lambda_{f,k}(p)$ be the coefficient of $p^{-s}$ in the unitary local symmetric-power Euler factor.
Assume that a continuous function $G_{\mathcal F}:(0,\infty)\to\mathbb R$ gives the prime-coefficient profile: for every compact set $K\Subset(0,\infty)$,
\begin{equation*}
\sqrt X\,
\mathbb E_{\mathcal F_{X,Y}}
\bigl[\varepsilon(f)\lambda_{f,1}(p)\bigr]
=
G_{\mathcal F}\left(\frac pX\right)+o_{\mathcal F,K}(1)
\end{equation*}
locally uniformly along primes $p=p(X)$ with $p/X\in K$.
Then, for every fixed integer $k\geq2$ and every compact set $K\Subset(0,\infty)$,
\begin{equation*}
\sqrt X\,
\mathbb E_{\mathcal F_{X,Y}}
\bigl[\varepsilon(f)\lambda_{f,k}(p)\bigr]
=
G_{\mathcal F}\left(\frac{p^k}{X}\right)+o_{\mathcal F,k,K}(1)
\end{equation*}
as $X\to\infty$ along primes $p=p(X)$ satisfying $p^k/X\in K$.
Thus the same function $G_{\mathcal F}$ applies to every fixed power. (Stated as a conjecture by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.636631+00:00","domain":"probability theory","id":"claim_b69c04ae4ec0d64e3bad283b55050885f92e09759047db5899adc510b809ddf5","kind":"definition","schema_version":1,"statement":"[Defi def0 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] A continuous random dynamical system on X over a metric dynamical system $(\Omega,\mathcal{F},P,{\{\theta_t\}}_{t \in \mathbb{R}})$ is a measurable mapping 
		\begin{align*}
			\varphi:\mathbb{R}^{+} \times \Omega \times X \rightarrow X,~~(t,\omega,x) \mapsto \varphi(t,\omega,x),
		\end{align*}
		satisfying for $P$-a.e.$~\omega \in \Omega:$\par
		$(i)~\varphi(0,\omega)=id~\mathrm{on}~X;$\par
		$(ii)~\varphi(t+s,\omega)=\varphi(t,\theta_s\omega)  \varphi(s,\omega)$ for all $t,s\in \mathbb{R}^+;$\par
		$(iii)~\varphi(t,\omega):X \to X$ is continuous.\newline
		A family of maps satisfyng $(ii)$ ia called a cocycle.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.287193+00:00","domain":"probability theory","id":"claim_b6a2fd6141a00e01e860a6fd17796e407b6c4561d5a4ef3a696ed44234447dc6","kind":"lemma","schema_version":1,"statement":"[Lemma expectations of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $(X_t)$ solve the Auffinger--Chen SDE with $X_0=0$ and set $M_t:=\partial_x\Phi_\zeta(t,X_t)$.
		Let $0\le s<t\le 1$.
		\begin{enumerate}[label=(\roman*)]
			\item
			\begin{equation}
				\mathbb{E}[(X_t-X_s)M_s]
				=\mathbb{E}[M_s^2]\int_s^t\zeta([0,u])\,\xi''(u)\,\mathrm{d} u.
			\end{equation}

			\item
			\begin{equation}
				\mathbb{E}[(M_t-M_s)\,X_s]=0.
			\end{equation}

			\item
			\begin{equation}
				\mathbb{E}[X_t M_t]
				=\xi'(t)-\int_{[0,1]}\xi'\bigl(\min(t,u)\bigr)\,\mathbb{E}[M_u^2]\;\zeta(\mathrm{d} u).
			\end{equation}

			Consequently, for all $s,t\in [0,1]$,
			\begin{equation}
				\mathbb{E}[X_s\, M_t]
				=\begin{cases}
					\mathbb{E}[X_s M_s], & s\le t,\\[4pt]
					\mathbb{E}[X_t M_t]+\mathbb{E}[M_t^2]\displaystyle\int_t^s\zeta([0,u])\,\xi''(u)\,\mathrm{d} u, & s\ge t.
				\end{cases}
			\end{equation}

			\item Suppose that $\mathbb{E}[\partial_x\Phi_\zeta(t,X_t)^2]=t$  for $\zeta$-a.e. $t\in [0,1]$. Suppose $\zeta((s,t))=0$ and $s,t\in\mathrm{supp}(\zeta)$. Then
			\begin{equation}
				\mathbb{E}[(M_t-M_s)(X_t-X_s)]
				=\bigl(\xi'(t)-\xi'(s)\bigr)\int_s^1\zeta([0,u])\,\mathrm{d} u.
			\end{equation}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.385575+00:00","domain":"probability theory","id":"claim_b6a32f6b414265373124b82a8da82a7cf50626ee87e73b27dca0f2e564772bf9","kind":"theorem","schema_version":1,"statement":"[Proposition prop_concentration of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] Let~$(S,\mathcal{S})$ be a measurable space and~$n \in \N$. Let~$\sigma$ be a probability measure on~$(S,\mathcal{S})$ and~$\p$ be the probability on~$(S^n,\mathcal{S}^n)$ given by the {$n$-fold} product measure of~$\sigma$. Set $X_1, \dots, X_n$ to be independent random elements taking values in~$S$ and let $X_i'$ be an independent copy of $X_i$. Set~$h: S^n \to\R$ to be a measurable function on $(S^n,\mathcal{S}^n,\p)$ and fix
    \[Z:=h(X_1,\dots,X_n), \ \ \text{and} \ \ Z^{(i)}:=h(X_1,\dots,X_{i-1},X_{i}',X_{i+1},\dots,X_n).\]
    Assume that there exist~$\kappa > 0$ and measurable sets~$E_1,\ldots, E_n \in \mathcal{S}^n$ such that, $\p$-a.s., for each $i \in \{1,\ldots,n\}$,
    \begin{equation}            Z^{(i)}-Z \le \kappa \cdot \mathbbm{1}_{E_i}.
    \end{equation}
	Then, 
        \begin{equation} 
            \mathrm{Var}Z \leq \kappa^2 \sum_{i=1}^n\p(E_i).
        \end{equation}
    Furthermore, for any~$\alpha > 0$ such that $\E[e^{\alpha Z}]< +\infty$, one has
    \begin{equation} 
       \E\left[\exp\left\{\alpha (\E[Z]-Z)\right\} \right] \le \E \left[ \exp \left\{ 2 \alpha^2 \kappa^2\sum_{i=1}^n \mathbbm{1}_{E_i}\right\} \right] 
    \end{equation}
    and, if~$\alpha > 0$ is such that $\E[e^{\alpha Z}]< +\infty$, then for all $\lambda \in(0,\alpha)$,
    \begin{equation} 
        \E\left[\exp\left\{\lambda (Z-\E[Z])\right\} \right] \le \E \left[ \exp \left\{ 2\lambda^2 \kappa^2 e^{\alpha\kappa} \sum_{i=1}^n \mathbbm{1}_{E_i}\right\} \right].
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.532930+00:00","domain":"probability theory","id":"claim_b6a460c4cf739f2cdbe798ff3c1c9e8fb8afbbc9560528fe3468dbc37cc3bb17","kind":"concept","schema_version":1,"statement":"[Thm lotka-volterra-main of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Suppose that $\max_{i=1,\dots,m} r_i(\mu) > 0$ for all $\mu \in P_{inv}(\mathcal{M}_0)$. Then coexistence (persistence) occurs in (equation eq:lotka-vol of the paper). Specifically,
