{"assumptions":[],"created_at":"2026-10-27T20:35:05.828932+00:00","domain":"probability theory","id":"claim_b92bdfeb5ea19a5461f1f814fe2709cfda20861fad6cdc02bf3a7985f42b0973","kind":"definition","schema_version":1,"statement":"[Defn integ1 of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] Suppose that $(\Omega,{\mathscr{B}},{\mathbb{P}})$ is a complete probability space endowed with the $\sigma$-algebra generated by $(B^{i}(t)\otimes W^{Q,i}(t))_{t\in[0,T],i=1\ldots,N}$ and that is still denoted as $({\mathscr{F}}_{t})_{t\in[0,T]}$. We say that an ${\mathscr{F}}(U)$-valued predictable process $\lambda^{i}(t)$, $t\in[0,T]$, is a weak solution to 

\begin{align}
&{\rm d}\lambda^{i}(t)= {\mathbb R}(X^i(t),\lambda^i(t),\mu^{N}(t))\,{\rm d} t+
\sqrt{2\sigma_\lambda}\,\Pi_{\lambda^i(t)}\,{\rm d} W^{Q,i}(t)   
\end{align}
if  for all $x^{\ast}\in ({\mathscr{F}}(U))^{\ast}$

\begin{align}
\nm{\lambda^{i}(t),x^{\ast}}=\nm{\lambda^{i}(0),x^{\ast}}+ \int_{0}^{t}\nm{{\mathbb R}(X^i(s),\lambda^i(s),\mu^{N}(s)),x^{\ast}}{\rm d} s+ \sqrt{2\sigma}T_{{\mathbbm{1}}_{i}}^{t}x^{\ast}
\end{align}
where ${\mathbbm{1}}_{i}\in {\mathcal H}_{Q}(L({\mathscr{F}}(U),{\mathscr{F}}(U)))$ denotes the projector operator $\Pi_{\lambda^{i}}$. Moreover, we say that $(\lambda^{i}(t))_{t\in[0,T]}$ is a strong solution if 
\begin{align}
\lambda^{i}(t)=\lambda^{i}(0)+ \int_{0}^{t}{\mathbb R}(X^i(s),\lambda^i(s),\mu^{N}(s)){\rm d} s+ \sqrt{2\sigma}\int_{0}^{t}\Pi_{\lambda^{i}(s)}{\rm d} s \hskip 0,4cm \text{${\mathbb{P}}$-a.s..}
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:59:45.008346+00:00","domain":"probability theory","id":"claim_b93a32107a46e8512291c0db2d7f89cb8cc675e1670458649ebf3486a238a134","kind":"lemma","schema_version":1,"statement":"[Lemma keyI of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Given a fixed $s_0\in\mathbb{R}$, assume the scaling $(\tilde{\mu}_{n,N},\tilde\sigma_{n,N})$ satisfies the order restriction in (equation restriction of recaling of the paper). Then under the assumption that $\frac{N}{n}\rightarrow\gamma\in(0,1)$, we have:
