{"assumptions":[],"created_at":"2026-10-27T17:42:08.458583+00:00","domain":"probability theory","id":"claim_ba0284c53233cffd459d8b71b728315e19e974aaabaa960430b5cb3b2ca3aa48","kind":"theorem","schema_version":1,"statement":"[Theorem MH2p1 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] Suppose there are two types of stations with intensities $\lambda_1, \lambda_2$ and speeds $v_1> v_2$. Let $\lambda_1+\lambda_2=\lambda$. Then we have:

\begin{enumerate}[(i).]
\item  The pure handover frequencies are 
\begin{equation}
     \Lambda_l= \frac{4v_l\sqrt{\lambda}}{\pi}\left(\frac{\lambda_l}{\lambda}\right)^2, \text{ for }l=1,2.
\end{equation}
\item   The mixed handover frequencies satisfies the relations $\Lambda^{(1)}_{1,2}=\Lambda^{(2)}_{2,1}$ and $\Lambda^{(2)}_{1,2}=\Lambda^{(1)}_{2,1}$.
\item  For $k=1,2$,
\begin{align}
\Lambda^{(k)}_{2,1}&= 4\lambda_1\lambda_2v_1v_2\int_{0}^{\infty}\left[\int_0^{h_1}\int_{t^*}^\infty e^{-\lambda\pi\hat h^2_k(t, h_1, h_2)}  \,{\rm d}t \, {\rm d}h_2  +\int_{h_1}^{\infty}\int_{0}^{\infty} e^{-\lambda\pi\hat h^2_k(t, h_1, h_2)}\,{\rm d}t \, {\rm d}h_2 \right] {\rm d}h_1 ,
\end{align}
\end{enumerate}

where $\hat h^2_k$ as in ((eq:HO_distance1 of the paper)), being a function of $t, h_1, h_2$.

\iffalse
\[
\hat h_k^2= v_1^2 \left(\frac{v_2^2 t+ (-1)^k \Delta^{\frac{1}{2}}}{v_1^2-v_2^2}\right)^2\!\! +h_1^2 \text{ and } \Delta= v_1^2v_2^2 t^2- (h_1^2-h_2^2)(v_1^2-v_2^2).
\]

The last two expressions are functions of $t, h_1, h_2$, determined in ((eq:HO_distance1 of the paper)) and ((eq:Delta of the paper)), respectively.
\fi","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:57:20.685380+00:00","domain":"probability theory","id":"claim_ba03b12e4b4d67f1263450b6fce9fb5a98c124db0941e454388e99311e318807","kind":"theorem","schema_version":1,"statement":"[Proposition prop:concentHtheo2 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] There exists  $0<C_\star<C_2$ such that if $t\in [0,1)$  and $x\in \mathbb{R}^d$ satisfy \begin{equation}
1-t^2\leq C_\star^{-1}\log(\epsilon^{-1})^{-C_\star} \text{ and } \|tx\|^2\leq 1-C_2^{-1}\log(\epsilon^{-1}+1)^{-K},
\end{equation}
then for all $i,j\in \{1,...,d\}$ we have
    $$\int H(y,x)_i^2 dp^{t,x}(y)\leq C(1-t^2)$$
    and 
    $$\int \left(H(y,x)^{\otimes2}_{ij}- \int H(z,x)^{\otimes2}_{ij}dp^{t,x}(z)\right)^2dp^{t,x}(y)\leq C(1-t^2)^{2}.$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:58:01.565479+00:00","domain":"probability theory","id":"claim_ba081f0c8af462cc82d690128742e71a9219317420d0382536fdb2672b2e9d83","kind":"definition","schema_version":1,"statement":"[Definition 2 (Regular right edge) of arXiv:2608.27307, '2608.27307'] We call $E_*\in\mb D_0$ a regular right edge of $\bnu$ if
