{"assumptions":[],"created_at":"2026-10-26T19:18:27.572429+00:00","domain":"probability theory","id":"claim_bb265b22d86b86c39498eebf2aa23f1303861b5f3378ae3d9ef5c29070f4c6d5","kind":"lemma","schema_version":1,"statement":"[Lem 17 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$. There exists $C>0$ such that the following holds. For every $G$ subgraph of $\mathbb Z^d$, every $\beta\in [\beta_c/2,\beta_c]$, every $J\in (\mathbb R^+)^{E(G)}$ which satisfies $J_{st}\leq \beta$ for every $st\in E(G)$, every $x,y\in V(G)$, and every $zw,uv\in E(G)$,
\begin{equation}
	\langle \sigma_x\sigma_y ; \sigma_z \sigma_w ; \sigma_{u}\sigma_v \rangle_{G,J}\leq C\Big(\langle \sigma_x\sigma_z\rangle_{G,\beta} \langle \sigma_w\sigma_u\rangle_{G,\beta}\langle \sigma_v\sigma_y\rangle_{G,\beta}+\langle \sigma_y\sigma_z\rangle_{G,\beta} \langle \sigma_w\sigma_u\rangle_{G,\beta}\langle \sigma_v\sigma_x\rangle_{G,\beta}\Big).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:17:13.075395+00:00","domain":"probability theory","id":"claim_bb2772fa1de5df953e22a35f04f61cdb8ef4c0846c9b453446b798dff53db1c8","kind":"concept","schema_version":1,"statement":"[Proposition prop:bound-T_n-non-optimal of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Assume that all the variances in $\Lambda_n$ are unitary and all the other variances vanish. Then there exist some small enough universal constant $c_{1,2}>0$ such that
 	\begin{equation}
 		\mathbf{P}\Big[ \mathbf{T}_{\Lambda_n}\leq \frac{c_1}{n} \Big] \leq c_2\exp(-n^{c_2}). 
 	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.227946+00:00","domain":"probability theory","id":"claim_bb27925cba3d30e5f30295c318396a9fac54a2a1e00250270f78585a318e461b","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_upper and lower for F-KPP of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] \begin{enumerate}[label= (\alph*)]
    \item Let $f, \phi, u_\phi$ be as in Proposition (Bramson-psi-estimate-for-one-sided-f of the paper) and $0<\alpha<\beta<\infty$. Then, there exist $t_0\ge 1, C_1, C_2 >0$ such that for all $t \ge t_0$ and $z \in [\alpha t, \beta t]$,
    \begin{equation}
        C_1\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t} \le u_\phi(t,z+\sqrt 2t)\le C_2\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t}.
    \end{equation}
The upper bound in the above holds for $\phi$ with $f\in C_c^+(\mathbb{R})$ as well. 
    \item Let $0< \alpha < \beta < \infty$. Then, there exists $t_0 \geq 1$, $K>0$ large enough and constants $C_1, C_2 >0$ such that for all $t\geq t_0$ and $z\in [\alpha t, \beta t]$,
    \begin{equation}
        C_1\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t} \le u_M(t, \sqrt{2}t + z - K ) - u_M(t, \sqrt{2}t + z + K )\le C_2\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t}.
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.868069+00:00","domain":"probability theory","id":"claim_bb336c3d85a6258d29a12c1937314d497364e70bcc1c29c0be2f1de8df3952b9","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] As $n\to\infty$,
\begin{equation}
Z_n=\sum_{j\ge n+1}2^j\exp\big(-\eee^{j^2-n^2}/2\big)\eta_j=o\big(\exp\big(-\eee^{2n}/2\big)\big)\quad\text{{\rm a.s.}}
