{"assumptions":[],"created_at":"2026-10-27T20:09:43.680649+00:00","domain":"probability theory","id":"claim_bdbd42315640d3f9e9a0e020702e1c5d39552705945fef6d1391620f9d69eab6","kind":"lemma","schema_version":1,"statement":"[Lemma l:BL-limits of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] Let  $\tilde{\mathcal{P}}$  be a marked point process on $\mathbb{R}^d\times\mathbb{K}$.  Let $\xi : \mathbb{R}^d \times \mathbb{K} \times \hat\mathcal{N}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ be an
real-valued score function, and assume that $\xi$ is \textnormal{BL}-localizing on all
finite windows of $\tilde{\mathcal{P}}$ as in~(equation Lp-stab of the paper) for a given $p \in \mathbb{N}$
(tacitly assuming the existence of the uniformly bounded correlation function $\rho^{(p)}(\bk{x}{1}{p})$).

\begin{enumerate}[wide,label=(\roman*),labelindent=0pt]
\item 
For a given vector  $\bk x1p \in(\mathbb{R}^d)^p$, 
the  random vectors  $\bk{\xi^{(r)}}1p(\tilde{x}, \tilde{\mathcal{P}})$ 
(under the Palm distributions ${\mathbb{P}}_{\bk x1p}$ of $\tilde{\mathcal{P}}$) 
converge in the $d_{\textnormal{BL}, \bk{x}{1}{p}}$ metric (and hence in law) as $r\to\infty$ to a probability distribution on $\mathbb{R}^p$, represented here by the random vector  $\Upsilon_{\bk x1p}=(\Upsilon_{\bk x1p}[1],\ldots,\Upsilon_{\bk x1p}[p])\in \mathbb{R}^p$, i.e.,
$$\bk{\xi^{(r)}}1p(\tilde{x}, \tilde{\mathcal{P}})
\xrightarrow[r \to \infty]{\textnormal{BL},\bk x1p} \Upsilon_{\bk x1p}
$$
and the speed of convergence is bounded by the same decreasing function $\varphi_p$ as in~(equation Lp-stab of the paper), namely
\begin{align} 
 \sup_{x_1,\ldots,x_p \in \mathbb{R}^d} 
 d_{\textnormal{BL}, \bk x1p}(\bk{\xi^{(r)}}1p(\tilde{x}, \tilde{\mathcal{P}}), \Upsilon_{\bk x1p})  \leq 4\varphi_p(r), \ r > 0.
\end{align}
\item 
The probability distributions represented by $\Upsilon_{\bk x1p}$ are probability kernels from $(\mathbb{R}^d)^p$ to $\mathbb{R}^p$; formally, for any measurable function $f$ on $\mathbb{R}^p$, the function $(\mathbb{R}^d)^p\owns\bk x1p\mapsto\mathbb{E} [f(\Upsilon_{\bk x1p})]\in\mathbb{R}$ is measurable.
\item   The convergence holds also for $\bk{\xi}1p(\tilde{x},\tilde{\mathcal{P}}_n)$:
\begin{equation}
\bk{\xi}1p(\tilde{x},\tilde{\mathcal{P}}_n) \xrightarrow[n \to \infty]{\textnormal{BL},\bk x1p} \Upsilon_{\bk x1p}
\end{equation}
with the speed of convergence bounded by the same decreasing function $\varphi_p$ of the  distance $ d(\bk x1p,\partial W_n)$ from  $\{x_1,\ldots, x_p\}\subset W_n$ to the boundary of $W_n$:
\begin{equation} d_{\textnormal{BL}, \bk x1p}(\bk{\xi}1p(\tilde{x}, \tilde{\mathcal{P}}_n),\Upsilon_{\bk x1p})  \leq
 6\varphi_{p}(d(\bk x1p,\partial W_n)).
 \end{equation}
\item  If $\tilde{\mathcal{P}}$ is stationary and $\xi$ is translation invariant, then the  distribution of $\Upsilon_{\cdot}$ is translation invariant:
i.e., for all $y\in\mathbb{R}^d$
 $$\Upsilon_{\bk x1p}
\overset{\text{law}}{=}\Upsilon_{\bk x1p-y}=\Upsilon_{(x_1-y,\ldots,x_p-y)}.
$$

\end{enumerate}

\begin{enumerate}[wide,label=(\roman*),  labelindent=0pt]
\setcounter{enumi}{4}
\item  When  $\xi$ is defined on  $\mathbb{R}^d \times \mathbb{K} \times
  \mathcal{N}_{\mathbb{R}^d \times \mathbb{K}}$ and satisfies \textnormal{BL}-localization~(equation Lp-stab-infinite of the paper)  for some $p\ge 1$, then for $\{x_1,\ldots, x_p\}\subset W_n$ we have
\begin{equation}
d_{\textnormal{BL}, \bk x1p}( \bk{\xi}1p(\tilde{x}, \tilde{\mathcal{P}}_n), \bk{\xi}1p(\tilde{x}, \tilde{\mathcal{P}}))\le 12\varphi_{p}(d(\bk x1p,\partial W_n)),
\end{equation}
and hence, under $\mathbb{P}_{\bk x1p}$, $\bk{\xi}1p(\tilde{x}, \tilde{\mathcal{P}})$ has the law of 
$\Upsilon_{\bk x1p}$.
\end{enumerate}","status":"unverified"}

