{"assumptions":[],"created_at":"2026-10-27T06:25:55.482638+00:00","domain":"probability theory","id":"claim_be1aa0069b21ed99c84ea56b490819952e585a5b4db7a5bd71c42468e5b1f2d3","kind":"definition","schema_version":1,"statement":"[Defn 26 of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] A pair $(u_\alpha^h,\nu_\alpha^h)$ is a kinetic solution of \eqref{eq:skeleton-obstacle-problem-viscous} with initial data $u^0$ and obstacle $\psi$ if the following conditions are satisfied.
\begin{enumerate}[label=\textbf{\arabic*}.]
  \item For any $p\geq1$, $u_\alpha^h\in L^\infty(0,T;L^p(\mathbb T^N))\cap L^2(0,T;H^1(\mathbb T^N)),$ and
\begin{align}
\underset{0\leq t\leq T}{{\rm{ess\sup}}}\ \Vert u_\alpha^h(t)\Vert ^p_{L^p(\mathbb{T}^N)}+\alpha \int_0^T\int_{\mathbb T^N}|\nabla u^h_{\alpha}|^2\dd x\dd s\leq C(p,M,T,D_0),
\end{align}
\item  We have 
\begin{equation*}
u^h_{\alpha}(x,t)\geq\psi(x,t),\quad\text{for }\dd x\otimes\dd t\text{-a.e. }(x,t),
\end{equation*}
and $\nu_\alpha^h$ is a nonnegative finite Radon measure on $\mathbb{T}^N\times[0,T)$.
\item  The function $u^h_{\alpha}$ satisfies
\begin{equation*}
\lim_{\tau\downarrow0}\frac{1}{\tau}\int_0^\tau\Vert u^h_{\alpha}(t)-u^0\Vert _{L^1(\mathbb{T}^N)}\dd t=0.
\end{equation*}
\item Let $\dd o^h_{\alpha}:=\alpha|\nabla u^h_{\alpha}|^2\delta_{u^h_{\alpha}(x,t)}(\dd\xi)\dd x\dd t$ be the parabolic defect measure. There exists a (deterministic) kinetic measure $q^h_{\alpha}\geq o^h_{\alpha}$ such that $f:= \one_{u^h_{\alpha}>\xi}$ satisfies for all $\varphi\in C^\infty_c(\mathbb{T}^N\times [0,T)\times \mathbb{R})$,
\begin{align}\notag
&\int^T_0\langle f(t), \partial_t \varphi(t)\rangle \dd t+\langle f^0, \varphi(0)\rangle +\int^T_0\langle f(t), a(\xi)\cdot \nabla_x \varphi (t)\rangle \dd t+\alpha\int^T_0\langle f(t), \Delta_x \varphi (t)\rangle \dd t \\
&= -\sum_{k\geq 1}\int^T_0\int_{\mathbb{T}^N} \int_{\mathbb{R}}g_k(x,\xi)\varphi (x,t,\xi)h_k(t)\dd \mu^{\alpha,h}_{x,t}(\xi)\dd x\dd t \\
&\quad + q^h_{\alpha}(\partial_{\xi} \varphi)-\int_0^T\int_{\mathbb{T}^N}\varphi(x,t,\psi(x,t))\dd\nu^h_{\alpha}(x,t),\nonumber
\end{align}
 where  $\mu^{\alpha,h}_{x,t}(\dd\xi)=\delta_{u^h_{\alpha}(x,t)}(\dd\xi)$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:03:59.164713+00:00","domain":"probability theory","id":"claim_be1bbc45d4c92f2102ac13ba630e7fbb6c594e49d2c57e3aa1c52ad451dc8552","kind":"concept","schema_version":1,"statement":"[Lemma l: 1wr thm step1 of arXiv:2507.04505, 'Heights of butterfly trees'] Let $\pi = (\pi_{\rho(1)} | \cdots | \pi_{\rho(m)}) \in S_n \wr S_m$, where $\rho \in S_m$ and $\pi'_j = \pi_{\rho(j)} - \min(\pi_{\rho(j)}) + 1 \in S_n$ for each $j$. For node $v$ in $\mathcal T(\pi_{\rho(j)}) \subset \mathcal T(\pi)$, let $x = v - \min(\pi_{\rho(j)}) + 1$, and $\V y = (y_1,y_2,\ldots,{\rho(j)})$ the subsequence of $\rho$ that denotes the node sequence in the shortest path in $\mathcal T(\rho)$ connecting the root $\rho(1) = y_1$ to node ${\rho(j)}$. Let $\ell_n^{(j)} = \ell(\pi_j)$ and $r_n^{(j)} = r(\pi_j)$ denote the top-left and top-right edge lengths of $\mathcal T(\pi_j)$, and define
    $$
    G({s,t},u,v) = \left\{ \begin{array}{ll}
    u, & {s > t},\\ v, & {s < t}.
    \end{array}\right.
    $$ Then
    \begin{equation*}
        \operatorname{depth}_{\pi}(v) = \operatorname{depth}_{\pi'_j}(x) +\sum_{k=1}^{\operatorname{depth}_{\rho}(\rho(j))} G(y_k,y_{k+1}, \ell_n^{({y_k})}+1,r_n^{({y_k})}+1).
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:17:04.327177+00:00","domain":"probability theory","id":"claim_be1ff327e69e528387f12500df4ece23b96c21bdfe55eda9b8b3e27dcfdb4037","kind":"concept","schema_version":1,"statement":"[Proposition eq:ssshortrange of arXiv:2606.01866, 'Phase Transition of a Semiflexible Membrane in Two Dimensions'] \label[proposition]{thm:ssshortrange}
