{"assumptions":[],"created_at":"2026-10-27T11:32:18.848218+00:00","domain":"probability theory","id":"claim_be796edcdee1e7a57b7e18aee9eda59b074ef215b3c3785272f321bc38f8a20f","kind":"definition","schema_version":1,"statement":"[Defi 5 of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] For any fixed $t_*\ge 0$ and for any  continuous  function $X(t,i)$ defined for $t\ge i+t_*$ and $i\in[0,i_\dagger)$,
	we say that a  bounded and continuous function $\underline u(t,i,x)$ defined for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and  $x\ge X(t,i)-R$ is a
	subsolution of   \eqref{moving frame-u} for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\ge X(t,i)$,
	if $\partial_t \underline u(t,i,x)$ and $\partial_i\underline u(t,i,x)$ exist a.e. such that 
		\begin{equation*}
		\begin{aligned}
			\left\{\begin{split}
				&	\partial_t \underline u(t,i,x)  + \partial_i \underline u(t,i,x) \le 0,~~~~~~~ ~~~~~~~~~~~~t\ge i+t_*, ~i\in(0,i_\dagger), ~x\ge X(t,i)-R, \\
				&	\underline u(t,0,x)\le \S_0 \int_0^{i_\dagger} \omega(i) e^{-\alpha_*c_* i} \K_* *\underline u(t,i,x)\md i,  ~~~~~~~~~~~~~~~t\ge  i_\dagger+t_*,   ~x\ge X(t,0).
			\end{split}\right.		
		\end{aligned}
	\end{equation*}
A supersolution $\overline u$ to \eqref{moving frame-u} for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\ge X(t,i)$ can be defined in the same way with the inequality signs being reversed.


	Analogously, 	for any fixed $t_*>0$ large and for any  continuous and nondecreasing  functions $X^\pm(s)$ defined for $s\ge t_*$ such that $X^-(s)\le X^+(s-i_\dagger)$ for all $s\ge t_*$,  a  bounded and continuous function $\underline u(t,i,x)$ defined for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and  $X^-(t)-R\le x\le X^+(t)+R$ is called a
	subsolution of \eqref{moving frame-u}   for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\in[X^-(t), X^+(t-i)]$,
	if $\partial_t \underline u(t,i,x)$ and $\partial_i\underline u(t,i,x)$ exist a.e. such that
\begin{equation*}
\begin{aligned}
	\left\{\begin{split}
		&	\partial_t \underline u(t,i,x)  + \partial_i \underline u(t,i,x) \le 0,~~~~~~~~~~~~~~~~~~~~~t\ge i+t_*, ~i\in(0,i_\dagger), ~X^-(t)\le x\le X^+(t-i), \\
		&\underline	u(t,0,x)\le \S_0 \int_0^{i_\dagger} \omega(i) e^{-\alpha_*c_* i} \K_* *\underline u(t,i,x)\md i,  ~~~~~~~~~~~~~~~~t\ge t_*+ i_\dagger,   ~X^-(t)\le x\le X^+(t).
	\end{split}\right.		
\end{aligned}
\end{equation*}
