{"assumptions":[],"created_at":"2026-10-27T19:48:47.285744+00:00","domain":"probability theory","id":"claim_bf0a27d3bc753d138e5250ffb9c5d8f1b979e74d0ecd0e2a88369ef516586f9d","kind":"concept","schema_version":1,"statement":"[Proposition prop:annealed 0 of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $f\in\mathbb{R}$, $u\in(0,1)$, $q\in(0,1)$, and $\zeta\in\mathrm{Prefix}_2(u,q)$. Recall $\mathcal{P}\mathrm{arisi}$ from (equation def:Par of the paper).
		Define the \emph{prefix free energy} 
		\begin{equation*}
			\mathcal{P}(u;q):=\inf_{\zeta'\in\mathrm{Prefix}_2(u,q)}\mathcal{P}\mathrm{arisi}(\zeta')
		\end{equation*}
		and the \emph{complexity functional at level $f$}
		\begin{equation}
			\mathcal{C}_f(u;q)
			\;:=\;
			u\,\bigl(\mathcal{P}(u;q)-f\bigr).
		\end{equation}

		We assume:
		\begin{enumerate}
			\item[\emph{(i)}]
			\emph{(Tail optimality.)} The infimum $\mathcal{P}(u;q)$ is attained at $\zeta$.
			\item[\emph{(ii)}]
			\emph{(Stationarity.)} $(u,q)$ is a critical point of $\mathcal{C}_f$.
		\end{enumerate}

		Let $\varepsilon\in(0,1)$ and let $\mathcal{N}_\varepsilon(f,\zeta,q)$ be the number of critical
		points of $F_{\mathrm{TAP},\zeta}$ in $\mathrm{SUSY}_1(\zeta,\varepsilon)$ with
		$\frac{1}{N}F_{\mathrm{TAP},\zeta}(\mathbf{m})\in(f-\varepsilon,f+\varepsilon)$.  Then
		\[
		\lim_{\varepsilon\to 0}\lim_{N\to\infty}
		\frac{1}{N}\log\mathbb{E}\bigl[\mathcal{N}_\varepsilon(f,\zeta,q)\bigr]
		\;=\;
		\mathcal{C}_f(u;q)
		\;=\;
		\zeta(\{0\})\,\bigl(\mathcal{P}\mathrm{arisi}(\zeta)-f\bigr).
		\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:23:25.637269+00:00","domain":"probability theory","id":"claim_bf0a8b499d8855da13fcd42f5870e371614225c18dcc389d3bd547eb5858b2d6","kind":"concept","schema_version":1,"statement":"[Cor Jackson_integral_qMPL of arXiv:2609.01458, 'Confluence relations for $q$-analogues of multiple zeta values'] Let $d\geq1$. When $x_{1},\dots,x_{d}$
are constant with respect to $z$, we have
\begin{align*}
\int\frac{\mathrm{Li}_{q;k_{1},\dots,k_{d}}(x_{1},\dots,x_{d-1},x_{d}z)}{z}d_{q}z & =\mathrm{Li}_{q;k_{1},\dots,k_{d-1},k_{d}+1}(x_{1},\dots,x_{d-1},x_{d}z),\\
\int\frac{\mathrm{Li}_{q;k_{1},\dots,k_{d}}(x_{1},\dots,x_{d-1},x_{d}z)}{z-a^{-1}}d_{q}z & =-\mathrm{Li}_{q;k_{1},\dots,k_{d},1}(x_{1},\dots,x_{d-1},x_{d}a^{-1},az),\\
\int\frac{1}{z-a^{-1}}d_{q}z & =-\mathrm{Li}_{q;1}(az),
\end{align*}
where $a\in\mathbb{C}^{\times}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:18:13.284081+00:00","domain":"probability theory","id":"claim_bf0fd0a2331ac9c362321127eeded9372784a3364277946e6aad017d89d2a641","kind":"definition","schema_version":1,"statement":"[Definition def:good_approximation of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Suppose that we have the setup above where $\mathcal {L}$ is the outermost loop of $\Gamma_\mathbf{D}$ that surrounds~$0$. Suppose that $\metapprox{\epsilon}{\cdot}{\cdot}{\Gamma}$ is an approximate ${\rm CLE}_{\kappa'}${} metric for each $\epsilon \in {(0,1]}$ with respect to the same constants $c_{\mathrm{s}} \ge 0$, $c_{\mathrm{p}}(N) > 0$. We say that $(\metapprox{\epsilon}{\cdot}{\cdot}{\Gamma})_{\epsilon \in {(0,1]}}$ is a \emph{good approximation scheme} if there exists a constant $\mathbf{a}_{\epsilon} > 0$ for each $\epsilon \in {(0,1]}$ and a constant $a_0 > 0$ such that
\begin{equation}
 \lim_{\epsilon \searrow 0} \frac{\mathbf{a}_{\epsilon}}{\epsilon^{a_0}\median{\epsilon}} = 0
\end{equation}
and for each $r>0$ we have
\begin{equation}
 \lim_{\epsilon \searrow 0} \mathbf{P}\left[ \sup_{V \in \metregions} \sup_{\substack{\dpath[\overline{V}](x,y) < \epsilon ,\\ \dpath(x, \Upsilon_\Gamma \setminus \overline{V}) \ge r}} \metapproxres{\epsilon}{V}{x}{y}{\Gamma} \le \mathbf{a}_{\epsilon} \right] = 1 .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:57:20.691790+00:00","domain":"probability theory","id":"claim_bf1628a0042868df601a902b921d3a29118f6f59a5f4eb878faa3ed057366544","kind":"theorem","schema_version":1,"statement":"[Proposition prop:lipptx33 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] Let $\delta_1,\delta_2\in [0,1)$, $\lambda_1\geq 0$ and $l\in \mathcal{H}_1^{\delta_1,\lambda_1}(\mathbb{R}^d)$, $h\in \mathcal{H}_1^{\delta_2}(\mathbb{R}^d)$, $z\in \mathbb{R}^d$. For $t\in [0,1)$ and $\theta_1,\theta_2\in \mathbb{R}^d$, in the case $\beta\geq 1$ we have 
    \begin{align*}
        \|&\int (l(y)-l(z))h(y)(p^{t,\theta_1}(y)-p^{t,\theta_2}(y))d\lambda^d(y)\|\\
        & \leq C \sum_{i=1}^2\left(\|\theta_1-\theta_2\|^{\delta_1}\log(\|\theta_1-\theta_2\|^{-1})^{-\lambda_1}\Biggl(\int\|h(y)\|^2p^{t,\theta_i}(y) \right)^{1/2}+\|\theta_1-\theta_2\|^{\delta_2}\left(\int\|l(y)-l(z)\|^2p^{t,\theta_i}(y) \right)^{1/2}\Biggl).
    \end{align*}
    and in the case $\beta<1$, $l(y)-l(z)=y-t\theta_1$, $h(y)=H(y,\theta_2)$ we have
    \begin{align*}
        &\|\int (y-t\theta_1)H(y,\theta_2)(p^{t,\theta_1}(y)-p^{t,\theta_2}(y))d\lambda^d(y)\|\\
         \leq &C\|\theta_1-\theta_2\|\left(\|\int H(y,\theta_2)dp^{t,\theta_2}(y) \|+\|\int \left(y-t\theta_1 \right)dp^{t,\theta_2}(y)\|\right)\\
        & +C\frac{\|\theta_1-\theta_2\|^{\beta}}{\log(\|\theta_1-\theta_2\|^{-1})^{\theta}}\left(\int\|y-t\theta_2\|^2dp^{t,\theta_2}(y) \right)^{1/2}\left(\int\|H(y,\theta_2)\|^2p^{t,\theta_1}(y) \right)^{1/2}.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:59:58.431587+00:00","domain":"probability theory","id":"claim_bf20bcdbbdf9bbcb020707385a3214eff622bb87fd57137db920c33cfc4924b7","kind":"definition","schema_version":1,"statement":"[Definition def:canonical-mgle-projection-final of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] For \(L\in\mathscr L(T,d)\), define \(L^{\mathrm{mgle}}\in\mathscr L_{\mathrm{mgle}}(T,d)\) by
\begin{equation}

(L^{\mathrm{mgle}})_{t,s}
:=
\frac{1}{T-s+1}\sum_{u=s}^T L_{u,s},
\qquad 1\le s\le t\le T.
\end{equation}
For \(\mathbb{X}=\mathbb{G}^{L}\), we define its corresponding martingale projection by \(
\mathbb{X}^{\mathrm{mgle}}:=\mathbb{G}^{L^{\mathrm{mgle}}}.
\) By [gunasingam2026adapted], this is the canonical representative of the
\(\mathcal{AW}_2\)-projection of \(\mathbb{G}^{L}\) onto the Gaussian martingale class, up to the
usual right-orthogonal equivalence of factor representatives.","status":"unverified"}

