    \left\|\left|\grad^k \Pop_t f\right|\right\|_{\Leb^2}^{2} \leq \upe^{-2k\left(p-1\right)t}\left(\upe^{4t}-1\right)^{-k(1-\frac{p}{2})}  \left\|f\right\|_{\Leb^{\infty}}^{2-p} \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.360230+00:00","domain":"probability theory","id":"claim_c0b6ba56daebcc26f9de2a15bd4bfab4f889dfcfc86fec0e823755e08bc3df75","kind":"theorem","schema_version":1,"statement":"[Proposition 33 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1} and \eqref{eq:liminf}. Then there exists constant $c>0$ such that for any $n$ sufficiently large, $h_*+\frac{n}{(\log n)^{1+\frac{\varepsilon}{8}}}\le  s \le h^*$ and $1\le k\le q_n(s)$, we have
    \begin{equation}
    \p_n\left(X_{s-{\frac{n}{(\log n)^{1+\frac{\varepsilon}{8}}}}}\le \dfrac{k}{(\log n)^{\frac{\varepsilon}{6}}}+(\log n)^{1+\frac{\varepsilon}{2}}\,\Big|\, X_s=k\right)\ge 1-c(\log n)^{-\frac{13}{24}\varepsilon}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:29:14.934682+00:00","domain":"probability theory","id":"claim_c0b70e338784571148bfaf7e83b0ef9b445634854ab9de4daa168bd69be7ee04","kind":"theorem","schema_version":1,"statement":"[Proposition prop.GreenQuartic of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] We have the following estimates for the quartic sum consisting of the finite difference of $\overline{g}_\lambda$:
		\begin{enumerate}
			\item We have the following estimates for the four-block quartic sum.
			\begin{enumerate}
				\item There exists a constant $C$ independent of $\lambda$ such that for every non-negative bounded weight function $f\in\ell^{\infty}(\mathbb{Z})$, the following estimate holds:
				\begin{multline*}
					\sum_{x,x',y,y'\in\mathbb{Z}}f(x)f(x') {\mathsf{D}}_1\overline{g}_\lambda(x,y){\mathsf{D}}_1\overline{g}_\lambda(x,y'){\mathsf{D}}_1\overline{g}_\lambda(x',y){\mathsf{D}}_1\overline{g}_\lambda(x',y')\\
					\leqslant C\left\Vert{f}\right\Vert_{\ell^\infty(\mathbb{Z})}^{2}\log(\lambda^{-1}).
				\end{multline*}
				\item There exists a constant $C$ independent of $\lambda$, such that for every $r\in\mathbb{Z}_{+}$, the following estimate holds:
				\begin{multline*}
					\sum_{z_i,z_i'\in\mathcal{Z}_m}{\mathsf{D}}^2_{(r)}\overline{g}_\lambda(z_1,z_1')\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_2,z_1')\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_1,z_2')\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_2,z_2')\\
					\leqslant C r^8\left((\log(\lambda^{-1}))^{\frac{3}{2}}+1\right).
				\end{multline*}
			\end{enumerate}

			\item	There exists a constant $C$ independent of $\lambda$, such that for every $r\in\mathbb{Z}_{+}$, the following estimates about the three-block quartic sum hold.

			\begin{enumerate}
				\item For some terms which we can write as a summation of quadratic terms
				\begin{multline*}
					\sum_{z\in\mathcal{Z}_m}\left(\sum_{z'\in\mathcal{Z}_m}\left(\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z,z')\right)^2\right)^2+	\sum_{z'\in\mathcal{Z}_m}\left(\sum_{z\in\mathcal{Z}_m}\left(\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z,z')\right)^2\right)^2\\
					\leqslant Cr^8\left(\log(\lambda^{-1})+1\right),
				\end{multline*} 
				\item For some other three blocks  quartic sum $\operatorname{TB}$
				\begin{equation*}
					\operatorname{TB}\leqslant Cr^8\left(\left(\log(\lambda^{-1})\right)^{\frac{3}{2}}+1\right),
				\end{equation*}
				where $\operatorname{TB}$ can be one of the following:
				\begin{multline*}
					\sum_{z_i\in\mathcal{Z}_m}\left(\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_1,z_1)+\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_1,z_2)\right)\left(\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_2,z_2)+\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_2,z_1)\right)\\
					\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_1,z_3)\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_2,z_3),
				\end{multline*}
				or
				\begin{equation*}
					\sum_{z_i\in\mathcal{Z}_m}\left(\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_1,z_3)\right)^2\left(\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_2,z_2)+\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_2,z_1)\right)^2.
				\end{equation*}
			\end{enumerate}

			\item There exists a constant $C$ independent of $\lambda$, such that for every $r\in\mathbb{Z}_{+}$, the following estimate about the two-block quartic sum holds:
			\begin{multline*}
				\sum_{z_i\in\mathcal{Z}_m}\left(\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_1,z_1)+\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_1,z_2)\right)^2\left(\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_2,z_2)+\widetilde{{\mathsf{D}}}_{(r)}\overline{g}_\lambda(z_2,z_1)\right)^2\\
				\leqslant Cr^8 \left(\log(\lambda^{-1})+1\right).
			\end{multline*}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.360377+00:00","domain":"probability theory","id":"claim_c0bb28ff5ff31348367771226d88e57b9cee9916480e4ab2fbcf71cb155a0c8b","kind":"lemma","schema_version":1,"statement":"[Lemma 35 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1} and \eqref{eq:liminf}. Then there exists constant $c>0$ such that for all $n$ sufficiently large and $h_*+\frac{n}{(\log n)^{1+\frac{\varepsilon}{8}}}\le s \le h^*$,
